TURATH_CHUNK(1,[{"num":200,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيُّمَا رَجُلٍ مُسْلِمٍ أَكْفَرَ رَجُلًا مُسْلِمًا، فَإِنْ كَانَ كَافِرًا وَإِلَّا كَانَ هُوَ الْكَافِرُ."],"takhrij":"صحيح: رواه أبو داود (4687) عن عثمان بن أبي شيبة، حدثنا جرير، عن فُضيل بن غزوان، عن نافع، عن ابن عمر، فذكر الحديث، وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء من التحذير في تكفير المسلم","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (4687).","chapter_en":"What Has Been Reported Concerning the Warning Against Declaring a Muslim to Be a Disbeliever","part_en":"The Book of Faith","group_ar":"مجموع أبواب خصال الإيمان","group_en":"Collection of Chapters on the Characteristics of Faith","part_no":2,"group_no":1,"chapter_no":58,"content":{"translation":{"en":["Ibn ʿUmar may Allah be pleased with them reported that the Messenger of Allah ﷺ said: “Whenever a Muslim man declares another Muslim to be a disbeliever, then if the latter truly is a disbeliever, the statement applies to him; otherwise, it returns upon the one who declared him so.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4687)."},{"num":201,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَيْسَ مِنْ رَجُلٍ ادَّعَى لِغَيْرِ أَبِيهِ وَهُوَ يَعْلَمُهُ إِلَّا كَفَرَ، وَمَنِ ادَّعَى قَوْمًا لَيْسَ لَهُ فِيهِمْ فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ."],"takhrij":"متفق عليه: رواه البخاريّ في المناقب (3508)، ومسلم في الإيمان (61) كلاهما من حديث عبدالوارث، عن حسين المعلم، عن عبدالله بن بريدة، قال: حدثني يحيى بن يعمر، أنّ أبا الأسود الدّيليّ حدّثه عن أبي ذر، فذكر الحديث، ولفظهما سواء، وزاد مسلم: ومن دعا رجلاً بالكفر، أو قال: عدو الله ليس كذلك إلاّ حار عليه.","grade":"متفق عليه","chapter_ar":"باب بيان حال إيمان من رغب عن أبيه وهو يعلم","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3508) and Muslim (61).","chapter_en":"Clarifying the State of Faith of One Who Denies His Father While Knowing","part_en":"The Book of Faith","group_ar":"مجموع أبواب خصال الإيمان","group_en":"Collection of Chapters on the Characteristics of Faith","part_no":2,"group_no":1,"chapter_no":59,"content":{"translation":{"en":["Abū Dharr may Allah be pleased with him reported that he heard the Prophet ﷺ say: “No man knowingly claims someone other than his true father except that he has committed disbelief. And whoever claims to belong to a people to whom he does not belong, let him take his seat in the Fire.”"]},"buhuth":{"en":["Muslim added:","“Whoever calls a man a disbeliever, or says to him, ‘Enemy of Allah,’ when he is not so, the accusation returns upon him.”","The expression «حار عليه» means that it returns upon him and he bears its consequence."]}},"tuhfa":{},"full":1,"dr":1,"rep":[13033],"tks":"متفق عليه: رواه البخاري (3508)، ومسلم (61)."},{"num":202,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ يَقُولُ: سَمِعَ أُذُنَايَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَقُولُ: مَنِ ادَّعَى أَبًا فِي الإِسْلَامِ غَيْرَ أَبِيهِ، يَعْلَمُ أَنَّهُ غَيْرُ أَبِيهِ، فَالْجَنَّةُ عَلَيْهِ حَرَامٌ."],"takhrij":"متفق عليه: رواه مسلم في الإيمان (63) عن عمرو الناقد، حدثنا هشيم بن بشير، أخبرنا خالد الحذّاء، عن أبي عثمان، قال: لما ادُّعِي زياد، لقيتُ أبا بكرة فقلت له: ما هذا الذي صنعتُم؟ إني سمعت سعد بن أبي وقّاص يقول (فذكره). فقال أبو بكرة: وأنا سمعتُه من رسول الله صلى الله عليه وسلم.","grade":"متفق عليه","chapter_ar":"باب بيان حال إيمان من رغب عن أبيه وهو يعلم","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (63), whose wording is cited here, and al-Bukhārī (6766) in an abridged form.","chapter_en":"Clarifying the State of Faith of One Who Denies His Father While Knowing","part_en":"The Book of Faith","group_ar":"مجموع أبواب خصال الإيمان","group_en":"Collection of Chapters on the Characteristics of Faith","part_no":2,"group_no":1,"chapter_no":59,"content":{"translation":{"en":["Saʿd ibn Abī Waqqāṣ, may Allah be pleased with him, said: My own ears heard the Messenger of Allah ﷺ say: “Whoever, after Islam, claims as his father someone other than his true father, while knowing that he is not his father, Paradise is forbidden to him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (63) واللفظ له، والبخاري (6766) مختصرا."},{"num":203,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ وَأَبِي بَكْرَةَ كِلَاهُمَا يَقُولُ: سَمِعَتْهُ أُذُنَايَ، وَوَعَاهُ قَلْبِي مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: مَنِ ادَّعَى إِلَى غَيْرِ أَبِيهِ، وَهُوَ يَعْلَمُ أَنَّهُ غَيْرُ أَبِيهِ، فَالْجَنَّةُ عَلَيْهِ حَرَامٌ."],"takhrij":"متفق عليه: رواه البخاريّ في المغازي (4326)، ومسلم في الإيمان (63) كلاهما من حديث عاصم قال: سمعتُ أبا عثمان قال: سمعتُ سعداً وأبا بكرة كلاهما يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب بيان حال إيمان من رغب عن أبيه وهو يعلم","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4326) and Muslim (63).","chapter_en":"Clarifying the State of Faith of One Who Denies His Father While Knowing","part_en":"The Book of Faith","group_ar":"مجموع أبواب خصال الإيمان","group_en":"Collection of Chapters on the Characteristics of Faith","part_no":2,"group_no":1,"chapter_no":59,"content":{"translation":{"en":["Saʿd ibn Abī Waqqāṣ and Abū Bakrah may Allah be pleased with them both said: “My own ears heard it and my heart retained it: Muḥammad ﷺ said: ‘Whoever claims descent from someone other than his father while knowing that he is not his father, Paradise is forbidden to him.’”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4326)، ومسلم (63)."},{"num":204,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا تَرْغَبُوا عَنْ آبَائِكُمْ، فَمَنْ رَغِبَ عَنْ أَبِيهِ فَهُوَ كُفْرٌ."],"takhrij":"متفق عليه: رواه البخاريّ في الفرائض (6768)، ومسلم في الإيمان (62) كلاهما من حديث ابن وهب، أخبرني عمرو، عن جعفر بن ربيعة، عن عراك بن مالك، عن أبي هريرة، فذكره، ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب بيان حال إيمان من رغب عن أبيه وهو يعلم","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6768) and Muslim (62), with the same wording in both.","chapter_en":"Clarifying the State of Faith of One Who Denies His Father While Knowing","part_en":"The Book of Faith","group_ar":"مجموع أبواب خصال الإيمان","group_en":"Collection of Chapters on the Characteristics of Faith","part_no":2,"group_no":1,"chapter_no":59,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Prophet ﷺ said: “Do not deny your fathers, for whoever denies his father has committed an act of disbelief.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6768)، ومسلم (62)، ولفظهما سواء."},{"num":205,"demo":false,"sanad":"","matn":["عَنْ جَرِيرِ بْنِ عَبْدِ اللَّهِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا عَبْدٍ أَبَقَ، فَقَدْ بَرِئَتْ مِنْهُ الذِّمَّةُ.","وَفِي رِوَايَةٍ: إِذَا أَبَقَ الْعَبْدُ لَمْ تُقْبَلْ لَهُ صَلَاةٌ.","وَفِي رِوَايَةٍ: أَيُّمَا عَبْدٍ أَبَقَ مِنْ مَوَالِيهِ، فَقَدْ كَفَرَ حَتَّى يَرْجِعَ إِلَيْهِمْ."],"takhrij":"صحيح: رواه مسلم في الإيمان (68,69,70)، الروايات الثلاثة من طرق عن الشعبي عن جرير. ولكن قال الشعبي في الرواية الثالثة: قد والله رُوي عن النبيّ صلى الله عليه وسلم، ولكني أكره أن يُروى عني ههنا بالبصرة.","grade":"صحيح","chapter_ar":"باب إطلاق اسم الكفر على العبد الآبق","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (69).","chapter_en":"Applying the Term Disbelief to the Runaway Slave","part_en":"The Book of Faith","group_ar":"مجموع أبواب خصال الإيمان","group_en":"Collection of Chapters on the Characteristics of Faith","part_no":2,"group_no":1,"chapter_no":60,"content":{"translation":{"en":["Jarīr ibn ʿAbdillāh may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Any slave who runs away has the covenant of protection disclaimed from him.” In another narration:","“If a slave runs away, his prayer is not accepted.” And in another narration:","“Any slave who runs away from his masters has committed an act of disbelief until he returns to them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (69)."},{"num":206,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: سَأَلَ أُنَاسٌ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْكُهَّانِ ؟ فَقَالَ: إِنَّهُمْ لَيْسُوا بِشَيْءٍ، فَقَالُوا: يَا رَسُولَ اللَّهِ فَإِنَّهُمْ يُحَدِّثُونَ بِالشَّيْءِ يَكُونُ حَقًّا، قَالَ: فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تِلْكَ الْكَلِمَةُ مِنَ الْحَقِّ يَخْطَفُهَا الْجِنِّيُّ، فَيُقَرْقِرُهَا فِي أُذُنِ وَلِيِّهِ كَقَرْقَرَةِ الدَّجَاجَةِ، فَيَخْلِطُونَ فِيهِ أَكْثَرَ مِنْ مِائَةِ كَذْبَةٍ."],"takhrij":"متفق عليه: رواه البخاريّ في التوحيد (7561)، ومسلم في السلام (2228) كلاهما من حديث ابن شهاب، قال: أخبرني يحيى بن عروة بن الزبير، أنه سمع عروة ابن الزبير يقول: قالت عائشة، فذكر الحديث، واللّفظ للبخاريّ، ولفظ مسلم نحوه.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تحريم الكهانة وإتيان الكهان","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7561) and Muslim (2228).","chapter_en":"What Has Been Reported Concerning the Prohibition of Soothsaying and Visiting Soothsayers","part_en":"The Book of Faith","group_ar":"مجموع أبواب خصال الإيمان","group_en":"Collection of Chapters on the Characteristics of Faith","part_no":2,"group_no":1,"chapter_no":61,"content":{"translation":{"en":["ʿĀʾishah may Allah be pleased with her reported: Some people asked the Prophet ﷺ about soothsayers. He said: “They are nothing.” They said: “O Messenger of Allah, sometimes they tell us something that turns out to be true.” The Prophet ﷺ said: “That is a word of truth which a jinn snatches and pours into the ear of his ally like the clucking of a hen; then they mix with it more than one hundred lies.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (7561)، ومسلم (2228)."},{"num":207,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا مِنْ مَوْلُودٍ إِلَّا يُولَدُ عَلَى الْفِطْرَةِ، فَأَبَوَاهُ يُهَوِّدَانِهِ وَيُنَصِّرَانِهِ وَيُمَجِّسَانِهِ، كَمَا تُنْتَجُ الْبَهِيمَةُ بَهِيمَةً جَمْعَاءَ، هَلْ تُحِسُّونَ فِيهَا مِنْ جَدْعَاءَ؟ ثُمَّ يَقُولُ أَبُو هُرَيْرَةَ: وَاقْرَءُوا إِنْ شِئْتُمْ: ﴿فِطْرَتَ اللَّهِ الَّتِي فَطَرَ النَّاسَ عَلَيْهَا لَا تَبْدِيلَ لِخَلْقِ اللَّهِ ذَلِكَ الدِّينُ الْقَيِّمُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ﴾ [الروم: 30]."],"takhrij":"متفق عليه: رواه البخاريّ في الجنائز (1359)، ومسلم في القدر (2658) كلاهما من حديث يونس بن يزيد، عن ابن شهاب، أن أبا سلمة بن عبدالرحمن أخبره، أنّ أبا هريرة قال (فذكره).","grade":"متفق عليه","chapter_ar":"باب أخذ الله الميثاق من عباده على ربوبيته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1359) and Muslim (2658).","chapter_en":"Allah Taking the Covenant From His Servants Concerning His Lordship","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “No newborn is born except upon the natural disposition. Then his parents make him a Jew, a Christian, or a Magian, just as an animal gives birth to a complete and sound offspring. Do you perceive any mutilation in it?” Abū Hurayrah would then say: Recite, if you wish: “So set your face toward the religion, inclining to truth — the natural disposition of Allah upon which He created mankind. There is no altering the creation of Allah. That is the upright religion, but most people do not know.” [Sūrat al-Rūm 30:30]"]},"intro":{"ar":["قال الله تعالى:","﴿وَإِذْ أَخَذَ رَبُّكَ مِنْ بَنِي آدَمَ مِنْ ظُهُورِهِمْ ذُرِّيَّتَهُمْ وَأَشْهَدَهُمْ عَلَى أَنْفُسِهِمْ أَلَسْتُ بِرَبِّكُمْ قَالُوا بَلَى شَهِدْنَا أَنْ تَقُولُوا يَوْمَ الْقِيَامَةِ إِنَّا كُنَّا عَنْ هَذَا غَافِلِينَ﴾","[الأعراف: ١٧٢]","ومعنى الآية:","وإذ أخذ ربك من بني آدم من ظهورهم ذريتهم، وأشهدهم على أنفسهم: ألست بربكم؟ قالوا: بلى.","فقال الله وملائكته: شهدنا عليكم بإقراركم بالله ربكم، كيلا تقولوا يوم القيامة: إنا كنا عن هذا غافلين.","انظر: تفسير الطبري (١٠/٥٦٤).","وقال إسحاق بن راهويه:","«أجمع أهل العلم أن الله خلق الأرواح قبل الأجساد، وأنه استنطقهم وأشهدهم».","أي: على ربوبيته.","وقال ابن الأنباري:","«مذهب أهل الحديث وكبراء أهل العلم في هذه الآية أن الله أخرج ذرية آدم من صلبه، وصلب أولاده، وهم في صور الذر، فأخذ عليهم الميثاق أنه خالقهم وأنهم مصنوعون، فاعترفوا بذلك وقبلوا»."],"en":["Allah Most High said:","“And when your Lord brought forth from the children of Adam, from their backs, their descendants and made them testify concerning themselves: ‘Am I not your Lord?’ They said: ‘Yes, we testify,’ lest you should say on the Day of Resurrection, ‘Indeed, we were unaware of this.’”","[Sūrat al-Aʿrāf 7:172]","The meaning of the verse is:","Your Lord brought forth from the children of Adam, from their backs, their descendants and made them testify concerning themselves:","“Am I not your Lord?”","They replied:","“Yes.”","Allah and His angels then bore witness against them concerning their acknowledgment that Allah is their Lord, so that they could not say on the Day of Resurrection:","“We were unaware of this.”","See Tafsīr al-Ṭabarī (10/564).","Isḥāq ibn Rāhawayh said:","“The people of knowledge are agreed that Allah created the souls before the bodies, caused them to speak, and made them testify.”","That is, He made them testify concerning His Lordship.","Ibn al-Anbārī said:","“The position of the scholars of ḥadīth and the leading scholars concerning this verse is that Allah brought forth the descendants of Adam from his loins and from the loins of his descendants while they were in the form of tiny particles. He took from them the covenant that He was their Creator and that they were created beings. They acknowledged this and accepted it.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1359)، ومسلم (2658)."},{"num":208,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَقُولُ اللَّهُ تَعَالَى: لِأَهْوَنِ أَهْلِ النَّارِ عَذَابًا يَوْمَ الْقِيَامَةِ: لَوْ أَنَّ لَكَ مَا فِي الْأَرْضِ مِنْ شَيْءٍ أَكُنْتَ تَفْتَدِي بِهِ؟ فَيَقُولُ: نَعَمْ، فَيَقُولُ: أَرَدْتُ مِنْكَ أَهْوَنَ مِنْ هَذَا، وَأَنْتَ فِي صُلْبِ آدَمَ، أَنْ لَا تُشْرِكَ بِي شَيْئًا، فَأَبَيْتَ إِلَّا أَنْ تُشْرِكَ بِي."],"takhrij":"متفق عليه: رواه البخاريّ في الرقاق (6557)، ومسلم في صفات المنافقين (2805) كلاهما عن محمد بن بشّار، حدّثنا محمد بن جعفر غندر، حدثنا شعبة، عن أبي عمران، قال: سمعت أنس بن مالك، فذكره.","grade":"متفق عليه","chapter_ar":"باب أخذ الله الميثاق من عباده على ربوبيته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6557) and Muslim (2805).","chapter_en":"Allah Taking the Covenant From His Servants Concerning His Lordship","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Mālik may Allah be pleased with him reported that the Prophet ﷺ said: “Allah Most High will say to the person receiving the lightest punishment among the people of the Fire on the Day of Resurrection: ‘If you possessed everything upon the earth, would you ransom yourself with it?’ He will reply: ‘Yes.’ Allah will say: ‘I asked from you something easier than that while you were in the loins of Adam: that you not associate anything with Me, yet you refused except to associate partners with Me.’”"]},"buhuth":{"en":["Muslim also narrated through another route:","“I asked from you something easier than this while you were in the loins of Adam: that you not associate anything with Me” — the narrator said: I think he also said, “and then I would not admit you into the Fire” — “but you refused except to commit shirk.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[16479],"tks":"متفق عليه: رواه البخاري (6557)، ومسلم (2805)."},{"num":209,"demo":false,"sanad":"","matn":["عَنْ هِشَامِ بْنِ حَكِيمٍ، أَنَّ رَجُلًا أَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ أَنَبْتَدِئُ الْأَعْمَالَ، أَمْ قَدْ قُضِيَ الْقَضَاءُ؟ فَقَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللَّهَ تَعَالَى أَخَذَ ذُرِّيَّةَ آدَمَ مِنْ ظُهُورِهِمْ، وَأَشْهَدَهُمْ عَلَى أَنْفُسِهِمْ، ثُمَّ أَفَاضَ بِهِمْ فِي كَفَّيْهِ، فَقَالَ: هَؤُلَاءِ فِي الْجَنَّةِ، وَهَؤُلَاءِ فِي النَّارِ، فَأَهْلُ الْجَنَّةِ مُيَسَّرُونَ لِعَمَلِ أَهْلِ الْجَنَّةِ، وَأَهْلُ النَّارِ مُيَسَّرُونَ لِعَمَلِ أَهْلِ النَّارِ."],"takhrij":"حسن: رواه الفريابي في القدر (22) وعنه الآجري في الشريعة (330)، وابن أبي عاصم في السنة (168) كلهم من حديث عمرو بن عثمان بن سعيد بن كثير ابن دينار الحمصيّ، حدثنا بقية بن الوليد، حدثنا الزبيديّ، حدثني راشد بن سعد، عن عبدالرحمن بن قتادة النّصيريّ، عن هشام بن حكيم، فذكره.","grade":"حسن","chapter_ar":"باب أخذ الله الميثاق من عباده على ربوبيته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Firyābī in al-Qadar (22), through him by al-Ājurrī in al-Sharīʿah (330), and by Ibn Abī ʿĀṣim in al-Sunnah (168).","chapter_en":"Allah Taking the Covenant From His Servants Concerning His Lordship","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Hishām ibn Ḥakīm, may Allah be pleased with him, reported: A man came to the Prophet ﷺ and asked: “O Messenger of Allah, are deeds something that we begin anew, or has the decree already been determined?” The Messenger of Allah ﷺ replied: “Allah, Mighty and Majestic, took the descendants of Adam from his back and made them testify concerning themselves. Then He spread them forth in His two Hands and said: ‘These are for Paradise, and these are for the Fire.’ The people of Paradise are facilitated toward the deeds of the people of Paradise, and the people of the Fire are facilitated toward the deeds of the people of the Fire.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الفريابي في القدر (22)، وعنه الآجري في الشريعة (330)، وابن أبي عاصم في السنة (168)."},{"num":210,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَخَذَ اللَّهُ الْمِيثَاقَ مِنْ ظَهْرِ آدَمَ بِنَعْمَانَ يَعْنِي: عَرَفَةَ، فَأَخْرَجَ مِنْ صُلْبِهِ كُلَّ ذُرِّيَّةٍ ذَرَأَهَا، فَنَثَرَهُمْ بَيْنَ يَدَيْهِ كَالذَّرِّ، ثُمَّ كَلَّمَهُمْ قِبَلًا، قَالَ: ﴿أَلَسْتُ بِرَبِّكُمْ قَالُوا بَلَى شَهِدْنَا أَنْ تَقُولُوا يَوْمَ الْقِيَامَةِ إِنَّا كُنَّا عَنْ هَذَا غَافِلِينَ (172) أَوْ تَقُولُوا إِنَّمَا أَشْرَكَ آبَاؤُنَا مِنْ قَبْلُ وَكُنَّا ذُرِّيَّةً مِنْ بَعْدِهِمْ أَفَتُهْلِكُنَا بِمَا فَعَلَ الْمُبْطِلُونَ (173)﴾ [سورة الأعراف: 172، 173]."],"takhrij":"حسن: رواه أحمد (2455)، وابن أبي عاصم في السنة (202)، والبيهقي في الأسماء والصّفات (714)، وفي كتاب القدر (65)، وابن منده في الرّد على الجهميّة (29)، والحاكم (4000) كلّهم من طرق عن حسين بن محمد المروزيّ، حدثنا جرير، يعني ابن حازم، ، عن كلثوم بن جبر، عن سعيد بن جبير، عن ابن عباس فذكره، واللّفظ لأحمد.","grade":"حسن","chapter_ar":"باب أخذ الله الميثاق من عباده على ربوبيته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (2455), Ibn Abī ʿĀṣim in al-Sunnah (202), and al-Bayhaqī in al-Asmāʾ wa al-Ṣifāt (714).","chapter_en":"Allah Taking the Covenant From His Servants Concerning His Lordship","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Ibn ʿAbbās may Allah be pleased with them reported that the Messenger of Allah ﷺ said: “Allah took the covenant from the back of Adam at Nuʿmān — meaning ʿArafah. He brought forth from his loins every descendant whom He would create and scattered them before Him like tiny particles. Then He spoke to them directly, saying: ‘Am I not your Lord?’ They said, ‘Yes, we testify,’ lest you should say on the Day of Resurrection, ‘Indeed, we were unaware of this,’ or lest you should say, ‘It was only our forefathers who associated others with Allah before us, and we were merely descendants after them. Will You then destroy us for what the falsifiers did?’” [Sūrat al-Aʿrāf 7:172–173]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (2455)، وابن أبي عاصم في السنة (202)، والبيهقي في الأسماء والصفات (714)."},{"num":211,"demo":false,"sanad":"","matn":["عَنْ أُبَيِّ بْنِ كَعْبٍ، فِي قَوْلَ اللَّهُ تَعَالَى: ﴿وَإِذْ أَخَذَ رَبُّكَ مِنْ بَنِي آدَمَ مِنْ ظُهُورِهِمْ ذُرِّيَّتَهُمْ وَأَشْهَدَهُمْ عَلَى أَنْفُسِهِمْ أَلَسْتُ بِرَبِّكُمْ قَالُوا بَلَى شَهِدْنَا أَنْ تَقُولُوا يَوْمَ الْقِيَامَةِ إِنَّا كُنَّا عَنْ هَذَا غَافِلِينَ (172) أَوْ تَقُولُوا إِنَّمَا أَشْرَكَ آبَاؤُنَا مِنْ قَبْلُ وَكُنَّا ذُرِّيَّةً مِنْ بَعْدِهِمْ أَفَتُهْلِكُنَا بِمَا فَعَلَ الْمُبْطِلُونَ (173)﴾ [سورة الأعراف: 172، 173] قَالَ: جَمَعَهُ لَهُ يَوْمَئِذٍ جَمِيعًا مَا هُوَ كَائِنٌ مِنْهُ إِلَى يَوْمِ الْقِيَامَةِ، فَجَعَلَهُمْ أرْوَاحاً ثُمَّ صَوَّرَهُمْ، ثُمَّ اسْتَنْطَقَهُمْ فَتَكَلَّمُوا، وَأَخَذَ عَلَيْهِمُ الْعَهْدَ وَالْمِيثَاقَ ﴿وَأَشْهَدَهُمْ عَلَى أَنْفُسِهِمْ أَلَسْتُ بِرَبِّكُمْ قَالُوا بَلَى شَهِدْنَا أَنْ تَقُولُوا يَوْمَ الْقِيَامَةِ إِنَّا كُنَّا عَنْ هَذَا غَافِلِينَ (172) أَوْ تَقُولُوا إِنَّمَا أَشْرَكَ آبَاؤُنَا مِنْ قَبْلُ وَكُنَّا ذُرِّيَّةً مِنْ بَعْدِهِمْ أَفَتُهْلِكُنَا بِمَا فَعَلَ الْمُبْطِلُونَ (173)﴾ قَالَ: فَإِنِّي أُشْهِدُ عَلَيْكُمُ السَّمَاوَاتِ السَّبْعَ وَالْأَرَضِينَ السَّبْعَ، وَأُشْهِدُ عَلَيْكُمْ أَبَاكُمْ آدَمَ، أَنْ لَا تَقُولُوا يَوْمَ الْقِيَامَةِ: لَمْ نَعْلَمْ بِهَذَا . اعْلَمُوا أَنَّهُ لَا إِلَهَ غَيْرِي، وَلَا رَبَّ غَيْرِي، وَلَا تُشْرِكُوا بِي شَيْئًا، وَإِنِّي سَأُرْسِلُ إِلَيْكُمْ رُسُلًا يُنْذِرُونَكُمْ عَهْدِي وَمِيثَاقِي، وَأُنْزِلُ عَلَيْكُمْ كِتَابِي . قَالُوا: نَشْهَدُ أَنَّكَ رَبُّنَا، وَإِلَهُنَا لَا رَبَّ لَنَا غَيْرُكَ، وَلَا إِلَهَ لَنَا غَيْرُكَ . فَأَقَرُّوا لَهُ يَوْمَئِذٍ بِالطَّاعَةِ، وَرَفَعَ أَبَاهُمْ آدَمَ فَنَظَرَ إِلَيْهِمْ، فَرَأَى فِيهِمُ الْغَنِيَّ وَالْفَقِيرَ، وَحَسَنَ الصُّورَةِ وَدُونَ ذَلِكَ، فَقَالَ: يَا رَبِّ لَوْ سَوَّيْتَ بَيْنَ عِبَادِكَ . فَقَالَ: إِنِّي أَحْبَبْتُ أَنْ أُشْكَرَ، وَرَأَى فِيهِمُ الْأَنْبِيَاءَ مِثْلَ السُّرُّجِ عَلَيْهِمُ النُّورُ، وَخُصُّوا بِمِيثَاقٍ آخَرَ مِنَ الرِّسَالَةِ وَالنُّبُوَّةِ فَهُوَ الَّذِي يَقُولُ اللَّهُ تَعَالَى: ﴿وَإِذْ أَخَذْنَا مِنَ النَّبِيِّينَ مِيثَاقَهُمْ وَمِنْكَ وَمِنْ نُوحٍ وَإِبْرَاهِيمَ وَمُوسَى وَعِيسَى ابْنِ مَرْيَمَ وَأَخَذْنَا مِنْهُمْ مِيثَاقًا غَلِيظًا﴾ [سورة الأحزاب: 7]، وَهُوَ الَّذِي يَقُولُ: ﴿فَأَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفًا فِطْرَتَ اللَّهِ الَّتِي فَطَرَ النَّاسَ عَلَيْهَا لَا تَبْدِيلَ﴾ [سورة الروم: 30]، وَفِي ذَلِكَ قَالَ: ﴿هَذَا نَذِيرٌ مِنَ النُّذُرِ الْأُولَى﴾ [سورة النجم: 56]، وَفِي ذَلِكَ قَالَ: ﴿وَمَا وَجَدْنَا لِأَكْثَرِهِمْ مِنْ عَهْدٍ وَإِنْ وَجَدْنَا أَكْثَرَهُمْ لَفَاسِقِينَ﴾ [سورة الأعراف: 102]."],"takhrij":"حسن: رواه ابن أبي حاتم في تفسيره (8537)، وابن جرير الطبريّ في تفسيره (3278)، والحاكم (3255)، والضّياء في المختارة (1159) كلّهم من طرق عن أبي جعفر عيسى بن عبدالله بن ماهان، عن الرّبيع بن أنس، عن أبي العالية رُفيع، عن أُبيّ بن كعب من قوله.","grade":"حسن","chapter_ar":"باب أخذ الله الميثاق من عباده على ربوبيته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Abī Ḥātim in his Tafsīr (5/1615) and Ibn Jarīr al-Ṭabarī in his Tafsīr (10/557).","chapter_en":"Allah Taking the Covenant From His Servants Concerning His Lordship","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Ubayy ibn Kaʿb may Allah be pleased with him said concerning the statement of Allah Most High: “And when your Lord brought forth from the children of Adam, from their backs, their descendants and made them testify concerning themselves: ‘Am I not your Lord?’ They said: ‘Yes, we testify,’ lest you should say on the Day of Resurrection, ‘Indeed, we were unaware of this,’ or lest you should say, ‘It was only our forefathers who associated others with Allah before us, and we were merely descendants after them. Will You then destroy us for what the falsifiers did?’” [Sūrat al-Aʿrāf 7:172–173] He said: On that day, Allah gathered for Adam all those who would descend from him until the Day of Resurrection. He made them spirits, then gave them form, then caused them to speak, and they spoke. He took from them the covenant and the solemn pledge: “And He made them testify concerning themselves: ‘Am I not your Lord?’ They said: ‘Yes, we testify,’ lest you should say on the Day of Resurrection, ‘Indeed, we were unaware of this,’ or lest you should say, ‘It was only our forefathers who associated others with Allah before us, and we were merely descendants after them. Will You then destroy us for what the falsifiers did?’” He said: “Indeed, I call the seven heavens and the seven earths as witnesses against you, and I call your father Adam as a witness against you, lest you say on the Day of Resurrection: ‘We did not know of this.’ Know that there is no deity other than Me and no Lord other than Me. Do not associate anything with Me. I will surely send messengers to you who will remind you of My covenant and My pledge, and I will send down My Books to you.” They said: “We testify that You are our Lord and our God. We have no lord other than You and no deity other than You.” Thus, on that day they acknowledged obedience to Him. Their father Adam was raised before them. He saw among them the rich and the poor, those of beautiful appearance and those of lesser appearance. He asked: “My Lord, why did You not make Your servants equal?” Allah said: “I desired to be thanked.” Adam saw among them the prophets, like lamps with light upon them. They were distinguished by an additional covenant concerning messengership and prophethood. This is what Allah Most High says: “And when We took from the prophets their covenant, and from you, and from Noah, Abraham, Moses, and Jesus son of Mary; and We took from them a solemn covenant.” [Sūrat al-Aḥzāb 33:7] And it is what He says: “So set your face toward the religion, inclining to truth — the natural disposition of Allah upon which He created mankind. There is no changing the creation of Allah.” [Sūrat al-Rūm 30:30] And concerning this He said: “This is a warner from the former warners.” [Sūrat al-Najm 53:56] And concerning this He said: “We did not find in most of them any covenant; indeed, We found most of them defiantly disobedient.” [Sūrat al-Aʿrāf 7:102]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي حاتم في تفسيره (8537)، وابن جرير الطبري في تفسيره (3278)."},{"num":212,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَأْتِي الشَّيْطَانُ أَحَدَكُمْ، فَيَقُولُ: مَنْ خَلَقَ كَذَا؟ مَنْ خَلَقَ كَذَا؟ حَتَّى، يَقُولَ: مَنْ خَلَقَ رَبَّكَ؟ فَإِذَا بَلَغَهُ فَلْيَسْتَعِذْ بِاللَّهِ وَلْيَنْتَهِ.","وَفِي رِوَايَةٍ: فَلْيَقُلْ: آمَنْتُ بِاللَّهِ."],"takhrij":"متفق عليه: رواه البخاريّ في بدء الخلق (3276)، ومسلم في الإيمان (134) كلاهما من حديث اللّيث بن سعد، قال: حدثني عُقيل بن خالد، قال: قال ابن شهاب، أخبرني عروة بن الزبير، قال: قال أبو هريرة (فذكر الحديث)، واللّفظ للبخاريّ.","grade":"متفق عليه","chapter_ar":"باب ما جاء في رد الوسوسة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3276) and Muslim (134/214), with the wording of al-Bukhārī.","chapter_en":"What Has Been Reported Concerning Repelling Whisperings","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Satan comes to one of you and asks: ‘Who created this? Who created that?’ until he says: ‘Who created your Lord?’ When he reaches that point, let him seek refuge in Allah and stop.” In another narration:","“Let him say: ‘I believe in Allah.’”"]},"buhuth":{"en":["The second wording is narrated by Muslim.","Muslim also narrated:","“People will continue asking you concerning knowledge until they say:","‘Allah created us, so who created Allah?’”","Abū Hurayrah said this while holding the hand of a man and then said:","“Allah and His Messenger spoke the truth. Two people have already asked me this, and this is the third.”","Or he said:","“One person asked me this, and this is the second.”","In another narration, Abū Hurayrah said:","The Messenger of Allah ﷺ said to me:","“They will continue asking you, O Abū Hurayrah, until they say:","‘This is Allah — so who created Allah?’”","Abū Hurayrah said:","While I was in the mosque, some Bedouins came to me and said:","“O Abū Hurayrah, this is Allah — so who created Allah?”","He took some pebbles in his hand and threw them toward them, saying:","“Leave! Leave! My beloved companion spoke the truth.”","In another narration, the Messenger of Allah ﷺ said:","“They will continue asking until it is said:","‘Allah created us, so who created Allah, Mighty and Majestic?’”","Abū Hurayrah said:","By Allah, one day I was sitting when a man from Iraq said to me:","“Allah created us, so who created Allah, Mighty and Majestic?”","I put my finger into my ear and cried out:","“Allah and His Messenger spoke the truth:","‘Allah is One. Allah, the Self-Sufficient. He neither begets nor is born, and there is none comparable to Him.’”","Ibn Abī ʿĀṣim narrated it in al-Sunnah (653) and added:","“Then let him spit lightly to his left and seek refuge in Allah from Satan.”"]},"intro":{"ar":["قال الله تعالى:","﴿وَإِمَّا يَنْزَغَنَّكَ مِنَ الشَّيْطَانِ نَزْغٌ فَاسْتَعِذْ بِاللهِ﴾","[الأعراف: ٢٠٠؛ فصلت: ٣٦]","والنزغ والهمز: الوسوسة.","وقوله سبحانه حاكياً عن يوسف عليه السلام:","﴿مِنْ بَعْدِ أَنْ نَزَغَ الشَّيْطَانُ بَيْنِي وَبَيْنَ إِخْوَتِي﴾","[يوسف: ١٠٠]","أي: أفسد وأغرى.","وقوله تعالى:","﴿قُلْ أَعُوذُ بِرَبِّ النَّاسِ ۝ مَلِكِ النَّاسِ ۝ إِلَهِ النَّاسِ ۝ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ۝ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ۝ مِنَ الْجِنَّةِ وَالنَّاسِ﴾","[الناس: ١–٦]","والخناس هو الشيطان؛ يوسوس في صدر المرء، فإذا ذكر الله خنس، أي: انقبض وتأخر."],"en":["Allah Most High said:","“If a prompting from Satan provokes you, then seek refuge in Allah.”","[Sūrat al-Aʿrāf 7:200; Sūrat Fuṣṣilat 41:36]","The words al-nazgh and al-hamz refer to whispering and prompting.","Allah, Glorified is He, said while relating the words of Yūsuf, peace be upon him:","“After Satan had stirred up discord between me and my brothers.”","[Sūrat Yūsuf 12:100]","That is, Satan corrupted matters between them and incited them.","Allah Most High also said:","“Say: I seek refuge in the Lord of mankind, the King of mankind, the God of mankind, from the evil of the whisperer who withdraws, who whispers into the breasts of mankind, from among jinn and mankind.”","[Sūrat al-Nās 114:1–6]","Al-khannās is Satan. He whispers into a person’s chest, but when Allah is remembered he withdraws — that is, he recoils and retreats."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3276)، ومسلم (134/214)، واللفظ للبخاري."},{"num":213,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَنْ يَبْرَحَ النَّاسُ يَتَسَاءَلُونَ حَتَّى يَقُولُوا هَذَا اللَّهُ خَالِقُ كُلِّ شَيْءٍ فَمَنْ خَلَقَ اللَّهَ؟."],"takhrij":"متفق عليه: رواه البخاريّ في الاعتصام بالكتاب والسنة (7296) عن الحسن ابن صبّاح، حدثنا شبابة، حدثنا ورقاءُ، عن عبدالله بن عبدالرحمن، سمعت أنس بن مالك، يقول: فذكره. ورواه مسلم في الإيمان (136) من وجه آخر عن مختار بن فُلْفُل، عن أنس، عن رسول الله صلى الله عليه وسلم قال: قال الله عزّ وجلّ: إنّ أمّتَك لا يزالون يقولون: ما كذا؟ ما كذا؟ حتى يقولوا: هذا اللهُ خلق الخلقَ، فمن خلق الله؟. وفي رواية لم يذكر: قال الله: إنّ أمّتك.","grade":"متفق عليه","chapter_ar":"باب ما جاء في رد الوسوسة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7296), whose wording is cited here, and Muslim (136).","chapter_en":"What Has Been Reported Concerning Repelling Whisperings","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Mālik may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “People will not cease questioning until they say: ‘Allah is the Creator of everything, so who created Allah?’”"]},"buhuth":{"ar":["وفي رواية مسلم:","«قال الله عز وجل: إن أمتك لا يزالون يقولون: ما كذا؟ ما كذا؟ حتى يقولوا: هذا الله خلق الخلق، فمن خلق الله؟»"],"en":["In Muslim’s wording:","“Allah, Mighty and Majestic, said:","‘Your Ummah will continue saying: What about this? What about that? until they say: Allah created creation, so who created Allah?’”"]}},"tuhfa":{},"full":1,"rep":[8190],"tks":"متفق عليه: رواه البخاري (7296) واللفظ له، ومسلم (136)."},{"num":214,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ أَحَدَكُمْ يَأْتِيهِ الشَّيْطَانُ فَيَقُولُ: مَنْ خَلَقَكَ؟ فَيَقُولُ: اللَّهُ، فَيَقُولُ: فَمَنْ خَلَقَ اللَّهَ؟ فَإِذَا وَجَدَ ذَلِكَ أَحَدُكُمْ فَلْيَقْرَأْ: آمَنْتُ بِاللَّهِ وَرُسُلِهِ، فَإِنَّ ذَلِكَ يُذْهِبُ عَنْهُ."],"takhrij":"صحيح: رواه الإمام أحمد (26203)، والبزّار- كشف الأستار (50)، ، وأبو يعلى (4704) كلّهم من حديث هشام بن عروة، عن أبيه، عن عائشة.","grade":"صحيح","chapter_ar":"باب ما جاء في رد الوسوسة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Imām Aḥmad (26203), al-Bazzār in Kashf al-Astār (50), and Abū Yaʿlā (4704).","chapter_en":"What Has Been Reported Concerning Repelling Whisperings","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["ʿĀʾishah may Allah be pleased with her reported that the Messenger of Allah ﷺ said: “Satan comes to one of you and asks: ‘Who created you?’ He replies: ‘Allah.’ Satan then asks: ‘Who created Allah?’ If one of you experiences this, let him say: ‘I believe in Allah and His messengers,’ for that will cause it to leave him.”"]},"buhuth":{"en":["Ibn Ḥibbān (150) also authenticated it with the wording:","“Satan will not cease coming to one of you and asking:","‘Who created the heavens and the earth?’","He replies:","‘Allah.’","He asks:","‘Who created you?’","He replies:","‘Allah.’","Then he asks:","‘Who created Allah?’","If one of you senses this…”","and he mentioned the remainder of the ḥadīth."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (26203)، والبزار في كشف الأستار (50)، وأبو يعلى (4704)."},{"num":215,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ اللَّهَ تَجَاوَزَ عَنْ أُمَّتِي مَا حَدَّثَتْ بِهِ أَنْفُسَهَا مَا لَمْ تَعْمَلْ أَوْ تَتَكَلَّمْ. قَالَ قَتَادَةُ: إِذَا طَلَّقَ فِي نَفْسِهِ، فَلَيْسَ بِشَيْءٍ."],"takhrij":"متفق عليه: رواه البخاريّ في الطّلاق (5269)، ومسلم في الإيمان (127) كلاهما من طريق هشام، حدثنا قتادة، عن زرارة بن أوفى، عن أبي هريرة، فذكره، ولفظهما سواء إلاّ أنّ مسلماً لم يذكر قولَ قتادة.","grade":"متفق عليه","chapter_ar":"باب ما جاء في رد الوسوسة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5269) and Muslim (127).","chapter_en":"What Has Been Reported Concerning Repelling Whisperings","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Prophet ﷺ said: “Allah has pardoned my Ummah for what their souls whisper to them, so long as they neither act upon it nor speak it.” Qatādah said: “If a man divorces his wife only within his own mind, it counts as nothing.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5269)، ومسلم (127)."},{"num":216,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: نَحْنُ أَحَقُّ بِالشَّكِّ مِنْ إِبْرَاهِيمَ إِذْ قَالَ:﴿رَبِّ أَرِنِي كَيْفَ تُحْيِ الْمَوْتَى قَالَ أَوَلَمْ تُؤْمِنْ قَالَ بَلَى وَلَكِنْ لِّيَطْمَئِنَّ قَلْبِي﴾ [سورة البقرة: 260]، وَيَرْحَمُ اللَّهُ لُوطًا لَقَدْ كَانَ يَأْوِي إِلَى رُكْنٍ شَدِيدٍ وَلَوْ لَبِثْتُ فِي السِّجْنِ طُولَ مَا لَبِثَ يُوسُفُ لَأَجَبْتُ الدَّاعِيَ."],"takhrij":"متفق عليه: رواه البخاريّ في الأنبياء (3372)، ومسلم في الفضائل (2370: 152) كلاهما من حديث ابن وهب، قال: أخبرني يونس، عن ابن شهاب، عن أبي سلمة بن عبدالرحمن، وسعيد بن المسيب، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في رد الوسوسة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Anbiyāʾ (3372) and Muslim in al-Faḍāʾil (2370:152).","chapter_en":"What Has Been Reported Concerning Repelling Whisperings","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “We have more right to doubt than Ibrāhīm when he said: ‘My Lord, show me how You give life to the dead.’ He said, ‘Do you not believe?’ He replied, ‘Yes, but so that my heart may be reassured.’ [Sūrat al-Baqarah 2:260] May Allah have mercy upon Lūṭ; indeed, he used to seek refuge in a strong support. And if I had remained in prison for as long as Yūsuf remained, I would have answered the caller.”"]},"buhuth":{"en":["The words:","“I would have answered the caller”","mean that he would have hastened to respond to the invitation to leave the prison."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3372)، ومسلم (2370: 152)."},{"num":217,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: جَاءَ نَاسٌ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَأَلُوهُ: إِنَّا نَجِدُ فِي أَنْفُسِنَا مَا يَتَعَاظَمُ أَحَدُنَا أَنْ يَتَكَلَّمَ بِهِ، قَالَ: وَقَدْ وَجَدْتُمُوهُ؟ قَالُوا: نَعَمْ، قَالَ: ذَاكَ صَرِيحُ الإِيمَانِ."],"takhrij":"صحيح: رواه مسلم في الإيمان (132) عن زهير بن حرب، حدثنا جرير، عن سُهيل بن أبي صالح، عن أبيه، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب أن الوسوسة من صريح الإيمان","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (132).","chapter_en":"Whisperings and the Presence of Genuine Faith","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported: Some of the Companions of the Prophet ﷺ came to him and said: “We find within ourselves thoughts that one of us considers too terrible even to speak of.” He asked: “Have you really experienced that?” They replied: “Yes.” He said: “That is genuine faith.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (132)."},{"num":218,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَ: سُئِلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْوَسْوَسَةِ، قَالَ: تِلْكَ مَحْضُ الإِيمَانِ."],"takhrij":"صحيح: رواه مسلم في الإيمان (133) عن يوسف بن يعقوب الصفّار، حدّثني علي بن عثّام، عن سُعير بن الخِمْس، عن مغيرة بن مقسم، عن إبراهيم، عن علقمة، عن عبدالله، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب أن الوسوسة من صريح الإيمان","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (133).","chapter_en":"Whisperings and the Presence of Genuine Faith","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd, may Allah be pleased with him, reported: The Prophet ﷺ was asked about intrusive whisperings, and he said: “That is pure faith.”"]},"buhuth":{"en":["Al-Khaṭṭābī said:","The meaning of the words:","“Genuine faith”","is that genuine faith is what prevents you from accepting what Satan casts into your souls and from believing it.","It does not mean that the whispering itself is genuine faith, because such whisperings arise from Satan’s actions and enticement. How, then, could the whispering itself be genuine faith?","It has also been narrated in another ḥadīth that when they complained to the Prophet ﷺ about this, he said:","“Praise be to Allah who reduced his plotting to mere whispering.”","This is the ḥadīth of Ibn ʿAbbās that follows."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (133)."},{"num":219,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ إِنَّ أَحَدَنَا يَجِدُ فِي نَفْسِهِ يُعَرِّضُ بِالشَّيْءِ لَأَنْ يَكُونَ حُمَمَةً أَحَبُّ إِلَيْهِ مِنْ أَنْ يَتَكَلَّمَ بِهِ، فَقَالَ: اللَّهُ أَكْبَرُ! اللَّهُ أَكْبَرُ! اللَّهُ أَكْبَرُ! الْحَمْدُ لِلَّهِ الَّذِي رَدَّ كَيْدَهُ إِلَى الْوَسْوَسَةِ."],"takhrij":"صحيح: رواه أبو داود (5112) عن عثمان بن أبي شيبة، وابن قدامة بن أعين، قالا: حدثنا جرير، عن منصور، عن ذرّ، عن عبدالله بن شدّاد، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب أن الوسوسة من صريح الإيمان","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (5112).","chapter_en":"Whisperings and the Presence of Genuine Faith","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿAbbās, may Allah be pleased with them, reported: A man came to the Prophet ﷺ and said: “O Messenger of Allah, one of us finds something within himself” — alluding to a terrible thought — “such that he would rather become a piece of burning charcoal than speak of it.” The Prophet ﷺ said: “Allāhu akbar! Allāhu akbar! Allāhu akbar! Praise be to Allah who has reduced Satan’s plotting to mere whispering.”"]},"buhuth":{"en":["The words:","“Praise be to Allah who has reduced his plotting…”","mean that Satan’s plotting has been confined to whisperings for which a person is not held accountable. Satan was not given power to compel the person beyond whispering; otherwise, he would have pursued him beyond whisperings just as he pursues him through them.","Rather, whether such thoughts are spoken has been placed within the person’s own control, and for this reason he refrains from speaking them.","This was explained by al-Sindī."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (5112)."},{"num":220,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَمْ يَكْذِبْ إِبْرَاهِيمُ النَّبِيُّ عَلَيْهِ السَّلَام قَطُّ، إِلَّا ثَلَاثَ كَذَبَاتٍ، ثِنْتَيْنِ فِي ذَاتِ اللَّهِ، قَوْلُهُ ﴿إِنِّي سَقِيمٌ﴾ [الصّافات: 89]، وَقَوْلُهُ:﴿بَلْ فَعَلَهُ كَبِيرُهُمْ هَذَا﴾ [سورة الأنبياء: 63]، وَوَاحِدَةٌ فِي شَأْنِ سَارَةَ: إِنَّكِ أُخْتِي...(وَذَكَرَ الْحَدِيثَ)."],"takhrij":"متفق عليه: رواه البخاريّ في كتاب الأنبياء (3358)، ومسلم في الفضائل (2371) كلاهما من حديث أيوب السختياني، عن محمد بن سيرين، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما ذكر في الذات","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3358) and Muslim (2371).","chapter_en":"What Has Been Mentioned Concerning the Essence","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Ibrāhīm never spoke anything described as a lie except on three occasions: two concerning the cause of Allah — his statement: ‘Indeed, I am ill.’ [Sūrat al-Ṣāffāt 37:89] and his statement: ‘Rather, this largest one of them did it.’ [Sūrat al-Anbiyāʾ 21:63] and one concerning Sārah, when he said to her: ‘You are my sister.’” Then he mentioned the remainder of the ḥadīth."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3358)، ومسلم (2371)."},{"num":221,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: بَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَشَرَةً مِنْهُمْ خُبَيْبٌ الْأَنْصَارِيُّ، فَأَخْبَرَنِي عُبَيْدُ اللَّهِ بْنُ عِيَاضٍ، أَنَّ ابْنَةَ الْحَارِثِ أَخْبَرَتْهُ، أَنَّهُمْ حِينَ اجْتَمَعُوا اسْتَعَارَ مِنْهَا مُوسَى يَسْتَحِدُّ بِهَا، فَلَمَّا خَرَجُوا مِنَ الْحَرَمِ لِيَقْتُلُوهُ قَالَ خُبَيْبٌ الْأَنْصَارِيُّ:","وَلَسْتُ أُبَالِي حِينَ أُقْتَلُ مُسْلِمًا.","عَلَى أَيِّ شِقٍّ كَانَ لِلَّهِ مَصْرَعِي.","وَذَلِكَ فِي ذَاتِ الْإِلَهِ وَإِنْ يَشَأْ.","يُبَارِكْ عَلَى أَوْصَالِ شِلْوٍ مُمَزَّعِ.","فَقَتَلَهُ ابْنُ الْحَارِثِ، فَأَخْبَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَصْحَابَهُ خَبَرَهُمْ يَوْمَ أُصِيبُوا."],"takhrij":"صحيح: رواه البخاريّ في التوحيد (7402) وبوّب عليه: ما يُذكر في الذّات والنّعوت وأسامي الله عزّ وجلّ، عن أبي اليمان، أخبرنا شعيب، عن الزّهريّ، أخبرني عمرو بن أبي سفيان بن أسيد بن خارجة الثّقفيّ حليف لبني زهرة وكان من أصحاب أبي هريرة، أنّ أبا هريرة قال (فذكره).","grade":"صحيح","chapter_ar":"باب ما ذكر في الذات","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (7402).","chapter_en":"What Has Been Mentioned Concerning the Essence","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported: The Messenger of Allah ﷺ sent out ten men, among them Khubayb al-Anṣārī. ʿUbaydullāh ibn ʿIyāḍ informed me that the daughter of al-Ḥārith told him that when they gathered together, Khubayb borrowed a razor from her with which to shave. When they took him outside the Sacred Precinct to kill him, Khubayb al-Anṣārī said: “I do not care, when I am killed as a Muslim,","upon which side I fall, so long as my death is for Allah.","That is for the sake of the Divine; and if He wills,","He will bless the limbs of a body torn apart.”","Ibn al-Ḥārith then killed him, and the Prophet ﷺ informed his Companions of what had happened to them on the very day they were killed."]},"buhuth":{"en":["(Commentary and note in the text)","We have been commanded to reflect and to use careful consideration regarding the creation of Allah. Allah, Glorified and Exalted, has praised those who reflect upon the creation of the heavens and the earth, saying: “Indeed, in the creation of the heavens and the earth and the alternation of night and day are signs for people of understanding—those who remember Allah while standing, sitting, and on their sides, and reflect on the creation of the heavens and the earth: ‘Our Lord, You did not create this without purpose. Glory be to You, so protect us from the punishment of the Fire.’” [Āl ʿImrān 3:190–191].","Allah has also condemned those who do not reflect upon His creation, saying: “Have they not traveled through the earth and observed how was the end of those before them? They were stronger than them in power…” [Ghāfir 40:21].","We have been forbidden from trying to reflect upon the Essence of Allah Most High, because the reality of His Essence cannot be grasped by reflection, no matter how much we attempt it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (7402)."},{"num":222,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ أَنَّ مُعَاذًا قَالَ: بَعَثَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الْيَمَنِ قَالَ: إِنَّكَ تَأْتِي قَوْمًا مِنْ أَهْلِ الْكِتَابِ، فَادْعُهُمْ إِلَى شَهَادَةِ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي رَسُولُ اللَّهِ، فَإِنْ هُمْ أَطَاعُوا لِذَلِكَ، فَأَعْلِمْهُمْ أَنَّ اللَّهَ افْتَرَضَ عَلَيْهِمْ خَمْسَ صَلَوَاتٍ فِي كُلِّ يَوْمٍ وَلَيْلَةٍ، فَإِنْ هُمْ أَطَاعُوا لِذَلِكَ، فَأَعْلِمْهُمْ أَنَّ اللَّهَ افْتَرَضَ عَلَيْهِمْ صَدَقَةً، تُؤْخَذُ مِنْ أَغْنِيَائِهِمْ، فَتُرَدُّ فِي فُقَرَائِهِمْ، فَإِنْ هُمْ أَطَاعُوا لِذَلِكَ، فَإِيَّاكَ وَكَرَائِمَ أَمْوَالِهِمْ، وَاتَّقِ دَعْوَةَ الْمَظْلُومِ فَإِنَّهُ لَيْسَ بَيْنَهَا وَبَيْنَ اللَّهِ حِجَابٌ."],"takhrij":"متفق عليه: رواه البخاريّ في الزّكاة (1496)، ومسلم في الإيمان (19) كلاهما من طريق زكريا بن إسحاق، عن يحيى بن عبدالله بن صيفيّ، عن أبي معبد مولى ابن عباس، عن ابن عباس، فذكره، ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب ما جاء من الدعوة إلى توحيد الإلهية","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1496) and Muslim (19).","chapter_en":"What Has Been Reported Concerning the Call to the Oneness of Worship","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿAbbās may Allah be pleased with them reported that Muʿādh, may Allah be pleased with him, said: The Messenger of Allah ﷺ sent me to Yemen and said: “You are going to a people from the People of the Book. Call them to testify that there is no deity worthy of worship except Allah and that I am the Messenger of Allah. If they obey you in that, inform them that Allah has made five prayers obligatory upon them during every day and night. If they obey you in that, inform them that Allah has made obligatory upon them a charity to be taken from their wealthy and returned to their poor. If they obey you in that, beware of taking the finest of their wealth, and fear the supplication of the oppressed, for there is no barrier between it and Allah.”"]},"intro":{"ar":["قال الله تعالى:","﴿وَاعْبُدُوا اللهَ وَلَا تُشْرِكُوا بِهِ شَيْئًا﴾","[النساء: ٣٦]","وقال تعالى:","﴿يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ وَالَّذِينَ مِنْ قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ﴾","[البقرة: ٢١]","وقال تعالى:","﴿وَمَا خَلَقْتُ الْجِنَّ وَالْإِنْسَ إِلَّا لِيَعْبُدُونِ﴾","[الذاريات: ٥٦]","وغيرها من الآيات، وهي كثيرة في كتاب الله؛ لأن دعوة الأنبياء عليهم السلام كانت لتوحيد الإلهية.","قال شيخ الإسلام ابن تيمية رحمه الله تعالى:","«إن عامة المتكلمين الذين يقررون التوحيد في كتب الكلام والنظر، غايتهم أن يجعلوا التوحيد ثلاثة أنواع، فيقولون: هو واحد في ذاته لا قسيم له، وواحد في صفاته لا شبيه له، وواحد في أفعاله لا شريك له.","وأشهر الأنواع الثلاثة عندهم هو الثالث، وهو توحيد الأفعال، وهو أن خالق العالم واحد. وهم يحتجون على ذلك بما يذكرونه من دلالة التمانع وغيرها، ويظنون أن هذا هو التوحيد المطلوب، وأن هذا هو معنى قولنا: لا إله إلا الله، حتى يجعلوا معنى الإلهية القدرة على الاختراع.","ومعلوم أن المشركين من العرب الذين بُعث إليهم محمد ﷺ أولاً لم يكونوا يخالفونه في هذا، بل كانوا يقرون بأن الله خالق كل شيء، حتى إنهم كانوا يقرون بالقدر أيضاً، وهم مع هذا مشركون».","مجموع الفتاوى (٣/٩٨)."],"en":["Allah Most High said:","“Worship Allah and do not associate anything with Him.”","[Sūrat al-Nisāʾ 4:36]","And He said:","“O mankind, worship your Lord who created you and those before you, so that you may become mindful of Him.”","[Sūrat al-Baqarah 2:21]","And He said:","“I did not create the jinn and mankind except to worship Me.”","[Sūrat al-Dhāriyāt 51:56]","There are many other verses of this kind in the Book of Allah, because the call of the prophets عليهم السلام was to the oneness of worship.","Shaykh al-Islām Ibn Taymiyyah, may Allah have mercy on him, said:","“Most of the theologians who establish tawḥīd in works of speculative theology and rational inquiry ultimately divide it into three types. They say: He is One in His essence with no division or counterpart; One in His attributes with no likeness; and One in His actions with no partner.","The best known of these three types among them is the third: oneness in actions, meaning that the Creator of the universe is One. They argue for this through what they call the proof of mutual hindrance and similar arguments. They imagine that this is the tawḥīd being sought and that this is the meaning of our statement, ‘There is no deity worthy of worship except Allah,’ until they interpret divinity as merely the power to create and originate.","Yet it is well known that the Arab polytheists to whom Muḥammad ﷺ was initially sent did not dispute this point. Rather, they acknowledged that Allah is the Creator of everything. They even acknowledged divine decree, yet despite this they remained polytheists.”","Majmūʿ al-Fatāwā (3/98)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1496)، ومسلم (19)."},{"num":223,"demo":false,"sanad":"","matn":["عَنْ طَارِقِ بْنِ أَشْيَمِ الْأَشْجَعِيِّ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: مَنْ قَالَ: لَا إِلَهَ إِلَّا اللَّهُ، وَكَفَرَ بِمَا يُعْبَدُ مِنْ دُونِ اللَّهِ، حَرُمَ مَالُهُ، وَدَمُهُ، وَحِسَابُهُ عَلَى اللَّهِ."],"takhrij":"صحيح: رواه مسلم في الإيمان (23) من طرق عن مروان بن معاوية الفزاريّ وغيره، عن أبي مالك سعد بن طارق الأشجعيّ، عن أبيه طارق بن أشيم الأشجعيّ، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء من الدعوة إلى توحيد الإلهية","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (23).","chapter_en":"What Has Been Reported Concerning the Call to the Oneness of Worship","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Ṭāriq ibn Ashyam al-Ashjaʿī, may Allah be pleased with him, reported: I heard the Messenger of Allah ﷺ say: “Whoever says, ‘There is no deity worthy of worship except Allah,’ and rejects whatever is worshipped besides Allah, his wealth and blood become inviolable, and his reckoning is with Allah.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (23)."},{"num":224,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ سَلَّامٍ أَنَّ أَبَا سَلَّامٍ حَدَّثَهُ، أَنَّ الْحَارِثَ الْأَشْعَرِيَّ حَدَّثَهُ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ اللَّهَ أَمَرَ يَحْيَى بْنَ زَكَرِيَّا بِخَمْسِ كَلِمَاتٍ أَنْ يَعْمَلَ بِهَا، وَيَأْمُرَ بَنِي إِسْرَائِيلَ، أَنْ يَعْمَلُوا بِهَا، وَإِنَّهُ كَادَ أَنْ يُبْطِئَ بِهَا، فَقَالَ عِيسَى: إِنَّ اللَّهَ أَمَرَكَ بِخَمْسِ كَلِمَاتٍ لِتَعْمَلَ بِهَا وَتَأْمُرَ بَنِي إِسْرَائِيلَ، أَنْ يَعْمَلُوا بِهَا، فَإِمَّا أَنْ تَأْمُرَهُمْ وَإِمَّا أَنْ آمُرَهُمْ، فَقَالَ يَحْيَى: أَخْشَى إِنْ سَبَقْتَنِي بِهَا أَنْ يُخْسَفَ بِي أَوْ أُعَذَّبَ، فَجَمَعَ النَّاسَ فِي بَيْتِ الْمَقْدِسِ فَامْتَلَأَ الْمَسْجِدُ وَقَعَدُوا عَلَى الشُّرَفِ، فَقَالَ: إِنَّ اللَّهَ أَمَرَنِي بِخَمْسِ كَلِمَاتٍ أَنْ أَعْمَلَ بِهِنَّ وَآمُرَكُمْ أَنْ تَعْمَلُوا بِهِنَّ.","أَوَّلُهُنَّ: أَنْ تَعْبُدُوا اللَّهَ وَلَا تُشْرِكُوا بِهِ شَيْئًا، وَإِنَّ مَثَلَ مَنْ أَشْرَكَ بِاللَّهِ كَمَثَلِ رَجُلٍ اشْتَرَى عَبْدًا مِنْ خَالِصِ مَالِهِ بِذَهَبٍ أَوْ وَرِقٍ، فَقَالَ: هَذِهِ دَارِي، وَهَذَا عَمَلِي فَاعْمَلْ وَأَدِّ إِلَيَّ، فَكَانَ يَعْمَلُ وَيُؤَدِّي إِلَى غَيْرِ سَيِّدِهِ، فَأَيُّكُمْ يَرْضَى أَنْ يَكُونَ عَبْدُهُ كَذَلِكَ؟","وَإِنَّ اللَّهَ أَمَرَكُمْ بِالصَّلَاةِ فَإِذَا صَلَّيْتُمْ فَلَا تَلْتَفِتُوا، فَإِنَّ اللَّهَ يَنْصِبُ وَجْهَهُ لِوَجْهِ عَبْدِهِ فِي صَلَاتِهِ مَا لَمْ يَلْتَفِتْ.","وَآمُرُكُمْ بِالصِّيَامِ، فَإِنَّ مَثَلَ ذَلِكَ كَمَثَلِ رَجُلٍ فِي عِصَابَةٍ، مَعَهُ صُرَّةٌ فِيهَا مِسْكٌ، فَكُلُّهُمْ يَعْجَبُ، أَوْ يُعْجِبُهُ رِيحُهَا، وَإِنَّ رِيحَ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ.","وَآمُرُكُمْ بِالصَّدَقَةِ فَإِنَّ مَثَلَ ذَلِكَ كَمَثَلِ رَجُلٍ أَسَرَهُ الْعَدُوُّ، فَأَوْثَقُوا يَدَهُ إِلَى عُنُقِهِ وَقَدَّمُوهُ لِيَضْرِبُوا عُنُقَهُ، فَقَالَ: أَنَا أَفْدِيهِ مِنْكُمْ بِالْقَلِيلِ وَالْكَثِيرِ فَفَدَى نَفْسَهُ مِنْهُمْ.","وَآمُرُكُمْ أَنْ تَذْكُرُوا اللَّهَ، فَإِنَّ مَثَلَ ذَلِكَ كَمَثَلِ رَجُلٍ خَرَجَ الْعَدُوُّ فِي أَثَرِهِ سِرَاعًا حَتَّى إِذَا أَتَى عَلَى حِصْنٍ حَصِينٍ فَأَحْرَزَ نَفْسَهُ مِنْهُمْ، كَذَلِكَ الْعَبْدُ لَا يُحْرِزُ نَفْسَهُ مِنَ الشَّيْطَانِ إِلَّا بِذِكْرِ اللَّهِ.","قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَأَنَا آمُرُكُمْ بِخَمْسٍ اللَّهُ أَمَرَنِي بِهِنَّ: السَّمْعُ، وَالطَّاعَةُ، وَالْجِهَادُ، وَالْهِجْرَةُ، وَالْجَمَاعَةُ، فَإِنَّهُ مَنْ فَارَقَ الْجَمَاعَةَ قِيدَ شِبْرٍ فَقَدْ خَلَعَ رِبْقَةَ الْإِسْلَامِ مِنْ عُنُقِهِ إِلَّا أَنْ يَرْجِعَ، وَمَنِ ادَّعَى دَعْوَى الْجَاهِلِيَّةِ فَإِنَّهُ مِنْ جُثَا جَهَنَّمَ، فَقَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ، وَإِنْ صَلَّى وَصَامَ؟ قَالَ: وَإِنْ صَلَّى وَصَامَ، فَادْعُوا بِدَعْوَى اللَّهِ الَّذِي سَمَّاكُمُ الْمُسْلِمِينَ الْمُؤْمِنِينَ عِبَادَ اللَّهِ."],"takhrij":"صحيح: رواه الترمذيّ (2863) عن محمد بن إسماعيل (البخاريّ) حدثنا موسى بن إسماعيل، حدثنا أبان بن يزيد، حدثنا يحيى بن أبي كثير، عن زيد بن سلام، أنّ أبا سلاّم، حدّثه، فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء من الدعوة إلى توحيد الإلهية","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Tirmidhī (2863), who said: “Ḥasan Ṣaḥīḥ Gharīb.”","chapter_en":"What Has Been Reported Concerning the Call to the Oneness of Worship","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Zayd ibn Salām reported from Abū Salām, who reported from al-Ḥārith al-Ashʿarī may Allah be pleased with him, that the Prophet ﷺ said: “Allah commanded Yaḥyā ibn Zakariyyā with five commands: that he act upon them and command the Children of Israel to act upon them. He was nearly delayed in carrying them out. ʿĪsā said: ‘Allah has commanded you with five commands so that you act upon them and command the Children of Israel to act upon them. Either you command them, or I will command them.’ Yaḥyā replied: ‘I fear that if you precede me in doing so, I may be swallowed by the earth or punished.’ He gathered the people in Bayt al-Maqdis. The mosque became full, and the people sat upon its elevated places. He said: ‘Allah has commanded me with five commands that I must act upon and command you to act upon. The first is that you worship Allah and do not associate anything with Him. The example of one who associates partners with Allah is like a man who purchased a slave entirely from his own wealth, with gold or silver, and said: “This is my house and this is my work. Work and deliver the proceeds to me.” Yet the slave worked and delivered the proceeds to someone other than his master. Which of you would be pleased for his slave to behave in that manner?","Allah has commanded you to pray. When you pray, do not turn away, for Allah directs His Face toward the face of His servant during his prayer so long as the servant does not turn away.","I command you to fast. Its likeness is that of a man among a group carrying a pouch containing musk, whose fragrance pleases them all — or pleases him. Indeed, the odor of the fasting person is more pleasant to Allah than the fragrance of musk.","I command you to give charity. Its likeness is that of a man captured by an enemy who tied his hands to his neck and brought him forward to strike off his head. He said: “I will ransom myself from you with a little and with much,” until he ransomed himself from them.","And I command you to remember Allah. Its likeness is that of a man whose enemy pursued him swiftly until he reached a strongly fortified fortress and protected himself from them. Likewise, the servant cannot protect himself from Satan except through the remembrance of Allah.’”","The Prophet ﷺ then said:","“And I command you with five things Allah has commanded me with: hearing and obeying, jihād, migration, and adhering to the community. Whoever separates from the community by even a handspan has removed the bond of Islam from his neck unless he returns. And whoever calls with the call of Jāhiliyyah is among the coals of Hell.” A man asked: “O Messenger of Allah, even if he prays and fasts?” He replied: “Even if he prays and fasts. So call yourselves by the designation of Allah, who named you Muslims, believers, and servants of Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (2863)، وقال: «حديث حسن صحيح غريب»."},{"num":225,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُئِلَ: أَيُّ الْعَمَلِ أَفْضَلُ؟ فَقَالَ: إِيمَانٌ بِاللَّهِ وَرَسُولِهِ، قِيلَ: ثُمَّ مَاذَا؟ قَالَ: الْجِهَادُ فِي سَبِيلِ اللَّهِ، قِيلَ: ثُمَّ مَاذَا؟ قَالَ: حَجٌّ مَبْرُورٌ."],"takhrij":"متفق عليه: رواه البخاريّ في الإيمان (26)، ومسلم في الإيمان (83) كلاهما من حديث إبراهيم بن سعد، حدثنا ابن شهاب، عن سعيد بن المسيب، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب أن الإيمان بالله تعالى من أفضل الأعمال","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (26) and Muslim (83).","chapter_en":"Faith in Allah Most High Is Among the Best of Deeds","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported: The Messenger of Allah ﷺ was asked: “Which deed is best?” He replied: “Faith in Allah and His Messenger.” It was asked: “Then what?” He replied: “Jihād in the way of Allah.” It was asked: “Then what?” He replied: “An accepted ḥajj.”"]}},"tuhfa":{},"full":1,"rep":[7724],"tks":"متفق عليه: رواه البخاري (26)، ومسلم (83)."},{"num":226,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ قَالَ: سَأَلْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيُّ الْعَمَلِ أَفْضَلُ؟ قَالَ: إِيمَانٌ بِاللَّهِ وَجِهَادٌ فِي سَبِيلِهِ، قُلْتُ: فَأَيُّ الرِّقَابِ أَفْضَلُ؟ قَالَ: أَغْلَاهَا ثَمَنًا، وَأَنْفَسُهَا عِنْدَ أَهْلِهَا، قُلْتُ: فَإِنْ لَمْ أَفْعَلْ؟ قَالَ: تُعِينُ صَانِعًا أَوْ تَصْنَعُ لِأَخْرَقَ، قَالَ: فَإِنْ لَمْ أَفْعَلْ؟ قَالَ: تَدَعُ النَّاسَ مِنَ الشَّرِّ، فَإِنَّهَا صَدَقَةٌ تَصَدَّقُ بِهَا عَلَى نَفْسِكَ."],"takhrij":"متفق عليه: رواه البخاريّ في العتق (2518)، ومسلم في الإيمان (84) كلاهما من حديث هشام بن عروة، عن أبيه، عن أبي مراوح، عن أبي ذرّ، فذكر الحديث،","grade":"متفق عليه","chapter_ar":"باب أن الإيمان بالله تعالى من أفضل الأعمال","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2518) and Muslim (84), with the wording of al-Bukhārī.","chapter_en":"Faith in Allah Most High Is Among the Best of Deeds","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Abū Dharr, may Allah be pleased with him, reported: I asked the Prophet ﷺ: “Which deed is best?” He replied: “Faith in Allah and jihād in His way.” I asked: “Which slaves are best to free?” He replied: “Those most valuable in price and most precious to their owners.” I asked: “What if I cannot do that?” He replied: “Assist a skilled worker, or work on behalf of one who is unable to work properly.” I asked: “What if I cannot do that?” He replied: “Refrain from harming people, for that is charity which you give on behalf of yourself.”"]},"buhuth":{"en":["In Muslim’s wording:","“Restrain your harm from people, for that is charity from you to yourself.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[6132,13940],"tks":"متفق عليه: رواه البخاري (2518)، ومسلم (84)، واللفظ للبخاري."},{"num":227,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَ: سَأَلْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَيُّ الذَّنْبِ أَعْظَمُ عِنْدَ اللَّهِ؟ قَالَ: أَنْ تَجْعَلَ لِلَّهِ نِدًّا وَهُوَ خَلَقَكَ، قُلْتُ: إِنَّ ذَلِكَ لَعَظِيمٌ، قُلْتُ: ثُمَّ أَيُّ؟ قَالَ: وَأَنْ تَقْتُلَ وَلَدَكَ تَخَافُ أَنْ يَطْعَمَ مَعَكَ، قُلْتُ: ثُمَّ أَيُّ؟ قَالَ: أَنْ تُزَانِيَ حَلِيلَةَ جَارِكَ."],"takhrij":"متفق عليه: رواه البخاريّ في التفسير (4477)، ومسلم في الإيمان (86) كلاهما عن عثمان بن أبي شيبة، حدثنا جرير، عن منصور، عن أبي وائل، عن عمرو بن شرحبيل، عن عبدالله، فذكره، ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب أن الشرك من أعظم الذنوب","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4477) and Muslim (86).","chapter_en":"Associating Partners With Allah Is Among the Greatest Sins","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd, may Allah be pleased with him, reported: I asked the Prophet ﷺ: “Which sin is greatest in the sight of Allah?” He replied: “That you set up a rival alongside Allah even though He created you.” I said: “That is indeed tremendous.” I asked: “Then which?” He replied: “That you kill your child out of fear that he will eat with you.” I asked: “Then which?” He replied: “That you commit adultery with your neighbor’s wife.”"]},"buhuth":{"en":["Al-Bukhārī and Muslim also narrated the report through other routes, and at its conclusion:","Allah, Mighty and Majestic, revealed in confirmation of these words:","“And those who do not invoke another deity alongside Allah, nor kill the soul which Allah has forbidden except with legal right, nor commit unlawful sexual intercourse; and whoever does that will meet a penalty.”","[Sūrat al-Furqān 25:68]"]},"intro":{"ar":["قال الله تعالى:","﴿فَلَا تَجْعَلُوا لِلَّهِ أَنْدَادًا وَأَنْتُمْ تَعْلَمُونَ﴾","[البقرة: ٢٢]"],"en":["Allah Most High said:","“So do not set up rivals to Allah while you know.”","[Sūrat al-Baqarah 2:22]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13002],"tks":"متفق عليه: رواه البخاري (4477)، ومسلم (86)."},{"num":228,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَ: لَمَّا نَزَلَتْ ﴿الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمَانَهُمْ بِظُلْمٍ﴾ [سورة الأنعام: 82] شَقَّ ذَلِكَ عَلَى أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَالُوا: أَيُّنَا لَا يَظْلِمُ نَفْسَهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَيْسَ هُوَ كَمَا تَظُنُّونَ، إِنَّمَا هُوَ كَمَا قَالَ لُقْمَانُ لِابْنِهِ: ﴿وَإِذْ قَالَ لُقْمَانُ لِابْنِهِ وَهُوَ يَعِظُهُ يَا بُنَيَّ لَا تُشْرِكْ بِاللَّهِ إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ﴾ [سورة لقمان: 13]."],"takhrij":"متفق عليه: رواه البخاريّ في أحاديث الأنبياء (3360)، ومسلم في الإيمان (124) كلاهما من حديث الأعمش، عن إبراهيم، عن علقمة، عن عبدالله، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب أن الشرك من أعظم الذنوب","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3360) and Muslim (124).","chapter_en":"Associating Partners With Allah Is Among the Greatest Sins","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd, may Allah be pleased with him, reported: When the verse was revealed: “Those who believe and do not mix their faith with wrongdoing…” [Sūrat al-Anʿām 6:82] this became difficult for the Companions of the Messenger of Allah ﷺ, and they said: “Which of us does not wrong himself?” The Messenger of Allah ﷺ said: “It is not as you think. Rather, it is as Luqmān said to his son: ‘O my son, do not associate anything with Allah. Indeed, shirk is a tremendous wrongdoing.’” [Sūrat Luqmān 31:13]"]},"buhuth":{"en":["Shirk is called wrongdoing because the fundamental meaning of wrongdoing is to place something somewhere it does not belong. Whoever commits shirk assigns a rival to Allah, and this is among the greatest forms of wrongdoing."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3360)، ومسلم (124)."},{"num":229,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرَةَ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَلَا أُنَبِّئُكُمْ بِأَكْبَرِ الْكَبَائِرِ ثَلَاثًا؟ قَالُوا: بَلَى يَا رَسُولَ اللَّهِ، قَالَ: الْإِشْرَاكُ بِاللَّهِ، وَعُقُوقُ الْوَالِدَيْنِ، وَجَلَسَ وَكَانَ مُتَّكِئًا فَقَالَ: أَلَا وَقَوْلُ الزُّورِ، قَالَ: فَمَا زَالَ يُكَرِّرُهَا حَتَّى قُلْنَا لَيْتَهُ سَكَتَ."],"takhrij":"متفق عليه: رواه البخاريّ في الشهادات (2654)، ومسلم في الإيمان (87) كلاهما من طريق سعيد الجريريّ، حدثنا عبدالرحمن بن أبي بكرة، عن أبيه، فذكره.","grade":"متفق عليه","chapter_ar":"باب أن الشرك من أعظم الذنوب","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2654) and Muslim (87).","chapter_en":"Associating Partners With Allah Is Among the Greatest Sins","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Abū Bakrah, may Allah be pleased with him, reported: The Prophet ﷺ said three times: “Shall I not inform you of the greatest of the major sins?” They replied: “Yes, O Messenger of Allah.” He said: “Associating partners with Allah and disobedience to parents.” He then sat upright after having been reclining and said: “And indeed, false speech.” He continued repeating it until we said: “If only he would stop.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12795,14298],"tks":"متفق عليه: رواه البخاري (2654)، ومسلم (87)."},{"num":230,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: اجْتَنِبُوا السَّبْعَ الْمُوبِقَاتِ، قَالُوا: يَا رَسُولَ اللَّهِ وَمَا هُنَّ؟ قَالَ: الشِّرْكُ بِاللَّهِ، وَالسِّحْرُ، وَقَتْلُ النَّفْسِ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ، وَأَكْلُ الرِّبَا، وَأَكْلُ مَالِ الْيَتِيمِ، وَالتَّوَلِّي يَوْمَ الزَّحْفِ، وَقَذْفُ الْمُحْصَنَاتِ الْمُؤْمِنَاتِ الْغَافِلَاتِ."],"takhrij":"متفق عليه: رواه البخاريّ في الوصايا (2766)، ومسلم في الإيمان (89) كلاهما من طريق سليمان بن بلال، عن ثور بن زيد المدنيّ، عن أبي الغيب، عن أبي هريرة.","grade":"متفق عليه","chapter_ar":"باب أن الشرك من أعظم الذنوب","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2766) and Muslim (89).","chapter_en":"Associating Partners With Allah Is Among the Greatest Sins","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Prophet ﷺ said: “Avoid the seven destructive sins.” They asked: “O Messenger of Allah, what are they?” He replied: “Associating partners with Allah, sorcery, killing a soul whom Allah has forbidden to be killed except with legal right, consuming usury, consuming the wealth of an orphan, fleeing on the day of battle, and falsely accusing chaste, believing, unsuspecting women of unlawful sexual intercourse.”"]}},"tuhfa":{},"full":1,"rep":[5690,6809,7001,7897,11517,12142,12362,12859],"tks":"متفق عليه: رواه البخاري (2766)، ومسلم (89)."},{"num":231,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو قَالَ: جَاءَ أَعْرَابِيٌّ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ مَا الْكَبَائِرُ ؟ قَالَ: الْإِشْرَاكُ بِاللَّهِ، قَالَ: ثُمَّ مَاذَا؟ قَالَ: ثُمَّ عُقُوقُ الْوَالِدَيْنِ، قَالَ: ثُمَّ مَاذَا؟ قَالَ: الْيَمِينُ الْغَمُوسُ، قُلْتُ: وَمَا الْيَمِينُ الْغَمُوسُ؟ قَالَ: الَّذِي يَقْتَطِعُ مَالَ امْرِئٍ مُسْلِمٍ هُوَ فِيهَا كَاذِبٌ."],"takhrij":"صحيح: رواه البخاريّ في استتابة المرتدين (6920) عن محمد بن الحسين بن إبراهيم، أخبرنا عبيد الله، أخبرنا شيبان، عن فراس، عن الشعبيّ، عن عبدالله بن عمرو بن العاص، قال: فذكره.","grade":"صحيح","chapter_ar":"باب أن الشرك من أعظم الذنوب","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (6920).","chapter_en":"Associating Partners With Allah Is Among the Greatest Sins","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr, may Allah be pleased with them, reported: A Bedouin came to the Prophet ﷺ and asked: “O Messenger of Allah, what are the major sins?” He replied: “Associating partners with Allah.” He asked: “Then what?” He replied: “Then disobedience to parents.” He asked: “Then what?” He replied: “The immersing oath.” I asked: “What is the immersing oath?” He replied: “It is the oath through which a person wrongfully takes the property of a Muslim while knowingly lying.”"]},"buhuth":{"en":["Al-Bukhārī also narrated it at (6675), with the additional mention:","“And killing a soul.”","It is called al-yamīn al-ghamūs — the “immersing oath” — because it immerses the person who swears it in sin and then in the Fire."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (6920)."},{"num":232,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: سُئِلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْكَبَائِرِ؟ قَالَ: الْإِشْرَاكُ بِاللَّهِ، وَعُقُوقُ الْوَالِدَيْنِ، وَقَتْلُ النَّفْسِ، وَشَهَادَةُ الزُّورِ.","وَفِي رِوَايَةٍ: قَوْلُ الزُّورِ."],"takhrij":"متفق عليه: رواه البخاريّ في الشّهادات (2653)، ومسلم في الإيمان (88) كلاهما من طريق شعبة، عن عبيد الله بن أبي بكر بن أنس، عن أنس، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب أن الشرك من أعظم الذنوب","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2653) and Muslim (88).","chapter_en":"Associating Partners With Allah Is Among the Greatest Sins","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Anas, may Allah be pleased with him, reported: The Prophet ﷺ was asked about the major sins. He replied: “Associating partners with Allah, disobedience to parents, killing a soul, and false testimony.”","In another wording: “False speech.”"]},"buhuth":{"en":["In another narration of Muslim, the Messenger of Allah ﷺ mentioned the major sins — or was asked about the major sins — and said:","“Associating partners with Allah, killing a soul, and disobedience to parents.”","Then he said:","“Shall I not inform you of the greatest of the major sins?”","He said:","“False speech,” or, “false testimony.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2653)، ومسلم (88)."},{"num":233,"demo":false,"sanad":"","matn":["عَنْ أَبِي أَيُّوبَ الْأَنْصَارِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا مِنْ عَبْدٍ يَعْبُدُ اللَّهَ لَا يُشْرِكُ بِهِ شَيْئًا، وَيُقِيمُ الصَّلَاةَ، وَيُؤْتِي الزَّكَاةَ، وَيَجْتَنِبُ الْكَبَائِرَ إِلَّا دَخَلَ الْجَنَّةَ، فَسَأَلُوهُ: مَا الْكَبَائِرُ ؟ فَقَالَ: الْإِشْرَاكُ بِاللَّهِ، وَالْفِرَارُ مِنَ الزَّحْفِ، وَقَتْلُ النَّفْسِ."],"takhrij":"حسن: رواه ابن منده في الإيمان (478) عن أحمد بن إسحاق بن أيوب، ثنا يوسف بن يعقوب، ثنا محمد بن أبي بكر، ثنا فُضيل بن سليمان، ثنا موسى بن عقبة، سمع عبيد الله بن سليمان الأغرّ، عن أبيه، عن أبي أيوب، فذكره.","grade":"حسن","chapter_ar":"باب أن الشرك من أعظم الذنوب","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Mandah in al-Īmān (478).","chapter_en":"Associating Partners With Allah Is Among the Greatest Sins","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Abū Ayyūb al-Anṣārī may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “There is no servant who worships Allah without associating anything with Him, establishes the prayer, gives zakāh, and avoids the major sins except that he will enter Paradise.” They asked him: “What are the major sins?” He replied: “Associating partners with Allah, fleeing from the battlefield, and killing a soul.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن منده في الإيمان (478)."},{"num":234,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ أَنَّ رَجُلًا قَالَ: يَا رَسُولَ اللَّهِ مَا الْكَبَائِرُ؟ قَالَ: الشِّرْكُ بِاللَّهِ، وَالْإِيَاسُ مِنْ رَوْحِ اللَّهِ، وَالْقَنُوطُ مِنْ رَحْمَةِ اللَّهِ."],"takhrij":"حسن: رواه البزار –كشف الأستار (106) عن عبدالله بن إسحاق العطّار، حدثنا الضحّاك بن مخلد، حدثنا شبيب بن بشر، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب أن الشرك من أعظم الذنوب","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Bazzār in Kashf al-Astār (106).","chapter_en":"Associating Partners With Allah Is Among the Greatest Sins","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿAbbās, may Allah be pleased with them, reported: A man asked: “O Messenger of Allah, what are the major sins?” He replied: “Associating partners with Allah, despairing of relief from Allah, and losing hope in the mercy of Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (106)."},{"num":235,"demo":false,"sanad":"","matn":["عَنْ عُبَادَةَ بْنِ الصَّامِتِ وَكَانَ شَهِدَ بَدْرًا وَهُوَ أَحَدُ النُّقَبَاءِ لَيْلَةَ الْعَقَبَةِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ وَحَوْلَهُ عِصَابَةٌ مِنْ أَصْحَابِهِ: بَايِعُونِي عَلَى أَنْ لَا تُشْرِكُوا بِاللَّهِ شَيْئًا، وَلَا تَسْرِقُوا، وَلَا تَزْنُوا، وَلَا تَقْتُلُوا أَوْلَادَكُمْ، وَلَا تَأْتُوا بِبُهْتَانٍ تَفْتَرُونَهُ بَيْنَ أَيْدِيكُمْ وَأَرْجُلِكُمْ، وَلَا تَعْصُوا فِي مَعْرُوفٍ، فَمَنْ وَفَى مِنْكُمْ فَأَجْرُهُ عَلَى اللَّهِ، وَمَنْ أَصَابَ مِنْ ذَلِكَ شَيْئًا فَعُوقِبَ فِي الدُّنْيَا فَهُوَ كَفَّارَةٌ لَهُ، وَمَنْ أَصَابَ مِنْ ذَلِكَ شَيْئًا ثُمَّ سَتَرَهُ اللَّهُ فَهُوَ إِلَى اللَّهِ إِنْ شَاءَ عَفَا عَنْهُ وَإِنْ شَاءَ عَاقَبَهُ."],"takhrij":"متفق عليه: رواه البخاريّ في الإيمان (18)، ومسلم في الحدود (1709) كلاهما من حديث الزهريّ، عن أبي إدريس عائذ الله بن عبدالله، أنّ عبادة بن الصّامت قال (فذكر الحديث)، واللّفظ للبخاريّ.","grade":"متفق عليه","chapter_ar":"باب المبايعة على عدم الإشراك بالله","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (18) and Muslim (1709), with the wording of al-Bukhārī.","chapter_en":"The Pledge of Allegiance to Not Associate Anything With Allah","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["ʿUbādah ibn al-Ṣāmit may Allah be pleased with him — who had participated in Badr and was one of the representatives on the night of al-ʿAqabah — reported that the Messenger of Allah ﷺ said while a group of his Companions were around him: “Pledge allegiance to me that you will not associate anything with Allah, will not steal, will not commit unlawful sexual intercourse, will not kill your children, will not bring a slander that you fabricate between your hands and feet, and will not disobey concerning what is right. Whoever among you fulfills this, his reward is with Allah. Whoever commits any of these things and is punished for it in this world, that punishment is an expiation for him. Whoever commits any of these things and Allah conceals it, his affair rests with Allah: if He wills, He will pardon him, and if He wills, He will punish him.”"]},"buhuth":{"en":["Al-Bukhārī (3893) narrated through another route with the additional wording:","“And that we would not plunder and would not disobey. Paradise would be ours if we fulfilled that; but if we committed any of those things, its judgment would rest with Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (18)، ومسلم (1709)، واللفظ للبخاري."},{"num":236,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُبَايِعُ النِّسَاءَ بِالْكَلَامِ بِهَذِهِ الْآيَةِ ﴿لَا يُشْرِكْنَ بِاللَّهِ شَيْئًا﴾ [الممتحنة: 12]. قَالَتْ: وَمَا مَسَّتْ يَدُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَ امْرَأَةٍ إِلَّا امْرَأَةً يَمْلِكُهَا."],"takhrij":"متفق عليه: رواه البخاريّ في الأحكام (7214) عن محمود، حدثنا عبدالرزاق، أخبرنا معمر، عن الزّهريّ، عن عروة، عن عائشة، فذكرته هكذا مختصراً.","grade":"متفق عليه","chapter_ar":"باب المبايعة على عدم الإشراك بالله","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (7214).","chapter_en":"The Pledge of Allegiance to Not Associate Anything With Allah","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["ʿĀʾishah may Allah be pleased with her reported: The Prophet ﷺ used to take the pledge of allegiance from women verbally in accordance with the verse: “They will not associate anything with Allah.” [Sūrat al-Mumtaḥanah 60:12] She said: “The hand of the Messenger of Allah ﷺ never touched the hand of any woman except a woman whom he owned.”"]},"buhuth":{"en":["Al-Bukhārī (5288) and Muslim (1866) also narrated that ʿĀʾishah may Allah be pleased with her said:","When believing women migrated to the Messenger of Allah ﷺ, they were tested according to the words of Allah, Mighty and Majestic:","“O Prophet, when believing women come to you pledging allegiance to you that they will not associate anything with Allah, nor steal, nor commit unlawful sexual intercourse…”","[Sūrat al-Mumtaḥanah 60:12]","ʿĀʾishah said:","“Whichever believing woman affirmed these conditions had passed the test.”","This is Muslim’s wording.","Al-Bukhārī added:","When they verbally affirmed these conditions, the Messenger of Allah ﷺ would say to them:","“Go, for I have accepted your pledge.”","By Allah, the hand of the Messenger of Allah ﷺ never touched the hand of any woman. He took their pledge only verbally. By Allah, the Messenger of Allah ﷺ imposed upon women nothing except what Allah had commanded him. When he accepted their pledge, he would say to them verbally:","“I have accepted your pledge.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7214)."},{"num":237,"demo":false,"sanad":"","matn":["عَنْ جَرِيرٍ قَالَ: بَايَعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى شَهَادَةِ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَإِقَامِ الصَّلَاةِ، وَإِيتَاءِ الزَّكَاةِ، وَالسَّمْعِ، وَالطَّاعَةِ، وَالنُّصْحِ لِكُلِّ مُسْلِمٍ."],"takhrij":"متفق عليه: رواه البخاريّ في البيوع (2157)، ومسلم في الإيمان (56) كلاهما من حديث إسماعيل بن أبي خالد، عن قيس، قال: سمعتُ جريراً، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب المبايعة على عدم الإشراك بالله","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2157) and Muslim (56), with the wording of al-Bukhārī.","chapter_en":"The Pledge of Allegiance to Not Associate Anything With Allah","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["Jarīr, may Allah be pleased with him, reported: “I pledged allegiance to the Messenger of Allah ﷺ upon testifying that there is no deity worthy of worship except Allah and that Muḥammad is the Messenger of Allah; establishing the prayer; giving zakāh; hearing and obeying; and offering sincere counsel to every Muslim.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2157)، ومسلم (56)، واللفظ للبخاري."},{"num":238,"demo":false,"sanad":"","matn":["عَنْ أُمِّ عَطِيَّةَ قَالَتْ: بَايَعْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَرَأَ عَلَيْنَا:﴿أَنْ لَا يُشْرِكْنَ بِاللَّهِ شَيْئًا﴾ [الممتحنة: 12]، وَنَهَانَا عَنِ النِّيَاحَةِ، فَقَبَضَتِ امْرَأَةٌ يَدَهَا، فَقَالَتْ: أَسْعَدَتْنِي فُلَانَةُ أُرِيدُ أَنْ أَجْزِيَهَا، فَمَا قَالَ لَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَيْئًا، فَانْطَلَقَتْ وَرَجَعَتْ فَبَايَعَهَا."],"takhrij":"متفق عليه: رواه البخاريّ في التفسير (4892)، ومسلم في الجنائز (936: 33) كلاهما من حديث حفصة بنت سيرين، عن أمّ عطيّة، فذكرتْه، واللّفظ للبخاريّ.","grade":"متفق عليه","chapter_ar":"باب المبايعة على عدم الإشراك بالله","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Tafsīr (4892) and Muslim in al-Janāʾiz (936:33), with the wording of al-Bukhārī.","chapter_en":"The Pledge of Allegiance to Not Associate Anything With Allah","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["Umm ʿAṭiyyah may Allah be pleased with her reported: We pledged allegiance to the Messenger of Allah ﷺ, and he recited to us: “That they will not associate anything with Allah.” [Sūrat al-Mumtaḥanah 60:12] He also prohibited us from wailing over the dead. One woman withdrew her hand and said: “So-and-so woman supported me in mourning, and I wish to repay her.” The Prophet ﷺ said nothing to her. She went away, then returned, and he accepted her pledge."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4892)، ومسلم (936: 33)، واللفظ للبخاري."},{"num":239,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: شَهِدْتُ صَلَاةَ الْفِطْرِ مَعَ نَبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَبِي بَكْرٍ، وَعُمَرَ، وَعُثْمَانَ، فَكُلُّهُمْ يُصَلِّيهَا قَبْلَ الْخُطْبَةِ، ثُمَّ يَخْطُبُ، قَالَ: فَنَزَلَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَأَنِّي أَنْظُرُ إِلَيْهِ حِينَ يُجَلِّسُ الرِّجَالَ بِيَدِهِ، ثُمَّ أَقْبَلَ يَشُقُّهُمْ حَتَّى جَاءَ النِّسَاءَ وَمَعَهُ بِلَالٌ، فَقَالَ:﴿يَا أَيُّهَا النَّبِيُّ إِذَا جَاءَكَ الْمُؤْمِنَاتُ يُبَايِعْنَكَ عَلَى أَنْ لَا يُشْرِكْنَ بِاللَّهِ شَيْئًا﴾ [سورة الممتحنة: 12] فَتَلَا هَذِهِ الْآيَةَ حَتَّى فَرَغَ مِنْهَا، ثُمَّ قَالَ حِينَ فَرَغَ مِنْهَا: أَنْتُنَّ عَلَى ذَلِكِ، فَقَالَتِ امْرَأَةٌ وَاحِدَةٌ لَمْ يُجِبْهُ غَيْرُهَا مِنْهُنَّ: نَعَمْ يَا نَبِيَّ اللَّهِ، لَا يُدْرَى حِينَئِذٍ مَنْ هِيَ، قَالَ: فَتَصَدَّقْنَ، فَبَسَطَ بِلَالٌ ثَوْبَهُ، ثُمَّ قَالَ: هَلُمَّ فِدًى لَكُنَّ أَبِي وَأُمِّي، فَجَعَلْنَ يُلْقِينَ الْفَتَخَ وَالْخَوَاتِمَ فِي ثَوْبِ بِلَالٍ."],"takhrij":"متفق عليه: رواه البخاريّ في العيدين (979)، ومسلم في العيدين (884) كلاهما من حديث عبدالرزاق، قال: حدثنا ابن جريج، قال: أخبرني الحسن بن مسلم، عن طاوس، عن ابن عباس، فذكره، واللّفظ لمسلم، ولفظ البخاريّ قريب منه.","grade":"متفق عليه","chapter_ar":"باب المبايعة على عدم الإشراك بالله","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (979) and Muslim (884), with the wording of Muslim.","chapter_en":"The Pledge of Allegiance to Not Associate Anything With Allah","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["Ibn ʿAbbās, may Allah be pleased with them, reported: I attended the ʿĪd al-Fiṭr prayer with the Prophet of Allah ﷺ, Abū Bakr, ʿUmar, and ʿUthmān. All of them would perform the prayer before the sermon and then deliver the sermon. He said: The Prophet of Allah ﷺ then came down. It is as though I can still see him motioning with his hand for the men to remain seated. He passed through their rows until he reached the women, with Bilāl accompanying him. He recited: “O Prophet, when believing women come to you pledging allegiance to you that they will not associate anything with Allah…” [Sūrat al-Mumtaḥanah 60:12] He continued reciting the verse until he completed it. When he had finished, he asked: “Are you committed to this?” One woman alone replied — none of the other women answered him: “Yes, O Prophet of Allah.” At that time, it was not known who she was. He then said: “Give charity.” Bilāl spread out his garment, and the women began throwing their large rings and other rings into Bilāl’s garment."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (979)، ومسلم (884)، واللفظ لمسلم."},{"num":240,"demo":false,"sanad":"","matn":["عَنْ عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ قَالَ: كُنَّا عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تِسْعَةً أَوْ ثَمَانِيَةً أَوْ سَبْعَةً، فَقَالَ: أَلَا تُبَايِعُونَ رَسُولَ اللَّهِ؟ وَكُنَّا حَدِيثَ عَهْدٍ بِبَيْعَةٍ، فَقُلْنَا: قَدْ بَايَعْنَاكَ يَا رَسُولَ اللَّهِ، ثُمَّ قَالَ: أَلَا تُبَايِعُونَ رَسُولَ اللَّهِ؟ فَقُلْنَا: قَدْ بَايَعْنَاكَ يَا رَسُولَ اللَّهِ، ثُمَّ قَالَ: أَلَا تُبَايِعُونَ رَسُولَ اللَّهِ؟ قَالَ: فَبَسَطْنَا أَيْدِيَنَا، وَقُلْنَا: قَدْ بَايَعْنَاكَ يَا رَسُولَ اللَّهِ فَعَلَامَ نُبَايِعُكَ؟ قَالَ: عَلَى أَنْ تَعْبُدُوا اللَّهَ وَلَا تُشْرِكُوا بِهِ شَيْئًا، وَالصَّلَوَاتِ الْخَمْسِ وَتُطِيعُوا، وَأَسَرَّ كَلِمَةً خَفِيَّةً، وَلَا تَسْأَلُوا النَّاسَ شَيْئًا، فَلَقَدْ رَأَيْتُ بَعْضَ أُولَئِكَ النَّفَرِ، يَسْقُطُ سَوْطُ أَحَدِهِمْ، فَمَا يَسْأَلُ أَحَدًا يُنَاوِلُهُ إِيَّاهُ."],"takhrij":"صحيح: رواه مسلم في الزكاة (1043) من طرق عن مروان (وهو ابن محمد الدمشقي)، ثنا سعيد (وهو ابن عبدالعزيز)، عن ربيعة بن يزيد، عن أبي إدريس الخولانيّ عن أبي مسلم الخولاني، قال: حدّثني الحبيب الأمين، أما هو فحبيبٌ إليَّ، وأما هو عندي أمين، عوف بن مالك الأشجعيّ، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب المبايعة على عدم الإشراك بالله","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1043).","chapter_en":"The Pledge of Allegiance to Not Associate Anything With Allah","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["ʿAwf ibn Mālik al-Ashjaʿī, may Allah be pleased with him, reported: We were with the Messenger of Allah ﷺ, nine — or eight, or seven — of us, when he said: “Will you not pledge allegiance to the Messenger of Allah?” We had only recently given him our pledge, so we said: “We have already pledged allegiance to you, O Messenger of Allah.” He again said: “Will you not pledge allegiance to the Messenger of Allah?” We replied: “We have already pledged allegiance to you, O Messenger of Allah.” Then he said a third time: “Will you not pledge allegiance to the Messenger of Allah?” So we extended our hands and said: “We have pledged allegiance to you, O Messenger of Allah. Upon what, then, are we to pledge?” He replied: “That you worship Allah and do not associate anything with Him, perform the five prayers, and obey.” Then he quietly added a subtle condition: “And that you do not ask people for anything.” I later saw some of those men drop a riding whip, yet they would not ask anyone to hand it back to them."]}},"tuhfa":{},"full":1,"rep":[4234,7644],"tks":"صحيح: رواه مسلم (1043)."},{"num":241,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو قَالَ: كُنَّا عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجَاءَ رَجُلٌ مِنْ أَهْلِ الْبَادِيَةِ، عَلَيْهِ جُبَّةٌ سِيجَانٍ مَزْرُورَةٌ بِالدِّيبَاجِ، فَقَالَ: أَلَا إِنَّ صَاحِبَكُمْ هَذَا قَدْ وَضَعَ كُلَّ فَارِسٍ ابْنِ فَارِسٍ! قَالَ: يُرِيدُ أَنْ يَضَعَ كُلَّ فَارِسٍ ابْنِ فَارِسٍ، وَيَرْفَعَ كُلَّ رَاعٍ ابْنِ رَاعٍ! قَالَ: فَأَخَذَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَجَامِعِ جُبَّتِهِ وَقَالَ: أَلَا أَرَى عَلَيْكَ لِبَاسَ مَنْ لَا يَعْقِلُ! ثُمَّ قَالَ: إِنَّ نَبِيَّ اللَّهِ نُوحًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا حَضَرَتْهُ الْوَفَاةُ قَالَ لِابْنِهِ: إِنِّي قَاصٌّ عَلَيْكَ الْوَصِيَّةَ آمُرُكَ بِاثْنَتَيْنِ، وَأَنْهَاكَ عَنِ اثْنَتَيْنِ، آمُرُكَ بِلَا إِلَهَ إِلَّا اللَّهُ، فَإِنَّ السَّمَوَاتِ السَّبْعَ، وَالْأَرْضِينَ السَّبْعَ، لَوْ وُضِعَتْ فِي كِفَّةٍ، وَوُضِعَتْ لَا إِلَهَ إِلَّا اللَّهُ فِي كِفَّةٍ، رَجَحَتْ بِهِنَّ لَا إِلَهَ إِلَّا اللَّهُ، وَلَوْ أَنَّ السَّمَوَاتِ السَّبْعَ، وَالْأَرْضِينَ السَّبْعَ، كُنَّ حَلْقَةً مُبْهَمَةً، قَصَمَتْهُنَّ لَا إِلَهَ إِلَّا اللَّهُ، وَسُبْحَانَ اللَّهِ وَبِحَمْدِهِ، فَإِنَّهَا صَلَاةُ كُلِّ شَيْءٍ، وَبِهَا يُرْزَقُ الْخَلْقُ، وَأَنْهَاكَ عَنِ الشِّرْكِ وَالْكِبْرِ، قَالَ: قُلْتُ، أَوْ قِيلَ: يَا رَسُولَ اللَّهِ، هَذَا الشِّرْكُ قَدْ عَرَفْنَاهُ، فَمَا الْكِبْرُ؟ قَالَ: أَنْ يَكُونَ لِأَحَدِنَا نَعْلَانِ حَسَنَتَانِ لَهُمَا شِرَاكَانِ حَسَنَانِ؟ قَالَ: لَا، قَالَ: هُوَ أَنْ يَكُونَ لِأَحَدِنَا حُلَّةٌ يَلْبَسُهَا؟ قَالَ: لَا، قَالَ: الْكِبْرُ هُوَ أَنْ يَكُونَ لِأَحَدِنَا دَابَّةٌ يَرْكَبُهَا؟ قَالَ: لَا، قَالَ: أَفَهُوَ أَنْ يَكُونَ لِأَحَدِنَا أَصْحَابٌ يَجْلِسُونَ إِلَيْهِ؟ قَالَ: لَا، قِيلَ: يَا رَسُولَ اللَّهِ، فَمَا الْكِبْرُ؟ قَالَ: سَفَهُ الْحَقِّ وَغَمْصُ النَّاسِ."],"takhrij":"صحيح: رواه الإمام أحمد (6583) عن سليمان بن حرب، حدثنا حماد بن زيد، عن الصقعَّب بن زهير، عن زيد بن أسلم، قال حماد: أظنه عن عطاء بن يسار، عن عبدالله بن عمرو، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب وصية نوح عليه السلام لابنه أن لا يشرك بالله","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Imām Aḥmad (6583, 7101).","chapter_en":"Noah’s Advice to His Son Not to Associate Anything With Allah","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr, may Allah be pleased with them, reported: We were with the Messenger of Allah ﷺ when a man from the desert came wearing a Sījān cloak fastened with silk. He said: “Indeed, this companion of yours has brought down every horseman, son of a horseman!” The narrator explained that he meant that the Prophet ﷺ was lowering every noble horseman descended from noble horsemen and raising every shepherd descended from shepherds. The Messenger of Allah ﷺ seized the front of his cloak and said: “Do I not see you wearing the clothing of one who lacks understanding?” Then he said: “When death approached the Prophet of Allah, Noah, peace be upon him,, he said to his son: ‘I will give you my final counsel. I command you with two things and forbid you from two things. I command you with “There is no deity worthy of worship except Allah.” If the seven heavens and the seven earths were placed on one side of a scale and “There is no deity worthy of worship except Allah” were placed on the other, “There is no deity worthy of worship except Allah” would outweigh them. And if the seven heavens and the seven earths formed one solid ring, “There is no deity worthy of worship except Allah” would break it apart. And I command you to say, “Glory be to Allah and praise be to Him,” for it is the prayer of everything, and through it creation is provided for. And I forbid you from associating partners with Allah and from arrogance.’” I asked — or it was asked: “O Messenger of Allah, we understand what shirk is, but what is arrogance? Is it that one of us has a fine pair of sandals with fine straps?” He replied: “No.” He asked: “Is it that one of us has a fine garment to wear?” He replied: “No.” He asked: “Is arrogance that one of us has a riding animal?” He replied: “No.” He asked: “Is it that one of us has companions who sit with him?” He replied: “No.” It was asked: “O Messenger of Allah, then what is arrogance?” He replied: “Rejecting the truth and looking down upon people.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (6583، 7101)."},{"num":242,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لِلَّهِ تِسْعَةٌ وَتِسْعُونَ اسْمًا مِائَةٌ إِلَّا وَاحِدًا، لَا يَحْفَظُهَا أَحَدٌ إِلَّا دَخَلَ الْجَنَّةَ، وَهُوَ وَتْرٌ يُحِبُّ الْوَتْرَ."],"takhrij":"متفق عليه: رواه البخاريّ في الدعوات (6410) عن علي بن عبدالله، حدثنا سفيان، قال: حفظناه من أبي الزّناد، عن الأعرج، عن أبي هريرة روايةً فذكره.","grade":"متفق عليه","chapter_ar":"باب ﴿وَلِلَّهِ الْأَسْمَاءُ الْحُسْنَى﴾ وهي توقيفية، أظهرها الله لعباده للمعرفة والدعاء","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6410) and Muslim (2677).","chapter_en":"“To Allah Belong the Most Beautiful Names”; They Are Established by Revelation, and Allah Has Made Them Known to His Servants for Knowledge and Supplication","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Allah has ninety-nine Names — one hundred minus one. Whoever preserves them will enter Paradise. He is One, and He loves what is odd.”"]},"buhuth":{"en":["The expression “one hundred minus one” appears in some narrations using a feminine grammatical form, while in the narration of Shuʿayb it appears in the masculine form.","Some scholars considered the masculine wording more correct.","Others explained the feminine wording on the basis that an “ism” — a name — may be treated as a “kalimah” — a word — which is grammatically feminine. They cited Sībawayh’s statement that a word may be a noun, a verb, or a particle, thereby referring to a noun as a word.","For further detail, see Fatḥ al-Bārī (11/219)."]},"intro":{"ar":["قال الله تعالى:","﴿وَلِلَّهِ الْأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا وَذَرُوا الَّذِينَ يُلْحِدُونَ فِي أَسْمَائِهِ سَيُجْزَوْنَ مَا كَانُوا يَعْمَلُونَ﴾","[الأعراف: ١٨٠]","وقال تعالى:","﴿قُلِ ادْعُوا اللهَ أَوِ ادْعُوا الرَّحْمَنَ أَيًّا مَا تَدْعُوا فَلَهُ الْأَسْمَاءُ الْحُسْنَى﴾","[الإسراء: ١١٠]","وقوله:","﴿فَادْعُوهُ بِهَا﴾","والدعاء هو العبادة."],"en":["Allah Most High said:","“To Allah belong the Most Beautiful Names, so call upon Him by them and leave those who deviate concerning His Names. They will be recompensed for what they used to do.”","[Sūrat al-Aʿrāf 7:180]","And He said:","“Say: Call upon Allah or call upon the Most Merciful. Whichever you call upon, to Him belong the Most Beautiful Names.”","[Sūrat al-Isrāʾ 17:110]","His statement:","“So call upon Him by them”","indicates supplication, and supplication is worship."]}},"tuhfa":{},"full":1,"dr":1,"rep":[10898,13527],"tks":"متفق عليه: رواه البخاري (6410)، ومسلم (2677)."},{"num":243,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَ: قَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا أَصَابَ مُسْلِمًا قَطُّ هَمٌ أَوْ حُزْنٌ فَقَالَ: اللهُمَّ إِنِّي عَبْدُكَ، وَابْنُ عَبْدِكَ، وَابْنُ أَمَتِكَ، نَاصِيَتِي بِيَدِكَ، مَاضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قَضَاؤُكَ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ، سَمَّيْتَ بِهِ نَفْسَكَ، أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ، أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ، أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ، أَنْ تَجْعَلَ الْقُرْآنَ رَبِيعَ قَلْبِي، وَنُورَ بَصَرِي، وَجِلَاءَ حُزْنِي، وَذَهَابَ هَمِّي، إِلَّا أَذْهَبَ اللهُ هَمَّهُ، وَأَبْدَلَهُ مَكَانَ حُزْنِهِ فَرَحًا، قَالُوا: يَا رَسُولَ اللهِ، أَفَلَا نَتَعَلَّمُ هَذِهِ الْكَلِمَاتِ؟ قَالَ: بَلَى يَنْبَغِي لِمَنْ سَمِعَهُنَّ أَنْ يَتَعَلَّمَهُنَّ."],"takhrij":"حسن: رواه الإمام أحمد (3712)، وأبو يعلى (5297)، والطبراني في الكبير (10352)، والبيهقي في الأسماء والصفات (7)، وصحّحه ابن حبان (972)، والحاكم (1877) كلهم من طريق فضيل بن مرزوق، قال: حدثنا أبو سلمة الجهني، عن القاسم بن عبدالرحمن، عن أبيه، عن ابن مسعود، فذكره.","grade":"حسن","chapter_ar":"باب ﴿وَلِلَّهِ الْأَسْمَاءُ الْحُسْنَى﴾ وهي توقيفية، أظهرها الله لعباده للمعرفة والدعاء","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (3712), Abū Yaʿlā (5297), and al-Ṭabarānī in al-Muʿjam al-Kabīr (10/209–210).","chapter_en":"“To Allah Belong the Most Beautiful Names”; They Are Established by Revelation, and Allah Has Made Them Known to His Servants for Knowledge and Supplication","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “No servant is ever afflicted by worry, distress, or grief and then says: ‘O Allah, I am Your servant, the son of Your servant, the son of Your maidservant. My forelock is in Your Hand. Your command concerning me is carried out, and Your decree concerning me is just. I ask You by every Name that belongs to You — with which You have named Yourself, which You have revealed in Your Book, which You have taught to any of Your creation, or which You have kept exclusively with Yourself in the knowledge of the unseen — that You make the Qurʾān the springtime of my heart, the light of my chest, the removal of my sorrow, and the departure of my worry and distress,’ except that Allah removes his worry and distress and replaces them with joy.” They asked: “O Messenger of Allah, should we not learn these words?” He replied: “Yes. Whoever hears them should learn them.”"]},"buhuth":{"en":["Important benefits","The foundation for affirming Allah’s Names and Attributes—or negating them—is the Qurʾān and the authentic Sunnah. Whatever is affirmed in them must be affirmed, and whatever is negated in them must be negated. As for what is neither affirmed nor negated, it is not correct to use it in the subject of Names and Attributes. Imām Aḥmad said: “Allah is not described except with what He described Himself with, or what His Messenger ﷺ described Him with; we do not go beyond the Qurʾān and the Sunnah.” See the introduction to al-ʿArsh by al-Dhahabī, edited by Dr. Muḥammad Khalīfah al-Tamīmī (1/238).","Accordingly, Allah’s Names are tawqīfiyyah—established only by revelation—and are not restricted to a specific number.","Al-Ḥāfiẓ Ibn al-Qayyim said in Badāʾiʿ al-Fawāʾid (1/293): “The Most Beautiful Names are not confined to a limited enumeration, nor restricted to a set number. Allah Most High has Names and Attributes which He has reserved for Himself in the knowledge of the unseen, known by no near angel and no sent prophet, as in the authentic ḥadīth: ‘I ask You by every Name that is Yours with which You have named Yourself, or revealed in Your Book, or kept exclusively in the knowledge of the unseen with You.’ Thus His Names are of three categories: a category by which He named Himself and disclosed it to whom He willed of His angels or others but did not reveal it in His Book; a category He revealed in His Book by which He made Himself known to His servants; and a category He kept exclusively in the knowledge of the unseen with Him and did not disclose to anyone of His creation. Hence the phrase ‘which You have kept exclusively’ means that You alone have kept its knowledge to Yourself; it does not mean exclusive in being named by it, because that exclusivity is already true of the Names He revealed in His Book. From this is the Prophet’s ﷺ statement in the ḥadīth of intercession: ‘Then He will open to me praises of Him which I do not know now.’ Those praises are by His Names and Attributes.” End quote.","As for the Prophet’s ﷺ statement, “Allah has ninety-nine Names…” it does not indicate that Allah’s Names are limited to this number. If the intent were restriction, it would have said, “Allah has no names except ninety-nine; whoever enumerates them will enter Paradise,” or similar. Rather, the meaning is that whoever enumerates and preserves these ninety-nine will enter Paradise."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (3712)، وأبو يعلى (5297)، والطبراني في المعجم الكبير (10309)."},{"num":244,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: قَالَ اللَّهُ تَعَالَى: أَنَا الرَّحْمَنُ وَهِيَ الرَّحِمُ شَقَقْتُ لَهَا اسْمًا مِنَ اسْمِي، مَنْ وَصَلَهَا وَصَلْتُهُ وَمَنْ قَطَعَهَا بَتَتُّهُ."],"takhrij":"صحيح: رواه أبو داود (1694) عن مسدّد، وأبي بكر بن أبي شيبة، قالا: حدّثنا سفيان، عن الزّهريّ، عن أبي سلمة، عن عبدالرحمن بن عوف، فذكره.","grade":"صحيح","chapter_ar":"باب أسماء الله تعالى دالة على صفاته وأفعاله","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (1694) and al-Tirmidhī (1907).","chapter_en":"Allah’s Names Indicate His Attributes and His Actions","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":11,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn ʿAwf, may Allah be pleased with him, reported: I heard the Messenger of Allah ﷺ say: “Allah Most High said: ‘I am al-Raḥmān, and this is al-raḥim — the bond of kinship. I derived its name from My Name. Whoever maintains it, I maintain him; and whoever cuts it off, I sever him.’”"]},"buhuth":{"en":["Ibn Mandah said in his book al-Tawḥīd (2/47): “This report indicates that all of Allah’s actions, Mighty and Majestic, are derived from His Names, unlike created beings. For example: the Provider, the Creator, the Resurrector, the Bestower, and so on. His Names precede His actions—meaning that He creates, provides, resurrects, bestows, gives life, and causes death—whereas the names of created beings are derived from their actions.” End."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1694)، والترمذي (1907)."},{"num":245,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قَالَ اللَّهُ عَزَّ وَجَلَّ: أَنَا الرَّحْمَنُ، وَهِيَ الرَّحِمُ شَقَقْتُ لَهَا اسمًا مِنَ اسْمِي، مَنْ يَصِلُهَا أَصِلُهُ، وَمَنْ يَقْطَعُهَا أَقْطَعُهُ، فَأَبُتُّهُ."],"takhrij":"حسن: رواه الإمام أحمد (10469) عن يزيد، قال: أخبرنا محمد، عن أبي سلمة، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب أسماء الله تعالى دالة على صفاته وأفعاله","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (10469) and al-Ḥākim (7267).","chapter_en":"Allah’s Names Indicate His Attributes and His Actions","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":11,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Allah, Mighty and Majestic, said: ‘I am al-Raḥmān, and this is al-raḥim — the bond of kinship. I derived for it a name from My Name. Whoever maintains it, I maintain him; and whoever cuts it off, I cut him off and sever him.’”"]},"buhuth":{"en":["Al-Bukhārī (5988) also narrated, through another route, from Abū Hurayrah, from the Prophet ﷺ: “Indeed, the womb/kinship-tie is a shajnah from al-Raḥmān. Allah, Mighty and Majestic, said: Whoever maintains you, I will maintain him; and whoever cuts you off, I will cut him off.”","“Shajnah” means a branch or offshoot from a tree limb, and from it comes the description of trees as “intertwined” when their branches wrap around one another."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (10469)، والحاكم (7267)."},{"num":246,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ رَجُلًا عَلَى سَرِيَّةٍ وَكَانَ يَقْرَأُ لِأَصْحَابِهِ فِي صَلَاتِهِمْ فَيَخْتِمُ بِـــ ﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾ فَلَمَّا رَجَعُوا ذَكَرُوا ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: سَلُوهُ لِأَيِّ شَيْءٍ يَصْنَعُ ذَلِكَ، فَسَأَلُوهُ ؟، فَقَالَ: لِأَنَّهَا صِفَةُ الرَّحْمَنِ وَأَنَا أُحِبُّ أَنْ أَقْرَأَ بِهَا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَخْبِرُوهُ أَنَّ اللَّهَ يُحِبُّهُ."],"takhrij":"متفق عليه: رواه البخاريّ في التوحيد (7375)، ومسلم في فضائل القرآن (813) كلاهما من حديث عبدالله بن وهب، حدّثنا عمرو بن الحارث، عن سعيد بن أبي هلال، أن أبا الرجال محمد بن عبدالرحمن حدّثه، عن أمِّه عمرة بنت عبدالرحمن، وكانت في حَجْر عائشة، ، عن عائشة، فذكرت مثله.","grade":"متفق عليه","chapter_ar":"باب ﴿قُلْ هُوَ اللهُ أَحَدٌ﴾ صفة الرحمن","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7375) and Muslim (813).","chapter_en":"“Say: He Is Allah, One” Is a Description of the Most Merciful","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":12,"content":{"translation":{"en":["ʿĀʾishah may Allah be pleased with her, the wife of the Prophet ﷺ, reported: The Prophet ﷺ appointed a man to lead a military expedition. When he led his companions in prayer, he would conclude his recitation with: “Say: He is Allah, One.” When they returned, they mentioned this to the Prophet ﷺ. He said: “Ask him why he does that.” They asked him, and he replied: “Because it is a description of al-Raḥmān, and I love to recite it.” The Prophet ﷺ said: “Tell him that Allah loves him.”"]}},"tuhfa":{},"full":1,"rep":[2031],"tks":"متفق عليه: رواه البخاري (7375)، ومسلم (813)."},{"num":247,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: كَانَ رَجُلٌ مِنْ الْأَنْصَارِ يَؤُمُّهُمْ فِي مَسْجِدِ قُبَاءَ، فَكَانَ كُلَّمَا افْتَتَحَ سُورَةً يَقْرَأُ لَهُمْ فِي الصَّلَاةِ فَقَرَأَ بِهَا افْتَتَحَ بِـــ ﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾ حَتَّى يَفْرُغَ مِنْهَا، ثُمَّ يَقْرَأُ بِسُورَةٍ أُخْرَى مَعَهَا، وَكَانَ يَصْنَعُ ذَلِكَ فِي كُلِّ رَكْعَةٍ، فَكَلَّمَهُ أَصْحَابُهُ فَقَالُوا: إِنَّكَ تَقْرَأُ بِهَذِهِ السُّورَةِ ثُمَّ لَا تَرَى أَنَّهَا تُجْزِيكَ حَتَّى تَقْرَأَ بِسُورَةٍ أُخْرَى، فَإِمَّا أَنْ تَقْرَأَ بِهَا وَإِمَّا أَنْ تَدَعَهَا وَتَقْرَأَ بِسُورَةٍ أُخْرَى، قَالَ: مَا أَنَا بِتَارِكِهَا، إِنْ أَحْبَبْتُمْ أَنْ أَؤُمَّكُمْ بِهَا فَعَلْتُ، وَإِنْ كَرِهْتُمْ تَرَكْتُكُمْ، وَكَانُوا يَرَوْنَهُ أَفْضَلَهُمْ وَكَرِهُوا أَنْ يَؤُمَّهُمْ غَيْرُهُ، فَلَمَّا أَتَاهُمُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخْبَرُوهُ الْخَبَرَ فَقَالَ: يَا فُلَانُ، مَا يَمْنَعُكَ مِمَّا يَأْمُرُ بِهِ أَصْحَابُكَ وَمَا يَحْمِلُكَ أَنْ تَقْرَأَ هَذِهِ السُّورَةَ فِي كُلِّ رَكْعَةٍ، فَقَالَ: يَا رَسُولَ اللَّهِ! إِنِّي أُحِبُّهَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ حُبَّهَا أَدْخَلَكَ الْجَنَّةَ."],"takhrij":"صحيح: أخرجه الترمذي (2901) قال: حدثنا محمد بن إسماعيل (البخاري) حدثنا إسماعيل بن أبي أويس، حدثنا عبدالعزيز بن محمد، عن عبيد الله بن عمر، عن ثابت البناني، عن أنس بن مالك فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ﴿قُلْ هُوَ اللهُ أَحَدٌ﴾ صفة الرحمن","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Tirmidhī (2901), who said: “Ḥasan Gharīb Ṣaḥīḥ.”","chapter_en":"“Say: He Is Allah, One” Is a Description of the Most Merciful","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":12,"content":{"translation":{"en":["Anas ibn Mālik, may Allah be pleased with him, reported: A man from the Anṣār used to lead his people in prayer at the Mosque of Qubāʾ. Whenever he began a sūrah for them in prayer, he would first recite: “Say: He is Allah, One,” until he completed it, and then recite another sūrah along with it. He did this in every rakʿah. His companions spoke to him and said: “You recite this sūrah, yet you apparently do not consider it sufficient until you recite another sūrah as well. Either recite this sūrah by itself or leave it and recite another sūrah.” He replied: “I will not abandon it. If you wish me to continue leading you while reciting it, I will do so; and if you dislike it, I will cease leading you.” They considered him the best among them and disliked having anyone else lead them. When the Prophet ﷺ came to them, they informed him of what had happened. He said: “O so-and-so, what prevents you from doing what your companions ask of you, and what causes you to recite this sūrah in every rakʿah?” He replied: “O Messenger of Allah, I love it.” The Messenger of Allah ﷺ said: “Your love for it has admitted you into Paradise.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2032],"tks":"صحيح: رواه الترمذي (2901)، وقال: «حسن غريب صحيح»."},{"num":248,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: أَعُوذُ بِعِزَّتِكَ الَّذِي لَا إِلَهَ إِلَّا أَنْتَ الَّذِي لَا يَمُوتُ وَالْجِنُّ وَالْإِنْسُ يَمُوتُونَ."],"takhrij":"متفق عليه: رواه البخاريّ في التوحيد (7383)، ومسلم في الذّكر (2717) كلاهما من حديث عبدالوارث، حدثنا حسين المعلم، حدثني عبدالله بن بريدة، عن يحيى بن يعمر، عن ابن عباس، فذكره.","grade":"متفق عليه","chapter_ar":"باب إثبات صفة الحياة لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7383) and Muslim (2717).","chapter_en":"Affirming the Attribute of Life for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":13,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās may Allah be pleased with them reported that the Prophet ﷺ used to say: “I seek refuge in Your Might. There is no deity worthy of worship except You. You are the One who does not die, while the jinn and mankind die.”"]},"intro":{"ar":["قال الله تعالى:","﴿اللهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ﴾","[البقرة: ٢٥٥]","وقال تعالى:","﴿وَتَوَكَّلْ عَلَى الْحَيِّ الَّذِي لَا يَمُوتُ﴾","[الفرقان: ٥٨]","وقال تعالى:","﴿وَعَنَتِ الْوُجُوهُ لِلْحَيِّ الْقَيُّومِ﴾","[طه: ١١١]","والآيات في هذا المعنى كثيرة."],"en":["Allah Most High said:","“Allah — there is no deity worthy of worship except Him, the Ever-Living, the Sustainer of all.”","[Sūrat al-Baqarah 2:255]","And He said:","“Place your trust in the Ever-Living who does not die.”","[Sūrat al-Furqān 25:58]","And He said:","“All faces will be humbled before the Ever-Living, the Sustainer.”","[Sūrat Ṭā Hā 20:111]","There are many verses carrying this meaning."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7383)، ومسلم (2717)."},{"num":249,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: كَانَ مِنْ دُعَاءِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَيْ حَيُّ، أَيْ قَيُّومُ."],"takhrij":"صحيح: رواه النسائيّ في عمل اليوم واللّيلة (613) عن محمد بن عبدالأعلى، قال: حدثنا المعتمر، عن أبيه، عن أنس، فذكر مثله.","grade":"صحيح","chapter_ar":"باب إثبات صفة الحياة لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Nasāʾī in ʿAmal al-Yawm wa al-Laylah (613) and al-Bayhaqī in al-Asmāʾ wa al-Ṣifāt (218).","chapter_en":"Affirming the Attribute of Life for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":13,"content":{"translation":{"en":["Anas, may Allah be pleased with him, reported: Among the supplications of the Prophet ﷺ was: “O Ever-Living, O Sustainer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي في عمل اليوم والليلة (613)، والبيهقي في الأسماء والصفات (218)."},{"num":250,"demo":false,"sanad":"","matn":["عَنْ أُبَيِّ بْنِ كَعْبٍ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ (فَذَكَرَ قِصَّةً مُوسَى وَالْخَضِرِ عَلَيْهِمَا السَّلَامُ) وَجَاءَ فِيهِ: فَانْطَلَقَا يَمْشِيَانِ عَلَى سَاحِلِ الْبَحْرِ لَيْسَ لَهُمَا سَفِينَةٌ، فَمَرَّتْ بِهِمَا سَفِينَةٌ فَكَلَّمُوهُمْ أَنْ يَحْمِلُوهُمَا، فَعُرِفَ الْخَضِرُ فَحَمَلُوهُمَا بِغَيْرِ نَوْلٍ، فَجَاءَ عُصْفُورٌ فَوَقَعَ عَلَى حَرْفِ السَّفِينَةِ فَنَقَرَ نَقْرَةً أَوْ نَقْرَتَيْنِ فِي الْبَحْرِ، فَقَالَ الْخَضِرُ: يَا مُوسَى، مَا نَقَصَ عِلْمِي وَعِلْمُكَ مِنْ عِلْمِ اللَّهِ إِلَّا كَنَقْرَةِ هَذَا الْعُصْفُورِ فِي الْبَحْرِ...(فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ)."],"takhrij":"متفق عليه: رواه البخاريّ في العلم (122)، ومسلم في الفضائل (2380) كلاهما من حديث سفيان بن عيينة، قال: حدثنا عمرو بن دينار، عن سعيد بن جبير، قال: قلت لابن عباس: إنّ نوفاً البكالي يزعم أنّ موسى ليس بموسى بني إسرائيل، إنّما هو موسى آخر؟ فقال: كذب عدوُّ الله! حدّثنا أُبي بن كعب، قال (فذكر الحديث بطوله).","grade":"متفق عليه","chapter_ar":"باب ما جاء في إثبات العلم لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (122) and Muslim (2380).","chapter_en":"What Has Been Reported Concerning Affirming Knowledge for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Ubayy ibn Kaʿb, may Allah be pleased with him, reported: I heard the Messenger of Allah ﷺ narrate the story of Moses and al-Khiḍr peace be upon them, and among it was: “They set out walking along the seashore and had no boat. A boat passed them, and they spoke to its people asking them to carry them. Al-Khiḍr was recognized, so they carried them without charging any fare. A small bird then came and landed upon the edge of the boat. It pecked once or twice into the sea. Al-Khiḍr said: ‘O Moses, my knowledge and your knowledge, compared with the knowledge of Allah, are no more than what this bird’s peck takes from the sea.’”"]},"buhuth":{"en":["His saying, “What my knowledge and your knowledge have diminished from Allah’s knowledge…” — the word “diminished” is not meant literally, because Allah’s knowledge does not accept decrease.","Abū Bakr Aḥmad ibn Ibrāhīm al-Ismāʿīlī said this has two possible meanings:","First, the bird’s pecking does not actually reduce the sea at all; likewise, our knowledge does not reduce Allah’s knowledge in any way. This is like the line of poetry: “We have no fault except that our swords / have nicks from striking armies,” meaning that we have no fault at all. Similarly, Allah’s statement, “They will not hear therein any idle talk—only peace” [Maryam 19:62], means that they will not hear idle talk whatsoever.","Second, what we have taken of knowledge, when compared with Allah’s knowledge that encompasses everything, amounts only to the tiny portion represented by what the bird takes from the sea: an extremely small part of something whose measure cannot be grasped. Likewise, what Allah has taught us, compared with what He knows, is like that tiny amount compared with the sea. Allah is the One who grants success.","See al-Asmāʾ wa al-Ṣifāt by al-Bayhaqī (1/297)."]},"intro":{"ar":["قال الله تعالى فيما يقوله حملة العرش:","﴿رَبَّنَا وَسِعْتَ كُلَّ شَيْءٍ رَحْمَةً وَعِلْمًا﴾","[غافر: ٧]","وقال الله تعالى:","﴿إِنَّ اللهَ عِنْدَهُ عِلْمُ السَّاعَةِ﴾","[لقمان: ٣٤]","وقال تعالى:","﴿إِنَّمَا الْعِلْمُ عِنْدَ اللهِ﴾","[الملك: ٢٦]","وقال تعالى:","﴿وَأَضَلَّهُ اللهُ عَلَى عِلْمٍ﴾","[الجاثية: ٢٣]","قال مالك رحمه الله تعالى:","«الله في السماء، وعلمه في كل مكان، لا يخلو منه شيء».","السنة لعبد الله بن أحمد (ص ٥٣٢)."],"en":["Allah Most High said concerning the words of the bearers of the Throne:","“Our Lord, You encompass all things in mercy and knowledge.”","[Sūrat Ghāfir 40:7]","And Allah Most High said:","“Indeed, Allah alone has knowledge of the Hour.”","[Sūrat Luqmān 31:34]","And He said:","“Knowledge is only with Allah.”","[Sūrat al-Mulk 67:26]","And He said:","“Allah led him astray upon knowledge.”","[Sūrat al-Jāthiyah 45:23]","Mālik رحمه الله said:","“Allah is above in the heaven, and His knowledge is everywhere; nothing is beyond it.”","Al-Sunnah by ʿAbdullāh ibn Aḥmad, p. 532."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (122)، ومسلم (2380)."},{"num":251,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُعَلِّمُنَا الِاسْتِخَارَةَ فِي الْأُمُورِ كُلِّهَا كَمَا يُعَلِّمُنَا السُّورَةَ مِنَ الْقُرْآنِ يَقُولُ: إِذَا هَمَّ أَحَدُكُمْ بِالْأَمْرِ فَلْيَرْكَعْ رَكْعَتَيْنِ مِنْ غَيْرِ الْفَرِيضَةِ، ثُمَّ لِيَق:ُلِ اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ، فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ وَتَعْلَمُ وَلَا أَعْلَمُ وَأَنْتَ عَلَّامُ الْغُيُوبِ، اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي أَوْ قَالَ عَاجِلِ أَمْرِي وَآجِلِهِ فَاقْدُرْهُ لِي وَيَسِّرْهُ لِي ثُمَّ بَارِكْ لِي فِيهِ، وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي أَوْ قَالَ فِي عَاجِلِ أَمْرِي وَآجِلِهِ فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ، وَاقْدُرْ لِي الْخَيْرَ حَيْثُ كَانَ ثُمَّ أَرْضِنِي، قَالَ: وَيُسَمِّي حَاجَتَهُ."],"takhrij":"صحيح: رواه البخاريّ في التهجد (1162) عن قتيبة، قال: حدثنا عبدالرحمن بن أبي الموالِي، عن محمد بن المنكدر، عن جابر بن عبدالله، فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في إثبات العلم لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (1162).","chapter_en":"What Has Been Reported Concerning Affirming Knowledge for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh, may Allah be pleased with them, reported: The Messenger of Allah ﷺ used to teach us istikhārah concerning all matters just as he taught us a sūrah from the Qurʾān. He would say: “When one of you intends a matter, let him perform two rakʿahs other than the obligatory prayer, then let him say: ‘O Allah, I seek the better choice from You through Your knowledge, and I seek ability from You through Your power, and I ask You from Your immense bounty. For You are able and I am not able; You know and I do not know; and You are the Knower of the unseen. O Allah, if You know that this matter is good for me in my religion, my livelihood, and the outcome of my affair — or he said: in the immediate and later consequences of my affair — then decree it for me, make it easy for me, and then bless it for me. And if You know that this matter is bad for me in my religion, my livelihood, and the outcome of my affair — or he said: in the immediate and later consequences of my affair — then turn it away from me and turn me away from it. Decree good for me wherever it may be, and then make me content with it.’” He said: “And he should mention his need.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1162)."},{"num":252,"demo":false,"sanad":"","matn":["عَنْ عَطَاءِ بْنِ السَّائِبِ، عَنْ أَبِيهِ، قَالَ: صَلَّى بِنَا عَمَّارُ بْنُ يَاسِرٍ يَوْمًا صَلَاةً فَأَوْجَزَ فِيهَا فَقَالَ بَعْضُ الْقَوْمِ لَقَدْ خَفَّفْتَ أَوْ كَلِمَةً نَحْوَهَا فَقَالَ: لَقَدْ دَعَوْتُ بِدَعَوَاتٍ سَمِعْتُهُنَّ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: فَلَمَّا انْطَلَقَ عَمَّارٌ اتَّبَعَهُ رَجُلٌ وَهُوَ أَبِي فَسَأَلَهُ عَنِ الدُّعَاءِ ثُمَّ جَاءَفَأَخْبَرَ بِهِ فَقَالَ: اللَّهُمَّ بِعِلْمِكَ الْغَيْبَ، وَقُدْرَتِكَ عَلَى الْخَلْقِ أَحْيِنِي مَا عَلِمْتَ الْحَيَاةَ خَيْرًا لِي، وَتَوَفَّنِي إِذَا كَانَتِ الْوَفَاةُ خَيْرًا لِي، اللَّهُمَّ إِنِّي أَسْأَلُكَ خَشْيَتَكَ فِي الْغَيْبِ وَالشَّهَادَةِ، وَأَسْأَلُكَ كَلِمَةَ الْحَقِّ فِي الْغَضَبِ وَالرِّضَا، وَأَسْأَلُكَ الْقَصْدَ فِي الْفَقْرِ وَالْغِنَى، وَأَسْأَلُكَ نَعِيمًا لا يَبِيدُ وَقُرَّةَ عَيْنٍ لا تَنْقَطِعُ، وَأَسْأَلُكَ الرِّضَا بَعْدَ الْقَضَاءِ، وَأَسْأَلُكَ بَرْدَ الْعَيْشِ بَعْدَ الْمَوْتِ، وَأَسْأَلُكَ لَذَّةَ النَّظَرِ إِلَى وَجْهِكَ، وَأَسْأَلُكَ الشَّوْقَ إِلَى لِقَائِكَ، فِي غَيْرِ ضَرَّاءَ مُضِرَّةٍ، وَلا فِتْنَةٍ مُضِلَّةٍ، اللَّهُمَّ زَيِّنَّا بِزِينَةِ الإِيمَانِ، وَاجْعَلْنَا هُدَاةً مُهْتَدِينَ."],"takhrij":"صحيح: رواه النسائيّ (1305)، وصحّحه ابن خزيمة في التوحيد (14) وعنه ابن حبان في صحيحه (1971)، والحاكم (1923)، والبيهقي في الأسماء والصّفات (227)، والدّارميّ في الرّد على الجهمية (188) كلّهم من حديث حماد ابن زيد، عن عطاء بن السّائب، عن أبيه، قال: صلّى بنا عمّار بن ياسر يوماً صلاة فأوجز فيها، فقال بعض القوم: لقد خفّفت، أو كلمة نحوها، فقال: لقد دعوتُ بدعوات سمعتهنّ من رسول الله صلى الله عليه وسلم. قال: فلما انطلق عمار أتبعه رجل، وهو أبي، فسأله عن الدّعاء، ثم جاء فأخبر به، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في إثبات العلم لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Nasāʾī (1305), and authenticated by Ibn Khuzaymah in al-Tawḥīd (14).","chapter_en":"What Has Been Reported Concerning Affirming Knowledge for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["ʿAmmār ibn Yāsir, may Allah be pleased with him, reported: I have supplicated with words of supplication that I heard from the Messenger of Allah ﷺ. He said: “O Allah, by Your knowledge of the unseen and Your power over creation, keep me alive for as long as You know life to be better for me, and cause me to die when You know death to be better for me. O Allah, I ask You for fear of You in private and in public. I ask You for the word of truth in anger and in contentment. I ask You for moderation in poverty and in wealth. I ask You for bliss that never perishes and comfort of the eye that never ceases. I ask You for contentment after Your decree, for the coolness and comfort of life after death, for the delight of looking upon Your Face, and for longing to meet You without harmful adversity or a misleading trial. O Allah, adorn us with the adornment of faith, and make us guides who are rightly guided.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1305)، وصححه ابن خزيمة في التوحيد (14)."},{"num":253,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ اللَّهَ عَزَّ وَجَلَّ خَلَقَ خَلْقَهُ فِي ظُلْمَةٍ، فَأَلْقَى عَلَيْهِمْ مِنْ نُورِهِ، فَمَنْ أَصَابَهُ مِنْ ذَلِكَ النُّورِ اهْتَدَى، وَمَنْ أَخْطَأَهُ ضَلَّ، فَلِذَلِكَ أَقُولُ: جَفَّ الْقَلَمُ عَلَى عِلْمِ اللَّهِ."],"takhrij":"حسن: رواه الترمذيّ (2642) عن الحسن بن عرفة، حدثنا إسماعيل بن عياش، عن يحيى بن أبي عمرو الشّيبانيّ، عن عبدالله بن الدّيلميّ، قال: سمعت عبدالله بن عمرو، فذكره. قال الترمذي: حديث حسن.","grade":"حسن","chapter_ar":"باب ما جاء في إثبات العلم لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Tirmidhī (2642), who said: “A Ḥasan ḥadīth.”","chapter_en":"What Has Been Reported Concerning Affirming Knowledge for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr, may Allah be pleased with them, reported: I heard the Messenger of Allah ﷺ say: “Indeed, Allah Most High created His creation in darkness, then cast upon them from His light. Whoever was reached by that light was guided, and whoever missed it went astray.” For this reason I say: “The Pen has dried upon the knowledge of Allah, Mighty and Majestic.”"]},"buhuth":{"en":["The statement:","“The Pen has dried upon the knowledge of Allah”","is the statement of ʿAbdullāh ibn ʿAmr may Allah be pleased with them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2642)، وقال: «حديث حسن»."},{"num":254,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُعَلِّمُنَا الِاسْتِخَارَةَ فِي الْأُمُورِ كُلِّهَا، كَمَا يُعَلِّمُنَا السُّورَةَ مِنَ الْقُرْآنِ يَقُولُ: إِذَا هَمَّ أَحَدُكُمْ بِالْأَمْرِ فَلْيَرْكَعْ رَكْعَتَيْنِ مِنْ غَيْرِ الْفَرِيضَةِ، ثُمَّ لِيَقُلِ: اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ، فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ وَتَعْلَمُ وَلَا أَعْلَمُ وَأَنْتَ عَلَّامُ الْغُيُوبِ، اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي أَوْ قَالَ عَاجِلِ أَمْرِي وَآجِلِهِ فَاقْدُرْهُ لِي وَيَسِّرْهُ لِي ثُمَّ بَارِكْ لِي فِيهِ، وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي أَوْ قَالَ فِي عَاجِلِ أَمْرِي وَآجِلِهِ فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ، وَاقْدُرْ لِي الْخَيْرَ حَيْثُ كَانَ ثُمَّ أَرْضِنِي، قَالَ: وَيُسَمِّي حَاجَتَهُ."],"takhrij":"صحيح: رواه البخاريّ في التهجد (1162) عن قتيبة، قال: حدثنا عبدالرحمن بن أبي الموالِي، عن محمد بن المنكدر، عن جابر بن عبدالله، فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في إثبات القدرة لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (1162).","chapter_en":"What Has Been Reported Concerning Affirming Power for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh, may Allah be pleased with them, reported: The Messenger of Allah ﷺ used to teach us istikhārah in all matters just as he taught us a sūrah from the Qurʾān. He would say: “When one of you intends a matter, let him perform two rakʿahs other than the obligatory prayer and then say: ‘O Allah, I seek the better choice from You through Your knowledge, and I seek ability from You through Your power, and I ask You from Your immense bounty. For You are able and I am not able; You know and I do not know; and You are the Knower of all unseen things. O Allah, if You know that this matter is good for me in my religion, my livelihood, and the outcome of my affair — or he said: in the immediate and later consequences of my affair — then decree it for me, make it easy for me, and bless it for me. And if You know that this matter is bad for me in my religion, my livelihood, and the outcome of my affair — or he said: in the immediate and later consequences of my affair — then turn it away from me and turn me away from it. Decree good for me wherever it may be, and then make me content with it.’” He said: “And he should mention his need.”"]},"intro":{"ar":["قال الله تعالى:","﴿تَبَارَكَ الَّذِي بِيَدِهِ الْمُلْكُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ﴾","[الملك: ١]","وقال تعالى:","﴿قُلْ هُوَ الْقَادِرُ عَلَى أَنْ يَبْعَثَ عَلَيْكُمْ عَذَابًا مِنْ فَوْقِكُمْ أَوْ مِنْ تَحْتِ أَرْجُلِكُمْ أَوْ يَلْبِسَكُمْ شِيَعًا وَيُذِيقَ بَعْضَكُمْ بَأْسَ بَعْضٍ﴾","[الأنعام: ٦٥]","وقال تعالى:","﴿بَلَى قَادِرِينَ عَلَى أَنْ نُسَوِّيَ بَنَانَهُ﴾","[القيامة: ٤]"],"en":["Allah Most High said:","“Blessed is He in whose Hand is dominion, and He has power over all things.”","[Sūrat al-Mulk 67:1]","And He said:","“Say: He is able to send upon you punishment from above you or from beneath your feet, or to divide you into factions and make some of you taste the violence of others.”","[Sūrat al-Anʿām 6:65]","And He said:","“Yes indeed; We are fully able even to restore his fingertips.”","[Sūrat al-Qiyāmah 75:4]"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (1162)."},{"num":255,"demo":false,"sanad":"","matn":["عَنْ عُثْمَانَ بْنِ أَبِي الْعَاصِ الثَّقَفِيِّ أَنَّهُ شَكَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَجَعًا يَجِدُهُ فِي جَسَدِهِ مُنْذُ أَسْلَمَ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ضَعْ يَدَكَ عَلَى الَّذِي تَأَلَّمَ مِنْ جَسَدِكَ، وَقُلْ بِاسْمِ اللَّهِ ثَلَاثًا، وَقُلْ سَبْعَ مَرَّاتٍ أَعُوذُ بِاللَّهِ، وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ."],"takhrij":"صحيح: رواه مسلم في السلام (2202) من طرق عن ابن وهب، أخبرني يونس، عن ابن شهاب، أخبرني نافع بن جبير بن مطعم، عن عثمان بن أبي العاص الثقفيّ، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في إثبات القدرة لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2202).","chapter_en":"What Has Been Reported Concerning Affirming Power for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["ʿUthmān ibn Abī al-ʿĀṣ al-Thaqafī, may Allah be pleased with him, reported: He complained to the Messenger of Allah ﷺ about pain that he had felt in his body since embracing Islam. The Messenger of Allah ﷺ said to him: “Place your hand upon the part of your body that hurts and say three times: ‘In the Name of Allah.’ Then say seven times: ‘I seek refuge in Allah and His power from the evil of what I feel and what I fear.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2202)."},{"num":256,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَ: أَقْرَأَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنِّي أَنَا الرَّزَّاقُ ذُو الْقُوَّةِ الْمَتِينُ."],"takhrij":"صحيح: رواه أبو داود (3993)، والترمذيّ (2940) كلاهما من حديث إسرائيل، عن أبي إسحاق، عن عبدالرحمن بن يزيد، عن عبدالله بن مسعود، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في إثبات القدرة لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (3993) and al-Tirmidhī (2940), who said: “Ḥasan Ṣaḥīḥ.”","chapter_en":"What Has Been Reported Concerning Affirming Power for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd, may Allah be pleased with him, reported: The Messenger of Allah ﷺ taught me to recite: “Indeed, I am the Provider, the Possessor of power, the Firm.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3993)، والترمذي (2940)، وقال: «حديث حسن صحيح»."},{"num":257,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: وَالْمَلَائِكَةُ يَتَعَاقَبُونَ فِيكُمْ، مَلَائِكَةٌ بِاللَّيْلِ وَمَلَائِكَةٌ بِالنَّهَارِ وَيَجْتَمِعُونَ فِي صَلَاةِ الْعَصْرِ، وَصَلَاةِ الْفَجْرِ، ثُمَّ يَعْرُجُ الَّذِينَ بَاتُوا فِيكُمْ فَيَسْأَلُهُمْ وَهُوَ أَعْلَمُ بِهِمْ كَيْفَ تَرَكْتُمْ عِبَادِي؟ فَيَقُولُونَ: تَرَكْنَاهُمْ وَهُمْ يُصَلُّونَ، وَأَتَيْنَاهُمْ وَهُمْ يُصَلُّونَ."],"takhrij":"متفق عليه: رواه مالك في قصر الصّلاة (82) عن أبي الزّناد، عن الأعرج، عن أبي هريرة، فذكره. ورواه البخاريّ في المواقيت (555)، ومسلم في المساجد (632) كلاهما من طريق مالك، به، مثله.","grade":"متفق عليه","chapter_ar":"باب إثبات العلو لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in Qaṣr al-Ṣalāh (82), al-Bukhārī (555), and Muslim (632).","chapter_en":"Affirming the Exaltedness of Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “The angels take turns among you: angels by night and angels by day. They gather at the ʿAṣr prayer and the Fajr prayer. Then those who spent the night among you ascend, and Allah asks them — although He knows them best: ‘How did you leave My servants?’ They reply: ‘We left them while they were praying, and we came to them while they were praying.’”"]},"intro":{"ar":["قال الله تعالى:","﴿وَهُوَ الْعَلِيُّ الْعَظِيمُ﴾","[البقرة: ٢٥٥]","وقال تعالى:","﴿يُدَبِّرُ الْأَمْرَ مِنَ السَّمَاءِ إِلَى الْأَرْضِ ثُمَّ يَعْرُجُ إِلَيْهِ﴾","[السجدة: ٥]","وقال تعالى:","﴿تَعْرُجُ الْمَلَائِكَةُ وَالرُّوحُ إِلَيْهِ﴾","[المعارج: ٤]","وقال تعالى:","﴿يَخَافُونَ رَبَّهُمْ مِنْ فَوْقِهِمْ﴾","[النحل: ٥٠]","وقال تعالى:","﴿أَأَمِنْتُمْ مَنْ فِي السَّمَاءِ أَنْ يَخْسِفَ بِكُمُ الْأَرْضَ﴾","[الملك: ١٦]"],"en":["Allah Most High said:","“And He is the Most High, the Most Great.”","[Sūrat al-Baqarah 2:255]","And He said:","“He directs the affair from the heaven to the earth; then it ascends to Him.”","[Sūrat al-Sajdah 32:5]","And He said:","“The angels and the Spirit ascend to Him.”","[Sūrat al-Maʿārij 70:4]","And He said:","“They fear their Lord above them.”","[Sūrat al-Naḥl 16:50]","And He said:","“Do you feel secure from the One who is in the heaven that He will not cause the earth to swallow you?”","[Sūrat al-Mulk 67:16]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه مالك (82)، والبخاري (555)، ومسلم (632)."},{"num":258,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَلَا تَأْمَنُونِي وَأَنَا أَمِينُ مَنْ فِي السَّمَاءِ، يَأْتِينِي خَبَرُ السَّمَاءِ صَبَاحًا وَمَسَاءً ؟.(فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ)."],"takhrij":"متفق عليه: رواه البخاريّ في المغازي (4351)، ومسلم في الزكاة (1064: 144) كلاهما من حديث عبدالواحد، عن عُمارة بن القعقاع، حدثنا عبدالرحمن ابن أبي نُعم، قال: سمعت أبا سعيد، فذكر الحديث في حديث طويل، سيأتي بكامله في كتاب الزكاة.","grade":"متفق عليه","chapter_ar":"باب إثبات العلو لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Maghāzī (4351) and Muslim in al-Zakāh (1064:144).","chapter_en":"Affirming the Exaltedness of Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Will you not trust me when I am the trusted one of the One who is in the heaven? News from the heaven comes to me morning and evening.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4351)، ومسلم (1064: 144)."},{"num":259,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ تَصَدَّقَ بِعَدْلِ تَمْرَةٍ مِنْ كَسْبٍ طَيِّبٍ وَلَا يَصْعَدُ إِلَى اللَّهِ إِلَّا الطَّيِّبُ فَإِنَّ اللَّهَ يَتَقَبَّلُهَا بِيَمِينِهِ ثُمَّ يُرَبِّيهَا لِصَاحِبِهِ كَمَا يُرَبِّي أَحَدُكُمْ فُلُوَّهُ حَتَّى تَكُونَ مِثْلَ الْجَبَلِ."],"takhrij":"متفق عليه: رواه البخاريّ في التوحيد (7430) قال: وقال خالد بن مخلد، حدثنا سليمان، حدّثني عبدالله بن دينار، عن أبي صالح، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب إثبات العلو لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7430) and Muslim (1014).","chapter_en":"Affirming the Exaltedness of Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Whoever gives in charity the equivalent of a date from lawful and wholesome earnings — and nothing ascends to Allah except what is good — Allah accepts it with His right hand and then nurtures it for its giver just as one of you raises his young foal, until it becomes like a mountain.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[344,4030],"tks":"متفق عليه: رواه البخاري (7430)، ومسلم (1014)."},{"num":260,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: كَانَ أَبُو ذَرٍّ يُحَدِّثُ قِصَّةُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَفِيهَا: ثُمَّ أَخَذَ بِيَدِي فَعَرَجَ بِي إِلَى السَّمَاءِ الدُّنْيَا....","قَالَ ابْنُ شِهَابٍ: فَأَخْبَرَنِي ابْنُ حَزْمٍ، أَنَّ ابْنَ عَبَّاسٍ وَأَبَا حَبَّةَ الْأَنْصَارِيَّ كَانَا يَقُولَانِ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ثُمَّ عُرِجَ بِي حَتَّى ظَهَرْتُ لِمُسْتَوًى أَسْمَعُ فِيهِ صَرِيفَ الْأَقْلَامِ...(فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ)."],"takhrij":"متفق عليه: رواه البخاريّ في كتاب الصلاة (349)، ومسلم في الإيمان (163) كلاهما من حديث يونس، عن ابن شهاب، عن أنس بن مالك في حديث طويل في قصة الإسراء والمعراج، وسيأتي كاملاً في الموضع المناسب إن شاء الله تعالى.","grade":"متفق عليه","chapter_ar":"باب إثبات العلو لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3342) and Muslim (163).","chapter_en":"Affirming the Exaltedness of Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Anas ibn Mālik, may Allah be pleased with him, reported: Abū Dharr may Allah be pleased with him used to narrate the account of the Miʿrāj from the Prophet ﷺ, and among it was: “Then Jibrīl took me by the hand and ascended with me to the lowest heaven…”","Ibn Shihāb said: Ibn Ḥazm informed me that Ibn ʿAbbās and Abū Ḥayyah al-Anṣārī may Allah be pleased with them used to report that the Prophet ﷺ said: “Then I was taken upward until I reached a level where I could hear the scratching of the pens.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (349)، ومسلم (163)."},{"num":261,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَالَّذِي نَفْسِي بِيَدِهِ، مَا مِنْ رَجُلٍ يَدْعُو امْرَأَتَهُ إِلَى فِرَاشِهَا، فَتَأْبَى عَلَيْهِ، إِلَّا كَانَ الَّذِي فِي السَّمَاءِ سَاخِطًا عَلَيْهَا حَتَّى يَرْضَى عَنْهَا."],"takhrij":"متفق عليه: رواه مسلم في النكاح (1436: 121) عن ابن أبي عمر، حدّثنا مروان، عن يزيد (يعني ابن كيسان)، عن أبي حازم، عن أبي هريرة، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب إثبات العلو لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in al-Nikāḥ (1436:121).","chapter_en":"Affirming the Exaltedness of Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “By the One in whose Hand is my soul, there is no man who calls his wife to his bed and she refuses him except that the One who is in the heaven is displeased with her until her husband is pleased with her.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (1436: 121)."},{"num":262,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ فِي خُطْبَتِهِ يَوْمُ عَرَفَةَ: (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ) وَأَنْتُمْ تُسْأَلُونَ عَنِّي فَمَا أَنْتُمْ قَائِلُونَ ؟ قَالُوا: نَشْهَدُ أَنَّكَ قَدْ بَلَّغْتَ وَأَدَّيْتَ وَنَصَحْتَ، فَقَالَ بِإِصْبَعِهِ السَّبَّابَةِ يَرْفَعُهَا إِلَى السَّمَاءِ وَيَنْكُتُهَا إِلَى النَّاسِ: اللَّهُمَّ اشْهَدِ اللَّهُمَّ اشْهَدْ ثَلَاثَ مَرَّاتٍ...الْحَدِيثَ."],"takhrij":"صحيح: طرف من حديث جابر الطّويل في حجّة النّبيّ صلى الله عليه وسلم، رواه مسلم (1218)، وسيأتي بكامله في كتاب الحجّ.","grade":"صحيح","chapter_ar":"باب إثبات العلو لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1218) in a longer form. It will appear in full in the Book of Ḥajj.","chapter_en":"Affirming the Exaltedness of Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh may Allah be pleased with them reported that during his sermon on the Day of ʿArafah, the Messenger of Allah ﷺ said: “You will be asked about me, so what will you say?” They replied: “We testify that you conveyed the message, fulfilled your duty, and gave sincere counsel.” He then raised his index finger toward the heaven and pointed it toward the people, saying: “O Allah, bear witness. O Allah, bear witness.” He did this three times."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1218) مطولا، وسيأتي بكامله في كتاب الحج."},{"num":263,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ أَنَّ زَيْنَبَ بِنْتِ جَحْشٍ كَانَتْ تَفْخَرُ عَلَى أَزْوَاجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَقُولُ: زَوَّجَكُنَّ أَهَالِيكُنَّ وَزَوَّجَنِي اللَّهُ تَعَالَى مِنْ فَوْقِ سَبْعِ سَمَوَاتٍ.","وَفِي رِوَايَةٍ: تَقُولُ: إِنَّ اللَّهَ أَنْكَحَنِي فِي السَّمَاءِ."],"takhrij":"صحيح: أخرجه البخاريّ في التوحيد (7420) عن أحمد، حدثنا محمد بن أبي بكر المقدميّ، حدّثنا حماد بن زيد، عن ثابت، عن أنس في قصة زيد بن حارثة الذي جاء إلى النبيّ صلى الله عليه وسلم يشكو، وجعل النبيُّ صلى الله عليه وسلم يقول: اتقِ الله وأمسك عليك زوجك. وسيأتي تفصيل ذلك في تفسير سورة الأحزاب.","grade":"صحيح","chapter_ar":"باب إثبات العلو لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (7420).","chapter_en":"Affirming the Exaltedness of Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Anas, may Allah be pleased with him, reported: Zaynab bint Jaḥsh may Allah be pleased with her used to express her distinction over the other wives of the Prophet ﷺ, saying: “Your families gave you in marriage, whereas Allah gave me in marriage from above seven heavens.”","In another wording she said: “Indeed, Allah gave me in marriage in the heaven.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: أخرجه البخاري (7420)."},{"num":264,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى قَالَ: قَامَ فِينَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِخَمْسِ كَلِمَاتٍ، فَقَالَ: إِنَّ اللَّهَ عَزَّ وَجَلَّ، لَا يَنَامُ، وَلَا يَنْبَغِي لَهُ أَنْ يَنَامَ، يَخْفِضُ الْقِسْطَ وَيَرْفَعُهُ، يُرْفَعُ إِلَيْهِ عَمَلُ اللَّيْلِ قَبْلَ عَمَلِ النَّهَارِ، وَعَمَلُ النَّهَارِ قَبْلَ عَمَلِ اللَّيْلِ، حِجَابُهُ النُّورُ.","وَفِي رِوَايَةِ: النَّارُ لَوْ كَشَفَهُ لَأَحْرَقَتْ سُبُحَاتُ وَجْهِهِ، مَا انْتَهَى إِلَيْهِ بَصَرُهُ مِنْ خَلْقِهِ."],"takhrij":"صحيح: رواه مسلم في الإيمان (179) من طرق عن أبي معاوية، حدثنا الأعمش، عن عمرو بن مرّة، عن أبي عبيدة، عن أبي موسى، فذكره.","grade":"صحيح","chapter_ar":"باب إثبات العلو لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (179).","chapter_en":"Affirming the Exaltedness of Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Abū Mūsā, may Allah be pleased with him, reported: The Messenger of Allah ﷺ stood among us and spoke five statements. He said: “Indeed, Allah, Mighty and Majestic, does not sleep, nor is it befitting for Him to sleep. He lowers the Scale and raises it. The deeds of the night are raised to Him before the deeds of the day, and the deeds of the day before the deeds of the night. His veil is light — and in another narration: fire — and if He were to remove it, the radiance of His Face would burn everything of His creation reached by His sight.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (179)."},{"num":265,"demo":false,"sanad":"","matn":["عَنْ مُعَاوِيَةَ بْنِ الْحَكَمِ السُّلَمِيِّ قَالَ (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ): وَكَانَتْ لِي جَارِيَةٌ تَرْعَى غَنَمًا لِي قِبَلَ أُحُدٍ وَالْجَوَّانِيَّةِ، فَاطَّلَعْتُ ذَاتَ يَوْمٍ فَإِذَا الذِّيبُ قَدْ ذَهَبَ بِشَاةٍ مِنْ غَنَمِهَا، وَأَنَا رَجُلٌ مِنْ بَنِي آدَمَ آسَفُ كَمَا يَأْسَفُونَ، لَكِنِّي صَكَكْتُهَا صَكَّةً، فَأَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَعَظَّمَ ذَلِكَ عَلَيَّ، قُلْتُ: يَا رَسُولَ اللَّهِ أَفَلَا أُعْتِقُهَ ؟ قَالَ: ائْتِنِي بِهَا، فَأَتَيْتُهُ بِهَا فَقَالَ لَهَا: أَيْنَ اللَّهُ؟ قَالَتْ: فِي السَّمَاءِ، قَالَ: مَنْ أَنَا؟ قَالَتْ: أَنْتَ رَسُولُ اللَّهِ، قَالَ: أَعْتِقْهَا فَإِنَّهَا مُؤْمِنَةٌ."],"takhrij":"صحيح: رواه مسلم في المساجد (537) من طرق عن إسماعيل بن إبراهيم (هو ابن علية)، عن حجّاج الصّواف، عن يحيى بن أبي كثير، عن هلال بن أبي ميمونة، عن عطاء بن يسار، عن معاوية بن الحكم السلميّ، فذكره في حديث طويل، وسيأتي في النهي عن الكلام في الصّلاة.","grade":"صحيح","chapter_ar":"باب إثبات العلو لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (537).","chapter_en":"Affirming the Exaltedness of Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Muʿāwiyah ibn al-Ḥakam al-Sulamī, may Allah be pleased with him, reported: I had a slave woman who used to tend sheep for me in the direction of Uḥud and al-Jawāniyyah. One day I discovered that a wolf had taken one of her sheep. I am a human being from the children of Adam and become upset as they become upset, so I struck her once. I then went to the Messenger of Allah ﷺ, and he regarded what I had done as a serious matter. I said: “O Messenger of Allah, should I not free her?” He replied: “Bring her to me.” So I brought her to him. He asked her: “Where is Allah?” She replied: “In the heaven.” He asked: “Who am I?” She replied: “You are the Messenger of Allah.” He said: “Free her, for she is a believer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (537)."},{"num":266,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: أَصَابَنَا وَنَحْنُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَطَرٌ، قَالَ: فَحَسَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَوْبَهُ حَتَّى أَصَابَهُ مِنَ الْمَطَرِ، فَقُلْنَا: يَا رَسُولَ اللَّهِ لِمَ صَنَعْتَ هَذَا؟ قَالَ: لِأَنَّهُ حَدِيثُ عَهْدٍ بِرَبِّهِ تَعَالَى."],"takhrij":"صحيح: رواه مسلم في الاستسقاء (898) عن يحيى بن يحيى، أخبرنا جعفر بن سليمان، عن ثابت البنانيّ، عن أنس، فذكره.","grade":"صحيح","chapter_ar":"باب إثبات العلو لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (898).","chapter_en":"Affirming the Exaltedness of Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Anas, may Allah be pleased with him, reported: Rain fell upon us while we were with the Messenger of Allah ﷺ. The Messenger of Allah ﷺ uncovered part of his garment until the rain fell upon him. We asked: “O Messenger of Allah, why did you do this?” He replied: “Because it has only recently come from its Lord, Most High.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (898)."},{"num":267,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ الرَّحِمَ مُعَلَّقَةٌ بِالْعَرْشِ، وَلَيْسَ الْوَاصِلُ بِالْمُكَافِئِ، وَلَكِنَّ الْوَاصِلَ الَّذِي إِذَا انْقَطَعَتْ رَحِمُهُ وَصَلَهَا."],"takhrij":"صحيح: رواه الإمام أحمد عن يعلى بن عبيد (6524)، وعن وكيع (6817) كلاهما عن فِطر (وهو ابن خليفة)، عن مجاهد، عن عبدالله بن عمرو، فذكره.","grade":"صحيح","chapter_ar":"باب إثبات العلو لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Aḥmad (6524, 6817), and authenticated by Ibn Ḥibbān (445).","chapter_en":"Affirming the Exaltedness of Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr may Allah be pleased with them reported that the Messenger of Allah ﷺ said: “Indeed, the bond of kinship is suspended from the Throne. The one who truly maintains kinship is not merely the one who reciprocates, but rather the one who, when his ties of kinship are severed, reconnects them.”"]},"buhuth":{"en":["Its basis is also found in Ṣaḥīḥ al-Bukhārī (5991)."]}},"tuhfa":{},"full":1,"dr":1,"rep":[284],"tks":"صحيح: رواه أحمد (6524، 6817)، وصححه ابن حبان (445)."},{"num":268,"demo":false,"sanad":"","matn":["عَنْ ذَكْوَانَ حَاجِب عَائِشَةَ قَالَ: أَنَّ ابْنَ عَبَّاسٍ دَخَلَ عَلَى عَائِشَةَ وَهِيَ تَمُوتُ، فَقَالَ لَهَا: كُنْتِ أَحَبَّ نِسَاءِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلَمْ يَكُنْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُحِبُّ إِلَّا طَيِّبًا. وَأَنْزَلَ اللَّهُ بَرَاءَتَكِ مِنْ فَوْقِ سَبْعِ سَمَاوَاتٍ، جَاءَ بِهَا الرُّوحُ الْأَمِينُ، فَأَصْبَحَ لَيْسَ لِلَّهِ مَسْجِدٌ مِنْ مَسَاجِدِ اللَّهِ يَذْكُرُ فِيهِ اسْمُ اللَّهِ إِلَّا وَهِيَ تُتْلَى فِيهِ آنَاءَ اللَّيْلِ وَآنَاءَ النَّهَارِ."],"takhrij":"حسن: رواه عثمان بن سعيد الدّارميّ في الرّد على بشر (1/520)، وفي الرّد على الجهميّة (84) عن النّفيليّ، ثنا زهير بن معاوية، ثنا عبدالله بن عثمان ابن خُثيم، حدثني عبدالله بن عبيد الله بن أبي مليكة أنّه حدّثه ذكوان صاحب عائشة، فذكره.","grade":"حسن","chapter_ar":"باب إثبات العلو لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by ʿUthmān ibn Saʿīd al-Dārimī in al-Radd ʿalā Bishr (1/520) and Aḥmad (2496).","chapter_en":"Affirming the Exaltedness of Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Dhakwān, the attendant of ʿĀʾishah, reported: Ibn ʿAbbās may Allah be pleased with them entered upon ʿĀʾishah may Allah be pleased with her while she was near death and said to her: “You were the most beloved of the wives of the Messenger of Allah ﷺ to the Messenger of Allah ﷺ, and the Messenger of Allah ﷺ loved only what was good and pure. Your vindication was sent down from above seven heavens, brought by the Trustworthy Spirit. There is now no mosque among the mosques of Allah in which the Name of Allah is mentioned except that your vindication is recited therein throughout the hours of the night and the hours of the day.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه عثمان بن سعيد الدارمي في الرد على بشر (1/520)، وأحمد (2496)."},{"num":269,"demo":false,"sanad":"","matn":["عَنْ الشَّرِيدِ بْنِ سُوَيْدٍ الثَّقَفِيِّ قَالَ: أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: إِنَّ أُمِّي أَوْصَتْ أَنْ تُعْتَقَ عَنْهَا رَقَبَةٌ، وَإِنَّ عِنْدِي جَارِيَةً نُوبِيَّةً أَفَيُجْزِئُ عَنِّي أَنْ أُعْتِقَهَا عَنْهَا؟ قَالَ: ائْتِنِي بِهَا، فَأَتَيْتُهُ بِهَا، فَقَالَ لَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ رَبُّكِ؟ قَالتْ: اللَّهُ، قَالَ: مَنْ أنَا؟ قَالَتْ: أَنْتَ رَسُولُ اللَّهِ، قَالَ: فَأَعْتِقْهَا فَإِنَّهَا مُؤْمِنَةٌ."],"takhrij":"حسن: رواه أبو داود (3283)، والنسائيّ (3653) كلاهما من طريق حماد ابن سلمة، عن محمد بن عمرو، عن أبي سلمة، عن الشّريد بن سويد، فذكره.","grade":"حسن","chapter_ar":"باب إثبات العلو لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (3283) and al-Nasāʾī (3653).","chapter_en":"Affirming the Exaltedness of Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Al-Sharīd ibn Suwayd al-Thaqafī, may Allah be pleased with him, reported: I came to the Messenger of Allah ﷺ and said: “My mother instructed that a slave be freed on her behalf. I have a Nubian slave woman. Would it fulfill the obligation if I freed her on my mother’s behalf?” He replied: “Bring her to me.” So I brought her to him. He asked: “Who is your Lord?” She replied: “Allah.” He asked: “Who am I?” She replied: “You are the Messenger of Allah.” He said: “Then free her, for she is a believer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3283)، والنسائي (3653)."},{"num":270,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ مِنَ الْأَنْصَارِ أَنَّهُ جَاءَ بِأَمَةٍ سَوْدَاءَ وَقَالَ: يَا رَسُولَ اللَّهِ، إِنَّ عَلَيَّ رَقَبَةً مُؤْمِنَةً، فَإِنْ كُنْتَ تَرَى هَذِهِ مُؤْمِنَةً أَعْتَقْتُهَا، فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَتَشْهَدِينَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ ؟ قَالَتْ: نَعَمْ، قَالَ: أَتَشْهَدِينَ أَنِّي رَسُولُ اللَّهِ؟ قَالَتْ: نَعَمْ، قَالَ: أَتُؤْمِنِينَ بِالْبَعْثِ بَعْدَ الْمَوْتِ ؟ قَالَتْ: نَعَمْ، قَالَ: أَعْتِقْهَا."],"takhrij":"صحيح: رواه الإمام أحمد (15743) عن عبدالرزّاق، وهو في مصنفه (16814)، حدثنا معمر، عن الزّهريّ، عن عبيد الله بن عبدالله، عن رجل من الأنصار، فذكره.","grade":"صحيح","chapter_ar":"باب إثبات العلو لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Imām Aḥmad (15743), ʿAbd al-Razzāq (16814), and Ibn Khuzaymah in Kitāb al-Tawḥīd (223).","chapter_en":"Affirming the Exaltedness of Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["A man from the Anṣār, may Allah be pleased with him, reported: He came with a black slave woman and said: “O Messenger of Allah, I am obligated to free a believing slave. If you consider this woman to be a believer, shall I free her?” The Messenger of Allah ﷺ asked her: “Do you testify that there is no deity worthy of worship except Allah?” She replied: “Yes.” He asked: “Do you testify that I am the Messenger of Allah?” She replied: “Yes.” He asked: “Do you believe in resurrection after death?” She replied: “Yes.” He said: “Free her.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (15743)، وعبد الرزاق (16814)، وابن خزيمة في كتاب التوحيد (223)."},{"num":271,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ الْعَبْدَ الْمُؤْمِنَ إِذَا كَانَ فِي انْقِطَاعٍ مِنَ الدُّنْيَا وَإِقْبَالٍ مِنَ الْآخِرَةِ، نَزَلَ إِلَيْهِ مَلَائِكَةٌ مِنَ السَّمَاءِ... فَسَاقَ الْحَدِيثَ كَمَا سَيَأْتِي بِكَامِلَةٍ فِي إثْبَاتِ عَذَابِ الْقَبْرِ...(فيخرج رُوحُهُ) فَيَصْعَدُونَ بِهَا... حَتَّى يَنْتَهُوا بِهَا إِلَى السَّمَاءِ الدُّنْيَا، فَيَسْتَفْتِحُونَ لَهُ، فَيُفْتَحُ لَهُمْ... حَتَّى يُنْتَهَى بِهِ إِلَى السَّمَاءِ السَّابِعَةِ، فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ: اكْتُبُوا كِتَابَ عَبْدِي فِي عِلِّيِّينَ (فِي السَّمَاءِ السَّابِعَةِ) وَأَعِيدُوهُ إِلَى الْأَرْضِ، فَإِنِّي مِنْهَا خَلَقْتُهُمْ، وَفِيهَا أُعِيدُهُمْ وَمِنْهَا أُخْرِجُهُمْ تَارَةً أُخْرَى...(وَأَمَّا الْكَافِرَ قَالَ) يُنْتَهَى بِهِ إِلَى السَّمَاءِ الدُّنْيَا، فَيُسْتَفْتَحُ لَهُ، فَلَا يُفْتَحُ لَهُ، ثُمَّ قَرَأَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ﴿لَا تُفَتَّحُ لَهُمْ أَبْوَابُ السَّمَاءِ﴾ [سورة الأعراف: 40] فَذَكَرَ الْحَدِيْثُ."],"takhrij":"صحيح: رواه أبو داود (4753) عن هناد بن السّريّ- وهو في زهده (339)، والإمام أحمد (18534) كلاهما، أعني هنّاداً والإمام أحمد، عن أبي معاوية، عن الأعمش، عن المنهال بن عمرو، عن زاذان، عن البراء.","grade":"صحيح","chapter_ar":"باب إثبات العلو لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (4753), Hannād ibn al-Sarī in al-Zuhd (339), and Imām Aḥmad (18534).","chapter_en":"Affirming the Exaltedness of Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Al-Barāʾ ibn ʿĀzib may Allah be pleased with him reported that the Prophet ﷺ said: “When the believing servant is at the point of departing from this world and approaching the Hereafter, Allah sends down to him angels from the heaven…” He then narrated the ḥadīth — which will appear in full later concerning the affirmation of the punishment of the grave — and in it: “His soul comes out, and they ascend with it until they reach the heaven. Permission is sought, and it is opened for him, until they reach the seventh heaven. Allah, Mighty and Majestic, says: ‘Record the book of My servant in ʿIlliyyīn in the seventh heaven, and return him to the earth, for from it I created them, to it I return them, and from it I will bring them forth once again.’” As for the disbeliever: “They take him to the lowest heaven and seek permission for it to be opened, but it is not opened for him.” Then he recited: “The gates of heaven will not be opened for them.” [Sūrat al-Aʿrāf 7:40] Then he continued the ḥadīth."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4753)، وهناد بن السري في الزهد (339)، والإمام أحمد (18534)."},{"num":272,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو يَبْلُغُ بِهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الرَّاحِمُونَ يَرْحَمُهُمُ الرَّحْمَنُ، ارْحَمُوا أَهْلَ الْأَرْضِ يَرْحَمْكُمْ مَنْ فِي السَّمَاءِ."],"takhrij":"حسن: رواه أبو داود (4941)، والترمذيّ (1924) كلاهما من حديث سفيان، عن عمرو بن دينار، عن أبي قابوس مولى لعبدالله بن عمرو، عن عبد الله بن عمرو، فذكره، واللّفظ لأبي داود.","grade":"حسن","chapter_ar":"باب إثبات العلو لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (4941) and al-Tirmidhī (1924), with the wording of Abū Dāwūd.","chapter_en":"Affirming the Exaltedness of Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ may Allah be pleased with them reported from the Prophet ﷺ: “Those who show mercy will be shown mercy by al-Raḥmān. Show mercy to those on the earth, and the One who is in the heaven will show mercy to you.”"]},"buhuth":{"en":["Al-Tirmidhī said:","“Ḥasan Ṣaḥīḥ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4941)، والترمذي (1924)، واللفظ لأبي داود."},{"num":273,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْمَيِّتُ تَحْضُرُهُ الْمَلَائِكَةُ، فَإِذَا كَانَ الرَّجُلُ صَالِحًا، قَالُوا: اخْرُجِي أَيَّتُهَا النَّفْسُ الطَّيِّبَةُ، كَانَتْ فِي الْجَسَدِ الطَّيِّبِ... حَتَّى تَخْرُجَ، ثُمَّ يُعْرَجُ بِهَا إِلَى السَّمَاءِ، فَيُفْتَحُ لَهَا، فَيُقَالُ: مَنْ هَذَا؟ فَيَقُولُونَ: فُلَانٌ، فَيُقَالُ: مَرْحَبًا بِالنَّفْسِ الطَّيِّبَةِ... فَلَا يَزَالُ يُقَالُ لَهَا ذَلِكَ حَتَّى يُنْتَهَى بِهَا إِلَى السَّمَاءِ الَّتِي فِيهَا اللَّهُ عَزَّوَجَلَّ."],"takhrij":"صحيح: رواه ابنُ ماجه (4262) عن أبي بكر بن أبي شيبة، قال: حدّثنا شبابةُ، عن ابن أبي ذئب، عن محمد بن عمرو بن عطاء، عن سعيد بن يسار، عن أبي هريرة، فذكره في حديث طويل سيأتي في الجنائز.","grade":"صحيح","chapter_ar":"باب إثبات العلو لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Ibn Mājah (4262) and Aḥmad (8769).","chapter_en":"Affirming the Exaltedness of Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Prophet ﷺ said: “The angels attend the dying person. If the person is righteous, they say: ‘Come out, O good soul that was within a good body…’ until it comes out. Then it is taken upward to the heaven, and the gate is opened for it. It is asked: ‘Who is this?’ They reply: ‘So-and-so.’ Then it is said: ‘Welcome to the good soul…’ It continues to be greeted in this manner until it reaches the heaven in which Allah, Mighty and Majestic, is.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (4262)، وأحمد (8769)."},{"num":274,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو قَالَ: صَلَّيْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَغْرِبَ، فَرَجَعَ مَنْ رَجَعَ، وَعَقَّبَ مَنْ عَقَّبَ، فَجَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُسْرِعًا قَدْ حَفَزَهُ النَّفَسُ، وَقَدْ حَسَرَ عَنْ رُكْبَتَيْهِ، فَقَالَ: أَبْشِرُوا، هَذَا رَبُّكُمْ قَدْ فَتَحَ بَابًا مِنْ أَبْوَابِ السَّمَاءِ يُبَاهِي بِكُمُ الْمَلَائِكَةَ، يَقُولُ: انْظُرُوا إِلَى عِبَادِي قَدْ قَضَوْا فَرِيضَةً، وَهُمْ يَنْتَظِرُونَ أُخْرَى."],"takhrij":"صحيح: رواه ابن ماجه (801) عن أحمد بن سعيد الدّارميّ، حدّثنا النّضر بن شُميل، قال: حدّثنا حمّاد، عن ثابت، عن أبي أيوب، عن عبدالله بن عمرو بن العاص، فذكره.","grade":"صحيح","chapter_ar":"باب إثبات العلو لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Ibn Mājah (801).","chapter_en":"Affirming the Exaltedness of Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr, may Allah be pleased with them, reported: We prayed Maghrib with the Messenger of Allah ﷺ. Those who wished to leave departed, while others remained waiting. The Messenger of Allah ﷺ then came quickly, breathing heavily from his haste, with his knees uncovered, and said: “Rejoice! Your Lord has opened one of the gates of heaven and is expressing pride in you before the angels, saying: ‘Look at My servants. They have completed one obligatory prayer and are waiting for another.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3051],"tks":"صحيح: رواه ابن ماجه (801)."},{"num":275,"demo":false,"sanad":"","matn":["عَنْ أُسَامَةَ بْنِ زَيْدٍ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ! لَمْ أَرَكَ تَصُومُ شَهْرًا مِنَ الشُّهُورِ مَا تَصُومُ مِنْ شَعْبَانَ؟ قَالَ: ذَلِكَ شَهْرٌ يَغْفُلُ النَّاسُ عَنْهُ بَيْنَ رَجَبٍ وَرَمَضَانَ، وَهُوَ شَهْرٌ تُرْفَعُ فِيهِ الْأَعْمَالُ إِلَى رَبِّ الْعَالَمِينَ، فَأُحِبُّ أَنْ يُرْفَعَ عَمَلِي وَأَنَا صَائِمٌ."],"takhrij":"حسن: رواه النسائيّ (2357) عن عمرو بن علي، عن عبدالرحمن، قال: حدّثنا ثابت بن قيس أبو الغصْن، شيخٌ من أهل المدينة، ، قال: حدّثني أبو سعيد المقبريّ، قال: حدّثني أسامةُ بن زيد، فذكره.","grade":"حسن","chapter_ar":"باب إثبات العلو لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Nasāʾī (2357).","chapter_en":"Affirming the Exaltedness of Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Usāmah ibn Zayd, may Allah be pleased with them, reported: I asked: “O Messenger of Allah, I have not seen you fast during any month as much as you fast during Shaʿbān.” He replied: “That is a month to which people are heedless, between Rajab and Ramaḍān. It is a month in which deeds are raised to the Lord of the worlds, and I love for my deeds to be raised while I am fasting.”"]},"buhuth":{"en":["Imām Aḥmad (21753) also narrated it with the additional wording:","I asked:","“What about Monday and Thursday?”","He replied:","“Those are two days upon which deeds are presented to the Lord of the worlds, and I love for my deeds to be presented while I am fasting.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (2357)."},{"num":276,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَانَ مَلَكُ الْمَوْتِ يَأْتِي النَّاسَ عِيَانًا، فَأَتَى مُوسَى عَلَيْهِ السَّلَامُ فَلَطَمَهُ فَذَهَبَ بِعَيْنِهِ، فَعَرَجَ إِلَى رَبِّهِ عَزَّ وَجَلَّ وَ قَالَ: يَا رَبِّ بَعَثَتْنِي إِلَى مُوسَى فَلَطَمَنِي فَذَهَبَ بِعَيْنِي...."],"takhrij":"صحيح: ذكره الذّهبيّ في العلو (25) من صحيفة همّام بن منبّه وهو فيه (50) وليس فيه: فعرج إلى ربّه عزّ وجلّ بل ولكن فيه: فرجع الملك إلى الله عزّ وجلّ.","grade":"صحيح","chapter_ar":"باب إثبات العلو لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Al-Dhahabī mentioned it in al-ʿUluww (25) from the Ṣaḥīfah of Hammām ibn Munabbih, where it appears as no. 50.","chapter_en":"Affirming the Exaltedness of Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “The Angel of Death used to come to people visibly. He came to Moses, peace be upon him,, and Moses struck him, causing his eye to be lost. So the angel returned to Allah, Mighty and Majestic, and said: ‘My Lord, You sent me to Moses, and he struck me, causing my eye to be lost…’”"]},"buhuth":{"en":["That wording does not contain:","“He ascended to his Lord, Mighty and Majestic,”","but rather:","“The angel returned to Allah, Mighty and Majestic.”","The core narration is found in the two Ṣaḥīḥ collections and elsewhere in both marfūʿ and mawqūf forms."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: ذكره الذهبي في العلو (25) من صحيفة همام بن منبه، وهو فيها (50)."},{"num":277,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اتَّقُوا دَعَوَاتِ الْمَظْلُومِ فَإِنَّهَا تَصْعَدُ إِلَى السَّمَاءِ كَأَنَّهَا شَرَارٌ."],"takhrij":"صحيح: رواه الحاكم (81) من طرق عن أبي كُريب، ثنا حسين بن علي، عن زائدة، عن عاصم بن كليب، عن محارب بن دثار، عن ابن عمر، فذكره.","grade":"صحيح","chapter_ar":"باب إثبات العلو لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Ḥākim (81).","chapter_en":"Affirming the Exaltedness of Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Ibn ʿUmar may Allah be pleased with them reported that the Messenger of Allah ﷺ said: “Beware of the supplications of the oppressed, for they ascend to the heaven as though they were sparks.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10945],"tks":"صحيح: رواه الحاكم (81)."},{"num":278,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا مَكَثَ الْمَنِيَّ فِي الرَّحِمِ أَرْبَعِينَ لَيْلَةً أَتَاهُ مَلَكُ النُّفُوسِ فَعَرَجَ بِهِ إِلَى الرَّبِّ فِي رَاحَتِهِ، فَيَقُولُ: أَيْ رَبِّ عَبْدُكَ هَذَا ذَكَرٌ أَمْ أُنْثَى؟ فَيَقْضِي اللَّهُ إِلَيْهِ مَا هُوَ قَاضٍ، ثُمّ يَقُولُ: أَيْ رَبِّ أَشَقِيٌّ أَمْ سَعِيدٌ؟ فَيَكْتُبُ بَيْنَ عَيْنَيْهِ مَا هُوَ لَاقِ، قَالَ: وَتلاَ أَبُو ذَرٍّ مِنْ فَاتِحَةِ التَّغَابُنِ خَمْسَ آيَاتٍ."],"takhrij":"حسن: رواه عثمان بن سعيد الدّارميّ في الرّد على الجهميّة (94) عن عمرو بن خالد الحرانيّ، ثنا ابن لهيعة، عن بكر بن سوادة، عن أبي تميم الجيشانيّ، عن أبي ذر الغفاري، فذكره.","grade":"حسن","chapter_ar":"باب إثبات العلو لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan due to corroborating evidence: Narrated by ʿUthmān ibn Saʿīd al-Dārimī in al-Radd ʿalā al-Jahmiyyah (94).","chapter_en":"Affirming the Exaltedness of Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Abū Dharr may Allah be pleased with him reported that the Prophet ﷺ said: “When the semen has remained in the womb for forty nights, the angel of souls comes to it and ascends with it to the Lord in the palm of his hand. He says: ‘My Lord, is this servant of Yours male or female?’ Allah then decrees concerning it whatever He decrees. Then he asks: ‘My Lord, wretched or blessed?’ Then what he will encounter is written between his eyes.” Abū Dharr then recited five verses from the beginning of Sūrat al-Taghābun."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه عثمان بن سعيد الدارمي في الرد على الجهمية (94)."},{"num":279,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: كُنْتُ جَالِسًا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْحَلْقَةِ إِذْ جَاءَ رَجُلٌ فَسَلَّمَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَ عَلَى الْقَوْمِ، فَقَالَ: السَّلَامُ عَلَيْكُمْ، فَرَدَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَلَيْكُمْ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ فَلَمَّا جَلَسَ الرَّجُلُ قَالَ: الْحَمْدُ لِلَّهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ كَمَا يُحِبُّ رَبُّنَا وَيَرْضَى. فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَيْفَ قُلْتَ؟ فَرَدَّ عَلَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَمَا قَالَ، فَقَالَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَالَّذِي نَفْسِي بِيَدِهِ لَقَدْ ابْتَدَرَهَا عَشَرَةُ أَمْلَاكٍ كُلُّهُمْ حَرِيصٌ عَلَى أَنْ يَكْتُبُوهَا فَبَا دَرَوْا كَيْفَ يَكْتُبُونهَا حَتَّى رَفَعُوه إِلَى ذِي الْعِزَّةِ فَقَال:َ اكْتُبُوهَا كَمَا قَالَ عَبْدِي."],"takhrij":"حسن: رواه النسائيّ في عمل اليوم والليلة (341) عن قتيبة بن سعيد، قال: حدّثنا خلف، عن ابن أخي أنس، عن أنس، فذكره.","grade":"حسن","chapter_ar":"باب إثبات العلو لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Nasāʾī in ʿAmal al-Yawm wa al-Laylah (341) and Aḥmad (12612), and authenticated by Ibn Ḥibbān (845).","chapter_en":"Affirming the Exaltedness of Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Anas, may Allah be pleased with him, reported: I was sitting with the Messenger of Allah ﷺ in a gathering when a man came and greeted the Prophet ﷺ and the people, saying: “Peace be upon you.” The Prophet ﷺ replied: “And upon you be peace, the mercy of Allah, and His blessings.” When the man sat down, he said: “All praise belongs to Allah — abundant, good, and blessed praise — just as our Lord loves and is pleased with.” The Prophet ﷺ asked him: “How did you say it?” He repeated exactly what he had said. The Prophet ﷺ then said: “By the One in whose Hand is my soul, ten angels rushed toward those words, each one eager to record them. They did not know how to record them until they raised them to the Possessor of Might. He said: ‘Write them exactly as My servant said them.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي في عمل اليوم والليلة (341)، وأحمد (12612)، وصححه ابن حبان (845)."},{"num":280,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَمَّا كَانَتْ اللَّيْلَةُ الَّتِي أُسْرِيَ بِي فِيهَا، أَتَتْ عَلَيَّ رَائِحَةٌ طَيِّبَةٌ، فَقُلْتُ: يَا جِبْرِيلُ، مَا هَذِهِ الرَّائِحَةُ الطَّيِّبَةُ؟ فَقَالَ: هَذِهِ رَائِحَةُ مَاشِطَةِ ابْنَةِ فِرْعَوْنَ وَأَوْلَادِهَا، قَالَ: قُلْتُ وَمَا شَأْنُهَا؟ قَالَ: بَيْنَا هِيَ تُمَشِّطُ ابْنَةَ فِرْعَوْنَ ذَاتَ يَوْمٍ، إِذْ سَقَطَتْ الْمِدْرَى مِنْ يَدَيْهَا، فَقَالَتْ: بِسْمِ اللَّهِ، فَقَالَتْ لَهَا ابْنَةُ فِرْعَوْنَ: أَبِي؟ قَالَتْ: لَا وَلَكِنْ رَبِّي وَرَبُّ أَبِيكِ اللَّهُ. قَالَتْ: أُخْبِرُهُ بِذَلِكَ؟ قَالَتْ: نَعَمْ. فَأَخْبَرَتْهُ فَدَعَاهَا، فَقَالَ: يَا فُلَانَةُ وَإِنَّ لَكِ رَبًّا غَيْرِي، قَالَتْ: نَعَمْ، رَبِّي وَرَبُّكَ اللَّهُ، فَأَمَرَ بِبَقَرَةٍ مِنْ نُحَاسٍ فَأُحْمِيَتْ، ثُمَّ أَمَرَ بِهَا أَنْ تُلْقَى هِيَ وَأَوْلَادُهَا فِيهَا، قَالَتْ لَهُ: إِنَّ لِي إِلَيْكَ حَاجَةً، قَالَ: وَمَا حَاجَتُكِ؟ قَالَتْ: أُحِبُّ أَنْ تَجْمَعَ عِظَامِي وَعِظَامَ وَلَدِي فِي ثَوْبٍ وَاحِدٍ، وَتَدْفِنَنَا، قَالَ: ذَلِكَ لَكِ عَلَيْنَا مِنَ الْحَقِّ، قَالَ: فَأَمَرَ بِأَوْلَادِهَا فَأُلْقُوا بَيْنَ يَدَيْهَا وَاحِدًا وَاحِدًا، إِلَى أَنْ انْتَهَى ذَلِكَ إِلَى صَبِيٍّ لَهَا مُرْضَعٍ، وَكَأَنَّهَا تَقَاعَسَتْ مِنْ أَجْلِهِ، قَالَ: يَا أُمَّهْ، اقْتَحِمِي، فَإِنَّ عَذَابَ الدُّنْيَا أَهْوَنُ مِنْ عَذَابِ الْآخِرَةِ فَاقْتَحَمَتْ.","وَفِي رِوَايَةِ: قَالَتْ: رَبِّي وَرَبُّكَ مَنْ فِي السَّمَاءِ.","قَالَ ابْنُ عَبَّاسٍ: تَكَلَّمَ أَرْبَعَةٌ صِغَارٌ عِيسَى ابْنُ مَرْيَمَ عَلَيْهِ السَّلَام، وَصَاحِبُ جُرَيْجٍ، وَشَاهِدُ يُوسُفَ، وَابْنُ مَاشِطَةِ ابْنَةِ فِرْعَوْنَ.","وَفِي رِوَايَةِ: قَالَ: وَالرَّابِعُ لا أَحْفَظُهُ."],"takhrij":"صحيح: رواه الإمام أحمد (2821)، وأبو يعلى (2517)، والبزّار- كشف الأستار (54)، والطبرانيّ في الكبير (12279) كلّهم من طرق عن حمّاد بن سلمة، عن عطاء بن السّائب، عن سعيد بن جبير، عن ابن عباس، فذكره، واللّفظ لأحمد.","grade":"صحيح","chapter_ar":"باب إثبات العلو لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Imām Aḥmad (2821), Abū Yaʿlā (2517), and al-Bazzār in Kashf al-Astār (54), with the wording of Aḥmad.","chapter_en":"Affirming the Exaltedness of Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Ibn ʿAbbās may Allah be pleased with them reported that the Messenger of Allah ﷺ said: “On the night when I was taken on the Night Journey, a pleasant fragrance came to me. I asked: ‘O Jibrīl, what is this pleasant fragrance?’ He replied: ‘This is the fragrance of the woman who combed the hair of Pharaoh’s daughter and of her children.’ I asked: ‘What was her story?’ He replied: ‘One day, while she was combing Pharaoh’s daughter’s hair, the comb fell from her hand, and she said: “In the Name of Allah.” Pharaoh’s daughter asked: “My father?” She replied: “No. Rather, my Lord and your father’s Lord is Allah.” She asked: “Shall I tell him that?” She replied: “Yes.” So she informed him. Pharaoh summoned the woman and asked: “O so-and-so, do you have a lord other than me?” She replied: “Yes. My Lord and your Lord is Allah.” He ordered a large vessel of copper to be heated and then ordered that she and her children be thrown into it. She said to him: “I have one request of you.” He asked: “What is your request?” She replied: “I would like you to gather my bones and the bones of my children together in one cloth and bury us.” He replied: “That is a right you have upon us.” He then ordered her children to be thrown before her one by one until it came to her nursing infant. She appeared to hesitate because of him. The child said: “O mother, plunge in, for the punishment of this world is lighter than the punishment of the Hereafter.” So she plunged in.’” In another narration, she said: “My Lord and your Lord is the One who is in the heaven.”","Ibn ʿAbbās said: “Four children spoke while still very young: Jesus son of Mary peace be upon him, the child associated with Jurayj, the witness of Joseph, and the son of the woman who combed Pharaoh’s daughter’s hair.”","In another narration he said:","“And the fourth, I do not remember.”"]},"buhuth":{"en":["What the imams said regarding the Attribute of Highness/Exaltation (al-ʿuluww)","Al-Dhahabī said in al-ʿUluww (332): “It has reached us from Abū Muṭīʿ al-Ḥakam ibn ʿAbdullāh al-Balkhī, the author of al-Fiqh al-Akbar, that he said: ‘I asked Abū Ḥanīfah about someone who says: I do not know my Lord—whether He is in the heaven or on the earth. He said: He has disbelieved, because Allah says, “The Most Merciful rose over the Throne” [Ṭā Hā 20:5], and His Throne is above His heavens. I said: What if he says: I say He rose over the Throne, but I do not know whether the Throne is in the heaven or on the earth? He said: If he denies that it is in the heaven, then he has disbelieved.’”","He also said: “Allah Most High is called upon from above, not from below, because ‘below’ is not a description of Lordship or Divinity in any way.”","Mālik (may Allah have mercy on him) said: “Allah is in the heaven, and His knowledge is in every place; nothing is devoid of His knowledge.” al-ʿUluww (343).","Mālik was asked about Allah’s statement, “The Most Merciful rose over the Throne” [Ṭā Hā 20:5]: “How did He rise over it?” Mālik lowered his head and sweat came over him while the people waited to see what he would say. He then raised his head and said: “The rising over is not unknown; the ‘how’ is not comprehensible; believing in it is obligatory; asking about it is an innovation; and I think you are a bad man.” He then ordered that the man be removed. Ibn Qudāmah mentioned it in Ithbāt Ṣifat al-ʿUluww (p. 28), and al-Bayhaqī in al-Iʿtiqād (p. 116).","Abū ʿUthmān al-Ṣābūnī (d. 449 AH) reported the wording: “The rising over is known, the ‘how’ is unknown, believing in it is obligatory, and asking about it is an innovation; and I think you are a heretic, so remove him from the mosque.”","Al-Shāfiʿī (may Allah have mercy on him) said: “The position regarding the Sunnah upon which I am, and upon which I saw our companions—the people of ḥadīth whom I met and learned from—is affirming the testimony that there is no deity except Allah and that Muḥammad is the Messenger of Allah ﷺ, and that Allah Most High is upon His Throne in His heaven; He draws near to His creation however He wills; and Allah Most High descends to the lowest heaven however He wills.” Al-Dhahabī mentioned it in al-ʿUluww (404), with this meaning or close to it.","Al-Ḥākim reported that al-Aṣamm said: I heard al-Rabīʿ say: I heard al-Shāfiʿī—after he narrated a ḥadīth—when a man said, “Do you take this, O Abū ʿAbdullāh?” He replied: “If I narrate an authentic ḥadīth from the Messenger of Allah ﷺ and do not act upon it, then bear witness that my mind has gone.” al-ʿUluww (406).","ʿAbdullāh ibn Aḥmad said: It was said to my father: “Our Lord, Blessed and Exalted, is above the seventh heaven upon His Throne, distinct from His creation, while His power and knowledge are in every place?” He said: “Yes; nothing is devoid of His knowledge.” Ijtimāʿ al-Juyūsh al-Islāmiyyah by Ibn al-Qayyim (p. 135).","Based on these reports, the early imams stated that it is permissible to ask about Allah using “Where?”, and permissible for the one asked to say that He is in the heaven and to point upward with the fingers.","As for the claim that “being with” means that Allah mixes with creation in His Essence and that He is in every place in His Essence, this is a false statement attributed to people of incarnationism and extremists among some Ṣūfīs. The imams of the Salaf and later scholars refuted this view, including Abū Ḥanīfah, Mālik, al-Shāfiʿī, Aḥmad, Isḥāq ibn Rāhawayh, Ibn Taymiyyah, Ibn al-Qayyim, Muḥammad ibn ʿAbd al-Wahhāb, Ibn Bāz, and other Sunni scholars.","They explained Allah’s statement, “And He is with you wherever you may be, and Allah sees all that you do” [al-Ḥadīd 57:4], and similar verses, as referring to His knowledge, while He is above the heavens and established over the Throne as stated in His Book.","Ibn ʿAbd al-Barr said: “The scholars among the Companions and the Tābiʿīn whose interpretations have been transmitted agreed regarding the interpretation of His statement, ‘There is no private conversation among three except that He is the fourth of them’ [al-Mujādilah 58:7], that He is over the Throne and His knowledge is in every place, and no one whose statement is relied upon differed with them.”","Shaykh Ibn Bāz (may Allah have mercy on him) said: “Among what is established in the Qurʾān and Sunnah, and what the early generations of this Ummah agreed upon, is that Allah Most High is above His creation, distinct from them, established over His Throne in a manner befitting His majesty, not resembling created beings in their rising; and He is with them by His knowledge—nothing about them is hidden from Him. This is what the Qurʾān indicates in the clearest expressions and what the Sunnah indicates through authentic and explicit reports.” al-ʿAqīdah al-Ṣaḥīḥah wa-mā Yuḍāddihā (p. 39).","The statements of the Salaf on this meaning are too numerous to enumerate."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (2821)، وأبو يعلى (2517)، والبزار في كشف الأستار (54)، واللفظ لأحمد."},{"num":281,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَمَّا قَضَى اللَّهُ الْخَلْقَ كَتَبَ فِي كِتَابِهِ فَهُوَ عِنْدَهُ فَوْقَ الْعَرْشِ: إِنَّ رَحْمَتِي غَلَبَتْ غَضَبِي."],"takhrij":"متفق عليه: رواه البخاريّ في بدء الخلق (3194)، ومسلم في التوبة (2751) كلاهما من حديث أبي الزّناد، عن الأعرج، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في استواء الله تعالى على العرش","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3194) and Muslim (2751).","chapter_en":"What Has Been Reported Concerning Allah Most High Rising Over the Throne","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “When Allah completed the creation, He wrote in His Book — which is with Him above the Throne: ‘Indeed, My mercy has overcome My wrath.’”"]},"buhuth":{"en":["Ibn Khuzaymah said:","“This report indicates that our Lord, Majestic and Exalted, is above His Throne, and that His Book containing the words, ‘Indeed, My mercy has overcome My wrath,’ is with Him.”"]},"intro":{"ar":["قال الله تعالى:","﴿الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى﴾","[طه: ٥]","وقال تعالى:","﴿ثُمَّ اسْتَوَى عَلَى الْعَرْشِ﴾","[الأعراف: ٥٤؛ يونس: ٣؛ الرعد: ٢؛ الفرقان: ٥٩؛ السجدة: ٤؛ الحديد: ٤]","ومعنى قوله:","﴿اسْتَوَى عَلَى الْعَرْشِ﴾","علا على العرش.","قال ابن عباس رضي الله عنهما:","«الكرسي موضع القدمين، والعرش لا يقدر أحد قدره».","رواه الحاكم (٢/٢٨٢)، وصححه وقال: على شرط الشيخين.","Ibn ʿAbbās رضي الله عنهما said:"],"en":["Allah Most High said:","“The Most Merciful rose over the Throne.”","[Sūrat Ṭā Hā 20:5]","And He said:","“Then He rose over the Throne.”","[Sūrat al-Aʿrāf 7:54; Yūnus 10:3; al-Raʿd 13:2; al-Furqān 25:59; al-Sajdah 32:4; al-Ḥadīd 57:4]","The meaning of His statement:","“Rose over the Throne”","is: He rose above the Throne.","“The Kursī is the place of the Feet, and no one can estimate the magnitude of the Throne.”","Narrated by al-Ḥākim (2/282), who authenticated it and said that it meets the conditions of al-Bukhārī and Muslim."]}},"tuhfa":{},"full":1,"dr":1,"rep":[492,1009,11401,12307],"tks":"متفق عليه: رواه البخاري (3194)، ومسلم (2751)."},{"num":282,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِأَبِي ذَرٍّ حِينَ غَرَبَتِ الشَّمْسُ: تَدْرِي أَيْنَ تَذْهَبُ؟ قُلْتُ: اللَّهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: فَإِنَّهَا تَذْهَبُ حَتَّى تَسْجُدَ تَحْتَ الْعَرْشِ....(فَذَكَرَ الْحَدِيثَ)."],"takhrij":"متفق عليه: رواه البخاريّ في بدء الخلق (3199)، ومسلم في الإيمان (159) كلاهما من حديث إبراهيم التيميّ، عن أبيه، عن أبي ذر في حديث طويل، وهو مذكور في موضعه.","grade":"متفق عليه","chapter_ar":"باب ما جاء في استواء الله تعالى على العرش","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3199) and Muslim (159).","chapter_en":"What Has Been Reported Concerning Allah Most High Rising Over the Throne","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["Abū Dharr, may Allah be pleased with him, reported: When the sun set, the Prophet ﷺ asked Abū Dharr: “Do you know where it goes?” I replied: “Allah and His Messenger know best.” He said: “It goes until it prostrates beneath the Throne…”"]},"buhuth":{"en":["In another narration, Abū Dharr said:","I asked the Messenger of Allah ﷺ concerning the statement of Allah Most High:","“And the sun runs to its resting place.”","[Sūrat Yā Sīn 36:38]","He replied:","“Its resting place is beneath the Throne.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3199)، ومسلم (159)."},{"num":283,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الرَّحِمُ مُعَلَّقَةٌ بِالْعَرْشِ، تَقُولُ: مَنْ وَصَلَنِي وَصَلَهُ اللَّهُ، وَمَنْ قَطَعَنِي قَطَعَهُ اللَّهُ."],"takhrij":"متفق عليه: رواه مسلم في البر والصّلة (2555)، والبخاري في الأدب (5989) كلاهما من حديث معاوية بن أبي مُزرِّد، عن يزيد بن رومان، عن عروة، عن عائشة، فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء في استواء الله تعالى على العرش","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (2555) and al-Bukhārī (5989).","chapter_en":"What Has Been Reported Concerning Allah Most High Rising Over the Throne","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["ʿĀʾishah may Allah be pleased with her reported that the Messenger of Allah ﷺ said: “The bond of kinship is suspended from the Throne, saying: ‘Whoever maintains me, Allah will maintain him; and whoever cuts me off, Allah will cut him off.’”"]}},"tuhfa":{},"full":1,"rep":[14057],"tks":"متفق عليه: رواه مسلم (2555)، والبخاري (5989)."},{"num":284,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو قَالَ: قَالَ رَسُولُ اللّَهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ الرَّحِمَ مُعَلَّقَةٌ بِالْعَرْشِ، وَلَيْسَ الْوَاصِلُ بِالْمُكَافِئِ، وَلَكِنَّ الْوَاصِلَ الَّذِي إِذَا انْقَطَعَتْ رَحِمُهُ وَصَلَهَا."],"takhrij":"صحيح: رواه الإمام أحمد عن يعلى بن عبيد (6524)، وعن وكيع (6817) كلاهما عن فِطر (وهو ابن خليفة)، عن مجاهد، عن عبدالله بن عمرو، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في استواء الله تعالى على العرش","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Imām Aḥmad (6524, 6817), and authenticated by Ibn Ḥibbān (445).","chapter_en":"What Has Been Reported Concerning Allah Most High Rising Over the Throne","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr may Allah be pleased with them reported that the Messenger of Allah ﷺ said: “Indeed, the bond of kinship is suspended from the Throne. The one who truly maintains kinship is not merely the one who reciprocates; rather, the one who truly maintains it is the one who reconnects his ties of kinship when they are severed.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[267],"tks":"صحيح: رواه الإمام أحمد (6524، 6817)، وصححه ابن حبان (445)."},{"num":285,"demo":false,"sanad":"","matn":["عَنْ وَهْبِ بْنِ جَابِرٍ الْخَيْوَانِيِّ قَالَ: كُنْتُ عِنْدَ عَبْدِ اللَّهِ بْن عَمْرِو بْنِ الْعَاصِ، فَقَدِمَ عَلَيْهِ قَهْرَمَانٌ مِنَ الشَّامِ، وَقَدْ بَقِيَتْ لَيْلَة مِنْ رَمَضَانَ، فَقَالَ لَهُ عَبْدُ اللَّهِ: هَلْ تَرَكْتَ عِنْدَ أَهْلِي مَا يَكْفِيهِمْ؟ قَالَ: قَدْ تَرَكْتُ عِنْدَهُمْ نَفَقَةً، فَقَالَ عَبْدُ اللَّهِ: عَزَمْتُ عَلَيْكَ لَمَا رَجَعْتَ، وَ تَرَكْتَ لَهُمْ مَا يَكْفِيهِمْ، فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: كَفَى بِالْمَرْءِ إِثْمًا أَنْ يُضَيِّعَ مَنْ يَقُوتُ. قَالَ: ثُمَّ أَنْشَأَ يُحَدِّثُنَا قَالَ: إِنَّ الشَّمْسَ إِذَا غَرَبَتْ سَلَّمَتْ وَسَجَدَتْ وَاسْتَأْذَنَتْ، قَالَ فَيُؤْذَنُ لَهَا، حَتَّى إِذَا كَانَ يَوْمًا غَرَبَتْ، فَسَلَّمَتْ وَسَجَدَتْ وَاسْتَأْذَنْتُ، فَلا يُؤَذِّنُ لَهَا، فَتَقُولُ: أَيْ رَبِّ، إِنَّ الْمَسِيرَ بَعِيدٌ وَإِنِّي لا يُؤْذَنَ لِي لا أَبْلُغُ، قَالَ: فَتُحْبَسُ مَا شَاءَ اللَّهُ، ثُمَّ يُقَالُ لَهَا: اطْلُعِي مِنْ حَيْثُ غَرَبْتِ، قَالَ: فَمِنْ يَوْمِئِذٍ إِلَى يَوْمِ الْقِيَامَةِ ﴿لَا يَنْفَعُ نَفْسًا إِيمَانُهَا لَمْ تَكُنْ آمَنَتْ مِنْ قَبْلُ﴾ [سورة الأنعام: 158]. قَالَ: وَذَكَرَ يَأْجُوجَ وَمَأْجُوجَ، قَالَ: وَمَا يَمُوتُ الرَّجُلُ مِنْهُمْ، حَتَّى يُولَدَ لَهُ مِنْ صُلْبِهِ أَلْفٌ، وَإِنَّ مِنْ وَرَائِهِمْ ثَلاثُ أُمَمٍ، مَا يَعْلَمُ عِدَّتَهُمْ إِلا اللَّهُ: مَنْسَكُ، وَتَاوِيلُ، وَتَارِيسُ."],"takhrij":"حسن: رواه عبدالرزّاق في المصنف (21887) عن معمر، عن أبي إسحاق، عن وهب بن جابر الخيوانيّ، به، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في استواء الله تعالى على العرش","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by ʿAbd al-Razzāq in al-Muṣannaf (20810) and al-Ḥākim (8526).","chapter_en":"What Has Been Reported Concerning Allah Most High Rising Over the Throne","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["Wahb ibn Jābir al-Khaywānī reported: I was with ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ may Allah be pleased with them when a steward of his arrived from al-Shām, with only one night of Ramaḍān remaining. ʿAbdullāh asked him: “Did you leave with my family enough to provide for them?” He replied: “I left them some money for their expenses.” ʿAbdullāh said: “I insist that when you return, you leave them enough to provide for them, for I heard the Messenger of Allah ﷺ say: ‘It is sufficient sin for a man that he neglect those whom he is responsible for supporting.’” Then he began narrating to us and said: “Indeed, when the sun sets, it gives salām, prostrates, and seeks permission, and permission is granted to it. Then a day will come when it sets, gives salām, prostrates, and seeks permission, but permission will not be granted to it. It will say: ‘My Lord, the journey is long, and if permission is not granted to me, I will not reach my destination.’ It will then be held for as long as Allah wills. Then it will be said to it: ‘Rise from the place where you set.’ From that day until the Day of Resurrection: ‘No soul will benefit from its faith if it had not believed before.’” [Sūrat al-Anʿām 6:158] He then mentioned Yaʾjūj and Maʾjūj and said: “A man among them will not die until one thousand descendants have been born from his loins. Beyond them are three nations whose numbers no one knows except Allah: Mansak, Tāwīl, and Tāwīs.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه عبد الرزاق في المصنف (21887)، والحاكم (8526)."},{"num":286,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَنَا سَيِّدُ النَّاسِ يَوْمَ الْقِيَامَةِ....فَذَكَرَ حَدِيثَ الشَّفَاعَةِ الطَّوِيلِ، وَهُوَ مَخْرَجُ فِي مَوْضِعِهِ، وَفِيهِ: فَأَنْطَلِقُ فَآتِي تَحْتَ الْعَرْشِ فَأَقَعُ سَاجِدًا لِرَبِّي، ثُمَّ يَفْتَحُ اللَّهُ عَلَيَّ وَيُلْهِمُنِي مِنْ مَحَامِدِهِ وَحُسْنِ الثَّنَاءِ عَلَيْهِ شَيْئًا لَمْ يَفْتَحْهُ لِأَحَدٍ قَبْلِي....الْحَدِيثَ."],"takhrij":"متفق عليه: رواه البخاريّ في التفسير (4712)، ومسلم في الإيمان (194) كلاهما من حديث أبي حيان التيميّ، عن أبي زرعة بن عمرو بن جرير، عن أبي هريرة، فذكر الحديث بطوله، ولفظهما قريب.","grade":"متفق عليه","chapter_ar":"باب ما جاء في استواء الله تعالى على العرش","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4712) and Muslim (194).","chapter_en":"What Has Been Reported Concerning Allah Most High Rising Over the Throne","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Prophet ﷺ said: “I will be the master of mankind on the Day of Resurrection…” He then narrated the lengthy ḥadīth of intercession, which is presented in full in its proper place. Among its words are: “Then I will go and come beneath the Throne, and I will fall down in prostration before my Lord. Allah will then open for me and inspire me with forms of praise and beautiful glorification of Him that He had not opened for anyone before me…”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4712)، ومسلم (194)."},{"num":287,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: سَبْعَةٌ يُظِلُّهُمُ اللَّهُ فِي ظِلِّهِ يَوْمَ لَا ظِلَّ إِلَّا ظِلُّهُ....وَسَاقَ الْحَدِيثَ وَهُوَ مَذْكُورٌ فِي مَوْضِعِهِ."],"takhrij":"متفق عليه: رواه مالك في كتاب الشعر (14) عن خُبيب بن عبدالرحمن الأنصاريّ، عن حفص بن عاصم، عن أبي سعيد الخدريّ أو عن أبي هريرة، فذكره","grade":"متفق عليه","chapter_ar":"باب ما جاء في استواء الله تعالى على العرش","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (14), Muslim (1031), and al-Bukhārī (660).","chapter_en":"What Has Been Reported Concerning Allah Most High Rising Over the Throne","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Seven will be shaded by Allah in His shade on the Day when there will be no shade except His shade…” He then narrated the remainder of the ḥadīth, which is recorded in its proper place."]},"buhuth":{"en":["The words:","“In His shade”","mean: the shade of His Throne."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (14)، ومسلم (1031)، والبخاري (660)."},{"num":288,"demo":false,"sanad":"","matn":["عَنْ مَسْرُوقٍ قَالَ: سَأَلْنَا عَبْدِ اللَّهِ بْنُ مَسْعُودٍ عَنْ هَذِهِ الْآيَةِ ﴿وَلَا تَحْسَبَنَّ الَّذِينَ قُتِلُوا فِي سَبِيلِ اللَّهِ أَمْوَاتًا بَلْ أَحْيَاءٌ عِنْدَ رَبِّهِمْ يُرْزَقُونَ﴾ [آل عمران: 169]، فَقَالَ: أَمَا إِنَّا قَدْ سَأَلْنَا عَنْ ذَلِكَ، فَقَالَ: أَرْوَاحُهُمْ فِي جَوْفِ طَيْرٍ خُضْرٍ لَهَا قَنَادِيلُ مُعَلَّقَةٌ بِالْعَرْشِ تَسْرَحُ مِنَ الْجَنَّةِ حَيْثُ شَاءَتْ ثُمَّ تَأْوِي إِلَى تِلْكَ الْقَنَادِيلِ...فَذَكَرَ الْحَدِيثَ بِطُولِهِ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1887) من طرق عن الأعمش، عن عبدالله ابن مرّة، عن مسروق، فذكر الحديث، وسيأتي بكامله في موضعه.","grade":"صحيح","chapter_ar":"باب ما جاء في استواء الله تعالى على العرش","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1887).","chapter_en":"What Has Been Reported Concerning Allah Most High Rising Over the Throne","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["Masrūq reported: We asked ʿAbdullāh ibn Masʿūd may Allah be pleased with him concerning the verse: “Do not think of those who have been killed in the way of Allah as dead. Rather, they are alive with their Lord, receiving provision.” [Āl ʿImrān 3:169] He replied: “We indeed asked about that, and he said: ‘Their souls are within green birds. They have lamps suspended from the Throne. They roam freely in Paradise wherever they wish, then return to those lamps.’” He then mentioned the remainder of the lengthy ḥadīth."]},"buhuth":{"en":["Regarding the words:","“We asked about that,”","the apparent meaning is that the one who was asked was the Prophet ﷺ. He was not explicitly named because this was already understood, as Ibn al-Qayyim stated in Tahdhīb al-Sunan (3/374)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1887)."},{"num":289,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَجْمَعُ اللَّهُ الْأَوَّلِينَ وَالْآخَرِينَ لِمِيقَاتِ يَوْمٍ مَعْلُومٍ أَرْبَعِينَ سَنَةً شَاخِصَةً أَبْصَارُهُمْ إِلَى السَّمَاءِ يَنْتَظِرُونَ فَصْلَ الْقَضَاءِ، وَيَنْزِلُ اللَّهُ فِي ظُلَلٍ مِنَ الْغَمَامِ مِنَ الْعَرْشِ إِلَى الْكُرْسِيِّ...الْحَدِيثَ بِطُولِهِ."],"takhrij":"حسن: رواه ابن منده في التوحيد (531) من طرق عن إسماعيل بن عبيد بن أبي كريمة، حدّثنا محمد بن سلمة، عن أبي عبدالرحيم خالد بن أبي يزيد، عن زيد ابن أبي أنيسة، عن المنهال بن عمرو، عن أبي عبيدة، عن مسروق بن الأجدع، عن عبدالله بن مسعود، فذكر الحديث بطوله.","grade":"حسن","chapter_ar":"باب ما جاء في استواء الله تعالى على العرش","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Mandah in al-Tawḥīd (531).","chapter_en":"What Has Been Reported Concerning Allah Most High Rising Over the Throne","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd may Allah be pleased with him reported that the Prophet ﷺ said: “Allah will gather the first and the last generations for the appointed time of a known Day for forty years, their eyes fixed toward the heaven as they await the decisive judgment. Allah will descend in canopies of clouds from the Throne to the Kursī…” The ḥadīth continues at length."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن منده في التوحيد (531)."},{"num":290,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى يَقُولُ يَوْمَ الْقِيَامَةِ: أَيْنَ الْمُتَحَابُّونَ لِجَلَالِي؟ الْيَوْمَ أُظِلُّهُمْ فِي ظِلِّي يَوْمَ لَا ظِلَّ إِلَّا ظِلِّي."],"takhrij":"صحيح: رواه مالك في كتاب الشعر (13) عن عبدالله بن عبدالرحمن بن معمر، عن أبي الحباب سعيد بن يسار، عن أبي هريرة، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في استواء الله تعالى على العرش","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Mālik (13) and Muslim (2566).","chapter_en":"What Has Been Reported Concerning Allah Most High Rising Over the Throne","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Indeed, Allah, Blessed and Exalted, will say on the Day of Resurrection: ‘Where are those who loved one another for My majesty? Today I will shade them in My shade, on the Day when there will be no shade except My shade.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (13)، ومسلم (2566)."},{"num":291,"demo":false,"sanad":"","matn":["عَنِ الْعِرْبَاضِ بْنِ سَارِيَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قَالَ اللَّهُ عَزَّ وَجَلَّ: الْمُتَحَابُّونَ بِجَلَالِي فِي ظِلِّ عَرْشِي يَوْمَ لَا ظِلَّ إِلَّا ظِلِّي."],"takhrij":"حسن: رواه الإمام أحمد (17158)، والطبرانيّ في الكبير (644) كلاهما من حديث إسماعيل بن عياش، عن صفوان بن عمرو، عن عبدالرحمن بن ميسرة، عن العرباض بن سارية، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في استواء الله تعالى على العرش","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (17158) and al-Ṭabarānī in al-Muʿjam al-Kabīr (8/258).","chapter_en":"What Has Been Reported Concerning Allah Most High Rising Over the Throne","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["Al-ʿIrbāḍ ibn Sāriyah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Allah, Mighty and Majestic, said: ‘Those who love one another for My majesty will be beneath the shade of My Throne on the Day when there will be no shade except My shade.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[487,16167],"tks":"حسن: رواه الإمام أحمد (17158)، والطبراني في الكبير (644)."},{"num":292,"demo":false,"sanad":"","matn":["عَنْ مُعَاذِ بْنِ جَبَلٍ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: قَالَ اللَّهُ تَبَارَكَ وَتَعَالَى: وَجَبَتْ مَحَبَّتِي لِلْمُتَحَابِّينَ فِيَّ، وَالْمُتَجَالِسِينَ فِيَّ، وَالْمُتَزَاوِرِينَ فِيَّ، وَالْمُتَبَاذِلِينَ فِيَّ."],"takhrij":"صحيح: رواه مالك في الشعر (16) عن أبي حازم بن دينار، عن أبي إدريس الخولانيّ أنه قال: دخلتُ مسجد دمشق، فإذا فتى شابّ برّاق الثّنايا، وإذا النّاس معه، إذا اختلفوا في شيء أسندوا إليه، وصدروا عن قوله، فسألتُ عنه فقيل: هذا معاذ بن جبل، فلما كان الغد هجّرتُ، فوجدته قد سبقني بالتهجير، ووجدته يصلي، قال: فانتظرته حتى قضى صلاته، ثم جئتُه من قبل وجهه فسلمت عليه، ثم قلتُ: والله إنّي لأحبُّك لله، فقال آلله؟ فقلت: آلله، فقال: آلله؟ فقلت: آلله، فقال: آلله؟ فقلت: آلله. قال: فأخذ بحبْوة ردائي فجبذني إليه وقال: أبشرْ فإنّي سمعتُ رسول الله صلى الله عليه وسلم يقول (فذكر الحديث).","grade":"صحيح","chapter_ar":"باب ما جاء في استواء الله تعالى على العرش","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Mālik (16).","chapter_en":"What Has Been Reported Concerning Allah Most High Rising Over the Throne","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["Muʿādh ibn Jabal, may Allah be pleased with him, reported: I heard the Messenger of Allah ﷺ say: “Allah, Blessed and Exalted, said: ‘My love has become obligatory for those who love one another for My sake, those who sit together for My sake, those who visit one another for My sake, and those who give generously to one another for My sake.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (16)."},{"num":293,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ لِلَّهِ عِبَادًا لَيْسُوا بِأَنْبِيَاء وَلا شُهَدَاءَ، يَغْبِطُهُمُ الشُّهَدَاءُ وَالنَّبِيُّونَ يَوْمَ الْقِيَامَةِ لِقُرْبِهِمْ مِنَ اللَّهِ تَعَالَى، وَمَجْلِسِهِمْ مِنْهُ، فَجَثَا أَعْرَابِيٌّ عَلَى رُكْبَتَيْهِ فَقَالَ: يَا رَسُولَ اللَّهِ! صِفْهُمْ لَنَا وحَلِّهِمْ لَنَا. قَالَ: قَوْمٌ مِنْ أَقْنَاءِ النَّاسِ مِنْ نِزَاعِ الْقَبَائِلِ، تَصَادَقُوا فِي اللَّهِ، وَتَحَابَّوْا فِيهِ، يَضَعُ اللَّهُ عَزَّ وَجَلَّ لَهُمْ يَوْمَ الْقِيَامَةِ مَنَابِرَ مِنْ نُورٍ، يَخَافُ النَّاسُ وَلا يَخَافُونَ، هُمْ أَوْلِيَاءُ اللَّهِ عَزَّ وَجَلَّ الَّذِينَ ﴿لا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ﴾. [سورة البقرة: 62]."],"takhrij":"صحيح: رواه الحاكم (7318) عن أبي عبدالله محمد بن عبدالله الزّاهد الأصبهانيّ، ثنا أحمد بن يونس الضبيّ بأصبهان، ثنا أبو بدر شجاع بن الوليد، قال: سمعت زياد بن خيثمة، يحدّث عن أبيه، عن ابن عمر، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في استواء الله تعالى على العرش","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Ḥākim (7318).","chapter_en":"What Has Been Reported Concerning Allah Most High Rising Over the Throne","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["Ibn ʿUmar may Allah be pleased with them reported that the Messenger of Allah ﷺ said: “Indeed, Allah has servants who are neither prophets nor martyrs, yet the martyrs and prophets will envy them on the Day of Resurrection because of their nearness to Allah Most High and their station with Him.” A Bedouin fell to his knees and said: “O Messenger of Allah, describe them to us.” He replied: “They are people from among ordinary people and from scattered tribes who became sincere friends for the sake of Allah and loved one another for His sake. Allah, Mighty and Majestic, will place pulpits of light for them on the Day of Resurrection. The people will be afraid, but they will not be afraid. They are the allies of Allah, Mighty and Majestic, concerning whom there will be no fear, nor will they grieve.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الحاكم (7318)."},{"num":294,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَالِكٍ الْأَشْعَرِيِّ قَالَ: كُنْتُ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَنَزَلَتْ هَذِهِ الْآيَةُ ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَسْأَلُوا عَنْ أَشْيَاءَ إِنْ تُبْدَ لَكُمْ تَسُؤْكُمْ ﴾ [سورة المائدة: 101]. قَالُوا: فَنَحْنُ نَسْأَلُهُ إِذًا قَالَ: إِنَّ لِلَّهِ عِبَادًا لَيْسُوا بِأَنْبِيَاءَ وَلَا شُهَدَاءَ يَغْبِطُهُمُ النَّبِيُّونَ وَالشُّهَدَاءُ بِقُرْبِهِمْ وَمَقْعدِهِمْ مِنَ اللَّهِ يَوْمَ الْقِيَامَةِ، قَالَ: وَفِي نَاحِيَةِ الْقَوْمِ أَعْرَابِيٌّ فَقَامَ فَحَثَى عَلَى وَجْهِهِ وَرَمَى بِيَدَيْهِ ثُمَّ قَالَ: حَدِّثْنَا يَا رَسُولَ اللَّهِ عَنْهُمْ مَنْ هُمْ؟ قَالَ: فَرَأَيْتُ وَجْهَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَبْشَرَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هُمْ عِبَادٌ مِنْ عِبَادِ اللَّهِ مِنْ بُلْدَانٍ شَتَّى، وَقَبَائِلَ شَتَّى مِنْ شُعُوبِ الْقَبَائِلِ لَمْ يَكُنْ بَيْنَهُمْ أَرْحَامٌ يَتَوَاصَلُونَ بِهَا، وَلَا دُنْيَا يَتَبَاذَلُونَ بِهَا، يَتَحَابُّونَ بِرُوحِ اللَّهِ، يَجْعَلُ اللَّهُ وُجُوهَهُمْ نُورًا، وَيَجْعَلُ لَهُمْ مَنَابِرَ مِنْ لُؤْلُؤٍ قُدَّامَ الرَّحْمَنِ، يَفْزَعُ النَّاسُ وَلَا يَفْزَعُونَ، وَيَخَافُ النَّاسُ وَلَا يَخَافُونَ."],"takhrij":"حسن: رواه عبدالرزّاق في المصنف (21396) عن معمر، عن ابن أبي حسين، عن شهر بن حوشب، عن أبي مالك الأشعريّ، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في استواء الله تعالى على العرش","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by ʿAbd al-Razzāq (20324), ʿAbdullāh ibn al-Mubārak in al-Zuhd (714), and Aḥmad (22906).","chapter_en":"What Has Been Reported Concerning Allah Most High Rising Over the Throne","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["Abū Mālik al-Ashʿarī, may Allah be pleased with him, reported: I was with the Messenger of Allah ﷺ when the following verse was revealed: “O you who believe, do not ask about matters which, if disclosed to you, would distress you.” [Sūrat al-Māʾidah 5:101] They said: “Then we will ask him.” He said: “Indeed, Allah has servants who are neither prophets nor martyrs, yet the prophets and martyrs will envy them on the Day of Resurrection because of their nearness and their station with Allah.” At the edge of the gathering was a Bedouin. He rose, fell forward eagerly, extended his hands, and said: “Tell us about them, O Messenger of Allah. Who are they?” I saw the face of the Messenger of Allah ﷺ brighten. The Prophet ﷺ said: “They are servants from among the servants of Allah, from different lands and different tribes, from scattered peoples. They share no ties of kinship through which they maintain relations, nor worldly wealth that they exchange with one another. Rather, they love one another through the Spirit of Allah. Allah will make their faces light and will place for them pulpits of pearl before al-Raḥmān. The people will be terrified while they will not be terrified, and the people will fear while they will not fear.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه عبد الرزاق (21396)، وعبد الله بن المبارك في الزهد (714)، وأحمد (22906)."},{"num":295,"demo":false,"sanad":"","matn":["عَنْ أَبِي إِدْرِيسَ عَائِذِ اللَّهِ قَالَ: مَرَّ رَجُلٌ فَقُمْتُ إِلَيْهِ، فَقُلْتُ: إِنَّ هَذَا حَدَّثَنِي بِحَدِيثِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَهَلْ سَمِعْتَهُ؟ يَعْنِي مُعَاذًا، قَالَ: مَا كَانَ يُحَدِّثُكَ إِلا حَقًّا، فَأَخْبَرْتُهُ. قَالَ: قَدْ سَمِعْتُ هَذَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَعْنِي فِي الْمُتَحَابِّينَ فِي اللَّهِ يُظِلُّهُمُ اللَّهُ فِي ظِلِّ عَرْشِهِ يَوْمَ لا ظِلَّ إِلا ظِلُّهُ، وَمَا هُوَ أَفْضَلُ مِنْهُ. قُلْتُ: إِي رَحِمَكَ اللَّهُ، وَمَا هُوَ أَفْضَلُ مِنْهُ؟ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَأْثُرُ عَنِ اللَّهِ عَزَّ وَجَلَّ قَالَ: حَقَّتْ مَحَبَّتِي لِلْمُتَحَابِّينَ فِيَّ، وَحَقَّتْ مَحَبَّتِي لِلْمُتَوَاصِلِينَ فِيَّ، وَحَقَّتْ مَحَبَّتِي لِلْمُتَزَاوِرِينَ فِيَّ، وَحَقَّتْ مَحَبَّتِي لِلْمُتَبَاذِلِينَ فِيَّ. وَلا أَدْرِي بِأَيَّتِهِمَا بَدَأَ. قُلْتُ: مَنْ أَنْتَ رَحِمَكَ اللَّهُ؟ قَالَ: أَنَا عُبَادَةُ بْنُ الصَّامِتِ."],"takhrij":"صحيح: رواه الحاكم (7315) من طريق الأوزاعيّ، عن ابن حلبس، عن أبي إدريس، فذكره. وقال: هذا حديث صحيح على شرط الشيخين.","grade":"صحيح","chapter_ar":"باب ما جاء في استواء الله تعالى على العرش","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Ḥākim (7315) and Aḥmad (22002).","chapter_en":"What Has Been Reported Concerning Allah Most High Rising Over the Throne","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["Abū Idrīs ʿĀʾidhullāh reported: A man passed by, so I stood up to him and said: “This man narrated to me a ḥadīth from the Messenger of Allah ﷺ. Have you heard it?” — meaning Muʿādh. He replied: “He would only narrate to you what is true.” So I told him the narration. He said: “I heard this from the Messenger of Allah ﷺ” — meaning that those who love one another for Allah’s sake will be shaded by Allah beneath the shade of His Throne on the Day when there is no shade except His shade — “and there is something even better than that.” I asked: “May Allah have mercy upon you! What is better than that?” He replied: I heard the Messenger of Allah ﷺ narrate from Allah, Mighty and Majestic, that He said: “My love has become due for those who love one another for My sake. My love has become due for those who maintain relations with one another for My sake. My love has become due for those who visit one another for My sake. And My love has become due for those who give generously to one another for My sake.” I do not know with which of these he began. I asked: “Who are you, may Allah have mercy upon you?” He replied: “I am ʿUbādah ibn al-Ṣāmit.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الحاكم (7315)، وأحمد (22002)."},{"num":296,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ طَرْفَ صَاحِبِ الصُّوَرِ مُذْ وُكِّلَ بِهِ مُسْتَعِدٌّ، يَنْظُرُ نَحْوَ الْعَرْشِ، مَخَافَةَ أَنْ يُؤْمَرَ قَبْلَ أَنْ يَرْتَدَّ إِلَيْهِ طَرْفُهُ، كَأَنَّ عَيْنَيْهِ كَوْكَبَانِ دُرِّيَّانِ."],"takhrij":"حسن: رواه الحاكم (8676) من طريق محمد بن هشام بن ملاس النّمريّ، عن مروان بن معاوية الفزاريّ، عن عبيد الله بن عبدالله بن الأصمّ، ثنا يزيد بن الأصمّ، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في استواء الله تعالى على العرش","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ḥākim (8676) and Abū al-Shaykh in al-ʿAẓamah (391).","chapter_en":"What Has Been Reported Concerning Allah Most High Rising Over the Throne","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Indeed, ever since the bearer of the Trumpet was entrusted with it, his gaze has remained fixed and ready, looking toward the Throne out of fear that he may be commanded before his glance can return to him. His eyes are like two brilliant stars.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[953,13641],"tks":"حسن: رواه الحاكم (8676)، وأبو الشيخ في العظمة (391)."},{"num":297,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ: لَمَّا رَجَعَتْ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُهَاجِرَةُ الْبَحْرِ، قَالَ: أَلَا تُحَدِّثُونِي بِأَعَاجِيبِ مَا رَأَيْتُمْ بِأَرْضِ الْحَبَشَةِ؟. قَالَ فِتْيَةٌ مِنْهُمْ: بَلَى يَا رَسُولَ اللَّهِ، بَيْنَا نَحْنُ جُلُوسٌ مَرَّتْ بِنَا عَجُوزٌ مِنْ عَجَائِزِ رَهَابِينِهِمْ تَحْمِلُ عَلَى رَأْسِهَا قُلَّةً مِنْ مَاءٍ، فَمَرَّتْ بِفَتًى مِنْهُمْ، فَجَعَلَ إِحْدَى يَدَيْهِ بَيْنَ كَتِفَيْهَا، ثُمَّ دَفَعَهَا فَخَرَّتْ عَلَى رُكْبَتَيْهَا فَانْكَسَرَتْ قُلَّتُهَا، فَلَمَّا ارْتَفَعَتْ الْتَفَتَتْ إِلَيْهِ، فَقَالَتْ: سَوْفَ تَعْلَمُ يَا غُدَرُ! إِذَا وَضَعَ اللَّهُ الْكُرْسِيَّ وَجَمَعَ الْأَوَّلِينَ وَالْآخِرِينَ وَتَكَلَّمَتِ الْأَيْدِي وَالْأَرْجُلُ بِمَا كَانُوا يَكْسِبُونَ، فَسَوْفَ تَعْلَمُ كَيْفَ أَمْرِي وَأَمْرُكَ عِنْدَهُ غَدًا قَالَ: يَقُولُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: صَدَقَتْ صَدَقَتْ، كَيْفَ يُقَدِّسُ اللَّهُ أُمَّةً لَا يُؤْخَذُ لِضَعِيفِهِمْ مِنْ شَدِيدِهِمْ."],"takhrij":"حسن: رواه ابن ماجه (4010)، وابن حبان (5058)، وابن أبي الدنيا في الأهوال (242) كلهم من طريق عبدالله بن عثمان بن خثيم، عن أبي الزّبير، عن جابر بن عبدالله، قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في استواء الله تعالى على العرش","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Mājah (4010), Ibn Ḥibbān (5058), and Ibn Abī al-Dunyā in al-Ahwāl (242).","chapter_en":"What Has Been Reported Concerning Allah Most High Rising Over the Throne","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["Jābir, may Allah be pleased with him, reported: When the emigrants who had crossed the sea returned to the Messenger of Allah ﷺ, he asked: “Will you not tell me about some of the remarkable things you saw in the land of Abyssinia?” Some young men among them replied: “Yes, O Messenger of Allah. While we were sitting, an elderly woman from among their devoted worshippers passed by us carrying a water vessel upon her head. A young man passed by her, placed one of his hands between her shoulders, and pushed her. She fell upon her knees, and her water vessel broke. When she rose, she turned toward him and said: ‘You will soon know, O treacherous one! When Allah sets up the Kursī, gathers the first and the last, and the hands and feet speak concerning what they used to earn, then you will know tomorrow how my affair and your affair will be before Him.’” The Messenger of Allah ﷺ said: “She spoke the truth. She spoke the truth. How can Allah sanctify a nation in which the right of its weak is not taken from its strong?”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13224],"tks":"حسن: رواه ابن ماجه (4010)، وابن حبان (5058)، وابن أبي الدنيا في الأهوال (242)."},{"num":298,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ قَالَ: سَأَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَعْفَرًا حِينَ قَدِمَ مِنَ الْحَبَشَةِ: مَا أَعْجَبُ شَيْءٍ رَأَيْتَهُ؟ قَالَ: رَأَيْتُ امْرَأَةً تَحْمِلُ عَلَى رَأْسِهَا مِكْتَلًا مِنْ طَعَامٍ، فَمَرَّ فَارِسٌ فَرَكَضَهُ فَأَبْدَرَهُ، فَجَلَسَتْ تَجْمَعُ طَعَامَهَا ثُمَّ الْتَفَتَتْ فَقَالَتْ: وَيْلٌ لَكَ، إِذَا وَضَعَ الْمَلِكُ تَبَارَكَ وَتَعَالَى كُرْسِيَّهُ فَأَخَذَ لِلْمَظْلُومِ مِنَ الظَّالِمِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَصْدِيقًا لِقَوْلِهَا: لَا قُدِّسَتْ أُمَّةٌ، أَوْ كَيْفَ تُقَدَّسُ أُمَّةٌ، لَا يَأْخُذُ ضَعِيفُهَا حَقَّهُ مِنْ شَدِيدِهَا وَهُوَ غَيْرُ مُتَعْتَعٍ."],"takhrij":"حسن: رواه البزار - كشف الأستار (1596)، والبيهقي في الأسماء والصفات (860) كلاهما من طريق سعيد بن سليمان، عن منصور بن أبي الأسود، ثنا عطاء بن السائب، عن محارب بن دثار، عن ابن بريدة (وهو سليمان)، عن أبيه بريدة بن الحصيب، قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في استواء الله تعالى على العرش","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan due to supporting narrations: Narrated by al-Bazzār in Kashf al-Astār (1596) and al-Bayhaqī in al-Asmāʾ wa al-Ṣifāt (860).","chapter_en":"What Has Been Reported Concerning Allah Most High Rising Over the Throne","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["Buraydah, may Allah be pleased with him, reported: When Jaʿfar returned from Abyssinia, the Messenger of Allah ﷺ asked him: “What was the most remarkable thing you saw?” He replied: “I saw a woman carrying a basket of food upon her head. A horseman passed by and struck it, scattering its contents. She sat down gathering her food, then turned toward him and said: ‘Woe to you! When the King, Blessed and Exalted, sets up His Kursī and takes the right of the oppressed from the oppressor…’” The Messenger of Allah ﷺ said in confirmation of her words: “A nation is not sanctified — or: How can a nation be sanctified? — if its weak cannot obtain his right from its strong without intimidation or difficulty.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (1596)، والبيهقي في الأسماء والصفات (860)."},{"num":299,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَنْزِلُ رَبُّنَا تَبَارَكَ وَتَعَالَى كُلَّ لَيْلَةٍ إِلَى السَّمَاءِ الدُّنْيَا حِينَ يَبْقَى ثُلُثُ اللَّيْلِ الْآخِرُ، يَقُولُ: مَنْ يَدْعُونِي فَأَسْتَجِيبَ لَهُ، مَنْ يَسْأَلُنِي فَأُعْطِيَهُ، مَنْ يَسْتَغْفِرُنِي فَأَغْفِرَ لَهُ."],"takhrij":"متفق عليه: رواه مالك في القرآن (30) عن ابن شهاب، عن أبي عبدالله الأغرّ، وأبي سلمة، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب نزول الرب عز وجل إلى السماء الدنيا","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in al-Qurʾān (30) and al-Bukhārī (1145).","chapter_en":"The Descent of the Lord, Mighty and Majestic, to the Lowest Heaven","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":18,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Allah, Blessed and Exalted, descends every night to the lowest heaven when the final third of the night remains and says: ‘Who is calling upon Me so that I may answer him? Who is asking Me so that I may give him? Who is seeking My forgiveness so that I may forgive him?’”"]},"buhuth":{"en":["Muslim (758) also narrated it with the additional wording:","“Until the dawn begins to shine.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2704,10758,10926,13399],"tks":"متفق عليه: رواه مالك (30)، والبخاري (1145)."},{"num":300,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ وَأَبِي هُرَيْرَةَ قَالَا: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللَّهَ يُمْهِلُ حَتَّى إِذَا ذَهَبَ ثُلُثُ اللَّيْلِ الأَوَّلُ، نَزَلَ إِلَى السَّمَاءِ الدُّنْيَا، فَيَقُولُ: هَلْ مِنْ مُسْتَغْفِرٍ؟ هَلْ مِنْ تَائِبٍ؟ هَلْ مِنْ سَائِلٍ؟ هَلْ مِنْ دَاعٍ؟ حَتَّى يَنْفَجِرَ الْفَجْرُ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (758: 172) من طرق عن جرير، عن منصور، عن أبي إسحاق، عن الأغر أبي مسلم، يرويه عن أبي سعيد، وأبي هريرة، فذكراه.","grade":"صحيح","chapter_ar":"باب نزول الرب عز وجل إلى السماء الدنيا","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in Ṣalāt al-Musāfirīn (758:172).","chapter_en":"The Descent of the Lord, Mighty and Majestic, to the Lowest Heaven","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":18,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī and Abū Hurayrah may Allah be pleased with them reported that the Messenger of Allah ﷺ said: “Allah gives respite until the first third of the night has passed. Then He descends to the lowest heaven and says: ‘Is there anyone seeking forgiveness? Is there anyone repenting? Is there anyone asking? Is there anyone supplicating?’ This continues until dawn breaks.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10759],"tks":"صحيح: رواه مسلم (758: 172)."},{"num":301,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَنْزِلُ اللَّهُ فِي السَّمَاءِ الدُّنْيَا لِشَطْرِ اللَّيْلِ أَوْ لِثُلُثِ اللَّيْلِ الآخِرِ، فَيَقُولُ: مَنْ يَدْعُونِي فَأَسْتَجِيبَ لَهُ؟ أَوْ يَسْأَلُنِي فَأُعْطِيَهُ؟ ثُمَّ يَقُولُ: مَنْ يُقْرِضُ غَيْرَ عَدِيمٍ وَلَا ظَلُومٍ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (758: 171) عن حجّاج بن الشّاعر، حدّثنا محاضر أبو المورِّع، حدّثنا سعد بن سعيد، قال: أخبرني ابن مرجانة، قال: سمعتُ أبا هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب نزول الرب عز وجل إلى السماء الدنيا","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in Ṣalāt al-Musāfirīn (758:171).","chapter_en":"The Descent of the Lord, Mighty and Majestic, to the Lowest Heaven","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":18,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Allah descends to the lowest heaven at the middle of the night, or during the last third of the night, and says: ‘Who is calling upon Me so that I may answer him, or asking Me so that I may give him?’ Then He says: ‘Who will lend to One who is neither poor nor unjust?’”"]},"buhuth":{"en":["Regarding the expression:","“Neither poor,”","the scholars of the Arabic language said that a man is described as aʿdama when he becomes poor; hence the forms muʿdim, ʿadīm, and ʿadūm."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (758: 171)."},{"num":302,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: حَدَّثَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّ اللَّهَ عَزَّ وَجَلَّ إِذَا كَانَ يَوْمَ الْقِيَامَةِ نَزَلَ إِلَى الْعِبَادِ لِيَقْضِيَ بَيْنَهُمْ.(فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ)."],"takhrij":"صحيح: رواه الترمذيّ (2382) عن سويد بن نصر، أخبرنا عبدالله بن المبارك، أخبرنا حيوة بن شريح، أخبرنا الوليد بن أبي الوليد أبو عثمان المدائنيّ، أنّ عقبة بن مسلم حدّثه، أنّ شُفيّاً الأصبحيّ حدّثه، عن أبي هريرة، فذكره في حديث طويل وهو مذكور في موضعه.","grade":"صحيح","chapter_ar":"باب نزول الرب عز وجل إلى السماء الدنيا","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Tirmidhī (2382), and authenticated by Ibn Khuzaymah (2482) and al-Ḥākim (1527).","chapter_en":"The Descent of the Lord, Mighty and Majestic, to the Lowest Heaven","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":18,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported: The Messenger of Allah ﷺ told me: “Indeed, when the Day of Resurrection comes, Allah, Mighty and Majestic, will descend to the servants to judge between them.”"]},"buhuth":{"en":["The basis of this ḥadīth is also found in Ṣaḥīḥ Muslim through another route, but without mention of the descent (1905)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (2382)، وصححه ابن خزيمة (2482)، والحاكم (1527)."},{"num":303,"demo":false,"sanad":"","matn":["عَنْ رِفَاعَةَ الْجُهَنِيِّ قَالَ: أَقْبَلْنَا مَعَ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى إِذَا كُنَّا بِالْكَدِيدِ أَوْ قَالَ: بِقُدَيْدٍ فَجَعَلَ رِجَالٌ مِنَّا يَسْتَأْذِنُونَ إِلَى أَهْلِيهِمْ فَيَأْذَنُ لَهُمْ، فَقَامَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَحَمِدَ اللهَ، وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ: مَا بَالُ رِجَالٍ يَكُونُ شِقُّ الشَّجَرَةِ الَّتِي تَلِي رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَبْغَضَ إِلَيْهِمْ مِنَ الشِّقِّ الْآخَرِ، فَلَمْ نَرَ عِنْدَ ذَلِكَ مِنَ الْقَوْمِ إِلَّا بَاكِيًا، فَقَالَ رَجُلٌ: إِنَّ الَّذِي يَسْتَأْذِنُكَ بَعْدَ هَذَا لَسَفِيهٌ. فَحَمِدَ اللهَ وَقَالَ حِينَئِذٍ: أَشْهَدُ عِنْدَ اللهِ لَا يَمُوتُ عَبْدٌ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، وَأَنِّي رَسُولُ اللهِ صِدْقًا مِنْ قَلْبِهِ، ثُمَّ يُسَدِّدُ إِلَّا سُلِكَ فِي الْجَنَّةِ، قَالَ: وَقَدْ وَعَدَنِي رَبِّي عَزَّ وَجَلَّ أَنْ يُدْخِلَ مِنْ أُمَّتِي سَبْعِينَ أَلْفًا لَا حِسَابَ عَلَيْهِمْ، وَلَا عَذَابَ، وَإِنِّي لَأَرْجُو أَنْ لَا يَدْخُلُوهَا حَتَّى تَبَوَّءُوا أَنْتُمْ وَمَنْ صَلَحَ مِنْ آبَائِكُمْ وَأَزْوَاجِكُمْ وَذُرِّيَّاتِكُمْ مَسَاكِنَ فِي الْجَنَّةِ.","وَقَالَ: إِذَا مَضَى نِصْفُ اللَّيْلِ أَوْ قَالَ ثُلُثَا اللَّيْلِ يَنْزِلُ اللَّهُ عَزَّ وَجَلَّ إِلَى السَّمَاءِ الدُّنْيَا، فَيَقُولُ: لَا أَسْأَلُ عَنْ عِبَادِي أَحَدًا غَيْرِي، مَنْ ذَا يَسْتَغْفِرُنِي فَأَغْفِرَ لَهُ، مَنْ الَّذِي يَدْعُونِي أَسْتَجِيبُ لَهُ، مَنْ ذَا الَّذِي يَسْأَلُنِي أُعْطِيهِ حَتَّى يَنْفَجِرَ الصُّبْحُ."],"takhrij":"صحيح: رواه الإمام أحمد (16215) عن إسماعيل بن إبراهيم، قال: حدثنا هشام الدّستوائيّ، عن يحيى بن أبي كثير، عن هلال بن أبي ميمونة، عن عطاء بن يسار، عن رفاعة الجهنيّ، فذكره.","grade":"صحيح","chapter_ar":"باب نزول الرب عز وجل إلى السماء الدنيا","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Aḥmad (16215), Ibn Khuzaymah in Kitāb al-Tawḥīd (1/289–291), and Ibn Ḥibbān (212).","chapter_en":"The Descent of the Lord, Mighty and Majestic, to the Lowest Heaven","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":18,"content":{"translation":{"en":["Rifāʿah al-Juhanī, may Allah be pleased with him, reported: We were traveling with the Messenger of Allah ﷺ until we reached al-Kudayd — or he said Qudayd. Some men among us began asking permission to go to their families, and he gave them permission. The Messenger of Allah ﷺ then stood, praised Allah and extolled Him, and said: “What is the matter with some men that the side of the tree nearest to the Messenger of Allah ﷺ is more disliked by them than its other side?” At that, we saw no one among the people except that he was weeping. A man said: “Whoever asks your permission after this is surely foolish.” The Messenger of Allah ﷺ praised Allah and then said: “I testify before Allah that no servant dies while testifying that there is no deity worthy of worship except Allah and that I am the Messenger of Allah, truthfully from his heart, and then strives to remain upright, except that he will enter Paradise.” He continued: “My Lord, Mighty and Majestic, has promised me that He will admit seventy thousand from my Ummah without reckoning and without punishment. I hope that they will not enter it until you, together with the righteous among your fathers, spouses, and descendants, have taken up your dwellings in Paradise.” He also said: “When half the night has passed — or he said two-thirds of the night — Allah, Mighty and Majestic, descends to the lowest heaven and says:","‘I do not ask anyone other than Myself concerning My servants. Who is seeking My forgiveness so that I may forgive him? Who is calling upon Me so that I may answer him? Who is asking Me so that I may give him?’ This continues until dawn breaks.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (16215)، وابن خزيمة في كتاب التوحيد (1/289–291)، وابن حبان (212)."},{"num":304,"demo":false,"sanad":"","matn":["عَنْ نَافِعِ بْنِ جُبَيْرٍ، عَنِ أَبِيهِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَنْزِلُ اللَّهُ عَزَّ وَجَلَّ فِي كُلِّ لَيْلَةٍ إِلَى السَّمَاءِ الدُّنْيَا، فَيَقُولُ: هَلْ مِنْ سَائِلٍ فَأُعْطِيَهُ؟ هَلْ مِنْ مُسْتَغْفِرٍ فَأَغْفِرَ لَهُ؟ حَتَّى يَطْلُعَ الْفَجْرُ."],"takhrij":"صحيح: رواه الإمام أحمد (16745)، والبزّار- كشف الأستار (3152)، ، وأبو يعلى (7408)، والنسائيّ في اليوم واللّيلة (487)، وابن أبي عاصم في السنة (507)، والدّارقطنيّ في النزول (4) كلّهم من طريق حماد بن سلمة، عن عمرو بن دينار، عن نافع بن جبير، به، واللّفظ لأحمد.","grade":"صحيح","chapter_ar":"باب نزول الرب عز وجل إلى السماء الدنيا","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Imām Aḥmad (16745), al-Bazzār in Kashf al-Astār (3152), and Abū Yaʿlā (7408).","chapter_en":"The Descent of the Lord, Mighty and Majestic, to the Lowest Heaven","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":18,"content":{"translation":{"en":["Nāfiʿ ibn Jubayr reported from his father may Allah be pleased with him that the Prophet ﷺ said: “Allah, Mighty and Majestic, descends every night to the lowest heaven and says: ‘Is there anyone asking so that I may give him? Is there anyone seeking forgiveness so that I may forgive him?’ This continues until dawn rises.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (16745)، والبزار في كشف الأستار (3152)، وأبو يعلى (7408)."},{"num":305,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ، أَنَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ، وَلَأَخَّرْتُ الْعِشَاءَ الْآخِرَةَ إِلَى ثُلُثِ اللَّيْلِ، فَإِنَّهُ إِذَا مَضَى ثُلُثُ اللَّيْلِ الْأَوَّلُ هَبَطَ اللَّهُ عَزَّ وَجَلَّ إِلَى سَمَاءِ الدُّنْيَا، فَلَمْ يَزَلْ هُنَالِكَ حَتَّى يَطْلُعَ الْفَجْرُ، يَقُولُ: أَلَا سَائِلٌ فَيُعْطَى، أَلَا دَاعٍ يُجَابُ، أَلَا مُسْتَشْفِعٍ فَيُشَفَّعُ، أَلَا تَائِبٌ مُسْتَغْفِرٌ فَيُغْفَرَ لَهُ."],"takhrij":"حسن: رواه البزّار (477، 478) قال: حدثنا سليمان بن سيف الحرانيّ، ثنا سعيد بن بزيع، عن ابن إسحاق، قال: حدثني عبدالرحمن بن يسار، ح. وحدّثنا إبراهيم بن سعيد الجوهريّ، والفضل بن سهل، وأحمد بن منصور، قالوا: حدثنا يعقوب بن إبراهيم بن سعد، عن أبيه، عن ابن إسحاق، قال: حدثني عبدالرحمن بن يسار، عن عبيد الله بن أبي رافع، عن أبيه، عن علي بن أبي طالب، فذكر الحديث.","grade":"حسن","chapter_ar":"باب نزول الرب عز وجل إلى السماء الدنيا","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Bazzār (477, 478), Aḥmad (968), al-Dārimī (1492), and al-Dāraquṭnī in al-Nuzūl (1).","chapter_en":"The Descent of the Lord, Mighty and Majestic, to the Lowest Heaven","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":18,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Were it not that I would make matters difficult for my Ummah, I would have commanded them to use the siwāk at every prayer, and I would have delayed the ʿIshāʾ prayer until one-third of the night had passed. For when the first third of the night has passed, Allah, Blessed and Exalted, descends to the lowest heaven and remains there until dawn rises, saying: ‘Is there anyone asking so that he may be given? Is there anyone supplicating so that he may be answered? Is there anyone seeking intercession so that intercession may be granted to him? Is there any repentant person seeking forgiveness so that he may be forgiven?’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار (477، 478)، وأحمد (968)، والدارمي (1492)، والدارقطني في النزول (1)."},{"num":306,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا كَانَ ثُلُثُ اللَّيْلِ الْبَاقِي، يَهْبِطُ اللَّهُ عَزَّ وَجَلَّ إِلَى السَّمَاءِ الدُّنْيَا، ثُمَّ تُفْتَحُ أَبْوَابُ السَّمَاءِ، ثُمَّ يَبْسُطُ يَدَهُ، فَيَقُولُ: هَلْ مِنْ سَائِلٍ يُعْطَى سُؤْلَهُ؟ فَلَا يَزَالُ كَذَلِكَ، حَتَّى يَطْلُعَ الْفَجْرُ."],"takhrij":"حسن: رواه الإمام أحمد (3673، 3821) عن عبد الصّمد، حدّثنا عبدالعزيز بن مسلم، حدّثنا أبو إسحاق الهمدانيّ، عن أبي الأحوص، عن ابن مسعود، فذكره.","grade":"حسن","chapter_ar":"باب نزول الرب عز وجل إلى السماء الدنيا","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (3673, 3821) and Abū Yaʿlā (5319).","chapter_en":"The Descent of the Lord, Mighty and Majestic, to the Lowest Heaven","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":18,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “When the final third of the night remains, Allah, Mighty and Majestic, descends to the lowest heaven. Then the gates of heaven are opened, and He extends His Hand and says: ‘Is there anyone asking who may be given what he asks?’ He continues in this manner until dawn rises.”"]},"buhuth":{"en":["These narrations collectively indicate Allah’s descent to the lowest heaven every night. As for singling out the night of mid-Shaʿbān, the reports about it are all weak and are not relied upon."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (3673، 3821)، وأبو يعلى (5319)."},{"num":307,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ) عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: فَيَأْتِيهِمُ اللَّهُ تَبَارَكَ وَتَعَالَى فِي صُورَةٍ غَيْرِ صُورَتِهِ الَّتِي يَعْرِفُونَ، فَيَقُولُ: أَنَا رَبُّكُمْ، فَيَقُولُونَ: نَعُوذُ بِاللَّهِ مِنْكَ، هَذَا مَكَانُنَا حَتَّى يَأْتِيَنَا رَبُّنَا، فَإِذَا جَاءَ رَبُّنَا عَرَفْنَاهُ، فَيَأْتِيهِمُ اللَّهُ تَعَالَى فِي صُورَتِهِ الَّتِي يَعْرِفُونَ...الْحَدِيثَ."],"takhrij":"متفق عليه: رواه البخاري في التوحيد (7437) ومسلم في الإيمان (182) كلاهما من حديث إبراهيم بن سعد، عن ابن شهاب، عن عطاء بن يزيد الليثي، عن أبي هريرة، فذكره في حديث طويل، انظر: باب الصراط جسر جهنم في جموع أبواب اليوم الآخر.","grade":"متفق عليه","chapter_ar":"باب إثبات الصورة لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7437) and Muslim (182).","chapter_en":"Affirming the Attribute of Form for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":19,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Prophet ﷺ said: “Allah will come to them in a form other than the form in which they recognize Him and will say: ‘I am your Lord.’ They will say: ‘We seek refuge in Allah from you. We will remain here until our Lord comes to us; when our Lord comes to us, we will recognize Him.’ Then Allah will come to them in the form in which they recognize Him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7437)، ومسلم (182)."},{"num":308,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ أَنَّهُ قَالَ: جَاءَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَعُودُنِي عَامَ حَجَّةِ الْوَدَاعِ مِنْ وَجَعٍ اشْتَدَّ بِي، فَقُلْتُ: يَا رَسُولَ اللَّهِ، قَدْ بَلَغَ بِي مِنَ الْوَجَعِ مَا تَرَى، وَأَنَا ذُو مَالٍ وَلَا يَرِثُنِي إِلَّا ابْنَةٌ لِي، أَفَأَتَصَدَّقُ بِثُلُثَيْ مَالِي؟ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا . فَقُلْتُ: فَالشَّطْرُ؟ قَالَ: لَا . ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الثُّلُثُ، وَالثُّلُثُ كَثِيرٌ، إِنَّكَ أَنْ تَذَرَ وَرَثَتَكَ أَغْنِيَاءَ، خَيْرٌ مِنْ أَنْ تَذَرَهُمْ عَالَةً يَتَكَفَّفُونَ النَّاسَ، وَإِنَّكَ لَنْ تُنْفِقَ نَفَقَةً تَبْتَغِي بِهَا وَجْهَ اللَّهِ إِلَّا أُجِرْتَ حَتَّى مَا تَجْعَلُ فِي فِي امْرَأَتِكَ.(فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ)."],"takhrij":"متفق عليه: رواه مالك في الوصية (4) عن ابن شهاب، عن عامر بن سعد بن أبي وقاص، عن أبيه، فذكر الحديث بطوله، وسيأتي في موضعه.","grade":"متفق عليه","chapter_ar":"باب ما جاء في إثبات الوجه لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (4), al-Bukhārī (1295), and Muslim (1628).","chapter_en":"What Has Been Reported Concerning Affirming the Face for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["Saʿd ibn Abī Waqqāṣ, may Allah be pleased with him, reported: During the year of the Farewell Pilgrimage, the Messenger of Allah ﷺ used to visit me because of an illness that had become severe. I said: “O Messenger of Allah, my illness has reached the severity that you see. I possess wealth, and no one will inherit from me except one daughter. Should I give two-thirds of my wealth in charity?” The Messenger of Allah ﷺ replied: “No.” I asked: “Then half?” He replied: “No.” Then the Messenger of Allah ﷺ said: “One-third, and one-third is much. Indeed, leaving your heirs wealthy is better than leaving them poor and begging from people. And you will never spend anything seeking thereby the Face of Allah except that you will be rewarded for it, even what you place in your wife’s mouth.”"]},"intro":{"ar":["قال الله تعالى:","﴿وَيَبْقَى وَجْهُ رَبِّكَ ذُو الْجَلَالِ وَالْإِكْرَامِ﴾","[الرحمن: ٢٧]","وقال تعالى:","﴿كُلُّ شَيْءٍ هَالِكٌ إِلَّا وَجْهَهُ﴾","[القصص: ٨٨]","وقال تعالى:","﴿وَمَا آتَيْتُمْ مِنْ زَكَاةٍ تُرِيدُونَ وَجْهَ اللهِ﴾","[الروم: ٣٩]","وقال تعالى:","﴿إِنَّمَا نُطْعِمُكُمْ لِوَجْهِ اللهِ﴾","[الإنسان: ٩]","وقال تعالى:","﴿وَالَّذِينَ صَبَرُوا ابْتِغَاءَ وَجْهِ رَبِّهِمْ﴾","[الرعد: ٢٢]","وقال تعالى:","﴿يُرِيدُونَ وَجْهَهُ﴾","[الكهف: ٢٨]","وقال تعالى:","﴿إِلَّا ابْتِغَاءَ وَجْهِ رَبِّهِ الْأَعْلَى﴾","[الليل: ٢٠]","وغيرها من الآيات البينات."],"en":["Allah Most High said:","“And the Face of your Lord, Possessor of Majesty and Honor, will remain.”","[Sūrat al-Raḥmān 55:27]","And He said:","“Everything will perish except His Face.”","[Sūrat al-Qaṣaṣ 28:88]","And He said:","“And whatever you give in zakāh, seeking the Face of Allah…”","[Sūrat al-Rūm 30:39]","And He said:","“We feed you only for the Face of Allah.”","[Sūrat al-Insān 76:9]","And He said:","“And those who remain patient, seeking the Face of their Lord…”","[Sūrat al-Raʿd 13:22]","And He said:","“They seek His Face.”","[Sūrat al-Kahf 18:28]","And He said:","“Except seeking the Face of his Lord, the Most High.”","[Sūrat al-Layl 92:20]","And there are other clear verses concerning this."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (4)، والبخاري (1295)، ومسلم (1628)."},{"num":309,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَ: لَمَّا كَانَ يَوْمُ حُنَيْنٍ آثَرَ أُنَاسًا فِي الْقِسْمَةِ، فَأَعْطَى الْأَقْرَعَ بْنَ حَابِسٍ مِائَةً مِنَ الْإِبِلِ وَأَعْطَى عُيَيْنَةَ مِثْلَ ذَلِكَ وَأَعْطَى أُنَاسًا مِنْ أَشْرَافِ الْعَرَبِ، فَآثَرَهُمْ يَوْمَئِذٍ فِي الْقِسْمَةِ. فَقَالَ: رَجُلٌ وَاللَّهِ إِنَّ هَذِهِ الْقِسْمَةَ مَا عُدِلَ فِيهَا، وَمَا أُرِيدَ بِهَا وَجْهُ اللَّهِ، فَقُلْتُ: وَاللَّهِ لَأُخْبِرَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَتَيْتُهُ فَأَخْبَرْتُهُ، فَقَالَ: فَمَنْ يَعْدِلُ إِذَا لَمْ يَعْدِلِ اللَّهُ وَرَسُولُهُ، رَحِمَ اللَّهُ مُوسَى قَدْ أُوذِيَ بِأَكْثَرَ مِنْ هَذَا فَصَبَرَ."],"takhrij":"متفق عليه: رواه البخاريّ في فرض الخمس (3150)، ومسلم في الزكاة (1062) كلاهما من حديث جرير، عن منصور، عن أبي وائل، عن عبدالله، فذكره، ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب ما جاء في إثبات الوجه لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3150) and Muslim (1062).","chapter_en":"What Has Been Reported Concerning Affirming the Face for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd, may Allah be pleased with him, reported: On the day of Ḥunayn, the Prophet ﷺ favored certain people in the distribution. He gave al-Aqraʿ ibn Ḥābis one hundred camels, gave ʿUyaynah the same amount, and gave gifts to several of the Arab nobles, favoring them in the distribution that day. A man said: “By Allah, there was no justice in this distribution, nor was the Face of Allah sought through it!” I said: “By Allah, I will inform the Prophet ﷺ.” I went to him and informed him. He said: “Then who would act justly if Allah and His Messenger did not act justly? May Allah have mercy upon Moses. He was harmed with more than this, yet he remained patient.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3150)، ومسلم (1062)."},{"num":310,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرِ بْنِ عَبْدِ اللَّهِ بْنِ قَيْسٍ، عَنْ أَبِيهِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: جَنَّتَانِ مِنْ فِضَّةٍ آنِيَتُهُمَا وَمَا فِيهِمَا، وَجَنَّتَانِ مِنْ ذَهَبٍ آنِيَتُهُمَا وَمَا فِيهِمَا، وَمَا بَيْنَ الْقَوْمِ وَبَيْنَ أَنْ يَنْظُرُوا إِلَى رَبِّهِمْ، إِلَّا رِدَاءُ الْكِبْرِيَاءِ، عَلَى وَجْهِهِ فِي جَنَّةِ عَدْنٍ."],"takhrij":"متفق عليه: رواه البخاريّ في التفسير (4878)، ومسلم في الإيمان (180) كلاهما من حديث عبدالعزيز بن عبدالصمد العمّيّ، حدثنا أبو عمران الجونيّ، عن أبي بكر بن عبدالله بن قيس، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في إثبات الوجه لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4878) and Muslim (180).","chapter_en":"What Has Been Reported Concerning Affirming the Face for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["ʿAbdullāh ibn Qays may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Two gardens will be of silver, along with their vessels and everything within them; and two gardens will be of gold, along with their vessels and everything within them. Nothing will stand between the people and their looking upon their Lord except the veil of Majesty over His Face in the Garden of ʿAdn.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4878)، ومسلم (180)."},{"num":311,"demo":false,"sanad":"","matn":["عَنْ عِتْبَانَ بْنِ مَالِكٍ يَقُولُ: غَدَا عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَجُلٌ: أَيْنَ مَالِكُ بْنُ الدُّخْشُنِ، فَقَالَ رَجُلٌ: مِنَّا ذَلِكَ مُنَافِقٌ لَا يُحِبُّ اللَّهَ وَرَسُولَهُ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَلَا تَقُولُوهُ يَقُولُ: لَا إِلَهَ إِلَّا اللَّهُ، يَبْتَغِي بِذَلِكَ وَجْهَ اللَّهِ، قَالَ: بَلَى، قَالَ: فَإِنَّهُ لَا يُوَافَى عَبْدٌ يَوْمَ الْقِيَامَةِ بِهِ إِلَّا حَرَّمَ اللَّهُ عَلَيْهِ النَّارَ."],"takhrij":"صحيح: رواه البخاريّ في استتابة المرتدين (6938) عن عبدان، أخبرنا عبدالله، أخبرنا معمر، عن الزهري، أخبرني محمود بن الربيع، قال: سمعت عتبان بن مالك، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في إثبات الوجه لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (6938).","chapter_en":"What Has Been Reported Concerning Affirming the Face for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["ʿItbān ibn Mālik, may Allah be pleased with him, reported: The Messenger of Allah ﷺ came to me one morning. A man asked: “Where is Mālik ibn al-Dukhshun?” One of us replied: “He is a hypocrite who does not love Allah and His Messenger.” The Prophet ﷺ said: “Do not say that! Does he not say, ‘There is no deity worthy of worship except Allah,’ seeking thereby the Face of Allah?” He replied: “Yes.” The Prophet ﷺ said: “No servant will come on the Day of Resurrection with that testimony except that Allah will make the Fire forbidden for him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (6938)."},{"num":312,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ ﴿قُلْ هُوَ الْقَادِرُ عَلَى أَنْ يَبْعَثَ عَلَيْكُمْ عَذَابًا مِنْ فَوْقِكُمْ﴾ [سورة الأنعام: 65] قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَعُوذُ بِوَجْهِكَ، فَقَالَ: ﴿أَوْ مِنْ تَحْتِ أَرْجُلِكُمْ﴾، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَعُوذُ بِوَجْهِكَ، قَالَ: ﴿أَوْ يَلْبِسَكُمْ شِيَعًا﴾، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَذَا أَيْسَرُ."],"takhrij":"صحيح: رواه البخاريّ في التوحيد (7406) في باب قوله تعالى: ﴿كُلُّ شَيْءٍ هَالِكٌ إِلَّا وَجْهَهُ﴾ [سورة القصص: 88] عن قتيبة بن سعيد، حدّثنا حمّاد بن زيد، عن عمرو، عن جابر بن عبدالله، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في إثبات الوجه لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (7406).","chapter_en":"What Has Been Reported Concerning Affirming the Face for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh, may Allah be pleased with them, reported: When the verse was revealed: “Say: He is able to send upon you punishment from above you…” [Sūrat al-Anʿām 6:65] the Prophet ﷺ said: “I seek refuge in Your Face.” Then came: “…or from beneath your feet…” and the Prophet ﷺ said: “I seek refuge in Your Face.” Then came: “…or to divide you into factions…” and the Prophet ﷺ said: “This is easier.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (7406)."},{"num":313,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سِتَّةَ نَفَرٍ، فَقَالَ الْمُشْرِكُونَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اطْرُدْ هَؤُلَاءِ لَا يَجْتَرِئُونَ عَلَيْنَا، قَالَ: وَكُنْتُ أَنَا، وَابْنُ مَسْعُودٍ، وَرَجُلٌ مِنْ هُذَيْلٍ، وَبِلَالٌ، وَرَجُلَانِ لَسْتُ أُسَمِّيهِمَا، فَوَقَعَ فِي نَفْسِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، مَا شَاءَ اللَّهُ أَنْ يَقَعَ فَحَدَّثَ نَفْسَهُ، فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ: ﴿وَلَا تَطْرُدِ الَّذِينَ يَدْعُونَ رَبَّهُمْ بِالْغَدَاةِ وَالْعَشِيِّ يُرِيدُونَ وَجْهَهُ مَا عَلَيْكَ مِنْ حِسَابِهِمْ مِنْ شَيْءٍ ﴾ [سورة الأنعام: 52]."],"takhrij":"صحيح: رواه مسلم في فضائل الصّحابة (2413) عن أبي بكر بن أبي شيبة، حدّثنا محمد بن عبدالله الأسديّ، عن إسرائيل، عن المقدام بن شريح، عن أبيه، عن سعد، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في إثبات الوجه لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2413).","chapter_en":"What Has Been Reported Concerning Affirming the Face for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["Saʿd ibn Abī Waqqāṣ, may Allah be pleased with him, reported: We were with the Prophet ﷺ, six men in all, when the polytheists said to the Prophet ﷺ: “Drive these men away so that they will not dare to sit with us.” I was among them, along with Ibn Masʿūd, a man from Hudhayl, Bilāl, and two men whose names I will not mention. Something occurred in the heart of the Messenger of Allah ﷺ as Allah willed, and he considered the matter. Allah, Mighty and Majestic, then revealed: “Do not drive away those who call upon their Lord morning and evening, seeking His Face. You are not accountable for them in anything…” [Sūrat al-Anʿām 6:52]"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2413)."},{"num":314,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنُ مَسْعُودٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ الْمَرْأَةَ عَوْرَةٌ، فَإِذَا خَرَجَتِ اسْتَشْرَفَهَا الشَّيْطَانُ، وَأَقْرَبُ مَا تَكُونُ مِنْ وَجْهِ رَبِّهَا وَهِيَ فِي قَعْرِ بَيْتِهَا."],"takhrij":"صحيح: رواه ابن خزيمة في صحيحه (1685)، وفي كتاب التوحيد sh13011(23)، وعنه ابن حبان في صحيحه (5599) عن أبي موسى محمد بن المثنى، نا عمرو بن عاصم، ثنا همّام، عن قتادة، عن مورق، عن أبي الأحوص، عن عبدالله، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في إثبات الوجه لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Ibn Khuzaymah in his Ṣaḥīḥ (1685) and in Kitāb al-Tawḥīd (23), and through him by Ibn Ḥibbān (5599).","chapter_en":"What Has Been Reported Concerning Affirming the Face for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd may Allah be pleased with him reported that the Prophet ﷺ said: “Indeed, a woman is ʿawrah. When she goes out, Satan looks upon her eagerly; and the closest she is to the Face of her Lord is when she is in the innermost part of her home.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن خزيمة في صحيحه (1685)، وفي كتاب التوحيد sh13011(23)، وعنه ابن حبان (5599)."},{"num":315,"demo":false,"sanad":"","matn":["عَنْ الْحَارِثِ الْأَشْعَرِيِّ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ اللَّهَ أَمَرَ يَحْيَى بْنَ زَكَرِيَّا بِخَمْسِ كَلِمَاتٍ أَنْ يَعْمَلَ بِهَا، وَيَأْمُرَ بَنِي إِسْرَائِيلَ أَنْ يَعْمَلُوا بِهَا، وَإِنَّهُ كَادَ أَنْ يُبْطِئَ بِهَا، فَقَالَ عِيسَى: إِنَّ اللَّهَ أَمَرَكَ بِخَمْسِ كَلِمَاتٍ لِتَعْمَلَ بِهَا وَتَأْمُرَ بَنِي إِسْرَائِيلَ، أَنْ يَعْمَلُوا بِهَا، فَإِمَّا أَنْ تَأْمُرَهُمْ وَإِمَّا أَنْ آمُرَهُمْ، فَقَالَ يَحْيَى: أَخْشَى إِنْ سَبَقْتَنِي بِهَا أَنْ يُخْسَفَ بِي أَوْ أُعَذَّبَ، فَجَمَعَ النَّاسَ فِي بَيْتِ الْمَقْدِسِ فَامْتَلَأَ الْمَسْجِدُ وَقَعَدُوا عَلَى الشُّرَفِ، فَقَالَ: إِنَّ اللَّهَ أَمَرَنِي بِخَمْسِ كَلِمَاتٍ أَنْ أَعْمَلَ بِهِنَّ وَآمُرَكُمْ أَنْ تَعْمَلُوا بِهِنَّ، أَوَّلُهُنَّ: أَنْ تَعْبُدُوا اللَّهَ وَلَا تُشْرِكُوا بِهِ شَيْئًا، وَإِنَّ مَثَلَ مَنْ أَشْرَكَ بِاللَّهِ كَمَثَلِ رَجُلٍ اشْتَرَى عَبْدًا مِنْ خَالِصِ مَالِهِ بِذَهَبٍ أَوْ وَرِقٍ فَقَالَ: هَذِهِ دَارِي وَهَذَا عَمَلِي فَاعْمَلْ وَأَدِّ إِلَيَّ، فَكَانَ يَعْمَلُ وَيُؤَدِّي إِلَى غَيْرِ سَيِّدِهِ، فَأَيُّكُمْ يَرْضَى أَنْ يَكُونَ عَبْدُهُ كَذَلِكَ ؟.وَإِنَّ اللَّهَ أَمَرَكُمْ بِالصَّلَاةِ فَإِذَا صَلَّيْتُمْ فَلَا تَلْتَفِتُوا، فَإِنَّ اللَّهَ يَنْصِبُ وَجْهَهُ لِوَجْهِ عَبْدِهِ فِي صَلَاتِهِ مَا لَمْ يَلْتَفِتْ...(فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ)."],"takhrij":"صحيح: رواه الترمذيّ (2863) عن محمد بن إسماعيل (البخاريّ) حدثنا موسى بن إسماعيل، حدثنا أبان بن يزيد، حدثنا يحيى بن أبي كثير، عن زيد بن سلام، أنّ أبا سلاّم، حدّثه، فذكر الحديث بطوله، وقد تقدّم في موضعه.","grade":"صحيح","chapter_ar":"باب ما جاء في إثبات الوجه لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Tirmidhī (2863), who said:","chapter_en":"What Has Been Reported Concerning Affirming the Face for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["Al-Ḥārith al-Ashʿarī may Allah be pleased with him reported that the Prophet ﷺ said: “Allah commanded Yaḥyā ibn Zakariyyā with five commands: that he act upon them and command the Children of Israel to act upon them… And Allah has commanded you to pray. When you pray, do not turn away, for Allah directs His Face toward the face of His servant during his prayer so long as the servant does not turn away…”"]},"buhuth":{"en":["“A Ḥasan Ṣaḥīḥ Gharīb ḥadīth.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (2863)، وقال:."},{"num":316,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ أَنّ نَبِيَّ اللَّهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ أَدَّى زَكَاةَ مَالِهِ، طَيِّبَ النَّفْسِ بِهَا، يُرِيدُ وَجْهَ اللَّهِ وَالدَّارَ الآخِرَةِ لَمْ يُغَيِّبْ شَيْئًا مِنْ مَالِهِ، وَأَقَامَ الصَّلاةَ، ثُمَّ أَدَّى الزَّكَاةَ فَتَعَدَّى عَلَيْهِ الْحَقَّ فَأَخَذَ سِلاحَهُ فَقَاتَلَ فَقُتِلَ فَهُوَ شَهِيدٌ."],"takhrij":"حسن: رواه الإمام أحمد (26574)، والطبراني في الكبير (632) كلاهما من طريق عبيد الله بن عمرو، عن زيد بن أبي أنيسة، عن القاسم بن عوف، عن علي بن الحسين، قال: حدّثتنا أمّ سلمة، فذكرت الحديث بطوله، وسيأتي في موضعه، واختصره الإمام أحمد فلم يذكر موضع الشّاهد وهو: يريد بها وجه الله.","grade":"حسن","chapter_ar":"باب ما جاء في إثبات الوجه لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (26574) and al-Ṭabarānī in al-Muʿjam al-Kabīr (23/287), and authenticated by Ibn Khuzaymah (2336).","chapter_en":"What Has Been Reported Concerning Affirming the Face for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["Umm Salamah may Allah be pleased with her reported that the Prophet of Allah ﷺ said: “Whoever pays the zakāh due upon his wealth willingly and with a content heart, seeking thereby the Face of Allah and the Hereafter, conceals nothing of his wealth, establishes the prayer, and then pays the zakāh; but afterward his right is transgressed against, so he takes up his weapon, fights, and is killed — then he is a martyr.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (26574)، والطبراني في الكبير (632)، وصححه ابن خزيمة (2336)."},{"num":317,"demo":false,"sanad":"","matn":["عَنْ عَطَاءِ بْنِ السَّائِبِ، عَنْ أَبِيهِ قَالَ: صَلَّى بِنَا عَمَّارُ بْنُ يَاسِرٍ صَلَاةً فَأَوْجَزَ فِيهَا، فَقَالَ لَهُ بَعْضُ الْقَوْمِ: لَقَدْ خَفَّفْتَ أَوْ أَوْجَزْتَ الصَّلَاةَ، فَقَالَ: أَمَّا عَلَى ذَلِكَ فَقَدْ دَعَوْتُ فِيهَا بِدَعَوَاتٍ سَمِعْتُهُنَّ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا قَامَ تَبِعَهُ رَجُلٌ مِنَ الْقَوْمِ هُوَ أُبَيٌّ غَيْرَ أَنَّهُ كَنَى عَنْ نَفْسِهِ فَسَأَلَهُ عَنِ الدُّعَاءِ، ثُمَّ جَاءَ فَأَخْبَرَ بِهِ الْقَوْمَ: اللَّهُمَّ بِعِلْمِكَ الْغَيْبَ وَقُدْرَتِكَ عَلَى الْخَلْقِ أَحْيِنِي مَا عَلِمْتَ الْحَيَاةَ خَيْرًا لِي، وَتَوَفَّنِي إِذَا عَلِمْتَ الْوَفَاةَ خَيْرًا لِي، اللَّهُمَّ وَأَسْأَلُكَ خَشْيَتَكَ فِي الْغَيْبِ وَالشَّهَادَةِ، وَأَسْأَلُكَ كَلِمَةَ الْحَقِّ فِي الرِّضَا وَالْغَضَبِ، وَأَسْأَلُكَ الْقَصْدَ فِي الْفَقْرِ وَالْغِنَى وَأَسْأَلُكَ نَعِيمًا لَا يَنْفَدُ، وَأَسْأَلُكَ قُرَّةَ عَيْنٍ لَا تَنْقَطِعُ، وَأَسْأَلُكَ الرِّضَاءَ بَعْدَ الْقَضَاءِ، وَأَسْأَلُكَ بَرْدَ الْعَيْشِ بَعْدَ الْمَوْتِ، وَأَسْأَلُكَ لَذَّةَ النَّظَرِ إِلَى وَجْهِكَ وَالشَّوْقَ إِلَى لِقَائِكَ فِي غَيْرِ ضَرَّاءَ مُضِرَّةٍ وَلَا فِتْنَةٍ مُضِلَّةٍ، اللَّهُمَّ زَيِّنَّا بِزِينَةِ الْإِيمَانِ وَاجْعَلْنَا هُدَاةً مُهْتَدِينَ."],"takhrij":"صحيح: رواه النسائيّ (1305) عن يحيى بن حبيب بن عربي، قال: حدّثنا حمّاد، قال: حدّثنا عطاء بن السّائب، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في إثبات الوجه لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Nasāʾī (1305) and al-Dārimī in al-Radd ʿalā al-Jahmiyyah (188).","chapter_en":"What Has Been Reported Concerning Affirming the Face for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["ʿAṭāʾ ibn al-Sāʾib reported from his father: ʿAmmār ibn Yāsir may Allah be pleased with him led us in prayer and made it brief… He then informed the people of the supplication: “O Allah, by Your knowledge of the unseen and Your power over creation, keep me alive for as long as You know life to be better for me… I ask You for the delight of looking upon Your Face and for longing to meet You, without harmful adversity and without a misleading trial. O Allah, adorn us with the adornment of faith and make us rightly guided guides.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11373],"tks":"صحيح: رواه النسائي (1305)، والدارمي في الرد على الجهمية (188)."},{"num":318,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَسْعُودٍ الْأَنْصَارِيِّ قَالَ: كُنْتُ أَضْرِبُ غُلَامًا لِي فَسَمِعْتُ مِنْ خَلْفِي صَوْتًا اعْلَمْ أَبَا مَسْعُودٍ لَلَّهُ أَقْدَرُ عَلَيْكَ مِنْكَ عَلَيْهِ فَالْتَفَتُّ، فَإِذَا هُوَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا رَسُولَ اللَّهِ، هُوَ حُرٌّ لِوَجْهِ اللَّهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَمَا لَوْ لَمْ تَفْعَلْ لَلَفَحَتْكَ النَّارُ أَوْ لَمَسَّتْكَ النَّارُ."],"takhrij":"صحيح: رواه مسلم في الأيمان والنذور (1659: 35) عن أبي كريب محمد ابن العلاء، حدثنا أبو معاوية، حدثنا الأعمش، عن إبراهيم التيميّ، عن أبيه، عن أبي مسعود الأنصاريّ، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في إثبات الوجه لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in al-Aymān wa al-Nudhūr (1658:35).","chapter_en":"What Has Been Reported Concerning Affirming the Face for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["Abū Masʿūd al-Anṣārī, may Allah be pleased with him, reported: I was striking a servant of mine when I heard a voice behind me that I did not recognize: “O Abū Masʿūd! Allah has more power over you than you have over him.” I turned around and found that it was the Messenger of Allah ﷺ. I said: “O Messenger of Allah, he is free for the Face of Allah.” The Messenger of Allah ﷺ said: “Had you not done so, the Fire would have scorched you — or the Fire would have touched you.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1658: 35)."},{"num":319,"demo":false,"sanad":"","matn":["عَنْ صُهَيْبٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي قَوْلُهُ عَزَّ وَجَلَّ: ﴿لِلَّذِينَ أَحْسَنُوا الْحُسْنَى وَزِيَادَةٌ﴾ [يونس: 26] قَالَ: النَّظَرُ إِلَى وَجْهِ رَبِّنَا عَزَّ وَجَلَّ."],"takhrij":"حسن: رواه البيهقيّ في الأسماء والصفات (665) بإسناده عن قبيصة بن عقبة أبي عامر، ثنا حماد بن سلمة، عن ثابت، عن عبدالرحمن بن أبي ليلى، عن صهيب، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في إثبات الوجه لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Bayhaqī in al-Asmāʾ wa al-Ṣifāt (665).","chapter_en":"What Has Been Reported Concerning Affirming the Face for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["Ṣuhayb may Allah be pleased with him reported that the Messenger of Allah ﷺ said concerning the words of Allah, Mighty and Majestic: “For those who do good is the best reward and an increase.” [Sūrat Yūnus 10:26] He said: “The increase is looking upon the Face of our Lord, Mighty and Majestic.”"]},"buhuth":{"en":["Hannād ibn al-Sarī also narrated it in al-Zuhd (171) with the wording:","The Messenger of Allah ﷺ recited:","“For those who do good is the best reward and an increase.”","Then he said:","“When the people of Paradise have entered Paradise and the people of the Fire have entered the Fire, a caller will call:","‘O people of Paradise, you have an appointment with Allah which He intends to fulfill for you.’","They will say:","‘What is it? Has Allah not made our scales heavy, brightened our faces, admitted us into Paradise, and saved us from the Fire?’","Then the veil will be removed and He will manifest Himself, and they will look upon Him.","By Allah, He will not have given them anything more beloved to them than looking upon Him — and that is the increase.”","The basis of this ḥadīth is found in Ṣaḥīḥ Muslim (181), where the wording is:","“Looking upon their Lord, Mighty and Majestic.”","The word “Face” is not mentioned in that version."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البيهقي في الأسماء والصفات (665)."},{"num":320,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا بَعَثَ اللَّهُ مِنْ نَبِيٍّ إِلَّا أَنْذَرَ قَوْمَهُ الْأَعْوَرَ الْكَذَّابَ، إِنَّهُ أَعْوَرُ، وَإِنَّ رَبَّكُمْ لَيْسَ بِأَعْوَرَ، مَكْتُوبٌ بَيْنَ عَيْنَيْهِ كَافِرٌ."],"takhrij":"متفق عليه: رواه البخاريّ في التوحيد (7408)، ومسلم في الفتن (2933) كلاهما من حديث شعبة، قال: أخبرنا قتادة، قال: سمعت أنساً، عن النّبيّ صلى الله عليه وسلم، فذكره.","grade":"متفق عليه","chapter_ar":"باب إثبات العينين لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7408) and Muslim (2933).","chapter_en":"Affirming the Two Eyes for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":21,"content":{"translation":{"en":["Anas may Allah be pleased with him reported that the Prophet ﷺ said: “Allah did not send any prophet except that he warned his people of the one-eyed liar. Indeed, he is one-eyed, while your Lord is not one-eyed. Written between his eyes is: ‘Disbeliever.’”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (7408)، ومسلم (2933)."},{"num":321,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ قَالَ: ذَكَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا بَيْنَ ظَهْرَيِ النَّاسِ الْمَسِيحَ الدَّجَّالَ، فَقَالَ: إِنَّ اللَّهَ لَيْسَ بِأَعْوَرَ أَلَا إِنَّ الْمَسِيحَ الدَّجَّالَ أَعْوَرُ الْعَيْنِ الْيُمْنَى كَأَنَّ عَيْنَهُ عِنَبَةٌ طَافِيَةٌ...(فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ)."],"takhrij":"متفق عليه: رواه البخاريّ في أحاديث الأنبياء (3439)، ومسلم في كتاب الإيمان (169: 274)، كلاهما من حديث أنس بن عياض أبي ضمرة، عن موسى ابن عقبة، عن نافع، عن ابن عمر، فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب إثبات العينين لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in Aḥādīth al-Anbiyāʾ (3439) and Muslim in al-Īmān (169:274).","chapter_en":"Affirming the Two Eyes for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":21,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar, may Allah be pleased with them, reported: One day, the Prophet ﷺ mentioned the False Messiah, the Dajjāl, while among the people and said: “Indeed, Allah is not one-eyed. Be aware that the False Messiah, the Dajjāl, is blind in his right eye, as though his eye were a floating grape.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3439)، ومسلم (169: 274)."},{"num":322,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّهُ لَمْ يَكُنْ نَبِيٌّ إِلَّا وَصَفَ الدَّجَّالَ لِأُمَّتِهِ، وَلَأَصِفَنَّهُ صِفَةً لَمْ يَصِفْهَا أَحَدٌ كَانَ قَبْلِي، إِنَّهُ أَعْوَرُ، وَإِنَّ اللَّهَ عَزَّ وَجَلَّ لَيْسَ بِأَعْوَرَ."],"takhrij":"حسن: رواه الإمام أحمد (1526)، والبزار في البحر الزّخار (1108)، وأبو يعلى (725) كلهم من طريق يزيد بن هارون، أخبرنا محمد بن إسحاق، عن داود بن عامر بن سعد بن مالك، عن أبيه، عن جدّه، فذكره.","grade":"حسن","chapter_ar":"باب إثبات العينين لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan due to supporting narrations: Narrated by Imām Aḥmad (1526), al-Bazzār (1108), and Abū Yaʿlā (725).","chapter_en":"Affirming the Two Eyes for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":21,"content":{"translation":{"en":["Saʿd ibn Abī Waqqāṣ may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “There was no prophet except that he described the Dajjāl to his nation. I will describe him to you with a description that no one before me gave: he is one-eyed, whereas Allah, Mighty and Majestic, is not one-eyed.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[16042],"tks":"حسن: رواه الإمام أحمد (1526)، والبزار (1108)، وأبو يعلى (725)."},{"num":323,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: دَخَلَ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا أَبْكِي، فَقَالَ لِي: مَا يُبْكِيكِ؟ قُلْتُ: يَا رَسُولَ اللَّهِ، ذَكَرْتُ الدَّجَّالَ فَبَكَيْتُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنْ يَخْرُجْ الدَّجَّالُ وَأَنَا حَيٌّ كَفَيْتُكُمُوهُ، وَإِنْ يَخْرُجْ بَعْدِي، فَإِنَّ رَبَّكُمْ عَزَّ وَجَلَّ لَيْسَ بِأَعْوَرَ...فِي حَدِيثِ طَوِيل."],"takhrij":"حسن: رواه الإمام أحمد (24467) عن سليمان بن داود، حدثنا حرب بن شدّاد، عن يحيى بن أبي كثير، قال: حدثني الحضرميّ بن لاحق، أن ذكوان أبا صالح، أخبره عن عائشة، فذكرتْ مثله.","grade":"حسن","chapter_ar":"باب إثبات العينين لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (24467), and authenticated by Ibn Ḥibbān (6822).","chapter_en":"Affirming the Two Eyes for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":21,"content":{"translation":{"en":["ʿĀʾishah may Allah be pleased with her reported: The Messenger of Allah ﷺ entered upon me while I was crying. He asked: “What makes you cry?” I replied: “O Messenger of Allah, you mentioned the Dajjāl, so I cried.” The Messenger of Allah ﷺ said: “If the Dajjāl emerges while I am alive, I will suffice you against him. But if he emerges after me, then indeed your Lord, Mighty and Majestic, is not one-eyed.” This occurs within a longer ḥadīth."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (24467)، وصححه ابن حبان (6822)."},{"num":324,"demo":false,"sanad":"","matn":["عَنْ أَبِي يُونُسَ سُلَيْم بْنِ جُبَيْرٍ مَوْلَى أَبِي هُرَيْرَةَ قَالَ: سَمِعْتُ أَبَا هُرَيْرَةَ يَقْرَأُ هَذِهِ الْآيَةَ: ﴿إِنَّ اللَّهَ يَأْمُرُكُمْ أَنْ تُؤَدُّوا الْأَمَانَاتِ إِلَى أَهْلِهَا﴾ إِلَى قَوْلِهِ: ﴿إِنَّ اللَّهَ كَانَ سَمِيعًا بَصِيرًا﴾ [سورة النساء: 58] قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَضَعُ إِبْهَامَهُ عَلَى أُذُنِهِ وَالَّتِي تَلِيهَا عَلَى عَيْنِهِ، قَالَ أَبُو هُرَيْرَةَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْرَؤُهَا وَيَضَعُ إِصْبَعَيْهِ. قَالَ ابْنُ يُونُسَ: قَالَ الْمُقْرِئُ: يَعْنِي إِنَّ اللَّهَ سَمِيعٌ بَصِيرٌ: يَعْنِي أَنَّ لِلَّهِ سَمْعًا وَبَصَرًا، قال أَبُو دَاوُد: وَهَذَا رَدٌّ عَلَى الْجَهْمِيَّةِ."],"takhrij":"صحيح: رواه أبو داود (4728) عن علي بن نصر، ومحمد بن يونس النسائيّ، المعنى، قالا: حدّثنا عبدالله بن يزيد المقرئ، حدّثنا حرملة، يعني ابن عمران، ، حدّثني أبو يونس سليم بن حبيب، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب إثبات العينين لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (4728), and authenticated and narrated by Ibn Khuzaymah in Kitāb al-Tawḥīd (49).","chapter_en":"Affirming the Two Eyes for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":21,"content":{"translation":{"en":["Abū Yūnus Sulaym ibn Jubayr, the freedman of Abū Hurayrah, reported: I heard Abū Hurayrah reciting the verse: “Indeed, Allah commands you to render trusts to those to whom they are due…” until the words: “Indeed, Allah is All-Hearing, All-Seeing.” [Sūrat al-Nisāʾ 4:58] He said: “I saw the Messenger of Allah ﷺ place his thumb upon his ear and the finger next to it upon his eye.” Abū Hurayrah said: “I saw the Messenger of Allah ﷺ reciting the verse and placing his two fingers.” Ibn Yūnus said: The reciter explained that Allah is Hearing and Seeing; that is, Allah possesses hearing and sight. Abū Dāwūd said: “This is a refutation of the Jahmiyyah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4728)، وصححه ابن خزيمة وأخرجه في كتاب التوحيد (49)."},{"num":325,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ زَوْجُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: ذَكَرْتُ الْمَسِيحَ الدَّجَّالَ لَيْلَةً، فَلَمْ يَأْتِنِي النَّوْمُ، فَلَمَّا أَصْبَحْتُ دَخَلْتُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرْتُهُ، فَقَالَ: لَا تَفْعَلِي، فَإِنَّهُ إِنْ يَخْرُجْ وَأَنَا حَيٌّ يَكْفِيكُمُوهُ اللَّهُ بِي، وَإِنْ يَخْرُجَ بَعْدَ أَنْ أَمُوتَ يَكْفِيكُمُوهُ اللَّهُ بِالصَّالِحِينَ، ثُمَّ قَالَ: مَا مِنْ نَبِيٍّ إِلَّا وَقَدْ حَذَّرَ أُمَّتَهُ الدَّجَّالَ، وَإِنِّي أُحَذِّرُكُمُوهُ، إِنَّهُ أَعْوَرُ، وَإِنَّ اللَّهَ لَيْسَ بِأَعْوَرَ، إِنَّهُ يَمْشِي فِي الْأَرْضِ، وَإِنَّ الْأَرْضَ وَالسَّمَاءَ لِلَّهِ، إِلَّا أَنَّ الْمَسِيحَ عَيْنَهُ الْيُمْنَى كَأَنَّهَا عِنَبَةٌ طَافِيَةٌ."],"takhrij":"حسن: رواه ابن خزيمة في التوحيد (56) عن أحمد بن عبدالرحمن بن وهب، قال: حدثنا عمّي، قال: حدثنا مخرمة بن بكير بن عبدالله بن الأشجّ، عن أبيه، عن عروة بن الزبير، قال: قالت أمُّ سلمة زوج النبيّ صلى الله عليه وسلم، فذكرت مثله.","grade":"حسن","chapter_ar":"باب إثبات العينين لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Khuzaymah in al-Tawḥīd (56).","chapter_en":"Affirming the Two Eyes for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":21,"content":{"translation":{"en":["Umm Salamah may Allah be pleased with her, the wife of the Prophet ﷺ, reported: One night I thought about the False Messiah, the Dajjāl, and sleep would not come to me. When morning came, I entered upon the Messenger of Allah ﷺ and told him. He said: “Do not do that. If he emerges while I am alive, Allah will suffice you against him through me; and if he emerges after I die, Allah will suffice you against him through the righteous.” Then he said: “There was no prophet except that he warned his nation about the Dajjāl, and I am warning you about him. He is one-eyed, whereas Allah is not one-eyed. He walks upon the earth, while the earth and the heaven belong to Allah. Be aware that the right eye of the False Messiah, the Dajjāl, is like a floating grape.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن خزيمة في التوحيد (56)."},{"num":326,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ بِنْتِ يَزِيدَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَلَسَ مَجْلِسًا مَرَّةً يُحَدِّثُهُمْ عَنْ أَعْوَرِ الدَّجَّالِ فَمِمَّا فَذَكَرَ فِيهِ: فَمَنْ حَضَرَ مَجْلِسِي وَسَمِعَ قَوْلِي، فَلْيُبَلِّغْ الشَّاهِدُ مِنْكُمْ الْغَائِبَ، وَاعْلَمُوا أَنَّ اللَّهَ عَزَّ وَجَلَّ صَحِيحٌ لَيْسَ بِأَعْوَرَ، وَأَنَّ الدَّجَّالَ أَعْوَرُ مَمْسُوحُ الْعَيْنِ، بَيْنَ عَيْنَيْهِ مَكْتُوبٌ كَافِرٌ يَقْرَؤُهُ كُلُّ مُؤْمِنٍ كَاتِبٍ وَغَيْرِ كَاتِبٍ."],"takhrij":"حسن: رواه الإمام أحمد (27585)، والطبراني في الكبير (430)، والحارث في مسنده، زوائده (783)، كلّهم من طرق عن عبدالحميد بن بهرام، قال: حدثنا شهر بن حوشب، قال: وحدثتني أسماء بنت يزيد، فذكرته.","grade":"حسن","chapter_ar":"باب إثبات العينين لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan due to supporting narrations: Narrated by Aḥmad (27585) and al-Ṭabarānī in al-Muʿjam al-Kabīr (24/177).","chapter_en":"Affirming the Two Eyes for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":21,"content":{"translation":{"en":["Asmāʾ bint Yazīd may Allah be pleased with her reported: The Messenger of Allah ﷺ once sat in a gathering speaking to them about the one-eyed Dajjāl. Among what he said was: “Whoever is present in my gathering and hears my words should convey them to those who are absent. Know that Allah, Mighty and Majestic, is perfect and not one-eyed, while the Dajjāl is one-eyed, with an obliterated eye. Between his eyes is written ‘Disbeliever,’ which every believer will read, whether literate or illiterate.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (27585)، والطبراني في الكبير (430)."},{"num":327,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ فِي حَدِيثِ طَوِيلٍ فِي خُرُوجِ الدَّجَّالِ، وَفِيه: فَيَقُولُ لِلنَّاسِ: أَنَا رَبُّكُمْ. وَهُوَ أَعْوَرُ، وَإِنَّ رَبَّكُمْ لَيْسَ بِأَعْوَرَ."],"takhrij":"حسن: رواه الإمام أحمد (14954) عن محمد بن سابق، حدثنا إبراهيم بن طهمان، عن أبي الزبير، عن جابر، فذكر الحديث.","grade":"حسن","chapter_ar":"باب إثبات العينين لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (14954), and authenticated by Ibn Khuzaymah in Kitāb al-Tawḥīd (55) and al-Ḥākim (4/530).","chapter_en":"Affirming the Two Eyes for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":21,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh may Allah be pleased with them reported, in a lengthy ḥadīth concerning the emergence of the Dajjāl, that among it is: “He will say to the people: ‘I am your Lord,’ while he is one-eyed, whereas your Lord is not one-eyed.”"]},"buhuth":{"en":["Imām al-Dārimī said in al-Radd ʿalā al-Marīsī (1/327):","“In the explanation of the statement of the Messenger of Allah ﷺ, ‘Allah is not one-eyed,’ is a clarification that He has two eyes, unlike one who is one-eyed.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (14954)، وصححه ابن خزيمة في كتاب التوحيد (55)، والحاكم (4/530)."},{"num":328,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أُمَّ الْمُؤْمِنِينَ أَنَّهَا قَالَتْ: لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَا رَسُولَ اللَّهِ! هَلْ أَتَى عَلَيْكَ يَوْمٌ كَانَ أَشَدَّ مِنْ يَوْمِ أُحُدٍ؟ فَقَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَذَكَرَ مَا لَقِيَ مِنْ قَوْمِهَا وَ قَالَ: فَانْطَلَقْتُ وَأَنَا مَهْمُومٌ عَلَى وَجْهِ، فَلَمْ أَسْتَفِقْ إِلَّا بِقَرْنِ الثَّعَالِبِ فَرَفَعْتُ رَأْسِي، فَإِذَا أَنَا بِسَحَابَةٍ قَدْ أَظَلَّتْنِي، فَنَظَرْتُ فَإِذَا فِيهَا جِبْرِيل، فَنَادَانِي فَقَالَ: إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ سَمِعَ قَوْلَ قَوْمِكَ لَكَ، وَمَا رُدُّوا عَلَيْكَ وَقَدْ بَعَثَ إِلَيْكَ مَلَكَ الْجِبَالِ لِتَأْمُرَهُ بِمَا شِئْتَ فِيهِم، قَالَ: فَنَادَانِي مَلَكُ الْجِبَالِ وَسَلَّمَ عَلَيَّ ثُمَّ قَالَ: يَا مُحَمَّدُ! إِنَّ اللَّهَ قَدْ سَمِعَ قَوْلَ قَوْمِكَ لَكَ وَأَنَا مَلَكُ الْجِبَال، وَقَدْ بَعَثَنِي رَبُّكَ إِلَيْكَ لِتَأْمُرَنِي بِأَمْرِكَ.... الْحَدِيثَ."],"takhrij":"متفق عليه: رواه البخاريّ في بدء الخلق (3231)، ومسلم في الجهاد والسير (1795) كلاهما من حديث ابن وهب، قال: أخبرني يونس، عن ابن شهاب، حدثني عروة، عن عائشة، فذكر الحديث بطوله، وهو مذكور في الإيمان بالملائكة.","grade":"متفق عليه","chapter_ar":"باب إثبات السمع والبصر لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3231) and Muslim (1795).","chapter_en":"Affirming Hearing and Seeing for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":22,"content":{"translation":{"en":["ʿĀʾishah, Mother of the Believers may Allah be pleased with her, asked the Prophet ﷺ: “Has there ever come upon you a day more severe than the Day of Uḥud?” He then mentioned what he had suffered from his people and said: “I went away, distressed and wandering, and did not regain full awareness until I reached Qarn al-Thaʿālib. I raised my head and saw a cloud shading me. I looked and saw Jibrīl, peace be upon him, within it. He called to me and said: ‘O Muḥammad, Allah, Mighty and Majestic, has heard what your people said to you and how they responded to you. Allah has sent the Angel of the Mountains to you so that you may command him to do whatever you wish concerning them.’” He continued: “Then the Angel of the Mountains called me, greeted me with salām, and said: ‘O Muḥammad, Allah, Mighty and Majestic, has heard what your people said to you. I am the Angel of the Mountains, and your Lord has sent me to you so that you may command me as you wish.’” He then mentioned the ḥadīth in full. It is recorded in the section concerning belief in the angels."]},"intro":{"ar":["قال الله تعالى:","﴿لَقَدْ سَمِعَ اللهُ قَوْلَ الَّذِينَ قَالُوا إِنَّ اللهَ فَقِيرٌ وَنَحْنُ أَغْنِيَاءُ﴾","[آل عمران: ١٨١]","وقال الله عز وجل في قصة المجادلة:","﴿قَدْ سَمِعَ اللهُ قَوْلَ الَّتِي تُجَادِلُكَ فِي زَوْجِهَا وَتَشْتَكِي إِلَى اللهِ وَاللهُ يَسْمَعُ تَحَاوُرَكُمَا إِنَّ اللهَ سَمِيعٌ بَصِيرٌ﴾","[المجادلة: ١]","وقال تعالى مخاطباً موسى وهارون عليهما السلام:","﴿قَالَ لَا تَخَافَا إِنَّنِي مَعَكُمَا أَسْمَعُ وَأَرَى﴾","[طه: ٤٦]","وقال تعالى:","﴿قَالَ كَلَّا فَاذْهَبَا بِآيَاتِنَا إِنَّا مَعَكُمْ مُسْتَمِعُونَ﴾","[الشعراء: ١٥]"],"en":["Allah Most High said:","“Allah has certainly heard the statement of those who said, ‘Indeed, Allah is poor while we are rich.’”","[Āl ʿImrān 3:181]","And Allah, Mighty and Majestic, said concerning the woman who disputed:","“Allah has certainly heard the statement of the woman who disputes with you concerning her husband and complains to Allah. Allah hears your conversation. Indeed, Allah is All-Hearing, All-Seeing.”","[Sūrat al-Mujādilah 58:1]","And He said, addressing Moses and Aaron peace be upon them:","“Do not fear. Indeed, I am with you both; I hear and I see.”","[Sūrat Ṭā Hā 20:46]","And He said:","“No. Go, both of you, with Our signs. Indeed, We are with you, listening.”","[Sūrat al-Shuʿarāʾ 26:15]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3231)، ومسلم (1795)."},{"num":329,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ قَالَ: لَمَّا غَزَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْبَرَ أَوْ قَالَ: لَمَّا تَوَجَّهَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَشْرَفَ النَّاسُ عَلَى وَادٍ فَرَفَعُوا أَصْوَاتَهُمْ بِالتَّكْبِيرِ: اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، لَا إِلَهَ إِلَّا اللَّهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ارْبَعُوا عَلَى أَنْفُسِكُمْ، إِنَّكُمْ لَا تَدْعُونَ أَصَمَّ وَلَا غَائِبًا، إِنَّكُمْ تَدْعُونَ سَمِيعًا قَرِيبًا وَهُوَ مَعَكُمْ...(فَذَكَرَ الْحَدِيثَ)."],"takhrij":"متفق عليه: رواه البخاريّ في المغازي (4205)، ومسلم في كتاب الذكر (2704) كلاهما من حديث عاصم، عن أبي عثمان، عن أبي موسى، فذكر الحديث، وهذا جزء منه.","grade":"متفق عليه","chapter_ar":"باب إثبات السمع والبصر لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4205) and Muslim (2704).","chapter_en":"Affirming Hearing and Seeing for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":22,"content":{"translation":{"en":["Abū Mūsā al-Ashʿarī, may Allah be pleased with him, reported: When the Messenger of Allah ﷺ went out for the campaign of Khaybar — or he said: when the Messenger of Allah ﷺ set out — the people came upon a valley and raised their voices, saying: “Allāhu akbar, Allāhu akbar, lā ilāha illa Allāh.” The Messenger of Allah ﷺ said: “Be gentle with yourselves. You are not calling upon one who is deaf or absent. Rather, you are calling upon One who is All-Hearing and Near, and He is with you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (4205)، ومسلم (2704)."},{"num":330,"demo":false,"sanad":"","matn":["عَنِ ابْنِ مَسْعُودٍ قَالَ: اجْتَمَعَ عِنْدَ الْبَيْتِ ثَلَاثَةُ نَفَرٍ قُرَشِيَّانِ وَثَقَفِيٌّ أَوْ ثَقَفِيَّانِ وَقُرَشِيٌّ قَلِيلٌ، فِقْهُ قُلُوبِهِمْ كَثِيرٌ شَحْمُ بُطُونِهِمْ، فَقَالَ أَحَدُهُمْ: أَتُرَوْنَ اللَّهَ يَسْمَعُ مَا نَقُولُ؟ وَقَالَ الْآخَرُ: يَسْمَعُ إِنْ جَهَرْنَا وَلَا يَسْمَعُ إِنْ أَخْفَيْنَا، وَقَالَ الْآخَرُ: إِنْ كَانَ يَسْمَعُ إِذَا جَهَرْنَا فَهُوَ يَسْمَعُ إِذَا أَخْفَيْنَا، فَأَنْزَلَ اللَّهُ ﴿وَمَا كُنْتُمْ تَسْتَتِرُونَ أَنْ يَشْهَدَ عَلَيْكُمْ سَمْعُكُمْ وَلَا أَبْصَارُكُمْ وَلَا جُلُودُكُمْ﴾ [سورة فصلت: 22]."],"takhrij":"متفق عليه: رواه البخاريّ في التفسير (4817)، ومسلم في صفات المنافقين (2775) كلاهما من حديث سفيان، عن منصور، عن مجاهد، عن أبي معمر، عن ابن مسعود، فذكره.","grade":"متفق عليه","chapter_ar":"باب إثبات السمع والبصر لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4817) and Muslim (2775).","chapter_en":"Affirming Hearing and Seeing for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":22,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd, may Allah be pleased with him, reported: Three men gathered near the House: two Qurashīs and one Thaqafī, or two Thaqafīs and one Qurashī. They possessed little understanding in their hearts but much flesh upon their bellies. One of them said: “Do you think Allah hears what we say?” Another replied: “He hears us if we speak aloud, but He does not hear us if we speak quietly.” The third said: “If He hears us when we speak aloud, then He also hears us when we speak quietly.” Allah then revealed: “You did not seek to conceal yourselves lest your hearing, your sight, and your skins should testify against you…” [Sūrat Fuṣṣilat 41:22]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4817)، ومسلم (2775)."},{"num":331,"demo":false,"sanad":"","matn":["عَنْ أَبِي يُونُسَ سُلَيْم بْنِ جُبَيْرٍ مَوْلَى أَبِي هُرَيْرَةَ قَالَ: سَمِعْتُ أَبَا هُرَيْرَةَ يَقْرَأُ هَذِهِ الْآيَةَ: ﴿إِنَّ اللَّهَ يَأْمُرُكُمْ أَنْ تُؤَدُّوا الْأَمَانَاتِ إِلَى أَهْلِهَا﴾ إِلَى قَوْلِهِ: ﴿إِنَّ اللَّهَ كَانَ سَمِيعًا بَصِيرًا﴾ [النساء: 58] قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَضَعُ إِبْهَامَهُ عَلَى أُذُنِهِ، وَالَّتِي تَلِيهَا عَلَى عَيْنِهِ، قَالَ أَبُو هُرَيْرَةَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْرَؤُهَا وَيَضَعُ إِصْبَعَيْهِ."],"takhrij":"صحيح: رواه أبو داود (4728) عن علي بن نصر، ومحمد بن يونس النسائيّ، المعنى، قالا: حدّثنا عبدالله بن يزيد المقرئ، حدّثنا حرملة، يعني ابن عمران، ، حدّثني أبو يونس سليم بن حبيب، فذكره. قال ابن يونس: قال المقرئ: يعني أنّ الله سميع بصير. يعني أنّ لله سمعاً وبصراً. قال أبو داود: وهذا ردٌّ على الجهميّة.","grade":"صحيح","chapter_ar":"باب إثبات السمع والبصر لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (4728), and authenticated and narrated by Ibn Khuzaymah in Kitāb al-Tawḥīd (49).","chapter_en":"Affirming Hearing and Seeing for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":22,"content":{"translation":{"en":["Abū Yūnus Sulaym ibn Jubayr, the freedman of Abū Hurayrah, reported: I heard Abū Hurayrah reciting the verse: “Indeed, Allah commands you to render trusts to those to whom they are due…” until the words: “Indeed, Allah is All-Hearing, All-Seeing.” [Sūrat al-Nisāʾ 4:58] He said: “I saw the Messenger of Allah ﷺ place his thumb upon his ear and the finger next to it upon his eye.” Abū Hurayrah said: “I saw the Messenger of Allah ﷺ reciting it and placing his two fingers.” Ibn Yūnus said: The reciter explained that Allah is Hearing and Seeing; that is, Allah possesses hearing and sight. Abū Dāwūd said: “This is a refutation of the Jahmiyyah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4728)، وصححه ابن خزيمة وأخرجه في كتاب التوحيد (49)."},{"num":332,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: الْحَمْدُ لِلَّهِ الَّذِي وَسِعَ سَمْعُهُ الْأَصْوَاتَ، لَقَدْ جَاءَتْ خَوْلَةُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَشْكُو زَوْجَهَا، فَكَانَ يَخْفَى عَلَيَّ كَلَامُهَا، فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ: ﴿قَدْ سَمِعَ اللَّهُ قَوْلَ الَّتِي تُجَادِلُكَ فِي زَوْجِهَا وَتَشْتَكِي إِلَى اللَّهِ وَاللَّهُ يَسْمَعُ تَحَاوُرَكُمَا إِنَّ اللَّهَ سَمِيعٌ بَصِيرٌ﴾ [سورة المجادلة: 1]."],"takhrij":"صحيح: رواه النسائيّ (3460)، وابن ماجه (188) كلاهما من حديث الأعمش، عن تميم بن سلمة، عن عروة بن الزبير، عن عائشة فقالت، مثله.","grade":"صحيح","chapter_ar":"باب إثبات السمع والبصر لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Nasāʾī (3460) and Ibn Mājah (188), also narrated by Aḥmad (24195), and authenticated by al-Ḥākim (2/481).","chapter_en":"Affirming Hearing and Seeing for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":22,"content":{"translation":{"en":["ʿĀʾishah may Allah be pleased with her reported: “All praise belongs to Allah whose hearing encompasses all voices. Khawlah came to the Messenger of Allah ﷺ complaining about her husband, and some of what she was saying was hidden from me. Then Allah, Mighty and Majestic, revealed: ‘Allah has certainly heard the statement of the woman who disputes with you concerning her husband and complains to Allah. Allah hears your conversation. Indeed, Allah is All-Hearing, All-Seeing.’” [Sūrat al-Mujādilah 58:1]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (3460)، وابن ماجه (188)، ورواه أحمد (24195)، وصححه الحاكم (2/481)."},{"num":333,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَجْمَعُ اللَّهُ النَّاسَ يَوْمَ الْقِيَامَةِ فَيَهْتَمُّونَ لِذَلِكَ، وَفِي رِوَايَةِ: فَيُلْهَمُونَ لِذَلِكَ، فَيَقُولُونَ: لَوِ اسْتَشْفَعْنَا عَلَى رَبِّنَا حَتَّى يُرِيحَنَا مِنْ مَكَانِنَا هَذَا فَيَأْتُونَ آدَمَ فَيَقُولُونَ: أَنْتَ آدَمُ أَبُو الْخَلْقِ، خَلَقَكَ اللَّهُ بِيَدِهِ وَنَفَخَ فِيكَ مِنْ رُوحِهِ...فَذَكَرَ الْحَدِيثَ بِطُولِهِ، وَهُوَ حَدِيثٌ الشَّفَاعَة."],"takhrij":"متفق عليه: رواه البخاريّ في الرّقاق (6565)، ومسلم في الإيمان (193) كلاهما من حديث أبي عوانة، عن قتادة، عن أنس، فذكر الحديث بطوله.","grade":"متفق عليه","chapter_ar":"باب إثبات اليدين لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6565) and Muslim (193).","chapter_en":"Affirming the Two Hands for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":23,"content":{"translation":{"en":["Anas ibn Mālik may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Allah will gather the people on the Day of Resurrection, and they will become deeply distressed because of it.” In another wording: “They will be inspired concerning what to do.” They will say: “If only we could seek someone to intercede with our Lord so that He might relieve us from this place of ours.” They will come to Adam and say: “You are Adam, the father of creation. Allah created you with His Hand and breathed into you from His spirit…” He then mentioned the lengthy ḥadīth of intercession."]},"intro":{"ar":["قال الله تعالى:","﴿وَقَالَتِ الْيَهُودُ يَدُ اللهِ مَغْلُولَةٌ غُلَّتْ أَيْدِيهِمْ وَلُعِنُوا بِمَا قَالُوا بَلْ يَدَاهُ مَبْسُوطَتَانِ يُنْفِقُ كَيْفَ يَشَاءُ﴾","[المائدة: ٦٤]","وقال تعالى:","﴿مَا مَنَعَكَ أَنْ تَسْجُدَ لِمَا خَلَقْتُ بِيَدَيَّ﴾","[ص: ٧٥]","وقال تعالى:","﴿فَسُبْحَانَ الَّذِي بِيَدِهِ مَلَكُوتُ كُلِّ شَيْءٍ وَإِلَيْهِ تُرْجَعُونَ﴾","[يس: ٨٣]","وقال تعالى:","﴿وَتُعِزُّ مَنْ تَشَاءُ وَتُذِلُّ مَنْ تَشَاءُ بِيَدِكَ الْخَيْرُ إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ﴾","[آل عمران: ٢٦]"],"en":["Allah Most High said:","“The Jews say, ‘Allah’s Hand is chained.’ Chained are their hands, and cursed are they for what they say. Rather, both His Hands are outstretched; He spends however He wills.”","[Sūrat al-Māʾidah 5:64]","And He said:","“What prevented you from prostrating to that which I created with My two Hands?”","[Sūrat Ṣād 38:75]","And He said:","“So glory be to the One in whose Hand is the dominion of all things, and to Him you will be returned.”","[Sūrat Yā Sīn 36:83]","And He said:","“You honor whom You will and humiliate whom You will. In Your Hand is all good. Indeed, You have power over all things.”","[Āl ʿImrān 3:26]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6565)، ومسلم (193)."},{"num":334,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: احْتَجَّ آدَمُ، وَمُوسَى، فَقَالَ لَهُ مُوسَى: يَا آدَمُ، أَنْتَ أَبُونَا خَيَّبْتَنَا وَأَخْرَجْتَنَا مِنَ الْجَنَّةِ، قَالَ لَهُ آدَمُ: يَا مُوسَى، اصْطَفَاكَ اللَّهُ بِكَلَامِهِ وَخَطَّ لَكَ بِيَدِهِ...(فَذَكَرَ الْحَدِيثَ)."],"takhrij":"متفق عليه: رواه البخاريّ في القدر (6614)، ومسلم في القدر (2652) كلاهما من حديث سفيان، عن عمرو بن دينار، عن طاوس، قال: سمعتُ أبا هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب إثبات اليدين لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6614) and Muslim (2652).","chapter_en":"Affirming the Two Hands for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":23,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Prophet ﷺ said: “Adam and Moses disputed. Moses said to him: ‘O Adam, you are our father. You disappointed us and caused us to be expelled from Paradise.’ Adam replied: ‘O Moses, Allah chose you with His Speech and wrote for you with His Hand…’”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6614)، ومسلم (2652)."},{"num":335,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: احْتَجَّ آدَمُ، وَمُوسَى عَلَيْهِمَا السَّلَام عِنْدَ رَبِّهِمَا، فَحَجَّ آدَمُ مُوسَى، قَالَ مُوسَى: أَنْتَ آدَمُ الَّذِي خَلَقَكَ اللَّهُ بِيَدِهِ، وَنَفَخَ فِيكَ مِنْ رُوحِهِ، وَأَسْجَدَ لَكَ مَلَائِكَتَهُ وَأَسْكَنَكَ فِي جَنَّتِهِ، ثُمَّ أَهْبَطْتَ النَّاسَ بِخَطِيئَتِكَ إِلَى الْأَرْضِ...(فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ)."],"takhrij":"صحيح: رواه مسلم في القدر (2652: 15) عن إسحاق بن موسى، حدثنا أنس بن عياض، حدثني الحارث بن أبي ذباب، عن يزيد بن هرمز، وعبدالرحمن بن الأعرج، قالا: سمعنا أبا هريرة، فذكر الحديث بطوله.","grade":"صحيح","chapter_ar":"باب إثبات اليدين لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in al-Qadar (2652:15).","chapter_en":"Affirming the Two Hands for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":23,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Adam and Moses peace be upon them disputed before their Lord, and Adam prevailed over Moses in the argument. Moses said: ‘You are Adam, whom Allah created with His Hand, breathed into you from His spirit, commanded His angels to prostrate to you, and settled you in His Paradise; then through your sin you caused mankind to descend to the earth…’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2652: 15)."},{"num":336,"demo":false,"sanad":"","matn":["عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ قَالَ: سَأَلَ مُوسَى رَبَّهُ: مَا أَدْنَى أَهْلِ الْجَنَّةِ مَنْزِلَةً؟... قَالَ (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ): رَبِّ فَأَعْلَاهُمْ مَنْزِلَةً، قَالَ: أُولَئِكَ الَّذِينَ أَرَدْتُ غَرَسْتُ كَرَامَتَهُمْ بِيَدِي وَخَتَمْتُ عَلَيْهَا، فَلَمْ تَرَ عَيْنٌ، وَلَمْ تَسْمَعْ أُذُنٌ، وَلَمْ يَخْطُرْ عَلَى قَلْبِ بَشَرٍ، وَمِصْدَاقُهُ فِي كِتَابِ اللَّهِ عَزَّ وَجَلَّ: ﴿فَلَا تَعْلَمُ نَفْسٌ مَا أُخْفِيَ لَهُمْ مِنْ قُرَّةِ أَعْيُنٍ﴾ [سورة السجدة: 17] الآية."],"takhrij":"صحيح: رواه مسلم في الإيمان (189) من طرق عن الشعبيّ يخبر عن المغيرة ابن شعبة، فذكر في حديث طويل.","grade":"صحيح","chapter_ar":"باب إثبات اليدين لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (189).","chapter_en":"Affirming the Two Hands for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":23,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Moses asked his Lord to show him the highest rank in Paradise. Allah said: ‘Those are the ones whom I intended. I planted their honor with My Hand and sealed it. No eye has seen it, no ear has heard it, and it has never occurred to the heart of any human being.’” Its confirmation is in the Book of Allah, Mighty and Majestic: “No soul knows what comfort of the eyes has been hidden for them.” [Sūrat al-Sajdah 32:17]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (189)."},{"num":337,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ بْنِ الْخَطَّابِ أَنَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْتَقَى آدَمُ وَمُوسَى، فَقَالَ مُوسَى: أَنْتُ الَّذِي خَلَقَكَ اللَّهُ بِيَدِهِ، وَأَسْجَدَ لَكَ مَلَائِكَتَهُ، وَنَفَخَ فِيكَ مِنْ رُوحِهِ، وَأَمَرَ بِأَمْرٍ فَعَصَيْتُهُ....(فَذَكَرَ الْحَدِيثَ)."],"takhrij":"حسن: رواه ابن خزيمة في كتاب التوحيد (62) عن أحمد بن عبدة الضّبيّ، قال: أخبرنا حمّاد بن زيد، عن مطر الورّاق، عن عبدالله بن بريدة، عن يحيى بن يعمر، قال: لما تكلّم معبدالجهني في القدر، فذكر الحديث بطوله، وفي الخبر قال عبدالله بن عمر: حدثني عمر بن الخطاب، فذكر الحديث.","grade":"حسن","chapter_ar":"باب إثبات اليدين لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Khuzaymah in Kitāb al-Tawḥīd (62).","chapter_en":"Affirming the Two Hands for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":23,"content":{"translation":{"en":["ʿUmar ibn al-Khaṭṭāb may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Adam and Moses met. Moses said: ‘You are the one whom Allah created with His Hand, before whom He caused His angels to prostrate, into whom He breathed from His spirit, and whom He commanded with a command, yet you disobeyed it…’”"]},"buhuth":{"en":["The ḥadīth of ʿUmar ibn al-Khaṭṭāb is also found in Ṣaḥīḥ Muslim in Kitāb al-Īmān (8), except that it does not mention the account of the debate between Adam and Moses."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن خزيمة في كتاب التوحيد (62)."},{"num":338,"demo":false,"sanad":"","matn":["عَنْ عُبَيْدِ اللَّهِ بْنِ مِقْسَمٍ أَنَّهُ نَظَرَ إِلَى عَبْدِ اللَّهِ بْنِ عُمَرَ كَيْفَ يَحْكِي رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: يَأْخُذُ اللَّهُ عَزَّ وَجَلَّ سَمَوَاتِهِ وَأَرَضِيهِ بِيَدَيْهِ فَيَقُولُ: أَنَا اللَّهُ وَيَقْبِضُ أَصَابِعَهُ وَيَبْسُطُهَا، أَنَا الْمَلِكُ حَتَّى نَظَرْتُ إِلَى الْمِنْبَرِ يَتَحَرَّكُ مِنْ أَسْفَلِ شَيْءٍ مِنْهُ حَتَّى إِنِّي لَأَقُولُ أَسَاقِطٌ هُوَ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه مسلم في صفة القيامة (2788: 25) عن سعيد بن منصور، حدثنا يعقوب (يعني ابن عبدالرحمن)، حدثني أبو حازم، عن عبيد الله بن مقسم، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في إثبات اليمين لله تعالى، وكلتا يديه يمين لا شمال له، تعالى الله عن صفات المخلوقين","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in Ṣifat al-Qiyāmah (2788:25).","chapter_en":"Affirming the Right Hand for Allah Most High; Both of His Hands Are Right, With No Left; Exalted Is Allah Above the Attributes of Created Beings","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":24,"content":{"translation":{"en":["ʿUbaydullāh ibn Miqsam reported: He watched ʿAbdullāh ibn ʿUmar may Allah be pleased with them demonstrate how the Messenger of Allah ﷺ described it. He said: “Allah, Mighty and Majestic, will take His heavens and His earths in His Hands and say: ‘I am Allah.’” He clenched his fingers and opened them, saying: “I am the King.” ʿUbaydullāh said: I saw the pulpit moving from beneath him so much that I began to wonder: “Will it fall with the Messenger of Allah ﷺ?”"]},"intro":{"ar":["قال الله تعالى:","﴿وَمَا قَدَرُوا اللهَ حَقَّ قَدْرِهِ وَالْأَرْضُ جَمِيعًا قَبْضَتُهُ يَوْمَ الْقِيَامَةِ وَالسَّمَاوَاتُ مَطْوِيَّاتٌ بِيَمِينِهِ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ﴾","[الزمر: ٦٧]","وقال مجاهد:","«وكلتا يدي الرحمن يمين»."],"en":["Allah Most High said:","“They did not appraise Allah with the appraisal due to Him. The earth altogether will be in His grasp on the Day of Resurrection, and the heavens will be folded in His Right Hand. Glorified and Exalted is He above what they associate with Him.”","[Sūrat al-Zumar 39:67]","Mujāhid said:","“Both Hands of al-Raḥmān are right.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2788: 25)."},{"num":339,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ اللَّهَ يَقْبِضُ يَوْمَ الْقِيَامَةِ الْأَرْضَ وَتَكُونُ السَّمَوَاتُ بِيَمِينِهِ ثُمَّ يَقُولُ: أَنَا الْمَلِكُ."],"takhrij":"صحيح: رواه البخاريّ في التوحيد (7412) عن مقدم بن محمد، قال: حدثني عمّي القاسم بن يحيى، عن عبيد الله، عن نافع، عن ابن عمر، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في إثبات اليمين لله تعالى، وكلتا يديه يمين لا شمال له، تعالى الله عن صفات المخلوقين","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (7412).","chapter_en":"Affirming the Right Hand for Allah Most High; Both of His Hands Are Right, With No Left; Exalted Is Allah Above the Attributes of Created Beings","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":24,"content":{"translation":{"en":["Ibn ʿUmar may Allah be pleased with them reported that the Messenger of Allah ﷺ said: “Indeed, Allah will grasp the earth on the Day of Resurrection, and the heavens will be in His Right Hand. Then He will say: ‘I am the King.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (7412)."},{"num":340,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَقْبِضُ اللَّهُ الْأَرْضَ يَوْمَ الْقِيَامَةِ، وَيَطْوِي السَّمَاءَ بِيَمِينِهِ، ثُمَّ يَقُولُ: أَنَا الْمَلِكُ أَيْنَ مُلُوكُ الْأَرْضِ ؟."],"takhrij":"متفق عليه: رواه البخاريّ في التوحيد (7382)، ومسلم في كتاب صفة القيامة (2787) كلاهما من حديث عبدالله بن وهب، أخبرني يونس، عن ابن شهاب، عن سعيد بن المسيب، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في إثبات اليمين لله تعالى، وكلتا يديه يمين لا شمال له، تعالى الله عن صفات المخلوقين","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7382) and Muslim (2787).","chapter_en":"Affirming the Right Hand for Allah Most High; Both of His Hands Are Right, With No Left; Exalted Is Allah Above the Attributes of Created Beings","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":24,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Prophet ﷺ said: “Allah will grasp the earth on the Day of Resurrection and fold the heaven in His Right Hand. Then He will say: ‘I am the King. Where are the kings of the earth?’”"]}},"tuhfa":{},"full":1,"rep":[12908,13207,16170],"tks":"متفق عليه: رواه البخاري (7382)، ومسلم (2787)."},{"num":341,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ الْمُقْسِطِينَ عِنْدَ اللَّهِ عَلَى مَنَابِرَ مِنْ نُورٍ عَنْ يَمِينِ الرَّحْمَنِ عَزَّ وَجَلَّ، وَكِلْتَا يَدَيْهِ يَمِينٌ الَّذِينَ يَعْدِلُونَ فِي حُكْمِهِمْ وَأَهْلِيهِمْ وَمَا وَلُوا."],"takhrij":"صحيح: رواه مسلم في كتاب الإمارة (1827) من طرق عن سفيان بن عيينة، عن عمرو بن دينار، عن عمرو بن أوس، عن عبدالله بن عمرو، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في إثبات اليمين لله تعالى، وكلتا يديه يمين لا شمال له، تعالى الله عن صفات المخلوقين","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1827).","chapter_en":"Affirming the Right Hand for Allah Most High; Both of His Hands Are Right, With No Left; Exalted Is Allah Above the Attributes of Created Beings","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":24,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr may Allah be pleased with them reported that the Prophet ﷺ said: “Indeed, those who act justly will be with Allah upon pulpits of light, at the right of al-Raḥmān, Mighty and Majestic — and both of His Hands are right. They are those who act justly in their judgments, with their families, and in whatever they are placed in charge of.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1827)."},{"num":342,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تَكُونُ الْأَرْضُ يَوْمَ الْقِيَامَةِ خُبْزَةً وَاحِدَةً يَتَكَفَّؤُهَا الْجَبَّارُ بِيَدِهِ كَمَا يَكْفَأُ أَحَدُكُمْ خُبْزَتَهُ فِي السَّفَرِ نُزُلًا لِأَهْلِ الْجَنَّةِ، فَأَتَى رَجُلٌ مِنَ الْيَهُودِ، فَقَالَ: بَارَكَ الرَّحْمَنُ عَلَيْكَ يَا أَبَا الْقَاسِمِ، أَلَا أُخْبِرُكَ بِنُزُلِ أَهْلِ الْجَنَّةِ يَوْمَ الْقِيَامَةِ؟ قَالَ: بَلَى، قَالَ: تَكُونُ الْأَرْضُ خُبْزَةً وَاحِدَةً كَمَا قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَنَظَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَيْنَا، ثُمَّ ضَحِكَ حَتَّى بَدَتْ نَوَاجِذُهُ، ثُمَّ قَالَ: أَلَا أُخْبِرُكَ بِإِدَامِهِمْ؟ قَالَ: إِدَامُهُمْ بَالَامٌ وَنُونٌ، قَالُوا: وَمَا هَذَا؟ قَالَ: ثَوْرٌ وَنُونٌ يَأْكُلُ مِنْ زَائِدَةِ كَبِدِهِمَا سَبْعُونَ أَلْفًا."],"takhrij":"متفق عليه: رواه البخاريّ في الرقاق (6520)، ومسلم في صفة القيامة (2792)، كلاهما من حديث اللّيث، عن خالد بن يزيد، عن سعيد بن أبي هلال، عن زيد بن أسلم، عن عطاء بن يسار، عن أبي سعيد الخدريّ، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في إثبات اليمين لله تعالى، وكلتا يديه يمين لا شمال له، تعالى الله عن صفات المخلوقين","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6520) and Muslim (2792).","chapter_en":"Affirming the Right Hand for Allah Most High; Both of His Hands Are Right, With No Left; Exalted Is Allah Above the Attributes of Created Beings","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":24,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī may Allah be pleased with him reported that the Prophet ﷺ said: “On the Day of Resurrection, the earth will become a single loaf of bread, which al-Jabbār will turn over in His Hand just as one of you turns over his loaf while traveling, as hospitality for the people of Paradise.” A Jewish man came and said: “May al-Raḥmān bless you, O Abū al-Qāsim. Shall I tell you about the hospitality of the people of Paradise on the Day of Resurrection?” He said: “Yes.” He said: “The earth will become a single loaf of bread,” just as the Prophet ﷺ had said. The Prophet ﷺ looked at us and laughed until his premolar teeth became visible. Then he said: “Shall I tell you about their accompanying food?” They said: “Yes.” He said: “Their accompanying food will be Balam and Nūn.” They asked: “What is that?” He said: “An ox and a fish. Seventy thousand people will eat from the caudate lobe of their livers.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6520)، ومسلم (2792)."},{"num":343,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ يَبْلُغُ بِهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: قَالَ اللَّهُ تَبَارَكَ وَتَعَالَى يَا ابْنَ آدَمَ أَنْفِقْ أُنْفِقْ عَلَيْكَ، وَقَالَ: يَمِينُ اللَّهِ مَلْأَى، وَقَالَ ابْنُ نُمَيْرٍ: مَلْآنُ سَحَّاءُ لَا يَغِيضُهَا شَيْءٌ اللَّيْلَ وَالنَّهَارَ.","وَفِي رِوَايَةِ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللَّهَ قَالَ لِي أَنْفِقْ أُنْفِقْ عَلَيْكَ. وَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَمِينُ اللَّهِ مَلْأَى، لَا يَغِيضُهَا سَحَّاءُ اللَّيْلَ وَالنَّهَارَ، أَرَأَيْتُمْ مَا أَنْفَقَ مُذْ خَلَقَ السَّمَاءَ وَالْأَرْضَ، فَإِنَّهُ لَمْ يَغِضْ مَا فِي يَمِينِهِ، قَالَ: وَعَرْشُهُ عَلَى الْمَاءِ، وَبِيَدِهِ الْأُخْرَى الْقَبْضَ، يَرْفَعُ وَيَخْفِضُ."],"takhrij":"متفق عليه: رواه البخاريّ في التوحيد (7419)، ومسلم في الزكاة (993) كلاهما من حديث عبدالرزاق، حدثنا معمر بن راشد، عن همام بن منبه، عن أبي هريرة، فذكر الحديث وهي الرواية الثانية عند مسلم، ولفظ البخاريّ قريب منه.","grade":"متفق عليه","chapter_ar":"باب ما جاء في إثبات اليمين لله تعالى، وكلتا يديه يمين لا شمال له، تعالى الله عن صفات المخلوقين","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7419) and Muslim (993).","chapter_en":"Affirming the Right Hand for Allah Most High; Both of His Hands Are Right, With No Left; Exalted Is Allah Above the Attributes of Created Beings","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":24,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported, attributing it to the Prophet ﷺ, that Allah, Blessed and Exalted, said: “O son of Adam, spend, and I will spend upon you.” And he said: “Allah’s Right Hand is full — and Ibn Numayr said: filled — ever-flowing; nothing diminishes it, by night or by day.” In another narration, the Messenger of Allah ﷺ said:","“Indeed, Allah said to me: Spend, and I will spend upon you.” And the Messenger of Allah ﷺ said: “Allah’s Right Hand is full; nothing diminishes it, ever-flowing by night and by day. Have you considered how much He has spent since He created the heaven and the earth? Indeed, it has not diminished what is in His Right Hand.” He said: “His Throne is upon the water, and in His other Hand is the power of withholding; He raises and lowers.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[467],"tks":"متفق عليه: رواه البخاري (7419)، ومسلم (993)."},{"num":344,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ تَصَدَّقَ بِعَدْلِ تَمْرَةٍ مِنْ كَسْبٍ طَيِّبٍ وَلَا يَصْعَدُ إِلَى اللَّهِ إِلَّا الطَّيِّبُ فَإِنَّ اللَّهَ يَتَقَبَّلُهَا بِيَمِينِهِ ثُمَّ يُرَبِّيهَا لِصَاحِبِهِ كَمَا يُرَبِّي أَحَدُكُمْ فُلُوَّهُ حَتَّى تَكُونَ مِثْلَ الْجَبَلِ."],"takhrij":"متفق عليه: رواه البخاريّ في التوحيد (7430)، ومسلم في الزكاة (1014) كلاهما من حديث أبي صالح، عن أبي هريرة، فذكره، ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب ما جاء في إثبات اليمين لله تعالى، وكلتا يديه يمين لا شمال له، تعالى الله عن صفات المخلوقين","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7430) and Muslim (1014).","chapter_en":"Affirming the Right Hand for Allah Most High; Both of His Hands Are Right, With No Left; Exalted Is Allah Above the Attributes of Created Beings","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":24,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Whoever gives in charity the equivalent of a date from lawful and wholesome earnings — and nothing ascends to Allah except what is good — Allah accepts it with His Right Hand and then nurtures it for its giver just as one of you raises his young foal, until it becomes like a mountain.”"]}},"tuhfa":{},"full":1,"rep":[259,4030],"tks":"متفق عليه: رواه البخاري (7430)، ومسلم (1014)."},{"num":345,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ اللَّهَ عَزَّ وَجَلَّ يَبْسُطُ يَدَهُ بِاللَّيْلِ لِيَتُوبَ مُسِيءُ النَّهَارِ، وَيَبْسُطُ يَدَهُ بِالنَّهَارِ لِيَتُوبَ مُسِيءُ اللَّيْلِ، حَتَّى تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا."],"takhrij":"صحيح: رواه مسلم في التوبة (2759) عن محمد بن المثنى، حدثنا محمد بن جعفر، حدثنا شعبة، عن عمرو بن مرة، قال: سمعت أبا عُبيدة يحدّث عن أبي موسى، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في إثبات اليمين لله تعالى، وكلتا يديه يمين لا شمال له، تعالى الله عن صفات المخلوقين","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2759).","chapter_en":"Affirming the Right Hand for Allah Most High; Both of His Hands Are Right, With No Left; Exalted Is Allah Above the Attributes of Created Beings","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":24,"content":{"translation":{"en":["Abū Mūsā may Allah be pleased with him reported that the Prophet ﷺ said: “Indeed, Allah, Mighty and Majestic, extends His Hand during the night so that the one who sinned during the day may repent, and He extends His Hand during the day so that the one who sinned during the night may repent, until the sun rises from the west.”"]}},"tuhfa":{},"full":1,"rep":[11453,12511,12914],"tks":"صحيح: رواه مسلم (2759)."},{"num":346,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَمَّا خَلَقَ اللَّهُ آدَمَ وَنَفَخَ فِيهِ الرُّوحَ... فَقَالَ اللَّهُ لَهُ وَيَدَاهُ مَقْبُوضَتَانِ: اخْتَرْ أَيَّهُمَا شِئْتَ، قَالَ: اخْتَرْتُ يَمِينَ رَبِّي، وَكِلْتَا يَدَيْ رَبِّي يَمِينٌ مُبَارَكَةٌ، ثُمَّ بَسَطَهَا فَإِذَا فِيهَا آدَمُ وَذُرِّيَّتُهُ، فَقَالَ: أَيْ رَبِّ! مَا هَؤُلَاءِ؟ فَقَالَ: هَؤُلَاءِ ذُرِّيَّتُكَ فَإِذَا كُلُّ إِنْسَانٍ مَكْتُوبٌ عُمْرُهُ بَيْنَ عَيْنَيْهِ...(فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ)."],"takhrij":"حسن: رواه الترمذيّ (3368)، وصحّحه ابن خزيمة ورواه في كتاب التوحيد (107) وعنه ابن حبان في صحيحه (6167)، وصحّحه الحاكم (214) على شرط مسلم، كلّهم من طرق عن صفوان بن عيسى، عن الحارث بن عبدالرحمن بن أبي ذُباب، عن سعيد بن أبي سعيد المقبريّ، عن أبي هريرة في حديث طويل مخرّج في القضاء والقدر.","grade":"حسن","chapter_ar":"باب ما جاء في إثبات اليمين لله تعالى، وكلتا يديه يمين لا شمال له، تعالى الله عن صفات المخلوقين","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Tirmidhī (3368), and authenticated and narrated by Ibn Khuzaymah in Kitāb al-Tawḥīd (107).","chapter_en":"Affirming the Right Hand for Allah Most High; Both of His Hands Are Right, With No Left; Exalted Is Allah Above the Attributes of Created Beings","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":24,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Prophet ﷺ said: “When Allah created Adam and breathed the soul into him… while His two Hands were closed, He said: ‘Choose whichever of them you wish.’ Adam said: ‘I choose the right Hand of my Lord, and both Hands of my Lord are blessed right Hands.’ Then He opened it, and within it were Adam and his descendants…”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3368)، وصححه ابن خزيمة ورواه في كتاب التوحيد (107)."},{"num":347,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَة قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّم: مَا مِنْ مُسْلِمٍ يَتَصَدَّقُ بِصَدَقَةٍ مِنْ كَسْبٍ طَيِّبٍ، وَلَا يَصْعَدُ إِلَى السَّمَاءِ إِلَّا طَيِّبٌ، إِلَّا كَأَنَّمَا يَضَعُهَا فِي كَفِّ الرَّحْمَنِ عَزَّ وَجَلَّ فَيُرَبِّيهَا، كَمَا يُرَبِّي الرَّجُلُ فَلُوَّهُ أَوْ فَصِيلَهُ، حَتَّى إِنَّ التَّمْرَةَ لَتَعُودُ مِثْلَ الْجَبَلِ الْعَظِيمِ."],"takhrij":"حسن: رواه الإمام أحمد (9565) عن يحيى، عن ابن عجلان، قال: حدثني سعيد بن يسار، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في كف الرحمن عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (9565), and authenticated and narrated by Ibn Khuzaymah in Kitāb al-Tawḥīd (89, 91).","chapter_en":"What Has Been Reported Concerning the Palm of al-Raḥmān, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":25,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “No Muslim gives charity from wholesome earnings — and nothing ascends to the heaven except what is wholesome — except that it is as though he places it in the Palm of al-Raḥmān, Mighty and Majestic. Then He nurtures it for him just as one of you nurtures his young horse or his young camel, until even a single date becomes like a great mountain.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (9565)، وصححه ابن خزيمة فرواه في كتاب التوحيد (89، 91)."},{"num":348,"demo":false,"sanad":"","matn":["عَنِ ابْنِ مَسْعُودٍ قَالَ: جَاءَ حَبْرٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا مُحَمَّدُ أَوْ يَا أَبَا الْقَاسِمِ إِنَّ اللَّهَ تَعَالَى يُمْسِكُ السَّمَاوَاتِ يَوْمَ الْقِيَامَةِ عَلَى إِصْبَعٍ، وَالْأَرَضِينَ عَلَى إِصْبَعٍ، وَالْجِبَالَ وَالشَّجَرَ عَلَى إِصْبَعٍ، وَالْمَاءَ وَالثَّرَى عَلَى إِصْبَعٍ، وَسَائِرَ الْخَلْقِ عَلَى إِصْبَعٍ، ثُمَّ يَهُزُّهُنَّ، فَيَقُولُ: أَنَا الْمَلِكُ أَنَا الْمَلِكُ؟ فَضَحِكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَعَجُّبًا مِمَّا قَالَ الْحَبْرُ تَصْدِيقًا لَهُ، ثُمَّ قَرَأَ ﴿وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ وَالْأَرْضُ جَمِيعًا قَبْضَتُهُ يَوْمَ الْقِيَامَةِ وَالسَّمَاوَاتُ مَطْوِيَّاتٌ بِيَمِينِهِ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ﴾ [سورة الزمر: 67]."],"takhrij":"متفق عليه: رواه مسلم في صفات المنافقين (2786) عن أحمد بن عبدالله بن يونس، حدثنا فضيل (يعني ابن عياض)، عن منصور، عن إبراهيم، عن عبيدة السلماني، عن عبدالله بن مسعود، فذكره.","grade":"متفق عليه","chapter_ar":"باب إثبات الأصابع لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (2786) and al-Bukhārī (7414).","chapter_en":"Affirming the Fingers for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":26,"content":{"translation":{"en":["Ibn Masʿūd, may Allah be pleased with him, reported: A Jewish scholar came to the Prophet ﷺ and said: “O Muḥammad — or O Abū al-Qāsim — indeed, on the Day of Resurrection Allah will hold the heavens upon one finger, the earths upon one finger, the mountains and trees upon one finger, the water and soil upon one finger, and the rest of creation upon one finger. Then He will shake them and say: ‘I am the King! I am the King!’” The Messenger of Allah ﷺ laughed in amazement at what the scholar said, affirming it, and then recited: “They did not appraise Allah with the appraisal due to Him. The earth altogether will be in His grasp on the Day of Resurrection, and the heavens will be folded in His Right Hand. Glorified and Exalted is He above what they associate with Him.” [Sūrat al-Zumar 39:67]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (2786)، والبخاري (7414)."},{"num":349,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: مَرَّ يَهُودِيٌّ بِالنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا يَهُودِيُّ، حَدِّثْنَا، فَقَالَ: كَيْفَ تَقُولُ يَا أَبَا الْقَاسِمِ إِذَا وَضَعَ اللَّهُ السَّمَوَاتِ عَلَى ذِهْ، وَالْأَرْضَ عَلَى ذِهْ، وَالْمَاءَ عَلَى ذِهْ، وَالْجِبَالَ عَلَى ذِهْ، وَسَائِرَ الْخَلْقِ عَلَى ذِهْ.","وَأَشَارَ أَبُو جَعْفَرٍ مُحَمَّدُ بْنُ الصَّلْتِ بِخِنْصَرِهِ أَوَّلًا، ثُمَّ تَابَعَ حَتَّى بَلَغَ الْإِبْهَامَ، فَأَنْزَلَ اللَّهُ: ﴿وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ﴾ [سورة الزمر: 67]."],"takhrij":"حسن: رواه الترمذيّ (3240) عن عبدالله بن عبدالرحمن، أخبرنا محمد بن الصّلتْ، حدثنا أبو كدينة، عن عطاء بن السائب، عن أبي الضُّحى، عن ابن عباس، فذكره.","grade":"حسن","chapter_ar":"باب إثبات الأصابع لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Tirmidhī (3240), Imām Aḥmad (2267, 2988), and Ibn Abī ʿĀṣim in al-Sunnah (545).","chapter_en":"Affirming the Fingers for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":26,"content":{"translation":{"en":["Ibn ʿAbbās, may Allah be pleased with them, reported: A Jewish man passed by the Prophet ﷺ, and the Prophet ﷺ said to him: “O Jew, tell us.” He said: “What do you say, O Abū al-Qāsim, when Allah places the heavens upon this, the earths upon this, the water upon this, the mountains upon this, and the rest of creation upon this?” Abū Jaʿfar Muḥammad ibn al-Ṣalt gestured first with his little finger and then continued through the fingers until he reached the thumb.","Then Allah revealed: “They did not appraise Allah with the appraisal due to Him.” [Sūrat al-Zumar 39:67]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3240)، ورواه الإمام أحمد (2267، 2988)، وابن أبي عاصم في السنة (545)."},{"num":350,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو قَالَ: أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ قُلُوبَ بَنِي آدَمَ كُلَّهَا بَيْنَ إِصْبَعَيْنِ مِنْ أَصَابِعِ الرَّحْمَنِ كَقَلْبٍ وَاحِدٍ يُصَرِّفُهُ حَيْثُ يَشَاءُ، ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اللَّهُمَّ مُصَرِّفَ الْقُلُوبِ صَرِّفْ قُلُوبَنَا عَلَى طَاعَتِكَ."],"takhrij":"صحيح: رواه مسلم في القدر (2654) من طرق عن عبدالله بن يزيد المقرئ، حدّثنا حَيَوَة، أخبرني أبو هانيء، أنه سمع أبا عبدالرحمن الحُبُليّ، أنه سمع عبدالله بن عمرو بن العاص، فذكره.","grade":"صحيح","chapter_ar":"باب إثبات الأصابع لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2654).","chapter_en":"Affirming the Fingers for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":26,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr may Allah be pleased with them reported that he heard the Messenger of Allah ﷺ say: “Indeed, all the hearts of the children of Adam are between two fingers of al-Raḥmān, like a single heart; He turns it wherever He wills.” Then the Messenger of Allah ﷺ said: “O Allah, Turner of the hearts, turn our hearts toward Your obedience.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2654)."},{"num":351,"demo":false,"sanad":"","matn":["عَنْ النَّوَّاسِ بْنِ سَمْعَانَ الْكِلَابِيِّ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَا مِنْ قَلْبٍ إِلَّا بَيْنَ إِصْبَعَيْنِ مِنْ أَصَابِعِ الرَّحْمَنِ، إِنْ شَاءَ أَقَامَهُ وَإِنْ شَاءَ أَزَاغَهُ، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: يَا مُثَبِّتَ الْقُلُوبِ ثَبِّتْ قُلُوبَنَا عَلَى دِينِكَ، قَالَ: وَالْمِيزَانُ بِيَدِ الرَّحْمَنِ يَرْفَعُ أَقْوَامًا، وَيَخْفِضُ آخَرِينَ إِلَى يَوْمِ الْقِيَامَةِ."],"takhrij":"صحيح: روه ابن ماجه (199) عن هشام بن عمّار، قال: حدّثنا صدقة بن خالد، قال: حدّثنا ابن جابر، قال: سمعت بُسْر بن عبيد الله يقول: سمعتُ أبا إدريس الخولانيّ يقول: حدثني النواس بن سمعان، فذكره.","grade":"صحيح","chapter_ar":"باب إثبات الأصابع لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Mājah (199), Ibn Abī ʿĀṣim in al-Sunnah (219), and Aḥmad (17630).","chapter_en":"Affirming the Fingers for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":26,"content":{"translation":{"en":["Al-Nawwās ibn Samʿān al-Kilābī, may Allah be pleased with him, reported: I heard the Messenger of Allah ﷺ say: “There is no heart except that it is between two fingers of al-Raḥmān. If He wills, He keeps it upright, and if He wills, He causes it to deviate.” The Messenger of Allah ﷺ used to say: “O One who makes hearts firm, make our hearts firm upon Your religion.” He also said: “The Scale is in the Hand of al-Raḥmān. He raises some people and lowers others until the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (199)، وابن أبي عاصم في السنة (219)، وأحمد (17630)."},{"num":352,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُكْثِرُ أَنْ يَقُولَ: يَا مُقَلِّبَ الْقُلُوبِ، ثَبِّتْ قَلْبِي عَلَى دِينِكَ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، آمَنَّا بِكَ وَبِمَا جِئْتَ بِهِ فَهَلْ تَخَافُ عَلَيْنَا؟ قَالَ: نَعَمْ، إِنَّ الْقُلُوبَ بَيْنَ أُصْبُعَيْنِ مِنْ أَصَابِعِ اللَّهِ يُقَلِّبُهَا كَيْفَ يَشَاءُ."],"takhrij":"حسن: رواه الترمذيّ (2140) عن هنّاد، حدّثنا أبو معاوية، عن الأعمش، عن أبي سفيان، عن أنس، فذكر مثله.","grade":"حسن","chapter_ar":"باب إثبات الأصابع لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Tirmidhī (2140), Aḥmad (12107), and al-Ḥākim (1927).","chapter_en":"Affirming the Fingers for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":26,"content":{"translation":{"en":["Anas, may Allah be pleased with him, reported: The Messenger of Allah ﷺ frequently used to say: “O Turner of the hearts, make my heart firm upon Your religion.” I said: “O Prophet of Allah, we have believed in you and in what you have brought. Do you still fear for us?” He replied: “Yes. Indeed, the hearts are between two fingers of the fingers of Allah; He turns them however He wills.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11368],"tks":"حسن: رواه الترمذي (2140)، وأحمد (12107)، والحاكم (1927)."},{"num":353,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ قَالَتْ: كَانَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُكْثِرُ فِي دُعَائِهِ أَنْ يَقُولَ: اللَّهُمَّ مُقَلِّبَ الْقُلُوبِ، ثَبِّتْ قَلْبِي عَلَى دِينِكَ، قَالَتْ: قُلْتُ: يَا رَسُولَ اللَّهِ، أَوَ إِنَّ الْقُلُوبَ لَتَتَقَلَّبُ؟ قَالَ: نَعَمْ، مَا مِنْ خَلْقِ اللَّهِ مِنْ بَنِي آدَمَ مِنْ بَشَرٍ إِلَّا أَنَّ قَلْبَهُ بَيْنَ أُصْبُعَيْنِ مِنْ أَصَابِعِ اللَّهِ، فَإِنْ شَاءَ اللَّهُ عَزَّ وَجَلَّ أَقَامَهُ، وَإِنْ شَاءَ اللَّهُ أَزَاغَهُ، فَنَسْأَلُ اللَّهَ رَبَّنَا أَنْ لَا يُزِيغَ قُلُوبَنَا بَعْدَ إِذْ هَدَانَا، وَنَسْأَلُهُ أَنْ يَهَبَ لَنَا مِنْ لَدُنْهُ رَحْمَةً، إِنَّهُ هُوَ الْوَهَّابُ. قَالَتْ: قُلْتُ: يَا رَسُولَ اللَّهِ، أَلَا تُعَلِّمُنِي دَعْوَةً أَدْعُو بِهَا لِنَفْسِي؟ قَالَ: بَلَى، قُولِي: اللَّهُمَّ رَبَّ مُحَمَّدٍ النَّبِيِّ اغْفِرْ لِي ذَنْبِي، وَأَذْهِبْ غَيْظَ قَلْبِي، وَأَجِرْنِي مِنْ مُضِلَّاتِ الْفِتَنِ مَا أَحْيَيْتَنَا."],"takhrij":"حسن: رواه الإمام أحمد (26576)، والطبرانيّ في الكبير (785)، وفي الدّعاء (1258) من طرق عن عبدالحميد قال: حدّثني شهر بن حوشب، قال: سمعت أمَّ سلمة تحدّث أنّ رسول الله صلى الله عليه وسلم كان يُكْثر في دُعائه أن يقول (فذكره).","grade":"حسن","chapter_ar":"باب إثبات الأصابع لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (26576), al-Ṭabarānī in al-Muʿjam al-Kabīr (23/338), and in al-Duʿāʾ (1258).","chapter_en":"Affirming the Fingers for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":26,"content":{"translation":{"en":["Umm Salamah may Allah be pleased with her reported: The Messenger of Allah ﷺ frequently used to say in his supplication: “O Allah, Turner of the hearts, make my heart firm upon Your religion.” She said: I asked: “O Messenger of Allah, do hearts truly change?” He replied: “Yes. There is no human being among the children of Adam except that his heart is between two fingers of the fingers of Allah. If Allah, Mighty and Majestic, wills, He keeps it upright, and if He wills, He causes it to deviate. So we ask Allah, our Lord, not to cause our hearts to deviate after He has guided us, and we ask Him to grant us mercy from Himself. Indeed, He is the Bestower.” She said: I asked: “O Messenger of Allah, will you not teach me a supplication with which I may supplicate for myself?” He replied: “Yes. Say: ‘O Allah, Lord of the Prophet Muḥammad, forgive my sin, remove the anger from my heart, and protect me from misleading trials for as long as You keep me alive.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (26576)، والطبراني في الكبير (785)، وفي الدعاء (1258)."},{"num":354,"demo":false,"sanad":"","matn":["عَنْ سَبْرَةَ بْنِ فَاكِهَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قَلْبُ ابْنِ آدَمَ بَيْنَ أُصْبُعَيْنِ مِنْ أَصَابِعِ الرَّحْمَنِ، إِنْ شَاءَ أَنْ يُقِيمَهُ أَقَامَهُ، وَإِنْ شَاءَ أَنْ يُزِيغَهُ أَزَاغَهُ."],"takhrij":"حسن: رواه ابن أبي عاصم في السنة (220) عن هشام بن عمار، ثنا أبو مطيع معاوية بن يحيى الأطرابلسيّ، حدثنا محمد بن الوليد الزّبيديّ،عن عبدالرحمن بن جبير بن نفير، عن أبيه، عن سبرة بن فاكهة، فذكره.","grade":"حسن","chapter_ar":"باب إثبات الأصابع لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Abī ʿĀṣim in al-Sunnah (220), al-Ṭabarānī (7/137–138), and al-Ājurrī (908).","chapter_en":"Affirming the Fingers for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":26,"content":{"translation":{"en":["Sabrah ibn al-Fākih may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “The heart of the son of Adam is between two fingers of al-Raḥmān. If He wills to keep it upright, He keeps it upright; and if He wills to cause it to deviate, He causes it to deviate.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي عاصم في السنة (220)، والطبراني (7/137–138)، والآجري (908)."},{"num":355,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّمَا قَلْبُ ابْنِ آدَمَ بَيْنَ أُصْبُعَيْنِ مِنْ أَصَابِعِ الرَّحْمَنِ."],"takhrij":"حسن: رواه ابن أبي عاصم في السنة (229) عن عمر بن الخطاب، ثنا أبو صالح، ثنا اللّيث، ثنا يحيى بن سعيد، عن خالد بن أبي عمران، حدثني أبو عياش، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب إثبات الأصابع لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan due to supporting narrations: Narrated by Ibn Abī ʿĀṣim in al-Sunnah (229).","chapter_en":"Affirming the Fingers for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":26,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “The heart of the son of Adam is only between two fingers of al-Raḥmān.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي عاصم في السنة (229)."},{"num":356,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَدُ اللَّهِ مَلْأَى لَا يَغِيضُهَا نَفَقَةٌ سَحَّاءُ اللَّيْلَ وَالنَّهَارَ، وَقَالَ: أَرَأَيْتُمْ مَا أَنْفَقَ مُنْذُ خَلَقَ السَّمَوَاتِ وَالْأَرْضَ فَإِنَّهُ لَمْ يَغِضْ مَا فِي يَدِهِ، وَقَالَ: عَرْشُهُ عَلَى الْمَاءِ وَبِيَدِهِ الْأُخْرَى الْمِيزَانُ يَخْفِضُ وَيَرْفَعُ."],"takhrij":"متفق عليه: رواه البخاريّ في التوحيد (7411) عن أبي اليمان، أخبرنا شعيب، حدثنا أبو الزّناد، عن الأعرج، عن أبي هريرة، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء أن يد الله ملأى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7411) and Muslim (993).","chapter_en":"What Has Been Reported That Allah’s Hand Is Full","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":27,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Allah’s Hand is full; spending does not diminish it, ever-flowing by night and by day.” He also said: “Have you considered how much He has spent since He created the heavens and the earth? Indeed, it has not diminished what is in His Hand.” And he said: “His Throne was upon the water, and in His other Hand is the Scale; He lowers and raises.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7411)، ومسلم (993)."},{"num":357,"demo":false,"sanad":"","matn":["عَنْ حَكِيمِ بْنِ حِزَامٍ قَالَ: سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الْمَالِ؟ فَأَلْحَفْتُ، فَقَالَ: يَا حَكِيمُ، مَا أنْكَرَ مَسْأَلَتَكَ! يَا حَكِيمُ، إِنَّ هَذَا الْمَالَ خَضِرَةٌ حُلْوَةٌ، وَإِنَّمَا هُوَ مَعَ ذَلِكَ أَوْسَاخُ أَيْدِي النَّاسِ، وَيَدُ اللَّهِ فَوْقَ يَدِ الْمُعْطِي، وَيَدُ الْمُعْطِي فَوْقَ يَدِ الْمُعْطَى، وَأَسْفَلُ الْأَيْدِي يَدُ الْمُعْطَى."],"takhrij":"صحيح: رواه أحمد (15321)، والطبراني في الكبير (3095) كلاهما من حديث ابن أبي ذئب، عن مسلم بن جندب، عن حكيم بن حزام، فذكره، ولفظهما سواء.","grade":"صحيح","chapter_ar":"باب أن يد الله فوق أيديهم جميعاً","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Aḥmad (15321) and al-Ṭabarānī in al-Muʿjam al-Kabīr (3/216–217), and authenticated by Ibn Khuzaymah, who narrated it in Kitāb al-Tawḥīd (103, 104), and by al-Ḥākim (6048).","chapter_en":"Allah’s Hand Is Above All Their Hands","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":28,"content":{"translation":{"en":["Ḥakīm ibn Ḥizām, may Allah be pleased with him, reported: I asked the Messenger of Allah ﷺ for wealth and persisted in asking. He said: “O Ḥakīm, how remarkable is your asking! O Ḥakīm, indeed this wealth is green and sweet, yet along with that it is the refuse of people’s hands. The Hand of Allah is above the hand of the giver, the hand of the giver is above the hand of the recipient, and the lowest of hands is the hand of the recipient.”"]},"intro":{"ar":["قال الله تعالى:","﴿يَدُ اللهِ فَوْقَ أَيْدِيهِمْ﴾","[الفتح: ١٠]"],"en":["Allah Most High said:","“The Hand of Allah is above their hands.”","[Sūrat al-Fatḥ 48:10]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (15321)، والطبراني في الكبير (3082)، وصححه ابن خزيمة وأخرجه في كتاب التوحيد (103، 104)، والحاكم (6048)."},{"num":358,"demo":false,"sanad":"","matn":["عَنْ مَالِكِ بْنِ نَضْلَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الأَيْدِي ثَلاثَةٌ: فَيَدُ اللَّهِ الْعُلْيَا، وَيَدُ الْمُعْطِي الَّتِي تَلِيهَا، وَيَدُ السَّائِلِ السُّفْلَى، فَأَعْطِ الْفَضْلَ، وَلا تَعْجَزْ عَنْ نَفْسِكِ."],"takhrij":"صحيح: رواه أبو داود (1649) عن أحمد بن حنبل، حدثنا عبيدة بن حُميد التيمي، حدثني أبو الزّعراء، عن أبي الأحوص، عن أبيه مالك بن نَضْلة، فذكره.","grade":"صحيح","chapter_ar":"باب أن يد الله فوق أيديهم جميعاً","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (1649) and Aḥmad (15890), and authenticated by Ibn Khuzaymah (2440) and Ibn Ḥibbān (3362).","chapter_en":"Allah’s Hand Is Above All Their Hands","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":28,"content":{"translation":{"en":["Mālik ibn Naḍlah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Hands are three: the Hand of Allah is the highest; the hand of the giver comes next; and the hand of the beggar is the lowest. So give from what is surplus, and do not render yourself helpless by neglecting your own needs.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[4196],"tks":"صحيح: رواه أبو داود (1649)، وأحمد (15890)، وصححه ابن خزيمة (2440)، وابن حبان (3362)."},{"num":359,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا تَزَالُ جَهَنَّمُ تَقُولُ: هَلْ مِنْ مَزِيدٍ؟ حَتَّى يَضَعَ رَبُّ الْعِزَّةِ فِيهَا قَدَمَهُ، فَتَقُولُ: قَطْ قَطْ وَعِزَّتِكَ، وَيُزْوَى بَعْضُهَا إِلَى بَعْضٍ."],"takhrij":"متفق عليه: رواه البخاري في الأيمان والنّذور (6661)، ومسلم في كتاب الجنة (2848) كلاهما من شيبان، عن قتادة، حدثنا أنس بن مالك، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب إثبات القدم لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6661) and Muslim (2848).","chapter_en":"Affirming the Foot for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":29,"content":{"translation":{"en":["Anas ibn Mālik may Allah be pleased with him reported that the Prophet ﷺ said: “Hell will continue saying: ‘Is there any more?’ until the Lord of Might places His Foot in it. Then it will say: ‘Enough! Enough! By Your Might!’ and its parts will draw together.”"]},"intro":{"ar":["قال الله تعالى:","﴿وَتَقُولُ هَلْ مِنْ مَزِيدٍ﴾","[ق: ٣٠]"],"en":["Allah Most High said:","“And it will say, ‘Is there any more?’”","[Sūrat Qāf 50:30]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[7048,16449],"tks":"متفق عليه: رواه البخاري (6661)، ومسلم (2848)."},{"num":360,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا تَزَالُ جَهَنَّمُ تَقُولُ: هَلْ مِنْ مَزِيدٍ؟ قَالَ: فَيُدَلِّي فِيهَا رَبُّ الْعَالَمِينَ قَدَمَهُ، قَالَ: فَيَنْزَوِي بَعْضُهَا إِلَى بَعْضٍ، وَتَقُولُ: قَطْ قَطْ بِعِزَّتِكَ، وَلَا يَزَالُ فِي الْجَنَّةِ فَضْلٌ حَتَّى يُنْشِئَ اللَّهُ لَهَا خَلْقًا آخَرَ فَيُسْكِنَهُ فِي فُضُولِ الْجَنَّةِ."],"takhrij":"صحيح: رواه الإمام أحمد (12380) عن بهز وعفان، قالا: حدثنا أبان بن يزيد العطّار، حدثنا قتادة، حدثنا أنس بن مالك، فذكره.","grade":"صحيح","chapter_ar":"باب إثبات القدم لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Imām Aḥmad (12380) and Ibn Khuzaymah in al-Tawḥīd (155).","chapter_en":"Affirming the Foot for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":29,"content":{"translation":{"en":["Anas ibn Mālik may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Hell will continue saying: ‘Is there any more?’ Then the Lord of the worlds will place His Foot in it, and its parts will draw together. It will say: ‘Enough! Enough! By Your Might!’ And there will continue to remain additional space in Paradise until Allah creates another creation for it and settles them in the remaining spaces of Paradise.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (12380)، ورواه ابن خزيمة في التوحيد (155)."},{"num":361,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تَحَاجَّتِ الْجَنَّةُ وَالنَّارُ، فَقَالَتِ النَّارُ: أُوثِرْتُ بِالْمُتَكَبِّرِينَ وَالْمُتَجَبِّرِينَ، وَقَالَتِ الْجَنَّةُ: فَمَا لِي لَا يَدْخُلُنِي إِلَّا ضُعَفَاءُ النَّاسِ وَسَقَطُهُمْ وَغِرَّتُهُمْ، قَالَ اللَّهُ لِلْجَنَّةِ: إِنَّمَا أَنْتِ رَحْمَتِي أَرْحَمُ بِكِ مَنْ أَشَاءُ مِنْ عِبَادِي، وَقَالَ لِلنَّارِ: إِنَّمَا أَنْتِ عَذَابِي أُعَذِّبُ بِكِ مَنْ أَشَاءُ مِنْ عِبَادِي، وَلِكُلِّ وَاحِدَةٍ مِنْكُمَا مِلْؤُهَا، فَأَمَّا النَّارُ فَلَا تَمْتَلِئُ حَتَّى يَضَعَ اللَّهُ تَبَارَكَ وَتَعَالَى رِجْلَهُ، تَقُولُ: قَطْ قَطْ قَطْ فَهُنَالِكَ تَمْتَلِئُ وَيُزْوَى بَعْضُهَا إِلَى بَعْضٍ، وَلَا يَظْلِمُ اللَّهُ مِنْ خَلْقِهِ أَحَدًا، وَأَمَّا الْجَنَّةُ فَإِنَّ اللَّهَ يُنْشِئُ لَهَا خَلْقًا."],"takhrij":"متفق عليه: رواه البخاريّ في التفسير (4850)، ومسلم في كتاب صفة الجنة (2846: 36) كلاهما عن محمد بن رافع، حدثنا عبدالرزاق، أخبرنا معمر، عن همام، عن أبي هريرة، قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب إثبات القدم لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Tafsīr (4850) and Muslim in Kitāb Ṣifat al-Jannah (2846:36).","chapter_en":"Affirming the Foot for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":29,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Paradise and the Fire disputed. The Fire said: ‘I have been favored with the arrogant and the tyrannical.’ Paradise said: ‘Why is it that none enter me except the weak among people, their lowly ones, and those looked down upon?’ Allah said to Paradise: ‘You are My mercy. Through you I show mercy to whomever I will among My servants.’ And He said to the Fire: ‘You are My punishment. Through you I punish whomever I will among My servants. Each of you shall have its full share.’ As for the Fire, it will not become full until Allah, Blessed and Exalted, places His Foot in it. It will say: ‘Enough! Enough! Enough!’ Then it will become full, and its parts will draw together. Allah will not wrong anyone from His creation. As for Paradise, Allah will create a creation for it.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4850)، ومسلم (2846: 36)."},{"num":362,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: احْتَجَّتِ الْجَنَّةُ وَالنَّارُ، فَقَالَتِ النَّارُ: أُوثِرْتُ بِالْمُتَكَبِّرِينَ وَالْمُتَجَبِّرِينَ، فَذَكَرَ الحَدِيثِ إِلَى قَوْلِهِ: وَلِكِلَيْكُمَا عَلَيَّ مِلْؤُهَا، وَلَمْ يَذْكُرْ مَا بَعْدَهُ مِنَ الزِّيَادَةِ.","وَفِي رِوَايَةِ: وَلِكُلِّ وَاحِدَةٍ مِنْكُمَا مِلْؤُهَا، فَيُلْقَى فِي النَّارِ أَهْلُهَا، فَتَقُولُ: هَلْ مِنْ مَزِيدٍ؟ قَالَ: وَيُلْقَى فِيهَا وَتَقُولُ: هَلْ مِنْ مَزِيدٍ؟ وَيُلْقَى فِيهَا، وَتَقُولُ: هَلْ مِنْ مَزِيدٍ؟ حَتَّى يَأْتِيَهَا تَبَارَكَ وَتَعَالَى فَيَضَعُ قَدَمَهُ عَلَيْهَا فَتُزْوَى، فَتَقُولُ: قَدِي قَدِي، وَأَمَّا الْجَنَّةُ فَيَبْقَى فِيهَا أَهْلُهَا مَا شَاءَ اللهُ أَنْ يَبْقَى فَيُنْشِئُ اللهُ لَهَا خَلْقًا مَا يَشَاءُ.","وَفِي رِوَايَةِ: وَلِكُلِّ وَاحِدَةٍ مِنْكُمَا مِلْؤُهَا فَأَمَّا النَّارُ، فَيُلْقَى فِيهَا أَهْلُهَا، فَتَقُولُ: هَلْ مِنْ مَزِيدٍ؟ حَتَّى يَأْتِيَهَا تَبَارَكَ وَتَعَالَى فَيَضَعُ قَدَمَهُ عَلَيْهَا فَتَنْزَوِي، وَتَقُولُ: قَدْنِي قَدْنِي، وَأَمَّا الْجَنَّةُ، فَيَبْقَى مِنْهَا مَا شَاءَ اللَّهُ أَنْ يَبْقَى فَيُنْشِئُ اللَّهُ لَهَا خَلْقًا مِمَّنْ يَشَاءُ."],"takhrij":"صحيح: رواها مسلم في صفة الجنة والنار (2847) عن عثمان بن أبي شيبة، حدثنا جرير، عن الأعمش، عن أبي صالح، عن أبي سعيد الخدريّ، فذكر الحديث، ولم يسق مسلمٌ لفظه كاملاً، وإنما أحال على لفظ أبي هريرة إلى قوله: ولكليكما عليّ ملؤها ولم يذكر ما بعد من الزيادة.","grade":"صحيح","chapter_ar":"باب إثبات القدم لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2847) and Aḥmad (11099).","chapter_en":"Affirming the Foot for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":29,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Paradise and the Fire disputed. The Fire said: ‘I have been favored with the arrogant and the tyrannical.’” He then mentioned the ḥadīth until the words:","“It is incumbent upon Me to fill both of you.” Another narration contains the additional wording: “Each one of you shall have its full share. As for the Fire, its people will be cast into it and it will say: ‘Is there any more?’ Its people will continue to be cast into it and it will say: ‘Is there any more?’ until He, Blessed and Exalted, comes to it and places His two Feet upon it. It will then contract and say:","‘Enough for me! Enough for me!’ As for Paradise, there will remain in it whatever Allah wills to remain, and Allah will create for it a creation from whomever He wills.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2847)، وأحمد (11099)."},{"num":363,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَجْمَعُ اللَّهُ النَّاسَ يَوْمَ الْقِيَامَةِ فِي صَعِيدٍ وَاحِدٍ ثُمَّ يَطَّلِعُ عَلَيْهِمْ رَبُّ الْعَالَمِينَ فَيَقُولُ: أَلَا يَتْبَعُ كُلُّ إِنْسَانٍ مَا كَانُوا يَعْبُدُونَهُ، فَيُمَثَّلُ لِصَاحِبِ الصَّلِيبِ صَلِيبُهُ، وَلِصَاحِبِ التَّصَاوِيرِ تَصَاوِيرُهُ، وَلِصَاحِبِ النَّارِ نَارُهُ، فَيَتْبَعُونَ مَا كَانُوا يَعْبُدُونَ، وَيَبْقَى الْمُسْلِمُونَ فَيَطَّلِعُ عَلَيْهِمْ رَبُّ الْعَالَمِينَ فَيَقُولُ: أَلَا تَتَّبِعُونَ النَّاسَ؟ فَيَقُولُونَ: نَعُوذُ بِاللَّهِ مِنْكَ نَعُوذُ بِاللَّهِ مِنْكَ اللَّهُ رَبُّنَا هَذَا مَكَانُنَا حَتَّى نَرَى رَبَّنَا، وَهُوَ يَأْمُرُهُمْ وَيُثَبِّتُهُمْ، ثُمَّ يَتَوَارَى، ثُمَّ يَطَّلِعُ فَيَقُولُ: أَلَا تَتَّبِعُونَ النَّاسَ؟ فَيَقُولُونَ: نَعُوذُ بِاللَّهِ مِنْكَ نَعُوذُ بِاللَّهِ مِنْكَ اللَّهُ رَبُّنَا وَهَذَا مَكَانُنَا حَتَّى نَرَى رَبَّنَا وَهُوَ يَأْمُرُهُمْ وَيُثَبِّتُهُمْ، قَالُوا: وَهَلْ نَرَاهُ يَا رَسُولَ اللَّهِ؟ قَالَ: وَهَلْ تُضَارُّونَ فِي رُؤْيَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ؟ قَالُوا: لَا يَا رَسُولَ اللَّهِ، قَالَ: فَإِنَّكُمْ لَا تُضَارُّونَ فِي رُؤْيَتِهِ تِلْكَ السَّاعَةَ، ثُمَّ يَتَوَارَى، ثُمَّ يَطَّلِعُ فَيُعَرِّفُهُمْ نَفْسَهُ ثُمَّ يَقُولُ: أَنَا رَبُّكُمْ فَاتَّبِعُونِي، فَيَقُومُ الْمُسْلِمُونَ وَيُوضَعُ الصِّرَاطُ فَيَمُرُّونَ عَلَيْهِ مِثْلَ جِيَادِ الْخَيْلِ وَالرِّكَابِ وَقَوْلُهُمْ عَلَيْهِ سَلِّمْ سَلِّمْ، وَيَبْقَى أَهْلُ النَّارِ فَيُطْرَحُ مِنْهُمْ فِيهَا فَوْجٌ، ثُمَّ يُقَالُ: هَلِ امْتَلَأْتِ؟ فَتَقُولُ: هَلْ مِنْ مَزِيدٍ؟ ثُمَّ يُطْرَحُ فِيهَا فَوْجٌ فَيُقَالُ: هَلِ امْتَلَأْتِ؟ فَتَقُولُ: هَلْ مِنْ مَزِيدٍ؟ حَتَّى إِذَا أُوعِبُوا فِيهَا وَضَعَ الرَّحْمَنُ قَدَمَهُ فِيهَا وَأَزْوَى بَعْضَهَا إِلَى بَعْضٍ، ثُمَّ قَالَ: قَطْ، قَالَتْ: قَطْ قَطْ، فَإِذَا أَدْخَلَ اللَّهُ أَهْلَ الْجَنَّةِ الْجَنَّةَ، وَأَهْلَ النَّارِ النَّارَ، قَالَ: أُتِيَ بِالْمَوْتِ مُلَبَّبًا فَيُوقَفُ عَلَى السُّورِ بَيْنَ أَهْلِ الْجَنَّةِ وَأَهْلِ النَّارِ، ثُمَّ يُقَالُ: يَا أَهْلَ الْجَنَّةِ، فَيَطَّلِعُونَ خَائِفِينَ، ثُمَّ يُقَالُ: يَا أَهْلَ النَّارِ، فَيَطَّلِعُونَ مُسْتَبْشِرِينَ يَرْجُونَ الشَّفَاعَةَ، فَيُقَالُ لِأَهْلِ الْجَنَّةِ وَأَهْلِ النَّارِ: هَلْ تَعْرِفُونَ هَذَا؟ فَيَقُولُونَ هَؤُلَاءِ وَهَؤُلَاءِ: قَدْ عَرَفْنَاهُ هُوَ الْمَوْتُ الَّذِي وُكِّلَ بِنَا، فَيُضْجَعُ فَيُذْبَحُ ذَبْحًا عَلَى السُّورِ الَّذِي بَيْنَ الْجَنَّةِ وَالنَّارِ، ثُمَّ يُقَالُ: يَا أَهْلَ الْجَنَّةِ خُلُودٌ لَا مَوْتَ، وَيَا أَهْلَ النَّارِ خُلُودٌ لَا مَوْتَ."],"takhrij":"حسن: رواه الترمذيّ (2557) عن قتيبة، حدثنا عبدالعزيز بن محمد، عن العلاء بن عبدالرحمن، عن أبيه، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب إثبات القدم لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Tirmidhī (2557) and Ibn Khuzaymah in al-Tawḥīd (150).","chapter_en":"Affirming the Foot for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":29,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Allah will gather the people on the Day of Resurrection upon a single plain. Then the Lord of the worlds will appear to them and say: ‘Should not every person follow what he used to worship?’ The cross will be represented to the one who worshipped the cross, images will be represented to the one who worshipped images, and fire will be represented to the one who worshipped fire. They will follow what they used to worship, while the Muslims will remain. Then the Lord of the worlds will appear to them and say: ‘Will you not follow the people?’ They will say: ‘We seek refuge in Allah from you! We seek refuge in Allah from you! Allah is our Lord, and this is our place until we see our Lord.’ And He will command them and make them firm. Then He will withdraw and appear again and say: ‘Will you not follow the people?’ They will say: ‘We seek refuge in Allah from you! We seek refuge in Allah from you! Allah is our Lord, and this is our place until we see our Lord.’ They asked: ‘Will we see Him, O Messenger of Allah?’ He replied: ‘Do you have any difficulty seeing the moon on the night of the full moon?’ They said: ‘No, O Messenger of Allah.’ He said: ‘Then you will have no difficulty seeing Him at that time.’ Then He will withdraw and afterward appear and make Himself known to them. He will say: ‘I am your Lord, so follow Me.’ The Muslims will rise, and the Ṣirāṭ will be placed. They will pass over it like swift horses and riding animals, and their words upon it will be: ‘Safety! Safety!’ The people of the Fire will remain. A group of them will be thrown into it, and it will be asked: ‘Are you full?’ It will reply: ‘Is there any more?’ Then another group will be thrown into it, and it will be asked: ‘Are you full?’ It will reply: ‘Is there any more?’ When they have all been placed into it, al-Raḥmān will place His Foot upon it, and its parts will draw together. Then He will say: ‘Enough.’ It will say: ‘Enough! Enough!’ When Allah has admitted the people of Paradise into Paradise and the people of the Fire into the Fire, death will be brought restrained and made to stand upon the wall between the people of Paradise and the people of the Fire. Then it will be said: ‘O people of Paradise!’ They will look out fearfully. Then it will be said: ‘O people of the Fire!’ They will look out joyfully, hoping for intercession. The people of Paradise and the people of the Fire will be asked: ‘Do you recognize this?’ Both groups will say: ‘We recognize it. It is death, which had been appointed over us.’ It will then be laid down and slaughtered upon the wall between Paradise and the Fire. Then it will be said: ‘O people of Paradise, everlasting life with no death! O people of the Fire, everlasting life with no death!’”"]},"buhuth":{"en":["Al-Tirmidhī said:","“A Ḥasan Ṣaḥīḥ ḥadīth.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2557)، وابن خزيمة في التوحيد (150)."},{"num":364,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: أَنْشَدَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْتَيْنِ مِنْ قَوْلِ أُمَيَّةَ بْنِ أَبِي الصَّلْتِ الثَّقَفِيِّ :","رَجُلٌ وَثَوْرٌ تَحْتَ رِجْلِ يَمِينِهِ وَالنَّسْرُ لِلْأُخْرَى وَلَيْثٌ مُرْصَدُ.","فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: صَدَقَ.وَأَنْشَدَ قَوْلَهُ:","لَا الشَّمْسُ تَأْبَى فَمَا تَخْرُجُ إِلَّا مُعَذَّبَةً وَإِلَّا تُجْلَدُ.","فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: صَدَقَ."],"takhrij":"حسن: رواه ابن خزيمة في كتاب التوحيد (137) عن محمد بن أبان، قال: حدثنا يونس بن بكير، قال: أخبرني محمد بن إسحاق، قال: حدثني يعقوب بن عتبة بن المغيرة بن الأخنس، عن عكرمة، عن ابن عباس، فذكره.","grade":"حسن","chapter_ar":"باب إثبات القدم لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Khuzaymah in Kitāb al-Tawḥīd (137).","chapter_en":"Affirming the Foot for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":29,"content":{"translation":{"en":["Ibn ʿAbbās, may Allah be pleased with them, reported: Two lines from the poetry of Umayyah ibn Abī al-Ṣalt al-Thaqafī were recited before the Messenger of Allah ﷺ: “A man and a bull are beneath the Foot of His Right,","and for the other is the eagle, while a lion lies in readiness.”","The Messenger of Allah ﷺ said: “He spoke truthfully.” Then another of his lines was recited:","“The sun refuses, and does not come forth except while punished, or else driven forth.”","The Messenger of Allah ﷺ said: “He spoke truthfully.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن خزيمة في كتاب التوحيد (137)."},{"num":365,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: يَكْشِفُ رَبُّنَا عَنْ سَاقِهِ، فَيَسْجُدُ لَهُ كُلُّ مُؤْمِنٍ وَمُؤْمِنَةٍ، وَيَبْقَى مَنْ كَانَ يَسْجُدُ فِي الدُّنْيَا رِيَاءً وَسُمْعَةً، فَيَذْهَبُ لِيَسْجُدَ، فَيَعُودُ ظَهْرُهُ طَبَقًا وَاحِدًا."],"takhrij":"متفق عليه: رواه البخاريّ في التفسير (4919) عن آدم بن أبي إياس، حدثنا اللّيث، عن خالد بن يزيد، عن سعيد بن أبي هلال، عن زيد بن أسلم، عن عطاء بن يسار، عن أبي سعيد، فذكره مختصراً هكذا.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الساق","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7439, 4919) and Muslim (183).","chapter_en":"What Has Been Reported Concerning the Shin","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":30,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī, may Allah be pleased with him, reported: I heard the Prophet ﷺ say: “Our Lord will uncover His Shin, and every believing man and believing woman will prostrate before Him. Those who used to prostrate in this world merely to show off and be seen by others will remain. They will try to prostrate, but their backs will become one rigid plate.”"]},"intro":{"ar":["قال الله تعالى:","﴿يَوْمَ يُكْشَفُ عَنْ سَاقٍ وَيُدْعَوْنَ إِلَى السُّجُودِ فَلَا يَسْتَطِيعُونَ ۝ خَاشِعَةً أَبْصَارُهُمْ تَرْهَقُهُمْ ذِلَّةٌ وَقَدْ كَانُوا يُدْعَوْنَ إِلَى السُّجُودِ وَهُمْ سَالِمُونَ﴾","[القلم: ٤٢–٤٣]"],"en":["Allah Most High said:","“On the Day when the Shin will be uncovered and they will be called to prostrate, but they will not be able. Their eyes humbled, humiliation will overwhelm them, for they had been called to prostrate while they were sound.”","[Sūrat al-Qalam 68:42–43]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13607],"tks":"متفق عليه: رواه البخاري (7439، 4919)، ومسلم (183)."},{"num":366,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِذَا جَمَعَ اللَّهُ الْعِبَادَ فِي صَعِيدٍ وَاحِدٍ نَادَى مُنَادٍ: لِيَلْحَقْ كُلُّ قَوْمٍ بِمَا كَانُوا يَعْبُدُونَ، فَيَلْحَقُ كُلُّ قَوْمٍ بِمَا كَانُوا يَعْبُدُونَ، وَيَبْقَى النَّاسُ عَلَى حَالِهِمْ، فَيَأْتِيهِمْ فَيَقُولُ: مَا بَالُ النَّاسِ ذَهَبُوا وَأَنْتُمْ هَاهُنَا ؟ فَيَقُولُونَ: نَنْتَظِرُ إِلَهَنَا، فَيَقُولُ: هَلْ تَعْرِفُونَهُ؟ فَيَقُولُونَ: إِذَا تَعَرَّفَ إِلَيْنَا عَرَفْنَاهُ، فَيَكْشِفُ لَهُمْ عَنْ سَاقِهِ فَيَقَعُونَ سُجُودًا، فَذَلِكَ قَوْلُ اللَّهِ تَعَالَى: ﴿يَوْمَ يُكْشَفُ عَنْ سَاقٍ وَيُدْعَوْنَ إِلَى السُّجُودِ فَلَا يَسْتَطِيعُونَ﴾ [سورة القلم: 42]، وَيَبْقَى كُلُّ مُنَافِقٍ فَلَا يَسْتَطِيعُ أَنْ يَسْجُدَ، ثُمَّ يَقُودُهُمْ إِلَى الْجَنَّةِ."],"takhrij":"حسن: رواه الدّارميّ (2845) عن محمد بن يزيد البزّار، عن يونس بن بُكير، أخبرني ابن إسحاق، أخبرني سعيد بن يسار، قال: سمعتُ أبا هريرة يقول (فذكر الحديث).","grade":"حسن","chapter_ar":"باب ما جاء في الساق","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Dārimī (2845).","chapter_en":"What Has Been Reported Concerning the Shin","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":30,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported: I heard the Messenger of Allah ﷺ say: “When Allah gathers the servants upon a single plain, a caller will announce: ‘Let every people follow what they used to worship.’ The people who remain will then be approached, and He will say: ‘Why have the people gone while you remain here?’ They will reply: ‘We are waiting for our God.’ He will ask: ‘Will you recognize Him?’ They will reply: ‘If He makes Himself known to us, we will recognize Him.’ He will then uncover His Shin, and they will fall down in prostration. This is the meaning of the statement of Allah Most High: ‘On the Day when the Shin will be uncovered and they will be called to prostrate, but they will not be able.’ [Sūrat al-Qalam 68:42] Every hypocrite will remain unable to prostrate. Then He will lead them to Paradise.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الدارمي (2845)."},{"num":367,"demo":false,"sanad":"","matn":["عَنْ عَبْدُ اللَّهِ بْنُ مَسْعُودٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فِي حَدِيثِ طَوِيل وَجَاءَ فِيهِ: فَيَتَمَثَّلُ الرَّبُّ عَزَّ وَجَلَّ فَيَأَتِيهِمْ فَيَقُولُ: مَا لَكُمْ لَا تَنْطَلِقُونَ كَمَا انْطَلَقَ النَّاسُ؟ قَالَ: فَيَقُولُونَ إِنَّ لَنَا لَإِلَهًا مَا رَأَيْنَاهُ بَعْدُ، فَيَقُولُ: هَلْ تَعْرِفُونَهُ إِنْ رَأَيْتُمُوهُ؟ فَيَقُولُونَ: إِنَّ بَيْنَنَا وَبَيْنَهُ عَلَامَةً إِذَا رَأَيْنَاهَا عَرَفْنَاهَا، قَالَ: فَيَقُولُ: مَا هِي ؟، فَيَقُولُونَ: يَكْشِفُ عَنْ سَاقِهِ، قَالَ: فَعِنْدَ ذَلِكَ يُكْشَفُ عَنْ سَاقٍ فَيَخِرُّ كُلُّ مَنْ كَانَ بِظَهْرِهِ طَبَقٌ، وَيَبْقَى قَوْمٌ ظُهُورُهُمْ كَصَياصِيِّ الْبَقَرِ يُرِيدُونَ السُّجُودَ فَلَا يَسْتَطِيعُونَ.... وَفِي رِوَايَةِ: يَكْشِفُ اللَّهُ عَنْ سَاقِهِ."],"takhrij":"حسن: رواه الطبرانيّ في الكبير (9763) عن علي بن عبدالعزيز، ثنا أبو غسان، ثنا عبد السلام بن حرب، عن أبي خالد الدالاني، عن المنهال بن عمرو، عن أبي عبيدة، عن مسروق، عن عبد الله بن مسعود فذكره في حديث طويل.","grade":"حسن","chapter_ar":"باب ما جاء في الساق","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (9/416–421).","chapter_en":"What Has Been Reported Concerning the Shin","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":30,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd may Allah be pleased with him reported from the Prophet ﷺ in a lengthy ḥadīth, in which it says: “The Lord, Mighty and Majestic, will appear to them and say: ‘Why do you not go as the other people have gone?’ They will reply: ‘We have a Lord whom we have not yet seen.’ He will ask: ‘How will you recognize your Lord if you see Him?’ They will reply: ‘There is a sign between us and Him; if we see it, we will recognize Him.’ He will ask: ‘What is it?’ They will reply: ‘He will uncover His Shin.’ Then at that point He will uncover His Shin, and everyone who used to prostrate willingly will fall down in prostration. A people will remain whose backs are like the horns of cattle; they will wish to prostrate but will be unable to do so…” In another narration: “Allah will uncover His Shin.”"]},"buhuth":{"en":["The expression:","“Like the ṣayāṣī of cattle”","means: like their horns."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (9723)."},{"num":368,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ أُنَاسٌ: يَا رَسُولَ اللَّهِ، هَلْ نَرَى رَبَّنَا يَوْمَ الْقِيَامَةِ؟ فَقَالَ: هَلْ تُضَارُّونَ فِي الشَّمْسِ لَيْسَ دُونَهَا سَحَابٌ ؟ قَالُوا: لَا يَا رَسُولَ اللَّهِ، قَالَ: هَلْ تُضَارُّونَ فِي الْقَمَرِ لَيْلَةَ الْبَدْرِ لَيْسَ دُونَهُ سَحَابٌ؟ قَالُوا: لَا يَا رَسُولَ اللَّهِ، قَالَ: فَإِنَّكُمْ تَرَوْنَهُ يَوْمَ الْقِيَامَةِ كَذَلِكَ، يَجْمَعُ اللَّهُ النَّاسَ فَيَقُولُ: مَنْ كَانَ يَعْبُدُ شَيْئًا فَلْيَتَّبِعْهُ، فَيَتْبَعُ مَنْ كَانَ يَعْبُدُ الشَّمْسَ، وَيَتْبَعُ مَنْ كَانَ يَعْبُدُ الْقَمَرَ، وَيَتْبَعُ مَنْ كَانَ يَعْبُدُ الطَّوَاغِيتَ، وَتَبْقَى هَذِهِ الْأُمَّةُ فِيهَا مُنَافِقُوهَا، فَيَأْتِيهِمُ اللَّهُ فِي غَيْرِ الصُّورَةِ الَّتِي يَعْرِفُونَ، فَيَقُولُ: أَنَا رَبُّكُمْ، فَيَقُولُونَ: نَعُوذُ بِاللَّهِ مِنْكَ هَذَا مَكَانُنَا حَتَّى يَأْتِيَنَا رَبُّنَا فَإِذَا أَتَانَا رَبُّنَا عَرَفْنَاهُ، فَيَأْتِيهِمُ اللَّهُ فِي الصُّورَةِ الَّتِي يَعْرِفُونَ، فَيَقُولُ: أَنَا رَبُّكُمْ، فَيَقُولُونَ: أَنْتَ رَبُّنَا فَيَتْبَعُونَهُ...(فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ)."],"takhrij":"متفق عليه: رواه البخاريّ في التوحيد (7437)، ومسلم في الإيمان (182) كلاهما من حديث إبراهيم بن سعد، عن ابن شهاب، عن عطاء بن يزيد اللّيثيّ، عن أبي هريرة، فذكر الحديث بطوله.","grade":"متفق عليه","chapter_ar":"باب في إتيان الرّب عزّ وجلَ يوم القيامة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Ibn Mājah (3792) and Aḥmad (10968).","chapter_en":"Chapter The coming of the Lord, Mighty and Majestic, on the Day of Resurrection.","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":31,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Prophet ﷺ said: “Indeed, Allah, Mighty and Majestic, says: ‘I am with My servant whenever he remembers Me and his lips move in remembrance of Me.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه ابن ماجه (3792)، وأحمد (10968)."},{"num":369,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَقُولُ اللَّهُ تَعَالَى: أَنَا عِنْدَ ظَنِّ عَبْدِي بِي، وَأَنَا مَعَهُ إِذَا ذَكَرَنِي، فَإِنْ ذَكَرَنِي فِي نَفْسِهِ ذَكَرْتُهُ فِي نَفْسِي، وَإِنْ ذَكَرَنِي فِي مَلَإٍ ذَكَرْتُهُ فِي مَلَإٍ خَيْرٍ مِنْهُمْ، وَإِنْ تَقَرَّبَ إِلَيَّ بِشِبْرٍ تَقَرَّبْتُ إِلَيْهِ ذِرَاعًا، وَإِنْ تَقَرَّبَ إِلَيَّ ذِرَاعًا تَقَرَّبْتُ إِلَيْهِ بَاعًا، وَإِنْ أَتَانِي يَمْشِي أَتَيْتُهُ هَرْوَلَةً."],"takhrij":"متفق عليه: رواه البخاريّ في التوحيد (7405)، ومسلم في الذكر والدّعاء (2675) كلاهما من حديث الأعمش، سمعت أبا صالح، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب قول الله تعالى  إن أتاني يمشي أتيتُه هرولةً )","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7405) and Muslim (2675).","chapter_en":"Chapter The saying of Allah Most High “If he comes to Me walking, I come to him at a run.”","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":32,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Prophet ﷺ said: “Allah Most High says: ‘I am as My servant thinks of Me, and I am with him when he remembers Me. If he remembers Me within himself, I remember him within Myself. If he remembers Me in a gathering, I remember him in a gathering better than it. If he draws near to Me by a handspan, I draw near to him by a cubit. If he draws near to Me by a cubit, I draw near to him by an armspan. And if he comes to Me walking, I come to him swiftly.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10765,11931],"tks":"متفق عليه: رواه البخاري (7405)، ومسلم (2675)."},{"num":370,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَرْوِيهِ عَنْ رَبِّهِ قَالَ: إِذَا تَقَرَّبَ الْعَبْدُ إِلَيَّ شِبْرًا تَقَرَّبْتُ إِلَيْهِ ذِرَاعًا، وَإِذَا تَقَرَّبَ مِنِّي ذِرَاعًا تَقَرَّبْتُ مِنْهُ بَاعًا، وَإِذَا أَتَانِي مَشْيًا أَتَيْتُهُ هَرْوَلَةً."],"takhrij":"صحيح: رواه البخاريّ في التوحيد (7536)، عن محمد بن عبدالرحيم، حدّثنا أبو زيد سعيد بن الرّبيع الهرويّ، حدثنا شعبة، عن قتادة، عن أنس، فذكره.","grade":"صحيح","chapter_ar":"باب قول الله تعالى  إن أتاني يمشي أتيتُه هرولةً )","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (7536).","chapter_en":"Chapter The saying of Allah Most High “If he comes to Me walking, I come to him at a run.”","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":32,"content":{"translation":{"en":["Anas may Allah be pleased with him reported from the Prophet ﷺ, narrating from his Lord, Mighty and Majestic: “When the servant draws near to Me by a handspan, I draw near to him by a cubit. When he draws near to Me by a cubit, I draw near to him by an armspan. And when he comes to Me walking, I come to him swiftly.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (7536)."},{"num":371,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَضْحَكُ اللَّهُ إِلَى رَجُلَيْنِ: يَقْتُلُ أَحَدُهُمَا الْآخَرَ كِلَاهُمَا يَدْخُلُ الْجَنَّةَ، يُقَاتِلُ هَذَا فِي سَبِيلِ اللَّهِ، فَيُقْتَلُ، ثُمَّ يَتُوبُ اللَّهُ عَلَى الْقَاتِلِ، فَيُقَاتِلُ، فَيُسْتَشْهَدُ.","وَفِي لَفْظٍ: ضَحِكَ رَبُّنَا مِنْ رَجُلَيْنِ قَتَلَ أَحَدُهُمَا صَاحِبَهُ وَكِلاهُمَا فِي الْجَنَّةِ."],"takhrij":"متفق عليه: رواه مالك في الجهاد (28) عن أبي الزناد، عن الأعرج عن أبي هريرة فذكره. ورواه البخاري في الجهاد (2826) عن عبدالله بن يوسف، عن مالك، بإسناده.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الضحك","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (28), al-Bukhārī (2826), and Muslim (1890).","chapter_en":"What Has Been Reported Concerning Laughter","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":33,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Allah laughs at two men, one of whom kills the other, yet both of them enter Paradise. One of them fights in the way of Allah and is killed. Then Allah accepts the repentance of the killer, and he fights and is martyred.” In another wording:","“Our Lord laughed at two men, one of whom killed his companion, while both of them are in Paradise.”"]},"buhuth":{"en":["The second wording was narrated by Ibn Khuzaymah in Kitāb al-Tawḥīd (456) and Ibn Ḥibbān in his Ṣaḥīḥ (4666)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (28)، والبخاري (2826)، ومسلم (1890)."},{"num":372,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ نَاسًا قَالُوا لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا رَسُولَ اللَّهِ! هَلْ نَرَى رَبَّنَا يَوْمَ الْقِيَامَةِ؟... وَجَاءَ فِيهِ: فَيَقُولُ اللَّهُ تَبَارَكَ وَتَعَالَى لَهُ: أَلَيْسَ قَدْ أَعْطَيْتَ عُهُودَكَ وَمَوَاثِيقَكَ، أَنْ لَا تَسْأَلَ غَيْرَ مَا أُعْطِيتَ؟ وَيْلَكَ يَا ابْنَ آدَمَ مَا أَغْدَرَكَ؟ فَيَقُولُ: أَيْ رَبِّ لَا أَكُونُ أَشْقَى خَلْقِكَ، فَلَا يَزَالُ يَدْعُو اللَّهَ حَتَّى يَضْحَكَ اللَّهُ تَبَارَكَ وَتَعَالَى مِنْهُ، فَإِذَا ضَحِكَ اللَّهُ مِنْهُ قَالَ: ادْخُلِ الْجَنَّةَ... فَذَكَرَ الْحَدِيثَ."],"takhrij":"متفق عليه: رواه البخاريّ في الأذان (806)، ومسلم في الإيمان (182) كلاهما من حديث أبي اليمان، قال: أخبرنا شعيب، عن الزهريّ، أخبرني سعيد بن المسيب، وعطاء بن يزيد اللّيثي، أنّ أبا هريرة، أخبرهما، فذكر الحديث بطوله، وهو مخرج في حديث الصّراط.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الضحك","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (806) and Muslim (182).","chapter_en":"What Has Been Reported Concerning Laughter","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":33,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported: The people asked the Prophet ﷺ: “Will we see our Lord on the Day of Resurrection?” And in the narration it says: “Then the Lord will say: ‘Did I not take covenants and pledges from you that you would not ask for anything beyond what you had been given?’ He will say: ‘My Lord, do not make me the most miserable of Your creation.’ He will continue supplicating to Allah until Allah, Blessed and Exalted, laughs at him. When Allah laughs at him, He will say: ‘Enter Paradise…’”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (806)، ومسلم (182)."},{"num":373,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: آخِرُ مَنْ يَدْخُلُ الْجَنَّةَ رَجُلٌ، فَهْوَ يَمْشِي مَرَّةً، وَيَكْبُو مَرَّةً، وَتَسْفَعُهُ النَّارُ مَرَّةً فَذَكَرَ الْحَدِيثَ بِطُولِهِ. وَقَالَ فِي آخَرَ الْحَدِيثِ: فَيَقُولُ اللَّهَ تَعَالَى: يَا ابْنَ آدَمَ، مَا يَصْرِينِي مِنْكَ، أَيُرْضِيكَ أَنْ أُعْطِيَكَ الدُّنْيَا وَمِثْلَهَا مَعَهَا؟ قَالَ: يَا رَبِّ أَتَسْتَهْزِئُ مِنِّي وَأَنْتَ رَبُّ الْعَالَمِينَ؟ فَضَحِكَ ابْنُ مَسْعُودٍ، فَقَالَ: أَلَا تَسْأَلُونِي مِمَّ أَضْحَكُ؟ فَقَالُوا: مِمَّ تَضْحَكُ؟ قَالَ: هَكَذَا ضَحِكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالُوا: مِمَّ تَضْحَكُ يَا رَسُولَ اللَّهِ؟ قَالَ: مِنْ ضِحْكِ رَبِّ الْعَالَمِينَ، حِينَ قَالَ: أَتَسْتَهْزِئُ مِنِّي وَأَنْتَ رَبُّ الْعَالَمِينَ؟ فَيَقُولُ: إِنِّي لَا أَسْتَهْزِئُ مِنْكَ، وَلَكِنِّي عَلَى مَا أَشَاءُ قَادِرٌ."],"takhrij":"صحيح: رواه مسلم في الإيمان (187) عن أبي بكر بن أبي شيبة، حدثنا عفان بن مسلم، حدثنا حماد بن سلمة، حدثنا ثابت، عن أنس، عن ابن مسعود، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الضحك","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (187).","chapter_en":"What Has Been Reported Concerning Laughter","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":33,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd may Allah be pleased with him reported that the Prophet ﷺ said: “Indeed, the last person to enter Paradise will be a man who walks at times, stumbles at times, and is scorched by the Fire at times…” He then mentioned the lengthy ḥadīth, and at its conclusion: “Allah Most High will say: ‘O son of Adam, what will bring your asking of Me to an end? Would it please you if I gave you the world and another like it along with it?’ He will say: ‘My Lord, are You mocking me while You are the Lord of the worlds?’” Ibn Masʿūd laughed and said: “Will you not ask me why I am laughing?” They asked: “Why are you laughing?” He replied: “This is how the Messenger of Allah ﷺ laughed.” They asked: “Why do you laugh, O Messenger of Allah?” He said: “Because of the laughter of the Lord of the worlds when the man said: ‘Are You mocking me while You are the Lord of the worlds?’ Allah will say: ‘I am not mocking you. Rather, I am capable of whatever I will.’”"]},"buhuth":{"en":["The expression:","“What will bring your asking of Me to an end?”","means: what will cause you to cease asking Me? The word al-ṣary means cutting off."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (187)."},{"num":374,"demo":false,"sanad":"","matn":["عَنْ جَابِرًا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فِي قِصَّةِ الْوُرُودِ قَالَ: نَجِيءُ نَحْنُ يَوْمَ الْقِيَامَةِ عَنْ كَذَا وَكَذَا، انْظُرْ أَيْ: ذَلِكَ فَوْقَ النَّاسِ، قَالَ: فَتُدْعَى الْأُمَمُ بِأَوْثَانِهَا وَمَا كَانَتْ تَعْبُدُ، الْأَوَّلَ فَالْأَوَّلَ، ثُمَّ يَأْتِينَا رَبُّنَا بَعْدَ ذَلِكَ، فَيَقُولُ: مَنْ تَنْظُرُونَ؟ فَيَقُولُونَ: نَنْظُرُ رَبَّنَا، فَيَقُولُ: أَنَا رَبُّكُمْ، فَيَقُولُونَ: حَتَّى نَنْظُرَ إِلَيْكَ، فَيَتَجَلَّى لَهُمْ يَضْحَكُ... (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ)."],"takhrij":"صحيح: رواه مسلم في الإيمان (191) من طرق عن روح بن عبادة القيسيّ، حدثنا ابن جريج، قال: أخبرني أبو الزبير، أنه سمع جابر بن عبدالله يسأل عن الورود، فذكر مثله في حديث طويل مخرج بكامله في حديث الصّراط.","grade":"صحيح","chapter_ar":"باب ما جاء في الضحك","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (191).","chapter_en":"What Has Been Reported Concerning Laughter","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":33,"content":{"translation":{"en":["Jābir may Allah be pleased with him reported from the Prophet ﷺ, in the account of the passage: “On the Day of Resurrection we will be upon such-and-such” — and he looked, meaning at a place above the people. He continued: “The nations will then be summoned along with their idols and whatever they used to worship, one after another. Then our Lord will come to us afterward and say: ‘Whom are you waiting for?’ They will reply: ‘We are waiting for our Lord.’ He will say: ‘I am your Lord.’ They will say: ‘Until we look at You.’ Then He will manifest Himself to them, laughing.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (191)."},{"num":375,"demo":false,"sanad":"","matn":["عَنْ إِبْرَاهِيمَ بْنِ سَعْدٍ أَخْبَرَنِي أَبِي قَالَ: كُنْتُ جَالِسًا إِلَى جَنْبِ حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ فِي الْمَسْجِدِ، فَمَرَّ شَيْخٌ جَمِيلٌ مِنْ بَنِي غِفَارٍ وَفِي أُذُنَيْهِ صَمَمٌ أَوْ قَالَ: وَقْرٌ، أَرْسَلَ إِلَيْهِ حُمَيْدٌ، فَلَمَّا أَقْبَلَ، قَالَ: يَا ابْنَ أَخِي، أَوْسِعْ لَهُ فِيمَا بَيْنِي وَبَيْنَكَ، فَإِنَّهُ قَدْ صَحِبَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَاءَ حَتَّى جَلَسَ فِيمَا بَيْنِي وَبَيْنَهُ، فَقَالَ لَهُ حُمَيْدٌ هَذَا الْحَدِيثُ الَّذِي حَدَّثْتَنِي، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ الشَّيْخُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ اللَّهَ عَزَّ وَجَلَّ يُنْشِئُ السَّحَابَ فَيَنْطِقُ أَحْسَنَ الْمَنْطِقِ، وَيَضْحَكُ أَحْسَنَ الضَّحِكِ."],"takhrij":"صحيح: رواه الإمام احمد (23686) والآجرى في الشريعة (648) والبيهقي في الأسماء والصفات (988) كلهم من طرق عن إبراهيم بن سعد بإسناده.","grade":"صحيح","chapter_ar":"باب ما جاء في الضحك","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Aḥmad (23686), al-Ājurrī in al-Sharīʿah (648), and al-Bayhaqī in al-Asmāʾ wa al-Ṣifāt (988).","chapter_en":"What Has Been Reported Concerning Laughter","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":33,"content":{"translation":{"en":["Ibrāhīm ibn Saʿd reported: My father informed me: I was sitting beside Ḥumayd ibn ʿAbd al-Raḥmān in the mosque when a handsome elderly man from Banū Ghifār passed by. He had deafness in his ears — or he said: heaviness of hearing. Ḥumayd sent for him. When he approached, Ḥumayd said: “O my nephew, make room for him between me and you, for he accompanied the Messenger of Allah ﷺ.” He came and sat between us. Ḥumayd said to him: “Narrate to me the ḥadīth that you previously narrated to me from the Messenger of Allah ﷺ.” The elderly man said: I heard the Messenger of Allah ﷺ say: “Indeed, Allah brings forth the clouds, and they speak with the finest speech and laugh with the finest laughter.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (23686)، والآجري في الشريعة (648)، والبيهقي في الأسماء والصفات (988)."},{"num":376,"demo":false,"sanad":"","matn":["عَنْ نُعَيْمِ بْنِ هَمَّارٍ أَنَّ رَجُلًا سَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيُّ الشُّهَدَاءِ أَفْضَلُ؟ قَالَ: الَّذِينَ إِنْ يُلْقَوْا فِي الصَّفِّ يَلْفِتُونَ وُجُوهَهُمْ حَتَّى يُقْتَلُوا، أُولَئِكَ يَنْطَلِقُونَ فِي الْغُرَفِ الْعُلَى مِنَ الْجَنَّةِ، وَيَضْحَكُ إِلَيْهِمْ رَبُّهُمْ، وَإِذَا ضَحِكَ رَبُّكَ إِلَى عَبْدٍ فِي الدُّنْيَا، فَلَا حِسَابَ عَلَيْهِ."],"takhrij":"حسن: رواه الإمام أحمد (22476)، وأبو يعلى (6855)، وابن أبي عاصم في الجهاد (228)، والبيهقي في الأسماء والصفات (986)، والآجريّ في الشريعة (650) كلّهم من طرق عن إسماعيل بن عياش، عن بحير بن سعيد، عن خالد بن معدان، عن كثير بن مرة، عن نعيم بن همّار، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الضحك","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (22476), Abū Yaʿlā (6855), and Ibn Abī ʿĀṣim in al-Jihād (228).","chapter_en":"What Has Been Reported Concerning Laughter","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":33,"content":{"translation":{"en":["Nuʿaym ibn Hammār, may Allah be pleased with him, reported: A man asked the Prophet ﷺ: “Which martyrs are the best?” He replied: “Those who, when they meet the enemy in the battle line, do not turn their faces away until they are killed. Those are the ones who will dwell in the lofty chambers of Paradise. Your Lord laughs toward them, and when your Lord laughs toward a servant in this world, there will be no reckoning for him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (22476)، وأبو يعلى (6855)، وابن أبي عاصم في الجهاد (228)."},{"num":377,"demo":false,"sanad":"","matn":["عَنْ أَبِي رَزِينٍ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ضَحِكَ رَبُّنَا عَزَّ وَجَلَّ مِنْ قُنُوطِ عِبَادِهِ، وَقُرْبِ غَيْرِهِ. قَالَ أَبُو رَزِينٍ: قُلْتُ: يَا رَسُولَ اللَّهِ، أَوَ يَضْحَكُ الرَّبُّ عَزَّ وَجَلَّ؟ قَالَ: نَعَمْ. وَلَنْ نَعْدَمَ مِنْ رَبٍّ يَضْحَكُ خَيْرًا."],"takhrij":"حسن: رواه الإمام أحمد (16187)، وأبو داود الطيالسيّ (1092)، والآجريّ في الشريعة (638، 639)، وابن أبي عاصم في السنة (554)، والبيهقي في الأسماء والصفات (987) كلهم من طرق عن حماد بن سلمة، عن يعلى بن عطاء، عن وكيع بن حدس، عن عمّه أبي رزين، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الضحك","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (16187), Abū Dāwūd al-Ṭayālisī (1092), and al-Ājurrī in al-Sharīʿah (638, 639).","chapter_en":"What Has Been Reported Concerning Laughter","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":33,"content":{"translation":{"en":["Abū Razīn may Allah be pleased with him reported that the Prophet ﷺ said: “Our Lord, Mighty and Majestic, laughs at the despair of His servants while the change in their condition is near.” Abū Razīn asked: “Does the Lord, Mighty and Majestic, laugh?” He replied: “Yes.” Abū Razīn said: “Then we will never be deprived of good from a Lord who laughs.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (16187)، وأبو داود الطيالسي (1092)، والآجري في الشريعة (638، 639)."},{"num":378,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ رَبِيعَةَ قَالَ: أَرْدَفَنِي عَلِيٌّ رِضْوَانُ اللَّهُ عَلَيْهِ خَلْفَهُ، ثُمَّ خَرَجَ إِلَى ظَهْرِ الْكُوفَةِ، ثُمَّ رَفَعَ رَأْسَهُ إِلَى السَّمَاءِ، فَقَالَ: ﴿لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ﴾ [سورة الأنبياء: 87]، فَاغْفِرْ لِي، ثُمَّ الْتَفَتَ إِلَىَّ فَضَحِكَ، فَقَالَ: أَلَا تَسْأَلُنِي مِمَّ ضَحِكْتُ؟ قَالَ: قُلْتُ: مِمَّ ضَحِكْتَ يَا أَمِيرَ الْمُؤْمِنِينَ؟ قَالَ: أَرْدَفَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَلْفَهُ، ثُمَّ خَرَجَ بِي إِلَى حَرَّةِ الْمَدِينَةِ ثُمَّ رَفَعَ رَأْسَهُ إِلَى السَّمَاءِ فَقَالَ: ﴿لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ﴾، فَاغْفِرْ لِي، ثُمَّ الْتَفَتَ إِلَىَّ فَضَحِكَ، فَقَالَ: أَلَا تَسْأَلُنِي مِمَّ ضَحِكْتُ؟ قَالَ: قُلْتُ: مِمَّ ضَحِكْتَ يَا رَسُولَ اللَّهِ؟ قَالَ: ضَحِكْتُ مِنْ ضَحِكِ رَبِّي، وَتَعَجُّبِهِ مِنْ عَبْدِهِ أَنَّهُ يَعْلَمُ أَنَّهُ لَا يَغْفِرُ الذُّنُوبَ غَيْرُهُ."],"takhrij":"حسن: رواه ابن خزيمة في التوحيد (465)، والآجري في الشريعة (642)، والطبراني في الدّعاء (777)، والبيهقي في الأسماء والصفات (980) كلّهم من طرق عن إسماعيل بن عبدالملك، عن علي بن ربيعة، قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الضحك","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Khuzaymah in al-Tawḥīd (465), al-Ājurrī in al-Sharīʿah (642), and al-Ṭabarānī in al-Duʿāʾ (777).","chapter_en":"What Has Been Reported Concerning Laughter","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":33,"content":{"translation":{"en":["ʿAlī ibn Rabīʿah reported: ʿAlī may Allah be pleased with him seated me behind him on his mount and took me out to the lava plain of Madinah. He then raised his head toward the heaven and said: “There is no deity worthy of worship except You. Glory be to You! Indeed, I have been among the wrongdoers.” [Sūrat al-Anbiyāʾ 21:87] “So forgive me.” He then turned toward me and laughed. He asked: “Will you not ask me why I laughed?” I said: “Why did you laugh, O Commander of the Believers?” He replied: The Messenger of Allah ﷺ once seated me behind him on his mount and took me out to the lava plain of Madinah. He raised his head toward the heaven and said: “There is no deity worthy of worship except You. Glory be to You! Indeed, I have been among the wrongdoers.” “So forgive me.” He then turned toward me and laughed. He asked: “Will you not ask me why I laughed?” I said: “Why did you laugh, O Messenger of Allah?” He replied: “I laughed because of the laughter of my Lord and His amazement at His servant, because the servant knows that no one forgives sins except Him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن خزيمة في التوحيد (465)، والآجري في الشريعة (642)، والطبراني في الدعاء (777)."},{"num":379,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: عَجِبَ اللَّهُ مِنْ قَوْمٍ يَدْخُلُونَ الْجَنَّةَ فِي السَّلَاسِلِ."],"takhrij":"صحيح: رواه البخاريّ في الجهاد (3010) عن محمد بن بشار، حدّثنا غندر، حدثنا شعبة، عن محمد بن زياد، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في إثبات العجب لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (3010).","chapter_en":"What Has Been Reported Concerning Affirming Amazement for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":34,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Prophet ﷺ said: “Allah is amazed at a people who will enter Paradise in chains.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[16362],"tks":"صحيح: رواه البخاري (3010)."},{"num":380,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: أَتَى رَجُلٌ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا رَسُولَ اللَّهِ، أَصَابَنِي الْجَهْدُ، فَأَرْسَلَ إِلَى نِسَائِهِ، فَلَمْ يَجِدْ عِنْدَهُنَّ شَيْئًا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَلَا رَجُلٌ يُضَيِّفُ هَذِهِ اللَّيْلَةَ يَرْحَمُهُ اللَّهُ، فَقَامَ رَجُلٌ مِنْ الْأَنْصَارِ، فَقَالَ: أَنَا يَا رَسُولَ اللَّهِ، فَذَهَبَ إِلَى أَهْلِهِ، فَقَالَ لِامْرَأَتِهِ: ضَيْفُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا تَدَّخِرِيهِ شَيْئًا، قَالَتْ: وَاللَّهِ مَا عِنْدِي إِلَّا قُوتُ الصِّبْيَةِ، قَالَ: فَإِذَا أَرَادَ الصِّبْيَةُ الْعَشَاءَ فَنَوِّمِيهِمْ وَتَعَالَيْ، فَأَطْفِئِي السِّرَاجَ، وَنَطْوِي بُطُونَنَا اللَّيْلَةَ، فَفَعَلَتْ، ثُمَّ غَدَا الرَّجُلُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: لَقَدْ عَجِبَ اللَّهُ عَزَّ وَجَلَّ أَوْ ضَحِكَ مِنْ فُلَانٍ وَفُلَانَةَ، فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ: ﴿وَيُؤْثِرُونَ عَلَى أَنْفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ﴾ [سورة الحشر: 9]."],"takhrij":"متفق عليه: رواه البخاريّ في مناقب الأنصار (3798)، وفي التفسير bukhari(4889)، ومسلم في كتاب الأشربة (2054) كلاهما من حديث فضيل بن غزوان، عن أبي حازم، عن أبي هريرة فذكره. واللّفظ للبخاريّ، ولفظ مسلم نحوه.","grade":"متفق عليه","chapter_ar":"باب ما جاء في إثبات العجب لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4889, 3798) and Muslim (2054), with the wording of al-Bukhārī; Muslim’s wording is similar.","chapter_en":"What Has Been Reported Concerning Affirming Amazement for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":34,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported: A man came to the Messenger of Allah ﷺ and said: “O Messenger of Allah, I have been afflicted by severe hunger and hardship.” The Prophet ﷺ sent word to his wives, but nothing was found with them. The Messenger of Allah ﷺ then said: “Is there anyone who will host this man tonight? May Allah have mercy upon him.” A man from the Anṣār stood and said: “I will, O Messenger of Allah.” He went to his family and said to his wife: “This is the guest of the Messenger of Allah ﷺ, so do not withhold anything from him.” She replied: “By Allah, I have nothing except the food of the children.” He said: “When the children ask for supper, put them to sleep. Then come and extinguish the lamp, and we will endure hunger tonight.” She did so. The following morning, the man went to the Messenger of Allah ﷺ, and he said: “Allah, Mighty and Majestic, was amazed — or laughed — at so-and-so and so-and-so.” Then Allah, Mighty and Majestic, revealed: “They give preference to others over themselves even though they themselves are in need.” [Sūrat al-Ḥashr 59:9]"]}},"tuhfa":{},"full":1,"rep":[13523,13658,13724],"tks":"متفق عليه: رواه البخاري (4889، 3798)، ومسلم (2054)، واللفظ للبخاري، ولفظ مسلم نحوه."},{"num":381,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: يَعْجَبُ رَبُّكَ مِنْ رَاعِي غَنْمٍ فِي رَأْسِ الشَّظِيَّةِ لِلْجَبَلِ، يُؤَذِّنُ لِلصَّلاةِ وَيُصَلِّي، فِيقُولُ اللَّهُ: انْظُرُوا إِلَى عَبْدِي هَذَا يُؤَذِّنُ وَيُقِيمُ لِلصَّلاةِ يَخَافُ مِنِّي، قَدْ غَفَرْتُ لِعَبْدِي وَأَدْخَلْتُهُ الْجَنَّةَ."],"takhrij":"صحيح: رواه أبو داود (1203)، والنسائي (665) كلاهما من طريق ابن وهب، عن عمرو بن الحارث، أنّ أبا عُشَّانة المعافريّ حدّثه عن عقبة بن عامر، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في إثبات العجب لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (1203) and al-Nasāʾī (665), and authenticated by Ibn Ḥibbān (1660).","chapter_en":"What Has Been Reported Concerning Affirming Amazement for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":34,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir, may Allah be pleased with him, said: I heard the Messenger of Allah ﷺ say: “Your Lord, Mighty and Majestic, is amazed at a shepherd on the top of a rugged mountain peak who gives the call to prayer and prays. Allah, Mighty and Majestic, says: ‘Look at this servant of Mine. He gives the call to prayer and establishes the prayer, fearing Me. I have forgiven My servant and admitted him to Paradise.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1203)، والنسائي (665)، وصححه ابن حبان (1660)."},{"num":382,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللَّهَ عَزَّ وَجَلَّ لَيَعْجَبُ مِنَ الشَّابِّ لَيْسَتْ لَهُ صَبْوَةٌ."],"takhrij":"حسن: رواه الإمام أحمد (17371)، والطبراني في الكبير (853) كلاهما من طريق قتيبة بن سعيد، حدثنا ابن لهيعة، عن أبي عشانة، عن عقبة بن عامر، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في إثبات العجب لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (17371), al-Ṭabarānī in al-Muʿjam al-Kabīr (17, no. 853), and Ibn Abī ʿĀṣim in al-Sunnah (571).","chapter_en":"What Has Been Reported Concerning Affirming Amazement for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":34,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir, may Allah be pleased with him, said: The Messenger of Allah ﷺ said: “Indeed, Allah is amazed at a young man who has no youthful inclination toward desire.”"]},"buhuth":{"en":["The phrase “he has no ṣabwah” means that he has no inclination toward desire or whim."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (17371)، والطبراني في الكبير (17/ رقم 853)، وابن أبي عاصم في السنة (571)."},{"num":383,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: عَجِبَ رَبُّنَا عَزَّ وَجَلَّ مِنْ رَجُلٍ غَزَا فِي سَبِيلِ اللَّهِ فَانْهَزَمَ يَعْنِي أَصْحَابَهُ، فَعَلِمَ مَا عَلَيْهِ فَرَجَعَ حَتَّى أُهَرِيقَ دَمُهُ، فَيَقُولُ اللَّهُ تَعَالَى لِمَلَائِكَتِهِ: انْظُرُوا إِلَى عَبْدِي رَجَعَ رَغْبَةً فِيمَا عِنْدِي وَشَفَقَةً مِمَّا عِنْدِي حَتَّى أُهَرِيقَ دَمُهُ.","وَفِي رِوَايَةِ: عَجِبَ رَبُّنَا مِنْ رَجُلَيْنِ: رَجُلٍ ثَارَ عَنْ وِطَائِهِ وَلِحَافِهِ مِنْ بَيْنَ حِبِّهِ وَأَهْلِهِ إِلَى صَلاتِهِ. فَيَقُولُ اللَّهُ جَلَّ وَعَلا لِمَلائِكَتِهِ: انْظُرُوا إِلَى عَبْدِي، ثَارَ عَنْ فِرَاشِهِ وَوِطَائِهِ مِنْ بَيْنَ حِبِّهِ وَأَهْلِهِ إِلَى صَلاتِهِ رَغْبَةً فِيمَا عِنْدِي، وَشَفَقَةً مِمَّا عِنْدِي، وَرَجُلٍ غَزَا فِي سَبِيلِ اللَّهِ...فَذَكَرَ الْحَدِيثَ."],"takhrij":"صحيح: رواه أبو داود (2536) عن موسى بن إسماعيل، حدثنا حماد، أخبرنا عطاء بن السائب، عن مرة الهمدانيّ، عن عبدالله بن مسعود، فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في إثبات العجب لله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (2536) and al-Ḥākim (2531). The second narration was narrated by Imām Aḥmad (3949) and authenticated by Ibn Ḥibbān (2557, 2558).","chapter_en":"What Has Been Reported Concerning Affirming Amazement for Allah Most High","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":34,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd, may Allah be pleased with him, said: The Messenger of Allah ﷺ said: “Our Lord, Mighty and Majestic, is amazed at a man who fought in the path of Allah and whose companions fled. He realized what was upon him, so he returned until his blood was shed. Allah Most High says to His angels: ‘Look at My servant. He returned out of desire for what is with Me and fear of what is with Me, until his blood was shed.’” In another narration:","“Our Lord is amazed at two men: a man who rises from his bedding and blanket, leaving his beloved family, to perform his prayer. Our Lord, Glorious and Exalted, says to His angels: ‘Look at My servant. He rose from his bed and bedding, leaving his beloved family, to perform his prayer, desiring what is with Me and fearing what is with Me.’ And a man who fought in the path of Allah…” Then he mentioned the remainder of the ḥadīth."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (2536)، والحاكم (2531). والرواية الثانية رواها الإمام أحمد (3949)، وصححها ابن حبان (2557، 2558)."},{"num":384,"demo":false,"sanad":"","matn":["عَنِ الْحَارِثِ بْنِ سُوَيْدٍ قَالَ: حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مَسْعُودٍ، حَدِيثَيْنِ أَحَدُهُمَا عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَالْآخَرُ عَنْ نَفْسِهِ، قَالَ (يَعْنِي ابْنَ مَسْعُودٍ): إِنَّ الْمُؤْمِنَ يَرَى ذُنُوبَهُ كَأَنَّهُ قَاعِدٌ تَحْتَ جَبَلٍ يَخَافُ أَنْ يَقَعَ عَلَيْهِ، وَإِنَّ الْفَاجِرَ يَرَى ذُنُوبَهُ كَذُبَابٍ مَرَّ عَلَى أَنْفِهِ فَقَال: بِهِ هَكَذَا، قَالَ أَبُو شِهَابٍ: بِيَدِهِ فَوْقَ أَنْفِهِ، ثُمَّ قَالَ (يَعْنِي ابْنَ مَسْعُودٍ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ) لَلَّهُ أَفْرَحُ بِتَوْبَةِ عَبْدِهِ مِنْ رَجُلٍ نَزَلَ مَنْزِلًا وَبِهِ مَهْلَكَةٌ وَمَعَهُ رَاحِلَتُهُ، عَلَيْهَا طَعَامُهُ وَشَرَابُهُ فَوَضَعَ رَأْسَهُ فَنَامَ نَوْمَةً، فَاسْتَيْقَظَ وَقَدْ ذَهَبَتْ رَاحِلَتُهُ حَتَّى إِذَا اشْتَدَّ عَلَيْهِ الْحَرُّ وَالْعَطَشُ أَوْ مَا شَاءَ اللَّهُ، قَالَ: أَرْجِعُ إِلَى مَكَانِي فَرَجَعَ فَنَامَ نَوْمَةً، ثُمَّ رَفَعَ رَأْسَهُ فَإِذَا رَاحِلَتُهُ عِنْدَهُ."],"takhrij":"متفق عليه: رواه البخاريّ في الدّعوات (6308)، ومسلم في التوبة (2744) كلاهما من حديث الأعمش، عن عمارة بن عمير، عن الحارث بن سويد، فذكره، واللّفظ للبخاريّ، ولفظ مسلم بنحوه.","grade":"متفق عليه","chapter_ar":"باب إثبات الفرح لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6308) and Muslim (2744), with the wording of al-Bukhārī.","chapter_en":"Affirming Joy for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":35,"content":{"translation":{"en":["Al-Ḥārith ibn Suwayd reported: ʿAbdullāh — meaning Ibn Masʿūd may Allah be pleased with him — narrated to us two reports: one from the Prophet ﷺ and the other from himself. Ibn Masʿūd said: “The believer sees his sins as though he were sitting beneath a mountain, fearing that it will fall upon him. The wicked person sees his sins like a fly that passes over his nose, and he brushes it away like this.” Abū Shihāb gestured with his hand above his nose. Then Ibn Masʿūd narrated from the Prophet ﷺ: “Allah is more joyful at the repentance of His believing servant than a man who stopped at a place where destruction threatened him, while his riding animal was with him carrying his food and drink. He laid his head down and slept. When he awoke, his riding animal had disappeared. The heat and thirst became severe upon him — or whatever Allah willed — so he said: ‘I will return to my place.’ He returned and slept. Then he raised his head, and suddenly his riding animal was there beside him.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6308)، ومسلم (2744)، واللفظ للبخاري."},{"num":385,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اللَّهُ أَفْرَحُ بِتَوْبَةِ عَبْدِهِ مِنْ أَحَدِكُمْ سَقَطَ عَلَى بَعِيرِهِ وَقَدْ أَضَلَّهُ فِي أَرْضِ فَلَاةٍ."],"takhrij":"متفق عليه: رواه البخاريّ في الدّعوات (6309)، ومسلم في التوبة (2747) كلاهما من حديث هُدبة بن خالد، ويقال: هدّاب، عن همّام بن يحيى، حدّثنا قتادة، عن أنس، فذكر مثله، واللّفظ للبخاريّ، ولفظ مسلم: للهُ أشدّ فرحاً بتوبة عبده من أحدكم إذا استيقظ على بعيره قد أضلّه بأرض فلاة.","grade":"متفق عليه","chapter_ar":"باب إثبات الفرح لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6309) and Muslim (2747), with the wording of al-Bukhārī.","chapter_en":"Affirming Joy for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":35,"content":{"translation":{"en":["Anas, may Allah be pleased with him, said: The Messenger of Allah ﷺ said: “Allah is more joyful at the repentance of His servant than one of you who suddenly comes upon his camel after having lost it in a desolate land.”"]},"buhuth":{"ar":["ولفظ مسلم:","«لله أشد فرحاً بتوبة عبده من أحدكم إذا استيقظ على بعيره قد أضله بأرض فلاة»."],"en":["Muslim’s wording is:","“Allah is more intensely joyful at the repentance of His servant than one of you when he awakens to find his camel after having lost it in a desolate land.”"]}},"tuhfa":{},"full":1,"rep":[11431],"tks":"متفق عليه: رواه البخاري (6309)، ومسلم (2747)، واللفظ للبخاري."},{"num":386,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَلَّهُ أَشَدُّ فَرَحًا بِتَوْبَةِ عَبْدِهِ حِينَ يَتُوبُ إِلَيْهِ مِنْ أَحَدِكُمْ كَانَ عَلَى رَاحِلَتِهِ بِأَرْضِ فَلَاةٍ، فَانْفَلَتَتْ مِنْهُ وَعَلَيْهَا طَعَامُهُ وَشَرَابُهُ، فَأَيِسَ مِنْهَا، فَأَتَى شَجَرَةً فَاضْطَجَعَ فِي ظِلِّهَا قَدْ أَيِسَ مِنْ رَاحِلَتِهِ فَبَيْنَا هُوَ كَذَلِكَ، إِذَا هُوَ بِهَا قَائِمَةً عِنْدَهُ فَأَخَذَ بِخِطَامِهَا، ثُمَّ قَالَ: مِنْ شِدَّةِ الْفَرَحِ: اللَّهُمَّ أَنْتَ عَبْدِي وَأَنَا رَبُّكَ أَخْطَأَ مِنْ شِدَّةِ الْفَرَحِ."],"takhrij":"صحيح: رواه مسلم في التوبة (2747) من طرق عن عمر بن يونس، حدّثنا عكرمة بن عمّار، حدّثنا إسحاق بن عبدالله بن أبي طلحة، حدّثنا أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب إثبات الفرح لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2747).","chapter_en":"Affirming Joy for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":35,"content":{"translation":{"en":["Anas ibn Mālik, may Allah be pleased with him, said: The Messenger of Allah ﷺ said: “Allah is more intensely joyful at the repentance of His servant when he repents to Him than one of you who was upon his riding animal in a desolate land and it escaped from him while his food and drink were upon it. He despaired of finding it, so he came to a tree and lay down in its shade, having lost all hope of recovering his riding animal. While he was in that state, suddenly it was standing beside him. He seized its reins and, from the intensity of his joy, said: ‘O Allah, You are my servant and I am Your lord!’ He made the mistake because of the intensity of his joy.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2747)."},{"num":387,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَلَّهُ أَشَدُّ فَرَحًا بِتَوْبَةِ أَحَدِكُمْ مِنْ أَحَدِكُمْ بِضَالَّتِهِ إِذَا وَجَدَهَا."],"takhrij":"صحيح: رواه مسلم في التوبة (2675) عن عبدالله بن مسلمة القعنبيّ، حدثنا المغيرة (يعني ابن عبدالرحمن الحزاميّ)، عن أبي الزّناد، عن الأعرج، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب إثبات الفرح لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2675).","chapter_en":"Affirming Joy for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":35,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, said: The Messenger of Allah ﷺ said: “Allah is more intensely joyful at the repentance of one of you than one of you is upon finding what he had lost.”"]},"buhuth":{"en":["It is also narrated with the wording:","“Allah, Mighty and Majestic, says:","‘I am as My servant thinks of Me, and I am with him wherever he remembers Me. By Allah, Allah is more joyful at the repentance of His servant than one of you who finds his lost property in a desolate land.","Whoever draws near to Me by a handspan, I draw near to him by a cubit; whoever draws near to Me by a cubit, I draw near to him by an armspan; and when he comes toward Me walking, I come toward him swiftly.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2675)."},{"num":388,"demo":false,"sanad":"","matn":["عَنِ النُّعْمَانِ بْنِ بَشِيرٍ قَالَ: لَلَّهُ أَشَدُّ فَرَحًا بِتَوْبَةِ عَبْدِهِ مِنْ رَجُلٍ حَمَلَ زَادَهُ وَمَزَادَهُ عَلَى بَعِيرٍ، ثُمَّ سَارَ حَتَّى كَانَ بِفَلَاةٍ مِنَ الْأَرْضِ، فَأَدْرَكَتْهُ الْقَائِلَةُ فَنَزَلَ فَقَالَ: تَحْتَ شَجَرَةٍ فَغَلَبَتْهُ عَيْنُهُ وَانْسَلَّ بَعِيرُهُ، فَاسْتَيْقَظَ فَسَعَى شَرَفًا، فَلَمْ يَرَ شَيْئًا ثُمَّ سَعَى شَرَفًا ثَانِيًا، فَلَمْ يَرَ شَيْئًا ثُمَّ سَعَى شَرَفًا ثَالِثًا، فَلَمْ يَرَ شَيْئًا فَأَقْبَلَ حَتَّى أَتَى مَكَانَهُ الَّذِي قَالَ فِيهِ فَبَيْنَمَا هُوَ قَاعِدٌ إِذْ جَاءَهُ بَعِيرُهُ يَمْشِي حَتَّى وَضَعَ خِطَامَهُ فِي يَدِهِ، فَلَلَّهُ أَشَدُّ فَرَحًا بِتَوْبَةِ الْعَبْدِ مِنْ هَذَا حِينَ وَجَدَ بَعِيرَهُ عَلَى حَالِهِ."],"takhrij":"صحيح: رواه مسلم في التوبة (2745) عن عبيد الله بن معاذ العنبريّ، حدثنا أبي، حدثنا أبو يونس، عن سماك، قال: خطب النعمان فقال (فذكره). قال سماك: فزعم الشعبيُّ أنّ النّعمان رفع هذا الحديث إلى النبيّ صلى الله عليه وسلم، وأما أنا فلم أسمعه.","grade":"صحيح","chapter_ar":"باب إثبات الفرح لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2745).","chapter_en":"Affirming Joy for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":35,"content":{"translation":{"en":["Al-Nuʿmān ibn Bashīr, may Allah be pleased with him, reported: “Allah is more intensely joyful at the repentance of His servant than a man who loaded his provisions and water upon a camel, then traveled until he reached a desolate stretch of land. The midday heat overtook him, so he stopped beneath a tree and sleep overcame him, while his camel slipped away. He awoke and climbed to a high place but saw nothing. Then he climbed to another high place but saw nothing. Then he climbed to a third high place but saw nothing. He returned to the place where he had been, and while he was sitting there, his camel came walking toward him until it placed its reins into his hand. Allah is more intensely joyful at the repentance of His servant than this man was when he found his camel in its original condition.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2745)."},{"num":389,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَيْفَ تَقُولُونَ بِفَرَحِ رَجُلٍ انْفَلَتَتْ مِنْهُ رَاحِلَتُهُ تَجُرُّ زِمَامَهَا بِأَرْضٍ قَفْرٍ لَيْسَ بِهَا طَعَامٌ وَلَا شَرَابٌ، وَعَلَيْهَا لَهُ طَعَامٌ وَشَرَابٌ، فَطَلَبَهَا حَتَّى شَقَّ عَلَيْهِ، ثُمَّ مَرَّتْ بِجِذْلِ شَجَرَةٍ فَتَعَلَّقَ زِمَامُهَا فَوَجَدَهَا مُتَعَلِّقَةً بِهِ؟ قُلْنَا: شَدِيدًا يَا رَسُولَ اللَّهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَمَا وَاللَّهِ لَلَّهُ أَشَدُّ فَرَحًا بِتَوْبَةِ عَبْدِهِ مِنَ الرَّجُلِ بِرَاحِلَتِهِ."],"takhrij":"صحيح: رواه مسلم في التوبة (2746) من طرق عن عبيد الله بن إياد بن لقيط، عن إياد، عن البراء بن عازب، فذكره.","grade":"صحيح","chapter_ar":"باب إثبات الفرح لله عز وجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2746).","chapter_en":"Affirming Joy for Allah, Mighty and Majestic","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":35,"content":{"translation":{"en":["Al-Barāʾ ibn ʿĀzib, may Allah be pleased with him, said: The Messenger of Allah ﷺ said: “What do you say about the joy of a man whose riding animal escapes from him, dragging its reins through a barren land containing neither food nor drink, while his own food and drink are upon it? He searches for it until the search becomes extremely difficult for him. The animal then passes by the trunk of a tree, its reins become caught there, and he finds it caught by its reins.” We said: “His joy would be intense, O Messenger of Allah.” He said: “By Allah, Allah is more intensely joyful at the repentance of His servant than that man is at recovering his riding animal.”"]}},"tuhfa":{},"full":1,"rep":[11434],"tks":"صحيح: رواه مسلم (2746)."},{"num":390,"demo":false,"sanad":"","matn":["عَنْ أَبِي وَاقِدٍ اللَّيْثِيِّ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَمَا هُوَ جَالِسٌ فِي الْمَسْجِدِ وَالنَّاسُ مَعَهُ، إِذْ أَقْبَلَ نَفَرٌ ثَلَاثَةٌ، فَأَقْبَلَ اثْنَانِ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَذَهَبَ وَاحِدٌ، فَلَمَّا وَقَفَا عَلَى مَجْلِسِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَلَّمَا، فَأَمَّا أَحَدُهُمَا فَرَأَى فُرْجَةً فِي الْحَلْقَةِ فَجَلَسَ فِيهَا وَأَمَّا الْآخَرُ فَجَلَسَ خَلْفَهُمْ وَأَمَّا الثَّالِثُ فَأَدْبَرَ ذَاهِبًا، فَلَمَّا فَرَغَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَلَا أُخْبِرُكُمْ عَنِ النَّفَرِ الثَّلَاثَةِ؟ أَمَّا أَحَدُهُمْ فَأَوَى إِلَى اللَّهِ فَآوَاهُ اللَّهُ، وَأَمَّا الْآخَرُ فَاسْتَحْيَا فَاسْتَحْيَا اللَّهُ مِنْهُ، وَأَمَّا الْآخَرُ فَأَعْرَضَ فَأَعْرَضَ اللَّهُ عَنْهُ."],"takhrij":"متفق عليه: رواه مالك في الموطأ في السلام (4) عن إسحاق بن عبدالله بن أبي طلحة، عن أبي مُرّة، مولى عقيل بن أبي طالب، عن أبي واقد اللّيثيّ، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الاستحياء","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (4), al-Bukhārī (66), and Muslim (2176).","chapter_en":"What Has Been Reported Concerning Modesty","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":36,"content":{"translation":{"en":["Abū Wāqid al-Laythī, may Allah be pleased with him, reported: While the Messenger of Allah ﷺ was sitting in the mosque with the people around him, three men approached. Two of them came toward the Messenger of Allah ﷺ, while one went away. When the two stood before the gathering of the Messenger of Allah ﷺ, they gave salām. One of them saw an opening in the circle and sat in it. The other sat behind the gathering. The third turned away and left. When the Messenger of Allah ﷺ had finished, he said: “Shall I not tell you about these three men? As for the first, he sought refuge with Allah, so Allah gave him refuge. As for the second, he felt shy, so Allah showed modesty toward him. And as for the third, he turned away, so Allah turned away from him.”"]},"intro":{"ar":["قال الله تعالى:","﴿إِنَّ اللهَ لَا يَسْتَحْيِي أَنْ يَضْرِبَ مَثَلًا مَا بَعُوضَةً فَمَا فَوْقَهَا﴾","[البقرة: ٢٦]"],"en":["Allah Most High said:","“Indeed, Allah is not ashamed to present an example — that of a mosquito or what is above it.”","[Sūrat al-Baqarah 2:26]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[1141],"tks":"متفق عليه: رواه مالك (4)، والبخاري (66)، ومسلم (2176)."},{"num":391,"demo":false,"sanad":"","matn":["عَنْ سَلْمَانَ الْفَارِسِيِّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ رَبَّكُمْ حَيِيٌّ كَرِيمٌ يَسْتَحْيِي مِنْ عَبْدِهِ إِذَا رَفَعَ يَدَيْهِ إِلَيْهِ أَنْ يَرُدَّهُمَا صِفْرًا."],"takhrij":"حسن: رواه أبو داود (1488)، والترمذيّ (3556)، وابن ماجه (3865)، وصحّحه ابن حبان (876)، والحاكم (1831) كلّهم من طرق عن جعفر بن ميمون، عن أبي عثمان النّهدي، عن سلمان الفارسيّ، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الاستحياء","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (1488), al-Tirmidhī (3556), and Ibn Mājah (3865), and authenticated by Ibn Ḥibbān (876) and al-Ḥākim (1/497).","chapter_en":"What Has Been Reported Concerning Modesty","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":36,"content":{"translation":{"en":["Salmān al-Fārisī may Allah be pleased with him reported that the Prophet ﷺ said: “Indeed, your Lord is Modest and Generous. He is shy to return His servant’s hands empty when the servant raises them to Him.”"]},"buhuth":{"en":["Al-Tirmidhī said:","“This is a Ḥasan Gharīb ḥadīth.”","The word “ṣifran,” with a kasrah on the ṣād, means “empty.” It is said, “A house is ṣifr of possessions,” meaning that it is empty."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1488)، والترمذي (3556)، وابن ماجه (3865)، وصححه ابن حبان (876)، والحاكم (1831)."},{"num":392,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللَّهَ رَحِيمٌ حَيِيٌّ كَرِيمٌ يَسْتَحِي مِنْ عَبْدِهِ أَنْ يَرْفَعَ إِلَيْهِ يَدَيْهِ، ثُمَّ لا يَضَعُ فِيهِمَا خَيْرًا."],"takhrij":"حسن: رواه الحاكم (1832) عن أبي عبدالله الصفّار، ثنا أبو بكر بن أبي الدّنيا، ثنا بشر بن الوليد القاضي، ثنا عامر بن يساف، عن حفص بن عمر بن عبدالله بن أبي طلحة الأنصاريّ، قال: حدثني أنس بن مالك، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الاستحياء","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ḥākim (1832).","chapter_en":"What Has Been Reported Concerning Modesty","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":36,"content":{"translation":{"en":["Anas ibn Mālik, may Allah be pleased with him, said: The Messenger of Allah ﷺ said: “Indeed, Allah is Merciful, Modest, and Generous. He is shy that His servant should raise his hands to Him and then that He should place no good in them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الحاكم (1832)."},{"num":393,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَ: لَا أَحَدَ أَغْيَرُ مِنَ اللَّهِ، وَلِذَلِكَ حَرَّمَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ، وَلَا شَيْءَ أَحَبُّ إِلَيْهِ الْمَدْحُ مِنَ اللَّهِ، وَلِذَلِكَ مَدَحَ نَفْسَهُ.","قُلْتُ: سَمِعْتَهُ مِنْ عَبْدِ اللَّهِ؟ قَالَ: نَعَمْ، قُلْتُ: وَرَفَعَه؟ُ قَالَ: نَعَمْ."],"takhrij":"متفق عليه: رواه البخاريّ في التفسير (4634)، ومسلم في كتاب التوبة (2760: 34) كلاهما من حديث شعبة، عن عمرو بن مرة، عن أبي وائل، عن عبدالله، فذكره.","grade":"متفق عليه","chapter_ar":"باب في غيرة الله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Tafsīr (4634) and Muslim in al-Tawbah (2760:34).","chapter_en":"Concerning Allah’s Protective Jealousy","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":37,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd, may Allah be pleased with him, said: “No one has greater protective jealousy than Allah, and because of that He prohibited indecencies, both those that are apparent and those that are hidden. And nothing is more beloved to Allah than praise, and because of that He praised Himself.” I asked:","“Did you hear this from ʿAbdullāh?” He replied: “Yes.” I asked: “Did he attribute it to the Prophet ﷺ?” He replied: “Yes.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4634)، ومسلم (2760: 34)."},{"num":394,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَيْسَ أَحَدٌ أَحَبَّ إِلَيْهِ الْمَدْحُ مِنَ اللَّهِ عَزَّ وَجَلَّ مِنْ أَجْلِ ذَلِكَ مَدَحَ نَفْسَهُ، وَلَيْسَ أَحَدٌ أَغْيَرَ مِنَ اللَّهِ مِنْ أَجْلِ ذَلِكَ حَرَّمَ الْفَوَاحِشَ، وَلَيْسَ أَحَدٌ أَحَبَّ إِلَيْهِ الْعُذْرُ مِنَ اللَّهِ مِنْ أَجْلِ ذَلِكَ أَنْزَلَ الْكِتَابَ وَأَرْسَلَ الرُّسُلَ."],"takhrij":"صحيح: رواه مسلم في التوبة (2760: 35) من طرق عن جرير، عن الأعمش، عن مالك بن الحارث، عن عبدالرحمن بن يزيد، عن عبدالله بن مسعود، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب في غيرة الله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in al-Tawbah (2760:35).","chapter_en":"Concerning Allah’s Protective Jealousy","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":37,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd, may Allah be pleased with him, said: The Messenger of Allah ﷺ said: “No one loves praise more than Allah, Mighty and Majestic, and because of that He praised Himself. No one has greater protective jealousy than Allah, and because of that He prohibited indecencies. And no one loves the establishment of an excuse more than Allah, and because of that He revealed the Book and sent the Messengers.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2760: 35)."},{"num":395,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ اللَّهَ يَغَارُ، وَغَيْرَةُ اللَّهِ أَنْ يَأْتِيَ الْمُؤْمِنُ مَا حَرَّمَ اللَّهُ."],"takhrij":"متفق عليه: رواه البخاريّ في النكاح (5223)، ومسلم في كتاب التوبة (2761) كلاهما من طريق يحيى، عن أبي سلمة، أنه سمع أبا هريرة، عن النبيّ صلى الله عليه وسلم يقول، فذكره، واللّفظ للبخاريّ.","grade":"متفق عليه","chapter_ar":"باب في غيرة الله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5223) and Muslim (2761), with the wording of al-Bukhārī.","chapter_en":"Concerning Allah’s Protective Jealousy","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":37,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Prophet ﷺ said: “Indeed, Allah has protective jealousy, and Allah’s protective jealousy is aroused when a believer commits what Allah has forbidden.”"]},"buhuth":{"en":["Muslim adds after the words, “Indeed, Allah has protective jealousy”:","“And indeed, the believer has protective jealousy.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5223)، ومسلم (2761)، واللفظ للبخاري."},{"num":396,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْمُؤْمِنُ يَغَارُ وَاللَّهُ أَشَدُّ غَيْرًا."],"takhrij":"صحيح: رواه مسلم في التوبة (2761) عن قتيبة بن سعيد، حدثنا عبدالعزيز ابن محمد، عن العلاء، عن أبيه، عن أبي هريرة، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب في غيرة الله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2761).","chapter_en":"Concerning Allah’s Protective Jealousy","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":37,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “The believer has protective jealousy, and Allah possesses it more intensely.”"]},"buhuth":{"ar":["وقوله: «غَيْراً» أي: غيرة."],"en":["The word “ghayran” means protective jealousy."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2761)."},{"num":397,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ أَنَّهَا سَمِعَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَا شَيْءَ أَغْيَرُ مِنَ اللَّهِ."],"takhrij":"متفق عليه: رواه البخاريّ في النكاح (5222)، ومسلم في كتاب التوبة (2762) كلاهما من حديث يحيى، عن أبي سلمة، أنّ عروة بن الزبير حدّثه أنّ أمَّه حدّثته، فذكرته.","grade":"متفق عليه","chapter_ar":"باب في غيرة الله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5222) and Muslim (2762).","chapter_en":"Concerning Allah’s Protective Jealousy","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":37,"content":{"translation":{"en":["Asmāʾ bint Abī Bakr may Allah be pleased with them reported that she heard the Messenger of Allah ﷺ say: “Nothing possesses greater protective jealousy than Allah.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5222)، ومسلم (2762)."},{"num":398,"demo":false,"sanad":"","matn":["عَنِ الْمُغِيرَةِ قَالَ: قَالَ سَعْدُ بْنُ عُبَادَةَ: لَوْ رَأَيْتُ رَجُلًا مَعَ امْرَأَتِي لَضَرَبْتُهُ بِالسَّيْفِ غَيْرَ مُصْفَحٍ، فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: أَتَعْجَبُونَ مِنْ غَيْرَةِ سَعْدٍ؟ وَاللَّهِ لَأَنَا أَغْيَرُ مِنْهُ، وَاللَّهُ أَغْيَرُ مِنِّي، وَمِنْ أَجْلِ غَيْرَةِ اللَّهِ حَرَّمَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ، وَلَا أَحَدَ أَحَبُّ إِلَيْهِ الْعُذْرُ مِنَ اللَّهِ وَمِنْ أَجْلِ ذَلِكَ بَعَثَ الْمُبَشِّرِينَ وَالْمُنْذِرِينَ، وَلَا أَحَدَ أَحَبُّ إِلَيْهِ الْمِدْحَةُ مِنَ اللَّهِ وَمِنْ أَجْلِ ذَلِكَ وَعَدَ اللَّهُ الْجَنَّةَ."],"takhrij":"متفق عليه: رواه البخاريّ في التوحيد (7416)، ومسلم في اللعان (1499) كلاهما من حديث أبي عوانة، عن عبدالملك بن عمير، عن ورّاد، كاتب المغيرة، ، عن المغيرة، فذكر الحديث. واللّفظ للبخاريّ، ولفظ مسلم نحوه إلاّ أنّ فيه: من أجل ذلك بعث الله المرسلين مبشرين ومنذرين.","grade":"متفق عليه","chapter_ar":"باب في غيرة الله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7416) and Muslim (1499).","chapter_en":"Concerning Allah’s Protective Jealousy","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":37,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah, may Allah be pleased with him, reported: Saʿd ibn ʿUbādah, may Allah be pleased with him, said: “If I were to see a man with my wife, I would strike him with the sharp edge of the sword, not with its flat side.” When this reached the Messenger of Allah ﷺ, he said: “Are you astonished by Saʿd’s protective jealousy? By Allah, I have greater protective jealousy than he does, and Allah has greater protective jealousy than I do. Because of Allah’s protective jealousy, He has prohibited indecencies, those that are apparent and those that are hidden. No one loves accepting an excuse more than Allah, and because of that He sent the bearers of glad tidings and the warners. And no one loves praise more than Allah, and because of that Allah promised Paradise.” In Muslim’s wording: “And because of that Allah sent the Messengers as bearers of glad tidings and warners.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (7416)، ومسلم (1499)."},{"num":399,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ (فَذَكَرَهَا فِي حَدِيثِ طَوِيل) أَنَّ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَا أُمَّةَ مُحَمَّدٍ وَاللَّهِ مَا مِنْ أَحَدٍ أَغْيَرُ مِنَ اللَّهِ أَنْ يَزْنِيَ عَبْدُهُ أَوْ تَزْنِيَ أَمَتُهُ، يَا أُمَّةَ مُحَمَّدٍ وَاللَّهِ لَوْ تَعْلَمُونَ مَا أَعْلَمُ لَضَحِكْتُمْ قَلِيلًا وَلبَكَيْتُمْ كَثِيرًا."],"takhrij":"متفق عليه: رواه مالك في الكسوف (1) عن هشام بن عروة، عن أبيه، عن عائشة، فذكرتْه. ورواه البخاري في الكسوف (1044) عن عبدالله بن مسلمة، ومسلم في الكسوف (901) عن قتيبة بن سعيد، كلاهما عن مالك في سياق طويل، سيأتي في كتاب الكسوف.","grade":"متفق عليه","chapter_ar":"باب في غيرة الله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (1), al-Bukhārī (1044), and Muslim (901).","chapter_en":"Concerning Allah’s Protective Jealousy","part_en":"The Book of Faith","group_ar":"مجموع أبواب الإيمان بالله عز وجل","group_en":"Collection of Chapters on Belief in Allah, Mighty and Majestic","part_no":2,"group_no":2,"chapter_no":37,"content":{"translation":{"en":["ʿĀʾishah may Allah be pleased with her reported that the Prophet ﷺ said: “O community of Muḥammad! By Allah, no one possesses greater protective jealousy than Allah when His male servant commits fornication or His female servant commits fornication. O community of Muḥammad! If you knew what I know, you would laugh little and weep much.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه مالك (1)، والبخاري (1044)، ومسلم (901)."}]);